// Generated by scripts/gen-l10n.mjs (gdetail n3, id) — 不要手改;改翻譯請改 scripts/out/l10n/id/ 再重 build。
window.GRAMMAR_DETAIL_L10N=window.GRAMMAR_DETAIL_L10N||{};window.GRAMMAR_DETAIL_L10N["id"]=Object.assign(window.GRAMMAR_DETAIL_L10N["id"]||{},{"n3-42":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜わけがない」artinya <b>「mana mungkin ～」「masa sih ～」</b>. 「わけ」di sini berarti「alasan／logika」, jadi 「わけがない」secara harfiah adalah「tidak ada logikanya」. Artinya kamu yakin sekali bahwa hal ini <b>sama sekali tidak mungkin</b>.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Menegaskan ketidakmungkinan</span>Berdasarkan akal sehat, atau karena kamu kenal orangnya, kamu merasa hal itu pasti tidak akan terjadi.</div><div class='gd-ex-line'>・<span class='gd-jp'>そんなに簡単に成功するわけがない。</span>(Mana mungkin sukses semudah itu)</div><div class='gd-ex-line'>・<span class='gd-jp'>こんな値段で本物が手に入るわけがない。</span>(Mana mungkin dapat barang asli dengan harga segini)</div><div class='gd-ex-line'>・<span class='gd-jp'>あんなに練習したんだから、負けるわけがない。</span>(Dia sudah latihan sekeras itu, mana mungkin kalah)</div><div class='gd-sec'><span class='gd-tag'>Membantah lawan bicara</span>Dipakai saat ngobrol dengan teman, seperti「masa sih, nggak mungkin lah」. Dalam percakapan, 「が」sering dihilangkan jadi「わけない」.</div><div class='gd-ex-line'>・<span class='gd-jp'>宝くじなんて、当たるわけないよ。</span>(Lotre begituan, mana mungkin menang)</div><div class='gd-ex-line'>・<span class='gd-jp'>そんなわけないでしょ。</span>(Ya nggak mungkin lah)</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Kata kerja</b>: disambung langsung. Bentuk negatif dan lampau juga boleh.<br><span class='gd-pair'><span class='gd-jp'>負ける</span> → <span class='gd-jp'>負けるわけがない</span></span><span class='gd-pair'><span class='gd-jp'>知らない</span> → <span class='gd-jp'>知らないわけがない</span></span><br><b>Kata sifat-い</b>: disambung langsung.<br><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いわけがない</span></span><br><b>Kata sifat-な</b>: ganti「だ」dengan「な」.<br><span class='gd-pair'><span class='gd-jp'>好きだ</span> → <span class='gd-jp'>好きなわけがない</span></span><br><b>Kata benda</b>: ganti「だ」dengan「の」. Untuk gaya yang lebih formal bisa pakai「である」.<br><span class='gd-pair'><span class='gd-jp'>本物だ</span> → <span class='gd-jp'>本物のわけがない</span></span><br>Untuk versi sopan, katakan「<span class='gd-jp'>わけがありません</span>」.</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Kata sifat-な dan kata benda tidak boleh dibiarkan dengan 「だ」: <span class='gd-jp'>好きだわけがない</span> dan <span class='gd-jp'>本物だわけがない</span> keduanya salah.<br>・「〜ないわけがない」adalah dua negasi yang bertumpuk, jadi artinya malah <b>「pasti」</b>: <span class='gd-jp'>彼が期限を守らないわけがない。</span> (Mana mungkin dia tidak menepati tenggat = dia pasti menepatinya)<br>・Hati-hati dengan「tidak bisa」dan「tidak mungkin」dalam bahasa Indonesia, di bahasa Jepang keduanya beda jauh. 「Besok ujian, jadi tidak bisa main」artinya kamu <b>tidak sempat atau tidak seharusnya</b> pergi, jadi pakai わけにはいかない: <span class='gd-jp'>明日は試験だから、遊びに行くわけにはいかない。</span> (Besok ujian, jadi tidak bisa pergi main) Kalau kamu menulis <span class='gd-jp'>遊びに行くわけがない</span>, artinya jadi「mana mungkin aku pergi main」.<br>・Nadanya sangat kuat, terasa seperti「kamu ngomong apa sih, konyol banget」. Kalau langsung menjawab <span class='gd-jp'>そんなわけないです</span> ke atasan atau orang yang lebih tua, kesannya kasar. Lebih baik pakai <span class='gd-jp'>それはないと思います</span>.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Situasi: kamu menawarkan kue ke Tanaka, tapi dia bilang tidak usah. Orang di sebelahmu bertanya, 「Tanaka tidak suka kue ya?」<br><b>わけがない</b> = <b>bantahan keras</b>, nadanya seperti「mana mungkin lah」:</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんがケーキが嫌いなわけがないよ。毎日食べてるもん。</span>(Mana mungkin Tanaka tidak suka kue, dia makan setiap hari lho)</div><div class='gd-sec'><b>はずがない</b> = <b>menyimpulkan secara logis</b> bahwa hal itu tidak begitu, nadanya lebih tenang:</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんは甘いものが大好きだから、ケーキが嫌いなはずがない。</span>(Tanaka suka sekali makanan manis, jadi seharusnya tidak mungkin dia tidak suka kue)</div><div class='gd-sec'>Dua pola ini sering bisa saling menggantikan. Bedanya, はずがない condong ke「dari petunjuk yang ada, kesimpulannya tidak begitu」, sedangkan わけがない condong ke「secara logika memang tidak masuk akal」, dan dalam percakapan emosinya lebih kuat.<br><b>わけではない</b> = <b>「bukan berarti ～」</b>, hanya meluruskan kesalahpahaman dan sama sekali tidak berarti「tidak mungkin」. Kalau Tanaka sendiri yang menjelaskan, dia akan bilang:</div><div class='gd-ex-line'>・<span class='gd-jp'>甘いものが嫌いなわけではない。今はおなかがいっぱいなだけだ。</span>(Bukan berarti aku tidak suka makanan manis, aku cuma lagi kenyang)</div><div class='gd-warn'>Trik memilih: kalau mau bilang「mana mungkin」pakai わけがない; kalau mau bilang「seharusnya tidak」pakai はずがない; kalau mau bilang「bukan berarti ～」pakai わけではない.</div><div class='gd-h'>Setelah ini, pelajari juga</div><div class='gd-sec'>Keluarga「わけ」masih punya: <span class='gd-jp'>わけではない</span> (bukan berarti ～), <span class='gd-jp'>わけにはいかない</span> (tidak bisa ～), ditambah <span class='gd-jp'>はずがない</span> yang artinya paling dekat. Kalau dipelajari bersama, kamu tidak akan tertukar.</div>","n3-43":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜わけではない」artinya <b>「bukan berarti ～」「bukannya ～」</b>. Lawan bicaramu mungkin mengira begitu, lalu kamu meluruskan: 「Bukan seperti yang kamu kira kok」. Mirip dengan kalimat「Bukannya aku nggak suka, cuma...」yang sering kita ucapkan, dan setelahnya biasanya ada alasan yang sebenarnya.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Meluruskan kesalahpahaman</span>Lawan bicara sepertinya salah paham, jadi kamu menjelaskan dengan jelas.</div><div class='gd-ex-line'>・<span class='gd-jp'>反対しているわけではありません。ちょっと心配なだけです。</span>(Saya bukannya menentang, hanya sedikit khawatir)</div><div class='gd-ex-line'>・<span class='gd-jp'>別に怒っているわけじゃないよ。</span>(Aku nggak marah kok)</div><div class='gd-sec'><span class='gd-tag'>Tidak selalu begitu</span>Dipakai bersama「<span class='gd-jp'>みんな</span>」「<span class='gd-jp'>いつも</span>」「<span class='gd-jp'>全部</span>」, artinya「belum tentu semuanya begitu」.</div><div class='gd-ex-line'>・<span class='gd-jp'>日本人がみんな納豆が好きなわけではない。</span>(Tidak semua orang Jepang suka natto)</div><div class='gd-ex-line'>・<span class='gd-jp'>高い服がいつもいいわけではない。</span>(Baju mahal belum tentu selalu lebih bagus)</div><div class='gd-sec'><span class='gd-tag'>Menolak dengan halus</span>Kamu tidak mau menutup pembicaraan secara kaku, jadi kamu menyangkal dulu kemungkinan salah paham, baru memberi alasan.</div><div class='gd-ex-line'>・<span class='gd-jp'>料理が嫌いなわけじゃないけど、毎日はちょっと…。</span>(Bukannya aku nggak suka masak, tapi kalau tiap hari agak...)</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Di depannya dipakai「bentuk biasa」, yaitu bentuk tanpa ます (bentuk kamus, bentuk ない, dan bentuk た semuanya boleh).<br><b>Kata kerja</b>: <span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くわけではない</span></span><span class='gd-pair'><span class='gd-jp'>行った</span> → <span class='gd-jp'>行ったわけではない</span></span><br><b>Kata sifat-い</b>: <span class='gd-pair'><span class='gd-jp'>忙しい</span> → <span class='gd-jp'>忙しいわけではない</span></span><br><b>Kata sifat-な</b>: tambahkan <b>な</b>　<span class='gd-pair'><span class='gd-jp'>嫌い</span> → <span class='gd-jp'>嫌いなわけではない</span></span><br><b>Kata benda</b>: tambahkan <b>な</b>, atau pakai「という」　<span class='gd-pair'><span class='gd-jp'>学生</span> → <span class='gd-jp'>学生というわけではない</span></span></div><div class='gd-sec'>Dalam percakapan sering jadi <b>わけじゃない</b>. Untuk versi lebih sopan, pakai <b>わけではありません</b> atau <b>わけじゃありません</b>.</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Setelah kata sifat-な dan kata benda <b>tidak boleh pakai だ</b>: katakan <span class='gd-jp'>嫌いなわけではない</span>, jangan「嫌いだわけではない」.<br>・「わけ」di sini bukan berarti「alasan」, jadi jangan diartikan「tidak ada alasan」.<br>・Nadanya lebih lembut daripada penyangkalan langsung: <span class='gd-jp'>嫌いじゃない</span> artinya「tidak benci」, sedangkan <span class='gd-jp'>嫌いなわけじゃない</span> artinya「bukan berarti benci (ada alasan lain)」, jadi biasanya setelahnya ada kalimat penjelasan.<br>・Kalau di depannya ada bentuk negatif, jadinya negasi ganda: <span class='gd-jp'>行きたくないわけじゃない。</span> (Bukan berarti tidak mau pergi), artinya sebenarnya agak ingin pergi.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Sama-sama membahas apakah sebuah toko mahal atau tidak:<br><b>わけではない</b> = <b>bukan berarti</b>: <span class='gd-jp'>この店、高いわけではないけど、ちょっと遠い。</span> (Toko ini bukannya mahal, hanya agak jauh)<br><b>わけがない</b> = <b>tidak mungkin</b>: <span class='gd-jp'>100円ショップだから、高いわけがない。</span> (Ini toko serba 100 yen, mana mungkin mahal)<br><b>わけだ</b> = <b>pantas saja</b>: <span class='gd-jp'>有名なシェフの店か。高いわけだ。</span> (Oh, ini toko chef terkenal. Pantas saja mahal)</div><div class='gd-warn'>Trik memilih: 「bukan berarti ～」pakai わけではない, 「tidak mungkin ～」pakai わけがない, 「pantas saja ～」pakai わけだ.</div><div class='gd-h'>Setelah ini, pelajari juga</div><div class='gd-sec'>「<span class='gd-jp'>〜ないことはない</span>」(bukannya tidak ～) artinya dekat dengan「〜ないわけではない」, keduanya bernada「yah, bisa lah, walau agak terpaksa」: <span class='gd-jp'>辛い料理も食べられないことはない。</span> (Makanan pedas pun bukannya tidak bisa kumakan)</div>","n3-41":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>「〜わけだ」 mirip dengan <b>“pantas saja ~” atau “oh, jadi begitu, makanya ~”</b>, dan bisa juga berarti <b>“jadi artinya ~”</b>. Kamu sudah punya satu fakta, lalu tahu alasan di baliknya (atau menghitung informasinya), dan begitu keduanya nyambung, kamu merasa “oh, masuk akal!”. Nah, di saat itulah kamu pakai わけだ.<br>(<span class='gd-jp'>わけ</span> kalau ditulis dengan kanji adalah 「訳」, artinya logika atau alasan.)</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Pantas saja</span> Hal yang dari dulu terasa janggal, dan sekarang kamu tahu sebabnya, jadi tiba-tiba paham. Sering muncul bersama <span class='gd-jp'>道理で</span> (pantas saja) dan <span class='gd-jp'>〜のか</span> (oh, ternyata ~).</div><div class='gd-ex-line'>・<span class='gd-jp'>道理で寒いわけだ。雪が降っている。</span> (Pantas saja dingin, ternyata lagi turun salju)</div><div class='gd-ex-line'>・<span class='gd-jp'>3年も住んでいたのか。日本語が上手なわけだ。</span> (Oh, sudah tinggal tiga tahun, pantas saja bahasa Jepangnya bagus)</div><div class='gd-sec'><span class='gd-tag'>Jadi artinya</span> Menyatakan informasi sebelumnya dengan cara lain, atau menghitung hasilnya, seperti bilang “jadi kesimpulannya ~”.</div><div class='gd-ex-line'>・<span class='gd-jp'>8時に出て9時に着いたから、1時間かかったわけだ。</span> (Berangkat jam 8, tiba jam 9, jadi artinya memakan waktu satu jam)</div><div class='gd-ex-line'>・<span class='gd-jp'>「明日は会社が休みです。」「じゃあ、ゆっくり寝られるわけですね。」</span> (“Besok kantor libur.” “Berarti bisa tidur puas, ya.”)</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Kata kerja</b>: bentuk biasa langsung disambung (bentuk biasa = bentuk tanpa ます, bentuk lampau dan negatif juga boleh)<br><span class='gd-pair'><span class='gd-jp'>眠れない</span> → <span class='gd-jp'>眠れないわけだ</span></span><span class='gd-pair'><span class='gd-jp'>かかった</span> → <span class='gd-jp'>かかったわけだ</span></span><br><b>Kata sifat い</b>: langsung disambung<br><span class='gd-pair'><span class='gd-jp'>寒い</span> → <span class='gd-jp'>寒いわけだ</span></span><br><b>Kata sifat な</b>: “な” harus dipertahankan<br><span class='gd-pair'><span class='gd-jp'>上手</span> → <span class='gd-jp'>上手なわけだ</span></span><br><b>Kata benda</b>: tambah “な” (untuk tulisan yang lebih formal pakai “である”)<br><span class='gd-pair'><span class='gd-jp'>休み</span> → <span class='gd-jp'>休みなわけだ</span></span><br>Kalau bicara dengan orang lain dan perlu sopan, ganti jadi <span class='gd-jp'>わけです</span>. Saat ngobrol, sering disingkat jadi <span class='gd-jp'>わけか</span> atau <span class='gd-jp'>わけね</span>.</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Setelah kata sifat な dan kata benda, <b>わけ tidak bisa langsung menyambung</b>: bilangnya <span class='gd-jp'>上手なわけだ</span>, bukan “上手わけだ”.<br>・わけだ bukan tebakan asal. Di depannya harus ada <b>fakta atau alasan yang sudah kamu ketahui</b>, dan kamu hanya menyambungkannya dengan hasilnya.<br>・Kalau dipakai untuk kekurangan orang lain, seperti <span class='gd-jp'>だから失敗したわけだ</span> (pantas saja gagal), nadanya terdengar seperti “ya iyalah”, jadi hati-hati dengan orang yang lebih tua atau tamu.<br>・Jangan tertukar dengan <span class='gd-jp'>わけがない</span>、<span class='gd-jp'>わけではない</span>、<span class='gd-jp'>わけにはいかない</span>. Bedanya cuma beberapa huruf, tapi artinya sama sekali berbeda.</div><div class='gd-h'>Bedakan dari yang mirip-mirip</div><div class='gd-sec'><b>はずだ</b> juga berarti “menyimpulkan berdasarkan alasan”. Perbedaan kuncinya ada pada saat <b>hasilnya belum pasti</b>: kalau cuma menduga secara logika, hanya boleh pakai はずだ, tidak boleh わけだ. Contoh situasinya sama: Pak Tanaka sudah tinggal sepuluh tahun di Amerika.<br><span class='gd-tag'>わけだ</span> Kamu sudah pernah mendengar dia bicara bahasa Inggris dan merasa dia sangat fasih, dan sekarang kamu tahu alasannya:<br><span class='gd-jp'>10年もアメリカにいたのか。英語がうまいわけだ。</span> (Oh, sepuluh tahun di Amerika, pantas saja bahasa Inggrisnya jago)<br><span class='gd-tag'>はずだ</span> Kamu belum pernah mendengar dia bicara bahasa Inggris dan hanya menduga secara logika (di sini tidak boleh pakai わけだ):<br><span class='gd-jp'>10年もアメリカにいたから、英語がうまいはずだ。</span> (Dia sudah sepuluh tahun di Amerika, seharusnya bahasa Inggrisnya bagus)<br>Satu contoh lagi: <span class='gd-jp'>彼は来ると言っていたから、来るはずだ。</span> (Dia bilang akan datang, jadi seharusnya datang.) Orangnya belum muncul dan hasilnya belum pasti, jadi pakai はずだ.<br>Namun untuk makna “pantas saja”, はずだ juga bisa dipakai. <span class='gd-jp'>道理で寒いはずだ。</span> dan <span class='gd-jp'>10年もアメリカにいたのか。英語がうまいはずだ。</span> terdengar sangat wajar, dan artinya hampir sama dengan わけだ.<br>Kalau alasannya pun tidak ada dan kamu cuma menebak “mungkin begitu”, itu <span class='gd-jp'>だろう</span>／<span class='gd-jp'>でしょう</span>, bukan はずだ dan bukan わけだ.</div><div class='gd-warn'>Trik cepat: kalau hasilnya belum pasti dan kamu hanya menduga secara logika, hanya はずだ yang bisa dipakai. Kalau hasilnya sudah ada di depan mata dan kamu mau bilang “pantas saja / oh, jadi begitu”, わけだ dan はずだ sama-sama bisa.</div><div class='gd-h'>Yang bisa dipelajari berikutnya</div><div class='gd-sec'>Lanjutkan ke keluarga わけ: <span class='gd-jp'>わけがない</span> (tidak mungkin)、<span class='gd-jp'>わけではない</span> (bukan berarti ~)、<span class='gd-jp'>わけにはいかない</span> (secara kewajiban tidak bisa ~). Selain itu, saat menutup penjelasan alasan, orang sering bilang <span class='gd-jp'>というわけで</span> (begitulah, jadi ~): <span class='gd-jp'>というわけで、明日は休みます。</span> (Begitulah, jadi besok aku izin libur.)</div>","n3-3":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'><span class='gd-jp'>〜について</span> artinya <b>“tentang ~” atau “mengenai ~”</b>. Kamu sebutkan dulu topiknya, lalu sambung dengan kata kerja seperti “bicara, bertanya, mencari tahu, memikirkan” untuk memberi tahu lawan bicara <b>isi</b> yang sedang kamu bahas atau teliti.</div><div class='gd-ex-line'>・<span class='gd-jp'>この映画についてどう思う？</span>（Menurutmu film ini bagaimana?）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Diikuti kata kerja</b>: nomina + について<br><span class='gd-pair'><span class='gd-jp'>日本の文化</span> → <span class='gd-jp'>日本の文化について調べる</span></span>（mencari tahu tentang budaya Jepang）<br><b>Diikuti nomina</b>: nomina + <b>についての</b> + nomina<br><span class='gd-pair'><span class='gd-jp'>日本の文化</span> → <span class='gd-jp'>日本の文化についての本</span></span>（buku tentang budaya Jepang）<br><b>Kalau di depannya satu kalimat utuh</b>: tambahkan dulu 「こと」 atau 「か」 supaya kalimat itu jadi satu topik.<br><span class='gd-pair'><span class='gd-jp'>留学する</span> → <span class='gd-jp'>留学することについて</span></span>（tentang hal kuliah di luar negeri）<br><span class='gd-pair'><span class='gd-jp'>どうする</span> → <span class='gd-jp'>どうするかについて話し合う</span></span>（berdiskusi tentang apa yang akan dilakukan）</div><div class='gd-sec'>Pengingat: <span class='gd-jp'>について</span> aslinya 「に＋就いて」, terasa seperti “berpijak pada hal ini”, jadi memang dipakai untuk membicarakan suatu topik.</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>について＋kata kerja</span>Pemakaian paling dasar. Kata kerja di belakangnya kebanyakan berarti “bicara, menulis, bertanya, mencari tahu, memikirkan”.</div><div class='gd-ex-line'>・<span class='gd-jp'>将来について考えたことある？</span>（Pernah memikirkan masa depan?）</div><div class='gd-ex-line'>・<span class='gd-jp'>旅行の予定について話しましょう。</span>（Yuk, kita bahas rencana perjalanan.）</div><div class='gd-sec'><span class='gd-tag'>についての＋nomina</span>Menerangkan nomina di belakangnya, mirip pola “… tentang ~” dalam bahasa Indonesia.</div><div class='gd-ex-line'>・<span class='gd-jp'>日本の歴史についての本を読んでいます。</span>（Aku sedang membaca buku tentang sejarah Jepang.）</div><div class='gd-sec'><span class='gd-tag'>については</span>Mengangkat topik itu untuk dibahas tersendiri, terasa seperti “kalau soal ~ ya…”.</div><div class='gd-ex-line'>・<span class='gd-jp'>料金については、受付で聞いてください。</span>（Soal biaya, silakan tanyakan di resepsionis.）</div><div class='gd-sec'><span class='gd-tag'>につきまして</span>Versi super sopan, sering terdengar dari layanan pelanggan dan pengumuman perusahaan.</div><div class='gd-ex-line'>・<span class='gd-jp'>この件につきましては、後ほどご連絡いたします。</span>（Mengenai hal ini, kami akan menghubungi Anda nanti.）</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Kalau diikuti nomina, 「の」 wajib ada: <span class='gd-jp'>日本の文化について本</span> itu salah, yang benar <span class='gd-jp'>日本の文化についての本</span>.<br>・Kalau di depannya kata kerja, tambahkan こと dulu: <span class='gd-jp'>日本で働くについて</span> itu salah, yang benar <span class='gd-jp'>日本で働くことについて</span>.<br>・“Tentang” memang praktis, tapi di belakang <span class='gd-jp'>について</span> harus ada tindakan yang berhubungan dengan “isi” (bicara, bertanya, mencari tahu, berpikir, berdiskusi). Hati-hati, <span class='gd-jp'>先生について行く</span> adalah ungkapan lain yang artinya “mengikuti guru”, bukan “pergi tentang guru”.<br>・<span class='gd-jp'>私について</span>（tentang aku）dan <span class='gd-jp'>私にとって</span>（bagiku）bedanya tipis sekali, tapi artinya sama sekali berbeda.</div><div class='gd-h'>Bedakan dari yang mirip-mirip</div><div class='gd-sec'>Sama-sama bicara soal “anak”, tapi ganti satu ungkapan saja artinya sudah jauh berbeda:<br><b>について</b> ＝ <b>topik</b> yang dibicarakan: <span class='gd-jp'>子どもの教育について話す。</span>（membicarakan pendidikan anak）<br><b>に対して</b> ＝ sikap atau tindakan yang <b>ditujukan ke siapa</b>: <span class='gd-jp'>子どもに対して優しい。</span>（lembut terhadap anak）<br><b>にとって</b> ＝ penilaian dari <b>sudut pandang</b> siapa: <span class='gd-jp'>子どもにとって大切なことだ。</span>（hal yang penting bagi anak）</div><div class='gd-sec'>Ada juga <b>に関して</b> yang artinya hampir sama. Di kebanyakan situasi bisa saling menggantikan, hanya saja lebih formal dan kaku, sering muncul di pengumuman, berita, dan laporan:<br><span class='gd-jp'>新しいルールについて説明します。</span>（Saya akan menjelaskan aturan baru, nada percakapan sehari-hari）<br><span class='gd-jp'>新しいルールに関して説明します。</span>（Penjelasan mengenai aturan baru, lebih formal）<br>Untuk menerangkan nomina, pasangan <span class='gd-jp'>についての</span> adalah <span class='gd-jp'>に関する</span>.</div><div class='gd-warn'>Trik menentukan: untuk “membahas apa, mencari tahu apa” pakai について; untuk “bersikap bagaimana terhadap siapa” pakai に対して; untuk “bagi siapa” pakai にとって; kalau menulis dokumen resmi dan ingin bilang “mengenai”, bisa diganti に関して.</div>","n3-2":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>「〜に対して」 punya dua arti:<br>Pertama, <b>“terhadap ~” atau “kepada ~”</b>, seperti anak panah yang menunjukkan sikap, tindakan, atau reaksi itu mengarah ke siapa atau apa.<br>Kedua, <b>“berbeda dengan ~, sedangkan ~”</b>, yaitu menaruh dua sisi berdampingan untuk dibandingkan: A begini, tapi B begitu.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Sasaran sikap</span>Sangat tegas, sangat lembut, atau sangat sopan terhadap seseorang.</div><div class='gd-ex-line'>・<span class='gd-jp'>先生は学生に対して厳しい。</span>（Guru itu tegas terhadap murid）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女は誰に対しても優しい。</span>（Dia lembut terhadap siapa pun）</div><div class='gd-sec'><span class='gd-tag'>Sasaran tanggapan</span>Menjawab atau bereaksi terhadap pertanyaan, pendapat, atau usulan.</div><div class='gd-ex-line'>・<span class='gd-jp'>質問に対して、丁寧に答えた。</span>（Menanggapi pertanyaan itu, dia menjawab dengan teliti）</div><div class='gd-ex-line'>・<span class='gd-jp'>新しいルールに対して、反対の意見が多い。</span>（Banyak yang berpendapat menentang aturan baru）</div><div class='gd-sec'><span class='gd-tag'>Perbandingan</span>Dipakai ketika kedua sisi jelas berbeda.</div><div class='gd-ex-line'>・<span class='gd-jp'>兄が静かなのに対して、弟はにぎやかだ。</span>（Kakaknya pendiam, sedangkan adiknya ramai）</div><div class='gd-ex-line'>・<span class='gd-jp'>東京は雨だったのに対して、大阪は晴れていた。</span>（Tokyo hujan, sedangkan Osaka cerah）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Pola “terhadap ~”</b>: nomina langsung diikuti に対して.<br><span class='gd-pair'><span class='gd-jp'>お客様</span> → <span class='gd-jp'>お客様に対して</span></span><br>Kalau di belakangnya nomina, ubah jadi <b>に対する</b>:<br><span class='gd-pair'><span class='gd-jp'>先生に対して</span> → <span class='gd-jp'>先生に対する態度</span>（sikap terhadap guru）</span></div><div class='gd-sec'><b>Pola “sedangkan ~”</b>: taruh satu kalimat utuh di depan, lalu tambahkan <b>のに対して</b>.<br>Kata kerja dan kata sifat-い langsung disambung: <span class='gd-pair'><span class='gd-jp'>よく食べる</span> → <span class='gd-jp'>よく食べるのに対して</span></span><br>Kata sifat-な dan nomina harus ditambah 「な」 dulu: <span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かなのに対して</span></span><span class='gd-pair'><span class='gd-jp'>学生</span> → <span class='gd-jp'>学生なのに対して</span></span><br>Untuk hal yang sudah lampau, pakai bentuk lampau: <span class='gd-pair'><span class='gd-jp'>雨だった</span> → <span class='gd-jp'>雨だったのに対して</span></span></div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Partikel di depannya adalah <b>に</b>, bukan を: menulis 「先生を対して」 itu salah.<br>・Kalau di belakangnya nomina, harus pakai <b>に対する</b>: 「先生に対して態度」 itu salah, yang benar <span class='gd-jp'>先生に対する態度</span>.<br>・Pada pola perbandingan, 「の」 wajib ada: 「静かに対して」 itu salah, yang benar <span class='gd-jp'>静かなのに対して</span>.<br>・Kata “terhadap/untuk/pada” dalam bahasa Indonesia itu serbaguna, tapi dalam bahasa Jepang tidak semuanya bisa diganti に対して. “Baik untuk tubuh” adalah <span class='gd-jp'>体にいい</span>; “tertarik pada budaya Jepang” adalah <span class='gd-jp'>日本文化に興味がある</span>; “bagi saya” adalah <span class='gd-jp'>私にとって</span>.<br>・に対して terdengar agak formal. Dalam obrolan sehari-hari, untuk “baik kepada teman” cukup bilang <span class='gd-jp'>友達に優しい</span>, itu sudah natural.</div><div class='gd-h'>Bedakan dari yang mirip-mirip</div><div class='gd-sec'>Sama-sama soal “aturan baru”, tapi ganti ungkapan, artinya ikut berubah:<br><b>について</b> ＝ topiknya apa (tentang ~): <span class='gd-jp'>新しいルールについて説明した。</span>（Menjelaskan isi aturan baru）<br><b>に対して</b> ＝ sikap atau reaksi itu mengarah ke siapa atau apa (terhadap ~): <span class='gd-jp'>新しいルールに対して、文句を言う人が多い。</span>（Banyak orang yang mengeluh terhadap aturan baru）<br><b>にとって</b> ＝ penilaian dari sudut pandang siapa (bagi ~): <span class='gd-jp'>学生にとって、新しいルールは厳しすぎる。</span>（Bagi murid, aturan baru terlalu ketat）</div><div class='gd-sec'>Pasangan yang paling mudah tertukar adalah ini:<br><span class='gd-jp'>先生は学生に対して厳しい。</span>（Guru tegas terhadap murid: yang tegas adalah gurunya）<br><span class='gd-jp'>この試験は学生にとって難しい。</span>（Ujian ini sulit bagi murid: yang merasa sulit adalah muridnya）<br>Satu lagi, <b>に関して</b> artinya sama dengan について, hanya saja lebih formal.</div><div class='gd-warn'>Trik menentukan: untuk “tentang topik apa” pakai について; untuk “bersikap atau bereaksi bagaimana terhadap siapa/apa” pakai に対して; untuk “bagi siapa itu terasa bagaimana” pakai にとって.</div><div class='gd-h'>Setelah ini belajar apa</div><div class='gd-sec'>Lanjutkan ke <span class='gd-jp'>〜にとって</span> dan <span class='gd-jp'>〜に関して</span> supaya kamu bisa membedakan semua ungkapan “terhadap, bagi, mengenai” ini sekaligus.</div>","n3-8":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>「〜にとって」artinya <b>「bagi ～」</b>. Kamu menyebut dulu sudut pandang siapa yang dipakai, lalu menjelaskan apakah hal itu <b>penting atau tidak, sulit atau tidak, bagus atau tidak</b> menurut orang itu. Hal yang sama bisa terasa sangat berbeda kalau dilihat orang lain. にとって dipakai untuk menunjukkan「ini perasaan siapa」.</div><div class='gd-ex-line'>・<span class='gd-jp'>私にとって、家族が一番大切です。</span>（Bagi saya, keluarga adalah yang paling penting）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Cukup tambahkan にとって setelah kata benda. Yang paling sering dipakai adalah orang, tapi hewan, perusahaan, dan negara juga bisa.<br><span class='gd-pair'><span class='gd-jp'>私</span> → <span class='gd-jp'>私にとって</span></span><span class='gd-pair'><span class='gd-jp'>外国人</span> → <span class='gd-jp'>外国人にとって</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>外国人にとって、敬語は難しい。</span>（Bagi orang asing, bahasa hormat itu sulit）</div><div class='gd-ex-line'>・<span class='gd-jp'>猫にとって、この部屋は暑すぎるかもしれない。</span>（Bagi kucing, ruangan ini mungkin terlalu panas）</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>にとって</span>bisa diletakkan di awal kalimat atau di tengah kalimat. Artinya「kalau dilihat dari posisi seseorang」hal ini bagaimana. Setelahnya boleh diberi koma, boleh juga tidak.</div><div class='gd-ex-line'>・<span class='gd-jp'>この経験は私にとって大きな財産だ。</span>（Pengalaman ini adalah harta yang besar bagi saya）</div><div class='gd-sec'><span class='gd-tag'>にとっては</span>ada tambahan は, sehingga terasa ada perbandingan:「bagi dia memang begitu, tapi bagi orang lain belum tentu」.</div><div class='gd-ex-line'>・<span class='gd-jp'>大人にとっては短い時間でも、子供にとっては長い。</span>（Waktu yang singkat bagi orang dewasa, bagi anak-anak terasa panjang）</div><div class='gd-sec'><span class='gd-tag'>にとっての＋名詞</span>dipakai kalau kamu ingin menjadikan「～ yang bagi ...」satu kesatuan kata benda. Di tengahnya harus ada <b>の</b>.</div><div class='gd-ex-line'>・<span class='gd-jp'>子供にとっての幸せを考えてみましょう。</span>（Mari kita pikirkan apa arti kebahagiaan bagi anak-anak）</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Setelah にとって yang muncul adalah <b>penilaian</b>, misalnya 大切、難しい、便利、貴重、意味がある. Kamu tidak bisa memakainya untuk「sikap atau tindakan terhadap seseorang」. Untuk「Guru ramah terhadap murid」kamu harus bilang <span class='gd-jp'>先生は学生に対して親切だ</span>. Kalau bilang 先生は学生にとって親切だ, itu salah.<br>・Kata Indonesia seperti「untuk」dan「terhadap」cakupannya luas, sedangkan bahasa Jepang membedakannya dengan tegas. Jangan langsung pakai にとって hanya karena kamu melihat kata「untuk」atau「terhadap」.<br>・Soal の: <span class='gd-jp'>私にとって、幸せは家族と過ごす時間です。</span>Kalimat ini sepenuhnya benar, karena にとって menjelaskan seluruh kalimat. Hanya kalau kamu ingin membuat satu kesatuan kata benda「～ yang bagi ...」, misalnya diletakkan sebelum を sebagai objek, kamu wajib memakai <span class='gd-jp'>にとっての</span>.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Kata「murid」yang sama bisa berubah arti tergantung pola tata bahasanya:<br><b>にとって</b>＝<b>menilai</b> dari sudut pandang murid: <span class='gd-jp'>学生にとって、この先生は怖い存在だ。</span>（Bagi murid, guru ini sosok yang menakutkan）<br><b>に対して</b>＝sikap atau tindakan yang <b>ditujukan</b> kepada murid: <span class='gd-jp'>この先生は学生に対して厳しい。</span>（Guru ini keras terhadap murid）<br><b>について</b>＝<b>topik</b> pembicaraan atau pemikiran: <span class='gd-jp'>先生は学生について話した。</span>（Guru membicarakan soal murid）</div><div class='gd-sec'>Satu lagi yang sering tertukar adalah <b>として</b>, yang artinya「sebagai ～」:<br><span class='gd-jp'>親として、子供を守りたい。</span>（Sebagai orang tua, saya ingin melindungi anak）<br><span class='gd-jp'>親にとって、子供は宝物だ。</span>（Bagi orang tua, anak adalah harta）</div><div class='gd-warn'>Trik cepat memilih: kalau setelahnya perasaan atau penilaian seperti「penting, sulit, berharga」, pakai にとって. Kalau setelahnya sikap terhadap orang seperti「keras, ramah, menentang」, pakai に対して. Kalau setelahnya「membicarakan, menyelidiki, mendiskusikan」, pakai について. Kalau mau bilang「sebagai ～」, pakai として.</div>","n3-28":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>「〜に関して」artinya <b>「mengenai ～」「terkait ～」</b>. Artinya hampir sama dengan「〜について」, tapi terdengar lebih <b>formal dan kaku</b>. Sama seperti dalam obrolan sehari-hari kita bilang「soal itu」, sedangkan pengumuman perusahaan atau berita menulis「terkait kasus ini」. Kamu akan sering melihatnya di berita, pemberitahuan perusahaan, pengumuman sekolah, dan balasan layanan pelanggan.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Di depannya selalu <b>kata benda</b>. Bentuk yang dipakai tergantung apa yang datang setelahnya:</div><div class='gd-sec'><span class='gd-tag'>Diikuti kalimat</span>Kata benda＋に関して, lalu diikuti satu kalimat utuh (melakukan apa, bagaimana).</div><div class='gd-ex-line'>・<span class='gd-jp'>事故の原因に関して、今調べています。</span>（Mengenai penyebab kecelakaan, sekarang sedang diselidiki）</div><div class='gd-ex-line'>・<span class='gd-jp'>この件に関して、何か質問はありますか。</span>（Mengenai hal ini, ada pertanyaan?）</div><div class='gd-sec'><span class='gd-tag'>Diikuti kata benda</span>Kata benda＋に関する＋kata benda, untuk menerangkan kata benda di belakangnya menjadi「〇〇 yang terkait ～」.</div><div class='gd-ex-line'>・<span class='gd-jp'>環境問題に関する本を探しています。</span>（Saya sedang mencari buku tentang masalah lingkungan）</div><div class='gd-ex-line'>・<span class='gd-jp'>日本の文化に関するレポートを書きました。</span>（Saya menulis laporan tentang budaya Jepang）</div><div class='gd-sec'>Sebelum kata benda, kamu juga bisa memakai <span class='gd-jp'>に関しての</span>, misalnya <span class='gd-jp'>環境問題に関しての本</span>. Artinya sama.</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>に関しては</span>Dengan tambahan「は」, terasa seperti「kalau soal bagian 〇〇」. Sering dipakai saat menjelaskan atau menjawab pertanyaan.</div><div class='gd-ex-line'>・<span class='gd-jp'>料金に関しては、こちらをご覧ください。</span>（Untuk soal biaya, silakan lihat di sini）</div><div class='gd-sec'><span class='gd-tag'>に関しまして</span>Versi yang lebih sopan. Sering terdengar dalam telepon bisnis dan penjelasan di situasi formal.</div><div class='gd-ex-line'>・<span class='gd-jp'>この件に関しまして、後ほどご連絡いたします。</span>（Mengenai hal ini, kami akan menghubungi Anda nanti）</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Sebelum kata benda, pakai <b>に関する</b> atau <b>に関しての</b>. <span class='gd-jp'>環境問題に関して本</span> itu salah, yang benar <span class='gd-jp'>環境問題に関する本</span>.<br>・Ini sangat formal, jadi kalau dipakai ngobrol dengan teman terdengar aneh, seperti sedang rapat. Untuk topik seperti「film kemarin」di antara teman, cukup pakai <span class='gd-jp'>について</span>.<br>・Kata「terhadap」atau「kepada」dalam bahasa Indonesia tidak selalu bisa diganti に関して. Dalam「sopan terhadap pelanggan」, maksudnya sikap yang ditujukan kepada seseorang, jadi pakai <span class='gd-jp'>に対して</span>, bukan に関して.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>について</b>＝「mengenai ～」, bisa dipakai di situasi sehari-hari maupun formal, cakupannya paling luas. <b>に関して</b> artinya sama, hanya lebih formal.<br><span class='gd-jp'>昨日の試合について話そうよ。</span>（Yuk ngobrolin pertandingan kemarin: obrolan antarteman）<br><span class='gd-jp'>昨日の試合に関して、監督がコメントを発表した。</span>（Mengenai pertandingan kemarin, pelatih menyampaikan komentarnya: berita）<br>Sekalian ingat: sebelum kata benda, bentuk について adalah <span class='gd-jp'>についての</span>, misalnya <span class='gd-jp'>日本についての本</span>.</div><div class='gd-sec'><b>に対して</b>＝「terhadap ～」, menunjukkan sikap atau tindakan yang ditujukan kepada siapa.<br><span class='gd-jp'>お客様に対して、丁寧な言葉を使います。</span>（Kepada pelanggan, kami menggunakan bahasa yang sopan）<br>Kalimat ini tidak bisa diganti に関して, karena kamu bukan sedang membahas「topik tentang pelanggan」, melainkan「berbicara kepada pelanggan」.</div><div class='gd-sec'><b>にとって</b>＝「bagi ～」, menilai dari sudut pandang seseorang.<br><span class='gd-jp'>私にとって、家族が一番大切です。</span>（Bagi saya, keluarga adalah yang paling penting）</div><div class='gd-warn'>Trik cepat memilih: kalau dalam bahasa Indonesia bisa diganti「mengenai ～ / terkait ～」, pakai に関して (formal) atau について (sehari-hari). Untuk「bersikap tertentu terhadap seseorang」pakai に対して. Untuk「bagi seseorang」pakai にとって.</div>","n3-44":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜わけにはいかない」 mirip dengan <b>「masa iya sih ～」 atau 「tidak bisa seenaknya ～」</b> dalam bahasa Indonesia. Intinya bukan kamu tidak mampu, tapi menurut akal sehat, rasa sungkan, atau posisimu, <b>tidak pantas berbuat begitu</b>. Atasan masih lembur, lalu dalam hati kamu berpikir 「masa iya aku pulang duluan」. Nah, begitulah rasanya.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><span class='gd-tag'>Tidak bisa melakukan</span>bentuk kamus＋わけにはいかない<br><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰るわけにはいかない</span></span>（masa iya pulang）</div><div class='gd-sec'><span class='gd-tag'>Tidak bisa tidak melakukan</span>bentuk ない＋わけにはいかない, artinya jadi <b>harus melakukan</b>.<br><span class='gd-pair'><span class='gd-jp'>行かない</span> → <span class='gd-jp'>行かないわけにはいかない</span></span>（masa iya tidak pergi ＝ mau tidak mau harus pergi）<br>Bentuk ない adalah bentuk negatif verba, yaitu 「tidak ～」. Contohnya <span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行かない</span></span><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べない</span></span>.</div><div class='gd-sec'>Kalau bicara dengan orang yang lebih tua atau tamu, supaya lebih sopan, ganti いかない dengan いきません: <span class='gd-jp'>休むわけにはいきません</span>（saya tidak bisa libur）</div><div class='gd-h'>Dipakai kapan</div><div class='gd-sec'><span class='gd-tag'>Masa iya melakukan</span>Tidak pantas dilakukan karena alasan atau posisi.</div><div class='gd-ex-line'>・<span class='gd-jp'>車で来たから、お酒を飲むわけにはいかない。</span>（Aku datang naik mobil, masa iya minum alkohol）</div><div class='gd-ex-line'>・<span class='gd-jp'>明日は大事な会議だから、休むわけにはいかない。</span>（Besok ada rapat penting, aku tidak bisa libur）</div><div class='gd-sec'><span class='gd-tag'>Masa iya tidak melakukan</span>Sebenarnya kurang mau, tapi karena soal rasa sungkan dan tanggung jawab, ya terpaksa dilakukan.</div><div class='gd-ex-line'>・<span class='gd-jp'>先輩に頼まれたから、手伝わないわけにはいかない。</span>（Senior yang minta tolong, masa iya tidak membantu）</div><div class='gd-ex-line'>・<span class='gd-jp'>約束したから、行かないわけにはいかない。</span>（Sudah janji, jadi tidak bisa tidak pergi）</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>わけにもいかない</span>Ganti は dengan も, jadi 「<b>juga</b> tidak bisa ～」. Sering dipakai saat serba salah.</div><div class='gd-ex-line'>・<span class='gd-jp'>早く帰りたいけど、先に帰るわけにもいかない。</span>（Pengin cepat pulang, tapi masa iya pulang duluan）</div><div class='gd-sec'>Saat bicara cepat, は kadang dihilangkan menjadi <span class='gd-jp'>わけにいかない</span>, artinya sama.</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Tidak bisa dipakai untuk 「tidak bisa karena tidak mampu」. 「Saya tidak bisa berenang」 adalah <span class='gd-jp'>泳げない</span>, bukan 泳ぐわけにはいかない.<br>・Akhirannya <b>いかない</b>, bukan いけない. 「わけにはいけない」 itu salah.<br>・Kalau bagian depannya positif atau negatif, artinya berbalik: <span class='gd-jp'>飲むわけにはいかない</span>＝tidak boleh minum; <span class='gd-jp'>飲まないわけにはいかない</span>＝tidak bisa tidak minum.<br>・Jangan dipakai untuk sekadar 「tidak mau」. Untuk itu pakai <span class='gd-jp'>行きたくない</span>. Di balik わけにはいかない selalu ada alasan 「seharusnya begitu」.<br>・Kebanyakan dipakai untuk menceritakan situasi <b>diri sendiri</b>, yaitu perasaan si pembicara 「masa iya aku ～」.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Sama-sama soal acara makan bersama kantor, lihat bedanya:<br><b>Negatif bentuk potensial</b>＝tidak bisa karena kondisi: <span class='gd-jp'>熱があって、飲み会に行けない。</span>（Demam, jadi tidak bisa pergi）<br><b>わけにはいかない</b>＝tidak bisa karena rasa sungkan atau posisi: <span class='gd-jp'>部長も来るから、行かないわけにはいかない。</span>（Kepala departemen juga datang, masa iya aku tidak pergi）<br><b>わけがない</b>＝menurut penilaianku mustahil: <span class='gd-jp'>田中さんは忙しいから、来るわけがない。</span>（Tanaka-san sibuk sekali, mustahil dia datang）<br><b>わけではない</b>＝bukan berarti: <span class='gd-jp'>飲み会が嫌いなわけではない。</span>（Bukan berarti aku benci acara makan bersama）</div><div class='gd-warn'>Trik cepat: 「tidak mampu」 pakai bentuk potensial, 「masa iya ～」 pakai わけにはいかない, 「mustahil」 pakai わけがない, 「bukan berarti」 pakai わけではない.</div><div class='gd-h'>Setelah ini bisa lanjut belajar</div><div class='gd-sec'>「〜ざるを得ない」 di N2 juga berarti 「mau tidak mau harus ～」, tapi nadanya lebih kaku dan lebih bergaya tulisan: <span class='gd-jp'>行かざるを得ない。</span>（mau tidak mau harus pergi）</div>","n3-61":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜べきだ」 sama dengan <b>「seharusnya ～」 atau 「sudah semestinya ～」</b> dalam bahasa Indonesia. Ini bukan menebak apa yang akan terjadi, tapi soal <b>benar dan salah</b>, yaitu kamu merasa begitulah yang benar. Seperti kita bilang 「utang harus dibayar」, dalam bahasa Jepang jadi <span class='gd-jp'>借りたお金は返すべきだ。</span></div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Verba bentuk kamus＋べきだ</b><br><span class='gd-pair'><span class='gd-jp'>守る</span> → <span class='gd-jp'>守るべきだ</span></span>（seharusnya ditaati）<br><span class='gd-pair'><span class='gd-jp'>謝る</span> → <span class='gd-jp'>謝るべきだ</span></span>（seharusnya minta maaf）</div><div class='gd-sec'><b>Untuk 「tidak seharusnya」</b>: tetap pakai bentuk kamus, lalu ganti 「だ」 dengan 「ではない」.<br><span class='gd-pair'><span class='gd-jp'>言う</span> → <span class='gd-jp'>言うべきではない</span></span>（tidak seharusnya dikatakan）</div><div class='gd-sec'><b>する agak spesial</b>: <span class='gd-jp'>するべき</span> dan <span class='gd-jp'>すべき</span> dua-duanya benar. <span class='gd-jp'>すべき</span> lebih sering muncul di tulisan dan berita, sedangkan dalam percakapan kedua-duanya terdengar.<br><span class='gd-pair'><span class='gd-jp'>確認する</span> → <span class='gd-jp'>確認すべきだ</span></span></div><div class='gd-sec'><b>Nomina dan kata sifat-な</b>: tambahkan 「であるべきだ」 di belakangnya.<br><span class='gd-pair'><span class='gd-jp'>公平</span> → <span class='gd-jp'>公平であるべきだ</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>先生は公平であるべきだ。</span>（Guru seharusnya bersikap adil）</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>べきだ／べきです</span>Menyatakan hal yang menurutmu 「seharusnya dilakukan」.</div><div class='gd-ex-line'>・<span class='gd-jp'>約束は守るべきだ。</span>（Janji seharusnya ditepati）</div><div class='gd-ex-line'>・<span class='gd-jp'>若いうちに、いろいろな経験をするべきです。</span>（Selagi muda, seharusnya kita mencoba banyak pengalaman）</div><div class='gd-sec'><span class='gd-tag'>べきではない</span>Hal yang menurutmu 「tidak seharusnya dilakukan」.</div><div class='gd-ex-line'>・<span class='gd-jp'>人の悪口を言うべきではない。</span>（Tidak seharusnya menjelek-jelekkan orang lain）</div><div class='gd-sec'><span class='gd-tag'>べきだった</span>Menengok ke belakang dengan penyesalan: dulu seharusnya dilakukan, tapi tidak dilakukan. Sebaliknya, <span class='gd-jp'>べきではなかった</span> berarti 「dulu seharusnya tidak dilakukan」.</div><div class='gd-ex-line'>・<span class='gd-jp'>あのとき、ちゃんと謝るべきだった。</span>（Waktu itu seharusnya aku minta maaf dengan benar）</div><div class='gd-ex-line'>・<span class='gd-jp'>あんなこと、言うべきではなかった。</span>（Seharusnya aku tidak mengatakan hal seperti itu）</div><div class='gd-sec'><span class='gd-tag'>べき＋nomina</span>「…yang seharusnya ～」, diletakkan langsung di depan nomina.</div><div class='gd-ex-line'>・<span class='gd-jp'>今やるべきことは何だろう。</span>（Apa ya yang seharusnya kulakukan sekarang）</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Untuk negatif, jangan bilang 「言わないべき」, tapi <span class='gd-jp'>言うべきではない</span>. Di depan べき selalu dipakai bentuk kamus.<br>・する tidak berubah menjadi 「しべき」, hanya ada <span class='gd-jp'>するべき</span> atau <span class='gd-jp'>すべき</span>.<br>・Nadanya kuat dan terdengar menggurui, seperti 「begini lho yang benar」. Kalau kamu bilang 「〜べきです」 langsung kepada atasan atau orang yang lebih tua, gampang terdengar seperti menceramahi. Untuk memberi saran, pakai <span class='gd-jp'>〜たほうがいいと思います</span>. Kalaupun mau pakai べき, setidaknya tambahkan <span class='gd-jp'>と思います</span> supaya nadanya lebih lembut.<br>・べき adalah hal yang <b>si pembicara sendiri anggap</b> perlu dilakukan, bukan aturan. Untuk hal yang wajib karena hukum atau peraturan sekolah, pakai <span class='gd-jp'>〜なければならない</span>: <span class='gd-jp'>日本では、車は左側を走らなければならない。</span>（Di Jepang, mobil harus berjalan di sisi kiri）Kalau diganti べき, kesannya jadi seperti opini pribadi, dan itu aneh.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>べき vs はず</b>: kata 「seharusnya」 dalam bahasa Indonesia punya dua arti, dan bahasa Jepang membedakannya dengan dua ungkapan.<br><b>べき</b>＝<b>seharusnya dilakukan</b> (penilaian benar atau salah)<br><b>はず</b>＝<b>seharusnya begitu / pasti begitu</b> (dugaan)</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんは約束を守るべきだ。</span>（Tanaka-san seharusnya menepati janji: menurutku dia harus begitu）</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんは約束を守るはずだ。</span>（Tanaka-san pasti menepati janji: dugaanku dia akan begitu）</div><div class='gd-sec'><b>べきではない vs ものではない</b>: keduanya bisa diterjemahkan 「tidak seharusnya」. <span class='gd-jp'>ものではない</span> bicara soal akal sehat dan norma yang diketahui semua orang, mirip orang tua yang mengajari anak 「orang tidak boleh begitu」. <span class='gd-jp'>べきではない</span> lebih ke penilaian dan pendirian si pembicara sendiri.</div><div class='gd-ex-line'>・<span class='gd-jp'>約束を破るものではない。</span>（Janji itu tidak patut dilanggar: norma umum）</div><div class='gd-ex-line'>・<span class='gd-jp'>約束を破るべきではない。</span>（Tidak seharusnya melanggar janji: menurutku itu salah）</div><div class='gd-warn'>Trik cepat: 「seharusnya / tidak seharusnya dilakukan」 pakai べき, 「seharusnya begitu / pasti begitu」 pakai はず. Kalau nadanya seperti norma umum, 「orang tidak boleh begitu」, pakai ものではない.</div>","n3-13":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>Arti 「〜うちに」 yang paling umum adalah <b>「selagi ~」</b>, mirip peribahasa \"mumpung masih panas, tempa besinya\": keadaan sekarang <b>nanti akan berubah</b>, jadi lakukan sekarang selagi masih sempat. Ada juga arti lain, yaitu <b>「lama-lama, tanpa sadar jadi…」</b>. Dua-duanya sering dipakai.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Selagi / mumpung ~</span>Keadaan sekarang (masih panas, masih muda, masih pelajar) tidak akan bertahan terus, jadi manfaatkan kesempatannya.</div><div class='gd-ex-line'>・<span class='gd-jp'>熱いうちに召し上がってください。</span>(Silakan dimakan selagi masih panas)</div><div class='gd-ex-line'>・<span class='gd-jp'>学生のうちに、たくさん本を読んでおきたい。</span>(Aku ingin banyak membaca buku selagi masih jadi pelajar)</div><div class='gd-ex-line'>・<span class='gd-jp'>両親が元気なうちに、一緒に旅行したい。</span>(Aku ingin jalan-jalan bersama orang tuaku selagi mereka masih sehat)</div><div class='gd-sec'><span class='gd-tag'>Sebelum ~ (selagi belum)</span>Pakai bentuk ない + うちに. Artinya \"selagi sesuatu belum terjadi\", dengan nuansa agak terburu-buru.</div><div class='gd-ex-line'>・<span class='gd-jp'>暗くならないうちに帰ろう。</span>(Ayo pulang sebelum gelap)</div><div class='gd-ex-line'>・<span class='gd-jp'>忘れないうちに、メモしておこう。</span>(Aku catat dulu sebelum lupa)</div><div class='gd-sec'><span class='gd-tag'>Tanpa sadar jadi…</span>Kamu terus melakukan sesuatu, lalu lama-lama muncul sebuah perubahan.</div><div class='gd-ex-line'>・<span class='gd-jp'>話しているうちに、仲良くなった。</span>(Sambil ngobrol, lama-lama jadi akrab)</div><div class='gd-ex-line'>・<span class='gd-jp'>何度も聞いているうちに、歌詞を覚えた。</span>(Setelah didengar berkali-kali, liriknya jadi hafal)</div><div class='gd-ex-line'>・<span class='gd-jp'>知らないうちに寝てしまった。</span>(Tanpa sadar aku tertidur)</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Kata kerja bentuk ている: <span class='gd-pair'><span class='gd-jp'>話している</span> → <span class='gd-jp'>話しているうちに</span></span><br>Kata kerja bentuk ない: <span class='gd-pair'><span class='gd-jp'>忘れない</span> → <span class='gd-jp'>忘れないうちに</span></span><br>Kata sifat い: langsung sambung　<span class='gd-pair'><span class='gd-jp'>熱い</span> → <span class='gd-jp'>熱いうちに</span></span><br>Kata sifat な: tambahkan な　<span class='gd-pair'><span class='gd-jp'>元気</span> → <span class='gd-jp'>元気なうちに</span></span><br>Kata benda: tambahkan の　<span class='gd-pair'><span class='gd-jp'>学生</span> → <span class='gd-jp'>学生のうちに</span></span><br>Bentuk kamus kata kerja juga bisa, tapi biasanya kata kerja \"keadaan\", seperti <span class='gd-jp'>日本にいるうちに</span> (selagi masih di Jepang).</div><div class='gd-h'>Hati-hati, ini sering salah</div><div class='gd-warn'>・Tidak bisa dipakai dengan bentuk た: <b>×話したうちに</b>. Yang benar: <span class='gd-jp'>話しているうちに</span>.<br>・Jangan tertukar antara kata sifat な dan kata benda: <span class='gd-jp'>元気なうちに</span> bukan 元気のうちに; <span class='gd-jp'>学生のうちに</span> bukan 学生なうちに; kata sifat い tidak pakai の, jadi <span class='gd-jp'>若いうちに</span>, bukan 若いのうちに.<br>・Kalau melihat 「ないうちに」, jangan panik karena ada bentuk negatif. Artinya <b>\"selagi belum\"</b>, bukan \"saat tidak ~\".<br>・Untuk arti \"selagi ~\", bagian belakangnya biasanya hal yang ingin atau harus kamu lakukan: <span class='gd-jp'>〜ておこう</span>、<span class='gd-jp'>〜たい</span>、<span class='gd-jp'>〜てください</span>.<br>・Untuk arti \"tanpa sadar\", bagian belakangnya adalah perubahan yang terjadi dengan sendirinya, biasanya <span class='gd-jp'>〜なった</span>、<span class='gd-jp'>〜てしまった</span>, bukan hal yang sengaja kamu lakukan.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'><b>間に</b> = sekadar \"di dalam rentang waktu itu\", tanpa perasaan khusus: <span class='gd-jp'>日本にいる間に、富士山に登りたい。</span>(Aku ingin mendaki Gunung Fuji selama berada di Jepang)<br><b>うちに</b> = ada rasa <b>\"selagi masih ada, nanti belum tentu ada kesempatan lagi\"</b>: <span class='gd-jp'>日本にいるうちに、富士山に登りたい。</span>(Aku ingin mendaki Gunung Fuji selagi masih di Jepang)<br>Kalau waktunya punya awal dan akhir yang jelas, seperti \"antara jam 3 sampai jam 5\", hanya bisa pakai <span class='gd-jp'>3時から5時の間に</span>, tidak bisa うちに.</div><div class='gd-sec'><b>前に</b> dan <b>ないうちに</b> juga mirip:<br><span class='gd-jp'>雨が降る前に帰ろう。</span>(Ayo pulang sebelum hujan: hanya soal urutan)<br><span class='gd-jp'>雨が降らないうちに帰ろう。</span>(Ayo pulang selagi belum hujan: terasa lebih terburu-buru)</div><div class='gd-warn'>Trik cepat: kalau maksudmu \"mumpung masih sempat, ayo cepat\", pakai うちに; kalau hanya menyebut \"selama rentang waktu itu\", pakai 間に; kalau hanya soal urutan, pakai 前に.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Lanjutkan ke 「〜間に」 dan 「〜最中に」 (sedang ~). Bandingkan ketiganya sekaligus, dan ungkapan tentang \"waktu\" tidak akan membingungkanmu lagi.</div>","n3-20":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>「〜ば〜ほど」 sama dengan <b>「semakin ~ semakin ~」</b> dalam bahasa Indonesia. Seperti \"semakin dilatih semakin kuat\" atau \"semakin dipikir semakin pusing\": makin banyak atau makin tinggi tingkat hal pertama, makin jelas pula hasil di belakangnya.<br>Cara Jepangnya: <b>sebut kata yang sama dua kali</b>. Pertama pakai bentuk ば (bentuk \"kalau ~\"), kedua pakai bentuk aslinya, lalu tambahkan ほど.</div><div class='gd-ex-line'>・<span class='gd-jp'>練習すればするほど上手になる。</span>(Semakin berlatih, semakin mahir)</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><span class='gd-tag'>Kata kerja</span>Ubah dulu ke bentuk ば, lalu sambung dengan bentuk kamus (bentuk dasar) kata kerja yang sama, lalu tambahkan ほど.<br><b>Golongan 1 (五段動詞)</b>: bunyi terakhir diganti bunyi baris 「え」 dari baris yang sama, lalu tambahkan ば.<br><span class='gd-pair'><span class='gd-jp'>読む</span> → む jadi め → <span class='gd-jp'>読めば読むほど</span></span><br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行けば行くほど</span></span><br><b>Golongan 2 (一段動詞)</b>: buang 「る」, lalu tambahkan れば.<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べれば食べるほど</span></span><br><b>Golongan 3</b>: <span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>すればするほど</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来れば来るほど</span>(くればくるほど)</span><br>Untuk kata kerja \"kata benda + する\" seperti 「<span class='gd-jp'>勉強する</span>」, yang kedua biasanya cukup する saja: <span class='gd-jp'>勉強すればするほど</span>.</div><div class='gd-sec'><span class='gd-tag'>Kata sifat い</span>Buang 「い」, tambahkan ければ, lalu sambung dengan kata sifat い aslinya + ほど.<br><span class='gd-pair'><span class='gd-jp'>安い</span> → <span class='gd-jp'>安ければ安いほど</span></span></div><div class='gd-sec'><span class='gd-tag'>Kata sifat な</span>Bagian pertama pakai なら, bagian kedua tambahkan な + ほど.<br><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かなら静かなほど</span></span></div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-ex-line'>・<span class='gd-jp'>日本語は勉強すればするほど面白くなる。</span>(Bahasa Jepang semakin dipelajari semakin menarik)</div><div class='gd-ex-line'>・<span class='gd-jp'>この本は読めば読むほど好きになる。</span>(Buku ini semakin dibaca semakin kusuka)</div><div class='gd-ex-line'>・<span class='gd-jp'>返事は早ければ早いほどいいです。</span>(Semakin cepat balasannya, semakin baik)</div><div class='gd-ex-line'>・<span class='gd-jp'>部屋は静かなら静かなほどいい。</span>(Semakin tenang kamarnya, semakin baik)</div><div class='gd-sec'>「<span class='gd-jp'>早ければ早いほどいい</span>」「<span class='gd-jp'>多ければ多いほどいい</span>」hampir jadi ungkapan baku. Hafalkan satu kalimat utuhnya, pasti berguna.</div><div class='gd-h'>Hati-hati, ini sering salah</div><div class='gd-warn'>・Bagian depan dan belakang harus <b>kata yang sama</b>. Dalam bahasa Indonesia kita bilang \"semakin A semakin B\", sedangkan bahasa Jepang menyebut A dua kali, dan B diletakkan di kalimat berikutnya.<br>・Bagian kedua pakai bentuk dasar, jangan pakai ば lagi: yang benar <span class='gd-jp'>考えれば考えるほど</span>, bukan 考えれば考えればほど.<br>・Bentuk ば dari <span class='gd-jp'>いい</span> adalah <span class='gd-jp'>よければ</span>, bukan いければ: <span class='gd-jp'>よければよいほど</span>.<br>・<span class='gd-jp'>来れば</span> dibaca くれば, bukan きれば.<br>・Kata sifat な: bagian depan なら, bagian belakang な, jadi tidak sama. Jangan tulis <span class='gd-jp'>静かなら静かならほど</span>.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'><b>〜ば〜ほど</b>: <span class='gd-jp'>練習すればするほど上手になる。</span>(Semakin berlatih, semakin mahir)<br><b>〜ほど</b> (tanpa ば di depan): <span class='gd-jp'>練習するほど上手になる。</span>(Artinya sama)<br>Versi tanpa ば lebih ringkas; versi dengan ば membuat nuansa \"semakin ~ semakin ~\" lebih jelas dan lebih kuat.<br><b>〜とともに</b>: <span class='gd-jp'>年をとるとともに、体力が落ちる。</span>(Seiring bertambahnya usia, stamina menurun)<br>Bandingkan: <span class='gd-jp'>年をとればとるほど、体力が落ちる。</span>(Semakin tua, semakin lemah staminanya)<br>とともに berarti \"seiring ~\", lebih formal dan lebih sering dipakai dalam tulisan; ば〜ほど berarti \"semakin ~ semakin ~\", umum dipakai baik dalam percakapan maupun tulisan.</div><div class='gd-warn'>Trik cepat: kalau maksudmu \"semakin ~ semakin ~\", pakai ば〜ほど; pakai とともに hanya kalau ingin bilang \"seiring ~\" dengan nuansa lebih formal.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>「〜ほど」 yang berdiri sendiri juga punya arti \"sampai tingkat ~\", misalnya <span class='gd-jp'>泣きたいほど痛い</span> (sakitnya sampai ingin menangis). Lanjutkan ke kartu 「〜ほど」.</div>","n3-21":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「<span class='gd-jp'>〜ないことはない</span>」kira-kira sama dengan <b>「bukannya tidak ～, sih」</b>. Dua kali \"tidak\" ditumpuk, jadi artinya sebenarnya \"bisa\". Tapi ini <b>\"bisa\" yang sudah didiskon</b>: dengan agak terpaksa masih sanggup, kemungkinannya ada, hanya saja kurang berminat dan kurang semangat. Bayangkan temanmu mengajak mendaki gunung jam empat pagi, lalu kamu jawab, \"Bukannya nggak bisa ikut, sih…\". Semua orang langsung paham kamu sebenarnya malas.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Ubah kata kerja ke bentuk ない dulu, lalu tambahkan <span class='gd-jp'>ことはない</span> atau <span class='gd-jp'>こともない</span>.<br><span class='gd-pair'><span class='gd-jp'>行ける</span> → <span class='gd-jp'>行けない</span> → <span class='gd-jp'>行けないことはない</span></span> (bukannya tidak bisa pergi)<br><span class='gd-pair'><span class='gd-jp'>食べられる</span> → <span class='gd-jp'>食べられない</span> → <span class='gd-jp'>食べられないこともない</span></span> (bukannya tidak bisa makan)<br>Pola ini paling sering dipakai bersama ungkapan \"bisa atau tidak bisa\", seperti <span class='gd-jp'>行ける</span>, <span class='gd-jp'>できる</span>, dan <span class='gd-jp'>食べられる</span>, karena pola ini memang sering dipakai untuk membahas \"sanggup atau tidak\".</div><div class='gd-sec'>Kalau kamu belum lancar dengan bentuk ない, yuk ulang sebentar:<br><b>Kelompok 1 (kata kerja godan)</b>: ubah bunyi terakhir ke bunyi baris 「あ」 di baris yang sama, lalu tambahkan ない. <span class='gd-pair'><span class='gd-jp'>行く</span> → く diganti か → <span class='gd-jp'>行かない</span></span>; yang berakhiran う diganti わ: <span class='gd-pair'><span class='gd-jp'>会う</span> → <span class='gd-jp'>会わない</span></span><br><b>Kelompok 2 (kata kerja ichidan)</b>: buang 「る」, lalu tambahkan ない. <span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べない</span></span><br><b>Kelompok 3 (する・来る)</b>: <span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>しない</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ない</span>（こない）</span></div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Sanggup, tapi terpaksa</span>Agak berat, tapi kalau dipaksa masih bisa.</div><div class='gd-ex-line'>・<span class='gd-jp'>この量なら、一人で食べられないことはない。</span>(Kalau porsinya segini, bukannya tidak bisa habis kumakan sendiri)</div><div class='gd-sec'><span class='gd-tag'>Diikuti catatan \"tapi\"</span>Bentuk yang paling umum: ditambah 「<span class='gd-jp'>けど</span>／<span class='gd-jp'>が</span>」, lalu kamu sebutkan kekhawatiran yang sebenarnya.</div><div class='gd-ex-line'>・<span class='gd-jp'>駅まで歩けないことはないけど、ちょっと遠いね。</span>(Bukannya tidak bisa jalan kaki sampai stasiun, tapi agak jauh ya)</div><div class='gd-ex-line'>・<span class='gd-jp'>行けないこともないが、あまり気が進まない。</span>(Bukannya tidak bisa pergi, tapi kurang berminat)</div><div class='gd-sec'><span class='gd-tag'>Jawaban yang menggantung</span>Dipakai saat ditanya dan kamu tidak mau langsung mengiyakan, tapi juga tidak mau menolak mentah-mentah.</div><div class='gd-ex-line'>・<span class='gd-jp'>明日までにできる？</span>(Bisa selesai sebelum besok?)</div><div class='gd-ex-line'>・<span class='gd-jp'>できないことはないですけど…。</span>(Bukannya tidak bisa selesai, sih…)</div><div class='gd-sec'><b>Apa bedanya ことはない dan こともない?</b> Artinya hampir sama dan bisa saling menggantikan. <span class='gd-jp'>こともない</span> punya tambahan 「も」, jadi nadanya lebih lembut dan samar, seperti bilang \"sebenarnya… ya bisa lah\".</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Kalimat ini artinya <b>positif</b>. <span class='gd-jp'>行けないことはない</span> = bisa pergi (hanya saja kurang rela). Jangan karena melihat dua \"tidak\" lalu mengira artinya \"tidak bisa pergi\".<br>・Ini <b>bukan \"bisa\" yang antusias</b>. Kalau temanmu mengajak lalu kamu menjawab <span class='gd-jp'>行けないことはない</span>, dia akan merasa kamu kurang mau datang. Kalau memang ingin pergi, bilang <span class='gd-jp'>行けるよ</span> atau <span class='gd-jp'>いいね、行こう</span>. Kalau dipakai ke atasan atau klien, kamu juga gampang dianggap kurang kooperatif.<br>・Bagian depannya harus <b>bentuk ない</b>. Tanpa ない, <span class='gd-jp'>行くことはない</span> jadi \"tidak perlu pergi\", artinya sama sekali berbeda.</div><div class='gd-h'>Bedakan dari pola yang mirip</div><div class='gd-sec'>Dengan contoh \"karaoke\" yang sama, cukup beda yang ada di depan, artinya sudah berubah total:<br><b>Bentuk ない＋ことはない</b> = bukannya tidak ～: <span class='gd-jp'>カラオケは行かないことはないけど、年に一回くらいかな。</span> (Bukannya tidak pernah pergi karaoke, tapi paling setahun sekali)<br><b>Bentuk kamus＋ことはない</b> = tidak perlu ～: <span class='gd-jp'>嫌なら、無理して行くことはないよ。</span> (Kalau tidak suka, tidak perlu memaksakan diri pergi)<br><b>Bentuk た＋ことはない</b> = belum pernah ～: <span class='gd-jp'>カラオケには一度も行ったことはない。</span> (Aku belum pernah sekali pun pergi ke karaoke)<br><b>ないわけではない</b> = bukan berarti ～: <span class='gd-jp'>カラオケが好きじゃないわけではない。</span> (Bukan berarti aku tidak suka karaoke)<br>Yang terakhir ini dekat sekali dengan ないことはない. Bedanya, inti <span class='gd-jp'>わけではない</span> adalah meluruskan kesalahpahaman lawan bicara: \"Bukan seperti yang kamu kira\". Sedangkan inti <span class='gd-jp'>ないことはない</span> adalah \"mungkin saja, dengan terpaksa bisa\".</div><div class='gd-warn'>Trik cepat: ada 「ない」 di depan ＋ <span class='gd-jp'>ことはない</span> = \"bukannya tidak ～\"; bentuk kamus ＋ <span class='gd-jp'>ことはない</span> = \"tidak perlu ～\"; bentuk た ＋ <span class='gd-jp'>ことはない</span> = \"belum pernah ～\", itu arti yang lain lagi. Kalau mau meluruskan kesalahpahaman orang, pakai <span class='gd-jp'>わけではない</span>.</div>","n3-29":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜わりに」kira-kira artinya <b>「untuk ukuran ～, ternyata cukup …」「seharusnya ～, tapi ternyata …」</b>. Dari hal yang disebut di depan, kamu membayangkan \"seharusnya begini\", tapi kenyataannya tidak sesuai bayangan. Di situlah kamu pakai わりに. Misalnya kamu bilang ke teman, \"Untuk harga segini, porsi warung ini banyak ya\". Itulah rasa わりに.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Kejutan yang menyenangkan</span>Hasilnya lebih baik dari bayangan.</div><div class='gd-ex-line'>・<span class='gd-jp'>この店は、値段のわりに量が多い。</span>(Untuk ukuran harganya, porsi di tempat ini banyak)</div><div class='gd-ex-line'>・<span class='gd-jp'>彼はよく食べるわりに、太らない。</span>(Dia makannya banyak, tapi tidak gemuk-gemuk)</div><div class='gd-sec'><span class='gd-tag'>Kejutan yang kurang menyenangkan</span>Hasilnya lebih buruk dari bayangan, dengan nada sedikit kecewa.</div><div class='gd-ex-line'>・<span class='gd-jp'>よく勉強したわりに、点数が悪かった。</span>(Untuk ukuran seberapa banyak dia belajar, nilainya jelek)</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は体が大きいわりには、気が小さい。</span>(Badannya sebesar itu, tapi nyalinya kecil)</div><div class='gd-sec'>Kalau mau menekankan, kamu bisa pakai <b>わりには</b>. Artinya sama.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Kata kerja</b>: sambung langsung; untuk hal yang sudah terjadi, pakai bentuk た.<br><span class='gd-pair'><span class='gd-jp'>よく食べる</span> → <span class='gd-jp'>よく食べるわりに</span></span><br><span class='gd-pair'><span class='gd-jp'>勉強した</span> → <span class='gd-jp'>勉強したわりに</span></span><br><b>Kata sifat-い</b>: sambung langsung.<br><span class='gd-pair'><span class='gd-jp'>近い</span> → <span class='gd-jp'>近いわりに</span></span><br><b>Kata sifat-な</b>: ganti だ dengan な.<br><span class='gd-pair'><span class='gd-jp'>丈夫だ</span> → <span class='gd-jp'>丈夫なわりに</span></span><br><b>Kata benda</b>: tambahkan の.<br><span class='gd-pair'><span class='gd-jp'>年齢</span> → <span class='gd-jp'>年齢のわりに</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>この部屋は駅から近いわりに、家賃が安い。</span>(Kamar ini dekat dari stasiun, tapi sewanya murah)</div><div class='gd-ex-line'>・<span class='gd-jp'>このかばんは丈夫なわりに軽い。</span>(Tas ini awet, tapi ringan)</div><div class='gd-ex-line'>・<span class='gd-jp'>父は年齢のわりに元気だ。</span>(Untuk ukuran usianya, ayahku masih sangat bersemangat)</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Kata sifat-な pakai 「な」, kata benda pakai 「の」: yang benar <span class='gd-jp'>丈夫なわりに</span> dan <span class='gd-jp'>年齢のわりに</span>, bukan 丈夫だわりに atau 年齢わりに.<br>・Harus ada unsur \"tidak sesuai harapan\" baru boleh dipakai. Barang mahal enak itu hal yang wajar, jadi <span class='gd-jp'>値段が高いわりにおいしい</span> terdengar aneh. Yang benar <span class='gd-jp'>値段が高いわりにおいしくない</span> (semahal itu tapi tidak enak).<br>・Sebaiknya bagian depan berupa sesuatu yang punya ukuran tinggi-rendah atau banyak-sedikit untuk dibandingkan: usia, harga, tinggi badan, banyaknya belajar.<br>・Bagian belakang berupa deskripsi atau penilaian. Tidak bisa diikuti permintaan atau ajakan seperti 「～してください」 (tolong ～) atau 「～しましょう」 (ayo ～).<br>・<span class='gd-jp'>わりに</span> yang berdiri sendiri di depan kata sifat (sering juga <span class='gd-jp'>わりと</span>) adalah pemakaian lain, artinya \"lebih ～ dari yang dibayangkan\": <span class='gd-jp'>今日のテストはわりに簡単だった。</span> (Ujian hari ini lebih mudah dari yang kukira)</div><div class='gd-h'>Bedakan dari pola yang mirip</div><div class='gd-sec'><b>にしては</b> juga berarti \"untuk ukuran ～, di luar dugaan\". Kalau diterjemahkan ke bahasa Indonesia hampir sama, bedanya ada pada apa yang ditaruh di depan.<br><b>わりに</b>: bagian depan boleh berupa tingkat yang umum seperti \"usia, harga\", dan bisa disambung dengan kata sifat maupun kata kerja.<br><b>にしては</b>: bagian depan berupa angka, status, atau fakta yang konkret, seperti 「60歳」「1000円」「初めて」. Terutama disambung dengan kata benda dan kata kerja, dan jarang dengan kata sifat.</div><div class='gd-ex-line'>・<span class='gd-jp'>父は年齢のわりに若く見える。</span>(Untuk ukuran usianya, ayahku kelihatan muda)</div><div class='gd-ex-line'>・<span class='gd-jp'>父は60歳にしては若く見える。</span>(Untuk orang berusia 60 tahun, ayahku kelihatan muda)</div><div class='gd-ex-line'>・<span class='gd-jp'>この料理は値段のわりにおいしい。</span>(Untuk ukuran harganya, masakan ini enak)</div><div class='gd-ex-line'>・<span class='gd-jp'>この料理は1000円にしてはおいしい。</span>(Untuk harga 1000 yen, masakan ini enak)</div><div class='gd-sec'>Sebaliknya, 「年齢にしては」「値段にしては」 terdengar tidak natural, karena \"usia\" dan \"harga\" di sini bukan angka yang konkret.</div><div class='gd-warn'>Trik cepat: kalau di depan ada tingkat yang umum seperti \"usia, harga\", atau berupa kata sifat, pakai わりに. Kalau di depan ada angka atau status yang konkret seperti \"60 tahun, 1000 yen, pertama kali\", pakai にしては.</div>","n3-30":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜にしては」 artinya <b>“untuk ukuran ～, ternyata cukup …” / “padahal ～, kok …”</b>. Kamu punya harapan tentang suatu status atau fakta, tapi kenyataannya <b>berbeda dari harapan itu</b>. Nah, di situlah kamu pakai pola ini.<br>Misalnya kamu lihat tulisan anak kecil yang bagus sekali, lalu bilang “Untuk ukuran anak kecil, tulisannya bagus ya”. Itu jadi <span class='gd-jp'>子どもにしては、字がきれいだ。</span></div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Lebih baik dari harapan</span>Awalnya tidak berharap banyak, tapi hasilnya bagus. Ada nuansa memuji sedikit.</div><div class='gd-ex-line'>・<span class='gd-jp'>初めて作ったにしては、おいしいね。</span>（Untuk ukuran pertama kali bikin, enak ya）</div><div class='gd-ex-line'>・<span class='gd-jp'>新人にしては、よくやっている。</span>（Untuk ukuran orang baru, kerjanya sudah bagus）</div><div class='gd-sec'><span class='gd-tag'>Lebih buruk dari harapan</span>Awalnya berharap tinggi, tapi hasilnya mengecewakan. Ada nuansa menyindir sedikit.</div><div class='gd-ex-line'>・<span class='gd-jp'>有名な店にしては、あまりおいしくなかった。</span>（Untuk ukuran restoran terkenal, rasanya biasa saja）</div><div class='gd-sec'><span class='gd-tag'>Cuaca, waktu</span>Keadaannya tidak seperti yang biasanya pada musim atau waktu itu.</div><div class='gd-ex-line'>・<span class='gd-jp'>4月にしては寒いですね。</span>（Untuk ukuran bulan April, dingin banget ya）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Nomina</b>: langsung disambung, <b>tanpa の dan tanpa だ</b>.<br><span class='gd-pair'><span class='gd-jp'>プロ</span> → <span class='gd-jp'>プロにしては</span></span><span class='gd-pair'><span class='gd-jp'>4月</span> → <span class='gd-jp'>4月にしては</span></span></div><div class='gd-sec'><b>Verba</b>: pakai bentuk biasa (bentuk kamus, bentuk た, dan sejenisnya, yang tidak pakai ます).<br><span class='gd-pair'><span class='gd-jp'>初めて作った</span> → <span class='gd-jp'>初めて作ったにしては</span></span><span class='gd-pair'><span class='gd-jp'>3年も住んでいる</span> → <span class='gd-jp'>3年も住んでいるにしては</span></span></div><div class='gd-h'>Bagian yang gampang keliru</div><div class='gd-warn'>・Setelah nomina, langsung sambung にしては, <b>jangan tambah の</b>: bilang <span class='gd-jp'>子どもにしては</span>, bukan 子どものにしては. (Yang pakai の itu <span class='gd-jp'>子どものわりに</span>, jangan sampai tertukar.)<br>・Yang ada di depan harus <b>status, angka, atau fakta yang konkret</b>, seperti 「新人」「60歳」「千円」「初めて」. Kata yang hanya menyebut sebuah rentang, seperti “umur”, “harga”, “tinggi badan”, tidak bisa langsung disambung: <span class='gd-jp'>値段にしては</span> terdengar tidak natural, harus diganti jadi <span class='gd-jp'>値段のわりに</span>.<br>・Kata sifat-い biasanya tidak langsung disambung dengan にしては. 「安いにしては」 terdengar aneh, jadi pakai <span class='gd-jp'>安いわりに</span>.<br>・Kalimat bagian belakang berisi <b>penilaian atau kesanmu</b>. Jangan diikuti perintah atau keputusan seperti “tolong ～” atau “aku akan ～”.<br>・Bisa juga dipakai untuk membicarakan diri sendiri: <span class='gd-jp'>私にしては、よく頑張ったと思う。</span>（Untuk ukuran diriku, kurasa aku sudah berusaha keras）</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>わりに</b> (n3-29) juga berarti “tidak sesuai harapan”, dan dalam bahasa Indonesia sering sama-sama diterjemahkan “untuk ukuran ～”. Bedanya ada pada <b>apa yang diletakkan di depannya</b>.<br>Situasi yang sama, seorang bapak yang kelihatan awet muda:<br><span class='gd-jp'>あの人は60歳にしては若く見える。</span>（Untuk ukuran 60 tahun, dia kelihatan muda）→ di depannya ada angka konkret “60歳”<br><span class='gd-jp'>あの人は年のわりに若く見える。</span>（Dia kelihatan lebih muda dari umur aslinya）→ di depannya ada kata rentang seperti “umur”<br>Sama-sama warung yang murah dan enak:<br><span class='gd-jp'>千円にしてはおいしい。</span>（Untuk harga seribu yen, enak）<br><span class='gd-jp'>値段のわりにおいしい。</span>／<span class='gd-jp'>安いわりにおいしい。</span>（Untuk harga segitu, enak／murah tapi enak）<br>Selain itu, にしては lebih terasa seperti kaget di saat itu juga, “padahal ～ lho”, dan penilaiannya juga lebih jelas.</div><div class='gd-sec'><b>として</b> (n3-5) juga sering diterjemahkan “sebagai ～”, tetapi artinya <b>berdiri di posisi status itu</b>, tanpa makna “berbeda dari harapan”.<br><span class='gd-jp'>先生として、生徒を守りたい。</span>（Sebagai guru, aku ingin melindungi murid）<br><span class='gd-jp'>先生にしては、字が汚いね。</span>（Untuk ukuran guru, tulisannya jelek juga ya）</div><div class='gd-warn'>Tips menentukan: kalau di depan ada status, angka, atau fakta yang konkret dan hasilnya mengejutkanmu, pakai にしては. Kalau di depan ada kata rentang seperti “umur” atau “harga”, atau kata sifat, pakai わりに. Kalau hanya bilang “sebagai ～” tanpa ada kejutan, pakai として.</div>","n3-5":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜として」 artinya <b>“sebagai ～” “dengan status ～” “dijadikan ～”</b>. Di depannya ada sebuah nomina yang menjelaskan “dengan status, peran, atau tujuan apa” hal itu dilakukan.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Status・posisi</span>Melakukan sesuatu dengan status tertentu. Ini yang paling sering.</div><div class='gd-ex-line'>・<span class='gd-jp'>留学生として日本に来ました。</span>（Aku datang ke Jepang sebagai pelajar internasional）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は医者として、また父として尊敬されている。</span>（Dia dihormati, baik sebagai dokter maupun sebagai ayah）</div><div class='gd-sec'><span class='gd-tag'>Dijadikan・tujuan</span>Menjadikan sesuatu untuk kegunaan tertentu.</div><div class='gd-ex-line'>・<span class='gd-jp'>これはお土産として買いました。</span>（Ini kubeli untuk oleh-oleh）</div><div class='gd-sec'><span class='gd-tag'>Sebagai kategori apa</span>Menyebut sesuatu terkenal atau dipandang “sebagai ～”.</div><div class='gd-ex-line'>・<span class='gd-jp'>京都は観光地として有名です。</span>（Kyoto terkenal sebagai tempat wisata）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Sederhana, <b>nomina langsung ditambah として</b>:<br><span class='gd-pair'><span class='gd-jp'>先生</span> → <span class='gd-jp'>先生として</span></span><span class='gd-pair'><span class='gd-jp'>趣味</span> → <span class='gd-jp'>趣味として</span></span></div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>としての＋nomina</span>Kalau di belakangnya ada nomina, tambahkan 「の」 di tengah.</div><div class='gd-ex-line'>・<span class='gd-jp'>親としての責任がある。</span>（Ada tanggung jawab sebagai orang tua）</div><div class='gd-sec'><span class='gd-tag'>私としては</span>“Dari sudut pandangku”, dipakai untuk menyampaikan pendapat dengan sopan. Sering terdengar di rapat dan di tempat kerja.</div><div class='gd-ex-line'>・<span class='gd-jp'>私としては、この案に賛成です。</span>（Dari sudut pandangku pribadi, aku setuju dengan usul ini）</div><div class='gd-h'>Bagian yang gampang keliru</div><div class='gd-warn'>・Kalau di belakangnya ada nomina, pakai <b>としての</b>: bilang <span class='gd-jp'>医者としての仕事</span>, jangan 「医者として仕事」 untuk maksud “pekerjaan sebagai dokter”.<br>・“Bagi” dalam kalimat “Bagi pelajar, belajar itu penting” bukan として. Yang benar <span class='gd-jp'>学生にとって、勉強は大切だ。</span> Kalau ditulis 「学生として、勉強は大切だ」, kedengarannya sangat aneh.<br>・Pada dasarnya, di depan として diletakkan nomina. Jangan langsung disambung dengan verba atau kata sifat.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>として</b> = nomina di depannya adalah <b>status atau peran si subjek sendiri</b>:<br><span class='gd-jp'>父として、子どもを守りたい。</span>（Sebagai ayah, aku ingin melindungi anakku: si pembicara “adalah” seorang ayah）<br><b>にとって</b> = nomina di depannya adalah <b>sudut pandang orang yang merasakan atau menilai</b>:<br><span class='gd-jp'>父にとって、子どもは一番大切だ。</span>（Bagi seorang ayah, anak adalah yang terpenting: dilihat dari sudut pandang sang ayah）<br>Satu pasang lagi: <span class='gd-jp'>京都は観光地として有名だ。</span>（Kyoto “adalah” tempat wisata, dan terkenal dengan status itu）／<span class='gd-jp'>私にとって、京都は特別な場所だ。</span>（Bagiku, Kyoto adalah tempat yang istimewa）</div><div class='gd-warn'>Tips menentukan: kalau nomina di depan adalah status, peran, atau kategori si subjek sendiri (dia “adalah” dokter, Kyoto “adalah” tempat wisata), pakai として. Kalau nomina itu menunjukkan “dari sudut pandang siapa seseorang merasakan atau menilai” (bagi orang tua, bagiku), pakai にとって.</div><div class='gd-h'>Setelah ini bisa lanjut belajar</div><div class='gd-sec'>Kamu bisa sekalian mengulang <span class='gd-jp'>〜にとって</span> yang ada di pelajaran yang sama. Selain itu, pada <span class='gd-jp'>〜をはじめ（として）</span> (dimulai dari ～, termasuk ～) juga ada bentuk として.</div>","n3-33":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜っぽい」mirip ungkapan Indonesia <b>\"agak ke-～-an\"</b>, <b>\"kayak ～\"</b>, atau <b>\"kesannya ～\"</b>. Contohnya untuk orang yang \"kekanak-kanakan\" atau baju yang \"kelihatan murahan\". Kalau dipasang setelah verba tertentu, artinya jadi <b>\"gampang ～ / sering ～\"</b>, misalnya \"pelupa\" atau \"gampang marah\". Ini ungkapan yang sangat kasual dan sering banget terdengar waktu ngobrol.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Kelihatan seperti ～</span>Nomina＋っぽい: sebenarnya bukan begitu, tapi kesannya begitu.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼はもう30歳なのに、子供っぽい。</span>（Dia sudah 30 tahun, tapi masih kekanak-kanakan）</div><div class='gd-ex-line'>・<span class='gd-jp'>今日はちょっと風邪っぽい。</span>（Hari ini kayaknya agak masuk angin）</div><div class='gd-sec'><span class='gd-tag'>Agak berwarna ～ / bernuansa ～</span>Adjektiva い＋っぽい: sering dipakai untuk warna atau tekstur.</div><div class='gd-ex-line'>・<span class='gd-jp'>白っぽいシャツを買った。</span>（Aku beli kemeja yang warnanya agak putih）</div><div class='gd-sec'><span class='gd-tag'>Gampang ～ / sering ～</span>Verba＋っぽい: untuk menggambarkan sifat seseorang.</div><div class='gd-ex-line'>・<span class='gd-jp'>父は年を取って、怒りっぽくなった。</span>（Ayah sudah tua, jadi gampang marah）</div><div class='gd-ex-line'>・<span class='gd-jp'>私は飽きっぽいから、何をしても続かない。</span>（Aku gampang bosan, jadi apa pun yang kulakukan tidak bertahan lama）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Nomina</b>: langsung tambahkan っぽい.<br><span class='gd-pair'><span class='gd-jp'>子供</span> → <span class='gd-jp'>子供っぽい</span></span><br><span class='gd-pair'><span class='gd-jp'>風邪</span> → <span class='gd-jp'>風邪っぽい</span>（kayaknya agak masuk angin）</span></div><div class='gd-sec'><b>Adjektiva い</b>: buang い di akhir, lalu tambahkan っぽい.<br><span class='gd-pair'><span class='gd-jp'>安い</span> → buang い → <span class='gd-jp'>安っぽい</span></span><br><span class='gd-pair'><span class='gd-jp'>白い</span> → <span class='gd-jp'>白っぽい</span></span></div><div class='gd-sec'><b>Verba</b>: ubah dulu ke bentuk ます, buang ます, lalu tambahkan っぽい.<br><span class='gd-pair'><span class='gd-jp'>忘れます</span> → buang ます → <span class='gd-jp'>忘れっぽい</span></span><br><span class='gd-pair'><span class='gd-jp'>怒ります</span> → <span class='gd-jp'>怒りっぽい</span></span></div><div class='gd-sec'>Setelah disambung, 「〜っぽい」 secara keseluruhan menjadi satu adjektiva い, dan berubah bentuk seperti <span class='gd-jp'>高い</span>:<br><span class='gd-pair'><span class='gd-jp'>忘れっぽい</span> → <span class='gd-jp'>忘れっぽくなった</span>（jadi pelupa）</span><br><span class='gd-pair'><span class='gd-jp'>子供っぽい</span> → <span class='gd-jp'>子供っぽくない</span>（tidak kekanak-kanakan）</span></div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Verba tidak boleh asal disambung. Yang umum dipakai hanya beberapa: <span class='gd-jp'>忘れっぽい</span>、<span class='gd-jp'>怒りっぽい</span>、<span class='gd-jp'>飽きっぽい</span>. Jangan bikin sendiri kata seperti <span class='gd-jp'>食べっぽい</span>.<br>・<span class='gd-jp'>安っぽい</span> bukan \"murah\" dalam arti harga, tapi \"kelihatan murahan dan norak\", jadi bernuansa negatif: <span class='gd-jp'>このバッグは安っぽい。</span>（Tas ini kelihatan murahan）. Kalau mau bilang harganya murah, pakai <span class='gd-jp'>安い</span>.<br>・Biasanya terdengar agak nyinyir. Bilang orang dewasa <span class='gd-jp'>子供っぽい</span> bukan pujian. Sebaliknya, bilang anak kecil atau anak muda <span class='gd-jp'>大人っぽい</span> (kelihatan dewasa) biasanya malah pujian.<br>・Ini ungkapan lisan, jadi jarang dipakai di laporan atau tulisan formal.<br>・Anak muda juga suka menempelkan っぽい di belakang satu kalimat utuh, artinya \"kayaknya ～\": <span class='gd-jp'>あの店、もう閉まったっぽい。</span>（Toko itu kayaknya sudah tutup）. Gaya ini santai banget, boleh dipakai ke teman, tapi jangan ke orang yang lebih tua.</div><div class='gd-h'>Bedakan dari yang mirip-mirip</div><div class='gd-sec'><b>らしい</b>: <span class='gd-jp'>子供らしい</span> berarti <b>sifat yang memang pantas dimiliki</b> anak kecil, biasanya untuk memuji anak yang benar-benar masih kecil. <span class='gd-jp'>子供っぽい</span> berarti <b>jelas bukan anak kecil, tapi bertingkah seperti anak kecil</b>, biasanya untuk orang dewasa.<br>・<span class='gd-jp'>元気で子供らしい子だ。</span>（Anak yang ceria dan polos seperti anak-anak）<br>・<span class='gd-jp'>彼は考え方が子供っぽい。</span>（Cara berpikirnya kekanak-kanakan）</div><div class='gd-sec'><b>がち</b>: <span class='gd-jp'>忘れっぽい</span> bicara tentang <b>sifat orangnya</b>. <span class='gd-jp'>忘れがち</span> bicara tentang <b>hal yang sering terjadi</b>, dan di depannya bisa disebut jelas apa yang dilupakan.<br>・<span class='gd-jp'>彼は忘れっぽい。</span>（Dia pelupa）<br>・<span class='gd-jp'>私はメールの返事を忘れがちだ。</span>（Aku sering lupa membalas email）</div><div class='gd-sec'><b>気味</b>: <span class='gd-jp'>風邪っぽい</span> dan <span class='gd-jp'>風邪気味</span> sama-sama berarti \"agak masuk angin\". っぽい lebih santai, cukup untuk ngobrol dengan teman. Saat izin ke kantor atau menjelaskan ke dokter, <span class='gd-jp'>風邪気味</span> lebih aman.</div><div class='gd-warn'>Tips menentukan: pakai らしい untuk \"memang begitu, sesuai yang seharusnya\"; pakai っぽい untuk \"bukan, tapi mirip\" atau \"sifatnya gampang ～\"; pakai がち untuk \"hal yang sering terjadi\".</div><div class='gd-h'>Setelah paham, lanjut belajar ini</div><div class='gd-sec'>Ungkapan lain yang juga menyatakan kecenderungan adalah <span class='gd-jp'>〜がち</span> dan <span class='gd-jp'>〜気味</span>. Kalau ketiganya dipelajari bareng, lebih mudah dibedakan.</div>","n3-34":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜がち」 artinya <b>\"gampang ～\"</b>, <b>\"sering ～\"</b>, atau <b>\"cenderung ～\"</b>. Ini menggambarkan kecenderungan yang <b>sering terjadi dan biasanya kurang baik</b>, misalnya gampang masuk angin, sering telat, atau gampang lupa.</div><div class='gd-ex-line'>・<span class='gd-jp'>冬は風邪を引きがちだ。</span>（Kalau musim dingin, gampang masuk angin）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><span class='gd-tag'>Verba</span>Ubah dulu ke bentuk ます, buang ます, lalu tambahkan がち.<br><span class='gd-pair'><span class='gd-jp'>休みます</span> → <span class='gd-jp'>休みがち</span></span>（sering bolos / sering tidak masuk）<br><span class='gd-pair'><span class='gd-jp'>遅れます</span> → <span class='gd-jp'>遅れがち</span></span>（sering telat, sering terlambat）<br><span class='gd-pair'><span class='gd-jp'>します</span> → <span class='gd-jp'>しがち</span></span>（cenderung sering melakukan）</div><div class='gd-sec'><span class='gd-tag'>Nomina</span>Langsung disambung, tapi hanya beberapa yang umum, tidak semua nomina bisa.<br><span class='gd-jp'>病気がち</span>（sering sakit）、<span class='gd-jp'>留守がち</span>（sering tidak di rumah）、<span class='gd-jp'>曇りがち</span>（sering mendung）</div><div class='gd-h'>Bentuk yang paling sering terdengar</div><div class='gd-sec'><span class='gd-tag'>〜がちだ</span>Diletakkan di akhir kalimat untuk bilang bahwa seseorang atau sesuatu sering begitu.</div><div class='gd-ex-line'>・<span class='gd-jp'>忙しいと、食事を抜きがちだ。</span>（Kalau sibuk, sering melewatkan waktu makan）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は最近、学校を休みがちだ。</span>（Belakangan ini dia sering tidak masuk sekolah）</div><div class='gd-sec'><span class='gd-tag'>〜がちな＋nomina</span>Di belakangnya dipasang nomina, polanya sama seperti 「静かな部屋」.</div><div class='gd-ex-line'>・<span class='gd-jp'>これは初心者にありがちなミスです。</span>（Ini kesalahan yang sering dilakukan pemula）</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Tidak bisa disambung dengan bentuk kamus: yang benar <span class='gd-jp'>休みがち</span>, bukan 「休むがち」.<br>・Ada nuansa \"kurang baik\", jadi untuk hal positif biasanya tidak dipakai. Kalau mau bilang \"aku sering belajar\", cukup <span class='gd-jp'>よく勉強する</span>. Kalau dibilang 「勉強しがち」, kedengarannya aneh, seolah belajar itu kebiasaan buruk.<br>・Tidak bisa untuk hal yang cuma terjadi sekali. がち bicara tentang \"sering, gampang\", bukan \"kali ini\".<br>・Nomina tidak boleh asal disambung. Hafalkan saja dulu yang umum seperti <span class='gd-jp'>病気がち</span> dan <span class='gd-jp'>留守がち</span>.<br>・<span class='gd-jp'>ガチ</span> yang dipakai anak muda (artinya \"serius, banget\") adalah bahasa gaul, dan beda urusan dengan 「〜がち」 di sini.</div><div class='gd-h'>Bedakan dari yang mirip-mirip</div><div class='gd-sec'><b>がち</b> = kecenderungan yang <b>sering terjadi</b>: <span class='gd-jp'>子どものころは病気がちだった。</span>（Waktu kecil aku sering sakit）<br><b>気味</b> = <b>saat ini sedang agak</b> terasa begitu: <span class='gd-jp'>今日はちょっと風邪気味だ。</span>（Hari ini rasanya agak masuk angin）</div><div class='gd-sec'><b>がち</b> = suatu hal <b>gampang terjadi</b>: <span class='gd-jp'>人の名前は忘れがちだ。</span>（Nama orang itu gampang lupa）<br><b>っぽい</b> = orangnya <b>punya</b> sifat itu secara keseluruhan: <span class='gd-jp'>祖父は最近忘れっぽい。</span>（Kakek belakangan ini jadi pelupa）</div><div class='gd-warn'>Tips menentukan: pakai がち untuk \"sering ～\", 気味 untuk \"sekarang agak ～\", dan っぽい untuk \"orangnya berkesan ～\".</div><div class='gd-h'>Setelah paham, lanjut belajar ini</div><div class='gd-sec'>Selanjutnya lihat <span class='gd-jp'>〜気味</span> dan <span class='gd-jp'>〜っぽい</span>. Kalau ketiganya diingat bareng, kamu paling kecil kemungkinan tertukar.</div>","n3-47":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>「〜ものだ」artinya <b>「memang begitulah adanya」「memang seharusnya ～」</b>. Pola ini dipakai untuk kebenaran atau akal sehat yang disetujui semua orang, bukan pendapat pribadimu. Sebaliknya, 「〜ものではない」seperti yang sering diucapkan orang yang lebih tua: <b>「tidak boleh ～」「mana ada orang yang begitu」</b>, dengan nada agak menceramahi.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Memang begitu</span>Untuk sifat bawaan manusia atau benda, dan kebenaran umum di dunia ini. Sering terasa seperti desahan, \"ya begitulah\".</div><div class='gd-ex-line'>・<span class='gd-jp'>人は誰でも間違えるものだ。</span>（Manusia memang pasti pernah berbuat salah.）</div><div class='gd-ex-line'>・<span class='gd-jp'>時間が経つのは早いものだ。</span>（Waktu memang cepat sekali berlalu ya.）</div><div class='gd-sec'><span class='gd-tag'>Memang seharusnya</span>Untuk hal yang \"sudah seharusnya dilakukan\" menurut kepatutan umum.</div><div class='gd-ex-line'>・<span class='gd-jp'>お年寄りには親切にするものだ。</span>（Kepada orang tua, kita memang seharusnya bersikap ramah.）</div><div class='gd-ex-line'>・<span class='gd-jp'>人の話は最後まで聞くものだ。</span>（Kalau orang lain bicara, kita memang seharusnya mendengarkan sampai selesai.）</div><div class='gd-sec'><span class='gd-tag'>Tidak seharusnya</span>Pakai 「〜ものではない」untuk menasihati atau menegur orang.</div><div class='gd-ex-line'>・<span class='gd-jp'>食べ物を粗末にするものではない。</span>（Tidak boleh menyia-nyiakan makanan.）</div><div class='gd-sec'><span class='gd-tag'>Nostalgia masa lalu</span>Pakai 「bentuk た＋ものだ」untuk hal yang <b>dulu sering</b> kamu lakukan. Nuansanya \"dulu ya ～\" yang penuh kenangan, dan sering muncul bersama 「よく」.</div><div class='gd-ex-line'>・<span class='gd-jp'>子供の頃は、よくこの川で遊んだものだ。</span>（Waktu kecil dulu, aku sering sekali main di sungai ini.）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Kata kerja bentuk kamus：<span class='gd-pair'><span class='gd-jp'>間違える</span> → <span class='gd-jp'>間違えるものだ</span></span><br>Kata kerja bentuk ない：<span class='gd-pair'><span class='gd-jp'>変わらない</span> → <span class='gd-jp'>変わらないものだ</span></span><br>Kata sifat-い disambung langsung：<span class='gd-pair'><span class='gd-jp'>早い</span> → <span class='gd-jp'>早いものだ</span></span><br>Kata sifat-な harus ditambah な：<span class='gd-pair'><span class='gd-jp'>元気</span> → <span class='gd-jp'>元気なものだ</span></span><br>Nostalgia masa lalu pakai bentuk た：<span class='gd-pair'><span class='gd-jp'>遊んだ</span> → <span class='gd-jp'>遊んだものだ</span></span><br>\"Tidak seharusnya\" pakai bentuk kamus：<span class='gd-pair'><span class='gd-jp'>言う</span> → <span class='gd-jp'>言うものではない</span></span></div><div class='gd-sec'>Dalam percakapan, sering disingkat jadi <b>もんだ</b>、<b>もんじゃない</b>：<span class='gd-jp'>そんなこと言うもんじゃないよ。</span>（Nggak boleh ngomong begitu, lho.）</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・ものだ membicarakan <b>kebenaran yang diakui semua orang</b>, jadi tidak bisa dipakai untuk rencanamu sendiri pada suatu kesempatan. 「Besok aku mau ke sekolah」cukup bilang <span class='gd-jp'>明日学校へ行きます</span>, tanpa ものだ.<br>・「ないものだ」dan「ものではない」artinya beda: <span class='gd-jp'>人は簡単には変わらないものだ</span> berarti 「manusia memang tidak mudah berubah」(soal sifat dasar); <span class='gd-jp'>人の悪口を言うものではない</span> berarti 「tidak seharusnya menjelek-jelekkan orang lain」(menasihati).<br>・Pemakaian untuk nostalgia membicarakan hal yang <b>dulu sering dilakukan</b>. Hal yang hanya terjadi sekali tidak bisa pakai pola ini: kalau kemarin kamu makan ramen, cukup bilang <span class='gd-jp'>昨日ラーメンを食べた</span>, tanpa ものだ.<br>・ものではない itu nada menegur, jadi kalau diucapkan kepada atasan atau guru akan sangat tidak sopan. Biasanya dipakai orang yang lebih tua kepada yang lebih muda, atau orang tua kepada anak.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Sama-sama \"seharusnya\", tapi lihat sudut pandang siapa yang bicara:<br><b>ものだ</b>＝<b>akal sehat masyarakat</b>, memang seharusnya begitu. Ini bicara soal prinsip umum: <span class='gd-jp'>約束は守るものだ。</span>（Janji memang seharusnya ditepati.）<br><b>べきだ</b>＝<b>penilaian si pembicara sendiri</b> bahwa hal itu seharusnya dilakukan. Nadanya lebih langsung dan lebih kuat: <span class='gd-jp'>あなたはこの約束を守るべきだ。</span>（Kamu seharusnya menepati janji ini.）<br><b>ことだ</b>＝<b>memberi saran</b> kepada orang di depanmu, \"sebaiknya ～\": <span class='gd-jp'>約束を守りたいなら、メモしておくことだ。</span>（Kalau mau menepati janji, sebaiknya dicatat dulu.）</div><div class='gd-warn'>Trik cepat: kalau bicara \"manusia memang seharusnya begini\", pakai ものだ. Kalau \"menurutku kamu seharusnya\", pakai べきだ. Kalau memberi saran \"sebaiknya kamu ～\", pakai ことだ. Satu lagi, <span class='gd-jp'>ものだから</span> menyatakan alasan (\"soalnya ～ sih\"), jadi bukan ものだ yang sama dengan di sini.</div><div class='gd-h'>Setelah paham, lanjut belajar ini</div><div class='gd-sec'>Pola lain untuk membicarakan kepatutan dan menasihati orang adalah 「〜べきだ・〜べきではない」dan 「〜ことだ」. Lanjutkan ke sana, lalu bandingkan ketiganya sekaligus supaya lebih jelas kapan memakai yang mana.</div>","n3-1":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>「〜において」artinya <b>「bertempat di ～」「pada ～」</b>. Dalam bahasa Indonesia sehari-hari kita bilang \"rapat di Taipei\", tapi dalam surat resmi jadi \"rapat diselenggarakan <b>bertempat di</b> Taipei\". Bahasa Jepang juga begitu: sehari-hari bilang 「<span class='gd-jp'>台北で</span>」, sedangkan di tulisan resmi, berita, dan pidato diganti jadi 「<span class='gd-jp'>台北において</span>」. Artinya sama-sama \"di ～\", hanya saja <b>jauh lebih formal</b>.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Di mana</span>Tempat acara atau upacara diadakan. Paling sering muncul di berita.</div><div class='gd-ex-line'>・<span class='gd-jp'>開会式は台北において行われた。</span>（Upacara pembukaan diadakan di Taipei.）</div><div class='gd-sec'><span class='gd-tag'>Dalam situasi apa</span>\"Situasi\" seperti rapat, wawancara, atau pertandingan.</div><div class='gd-ex-line'>・<span class='gd-jp'>面接において、一番大切なのは第一印象だ。</span>（Dalam wawancara, yang paling penting adalah kesan pertama.）</div><div class='gd-sec'><span class='gd-tag'>Di bidang apa</span>Suatu bidang atau aspek tertentu.</div><div class='gd-ex-line'>・<span class='gd-jp'>医療の分野において、AIの活用が進んでいる。</span>（Di bidang kedokteran, pemanfaatan AI semakin berkembang.）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Di depannya selalu <b>kata benda</b>. Yang penting adalah <b>apa yang datang setelahnya</b>:<br><b>Diikuti kata kerja atau kalimat</b> → pakai <b>において</b><br><span class='gd-pair'><span class='gd-jp'>京都で開催された</span> → <span class='gd-jp'>京都において開催された</span></span>（diselenggarakan di Kyoto）<br><b>Langsung diikuti kata benda</b> → pakai <b>における</b>. Fungsinya seperti 「<span class='gd-jp'>での</span>」, yaitu \"yang ada di ～\".<br><span class='gd-pair'><span class='gd-jp'>日本での問題</span> → <span class='gd-jp'>日本における問題</span></span>（masalah di Jepang）</div><div class='gd-ex-line'>・<span class='gd-jp'>日本における外国人労働者の数は年々増えている。</span>（Jumlah pekerja asing di Jepang bertambah dari tahun ke tahun.）</div><div class='gd-sec'>Setelahnya juga sering ditambah「は」「も」untuk penekanan:</div><div class='gd-ex-line'>・<span class='gd-jp'>この点においては、私も同じ意見です。</span>（Dalam hal ini, saya juga punya pendapat yang sama.）</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・<b>Jangan dipakai untuk hal kecil sehari-hari</b>: <span class='gd-jp'>コンビニにおいてパンを買った</span> terdengar seperti bahasa surat dinas, jadi aneh. Untuk ceritamu sehari-hari, cukup <span class='gd-jp'>コンビニでパンを買った</span>.<br>・<b>Kalau diikuti kata benda, jangan lupa ganti jadi における</b>: tidak bisa bilang 「日本において経済」, harus <span class='gd-jp'>日本における経済</span>.<br>・Pola ini hanya menggantikan で yang berarti 「<b>di mana, dalam situasi apa</b>」. で yang menyatakan alat tidak bisa diganti: <span class='gd-jp'>はしで食べる</span> (makan dengan sumpit) tidak bisa jadi 「はしにおいて」.<br>・Untuk 「di suatu tempat <b>ada</b> sesuatu」yang dipakai に, bukan で, jadi juga tidak bisa diganti において: katakan <span class='gd-jp'>公園に子どもがいる</span>.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'><b>で</b>＝bisa dipakai di percakapan dan keseharian: <span class='gd-jp'>会議で決まりました。</span>（Sudah diputuskan di rapat.）<br><b>において</b>＝cara formal untuk hal yang sama: <span class='gd-jp'>会議において決定されました。</span>（Diputuskan dalam rapat.）</div><div class='gd-sec'><b>について</b> mirip bentuknya, tapi artinya sama sekali berbeda, yaitu 「<b>tentang ～</b>」, untuk isi atau topik. Lihat kalimat ini, keduanya muncul bersamaan:</div><div class='gd-ex-line'>・<span class='gd-jp'>会議において、環境問題について話し合った。</span>（Dalam rapat, kami membahas tentang masalah lingkungan.）</div><div class='gd-sec'>「会議」adalah <b>tempat</b> membahas, sedangkan 「環境問題」adalah <b>apa yang dibahas</b>.</div><div class='gd-warn'>Trik cepat: kalau dalam bahasa Indonesia bisa diganti 「bertempat di ～」atau 「pada ～」, itu において. Kalau artinya 「tentang ～」, itu について.</div><div class='gd-h'>Setelah paham, lanjut belajar ini</div><div class='gd-sec'>Pola 「〜て」untuk menyambung ke kata kerja dan 「〜る」untuk menyambung ke kata benda ini ada di banyak pola tata bahasa lain, seperti <span class='gd-jp'>〜に関して／〜に関する</span> dan <span class='gd-jp'>〜によって／〜による</span>. Kalau yang ini sudah paham, pola-pola itu jadi lebih mudah.</div>","n3-17":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜さえ〜ば」 artinya <b>「asalkan ～, (maka) ～」</b>. Maksudnya: hal lain tidak perlu, <b>cukup dengan satu syarat ini saja</b>. Misalnya kamu mau bilang \"Asalkan ada internet, bisa kerja di mana saja\", dalam bahasa Jepang kamu pakai pola ini.</div><div class='gd-ex-line'>・<span class='gd-jp'>時間さえあれば、もっと旅行したい。</span>（Asalkan ada waktu, aku ingin lebih sering jalan-jalan）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Kita ulas dulu cara membentuk 「ば形」 (bentuk \"kalau ～\"), satu per satu:<br><span class='gd-pair'><span class='gd-jp'>書く</span> → ganti く jadi け → <span class='gd-jp'>書けば</span></span><br><span class='gd-pair'><span class='gd-jp'>ある</span> → <span class='gd-jp'>あれば</span></span><br><span class='gd-pair'><span class='gd-jp'>いい</span> → <span class='gd-jp'>よければ</span></span></div><div class='gd-sec'><span class='gd-tag'>Nomina＋さえ＋〜ば</span>Paling umum. Taruh さえ setelah hal yang ingin kamu tekankan, lalu sambung dengan bentuk ば dari verba atau adjektiva.</div><div class='gd-ex-line'>・<span class='gd-jp'>天気さえよければ、明日は富士山が見える。</span>（Asalkan cuacanya bagus, besok Gunung Fuji kelihatan）</div><div class='gd-sec'><span class='gd-tag'>Verba＋さえすれば</span>Menekankan \"asalkan melakukan tindakan ini\". Ubah verba ke bentuk ます, buang ます, lalu tambahkan さえすれば.<br><span class='gd-pair'><span class='gd-jp'>飲みます</span> → buang ます → <span class='gd-jp'>飲みさえすれば</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>この薬を飲みさえすれば、すぐ治りますよ。</span>（Asalkan minum obat ini, sebentar lagi pasti sembuh）</div><div class='gd-ex-line'>・<span class='gd-jp'>ボタンを押しさえすれば、あとは機械がやってくれる。</span>（Asalkan menekan tombolnya, sisanya dikerjakan mesin）</div><div class='gd-sec'><span class='gd-tag'>Bentuk て＋さえいれば</span>Menekankan \"asalkan tetap berada dalam keadaan ini\".<br><span class='gd-pair'><span class='gd-jp'>待って</span> → <span class='gd-jp'>待ってさえいれば</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>ここで待ってさえいれば、大丈夫です。</span>（Asalkan menunggu di sini, tidak masalah）</div><div class='gd-sec'><span class='gd-tag'>Adjektiva＋さえあれば</span>Untuk adjektiva-い, ganti い jadi く; untuk adjektiva-な, tambahkan で, lalu sambung さえあれば.<br><span class='gd-pair'><span class='gd-jp'>安い</span> → <span class='gd-jp'>安くさえあれば</span></span><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かでさえあれば</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>静かでさえあれば、狭い部屋でもかまわない。</span>（Asalkan tenang, kamar yang agak sempit pun tidak masalah）</div><div class='gd-h'>Dalam percakapan sering diganti たら atau なら</div><div class='gd-sec'>Kalau ば diganti 「たら」 atau 「なら」, artinya tetap \"asalkan ～\", dan sering sekali terdengar dalam percakapan.</div><div class='gd-ex-line'>・<span class='gd-jp'>時間さえあったら、手伝うよ。</span>（Asalkan ada waktu, aku bantu）</div><div class='gd-ex-line'>・<span class='gd-jp'>あなたさえいいなら、私はそれでいい。</span>（Asalkan kamu setuju, aku tidak masalah）</div><div class='gd-h'>Bagian yang sering keliru</div><div class='gd-warn'>・Verba harus memakai <b>bentuk ます tanpa ます</b>, baru disambung: yang benar <span class='gd-jp'>飲みさえすれば</span>, tidak boleh 「飲むさえすれば」.<br>・「が」「を」 setelah nomina digantikan oleh さえ: yang benar <span class='gd-jp'>お金さえあれば</span>, bukan 「お金がさえあれば」.<br>・Artinya \"asalkan\", bukan \"hanya kalau ～\". <span class='gd-jp'>練習さえすれば</span> berarti \"asalkan latihan, sudah cukup\"; intinya syaratnya mudah, bukan membatasi bahwa \"yang lain tidak boleh\".<br>・Setelah さえ harus ada bentuk syarat (ば、たら、なら) supaya berarti \"asalkan\"; kalau tidak ada, さえ jadi \"bahkan ～ pun\".</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Kata 「さえ」 yang sama, artinya ditentukan oleh apa yang mengikutinya:<br><b>さえ〜ば／たら／なら</b>＝asalkan ～: <span class='gd-jp'>ひらがなさえ読めれば、このゲームはできる。</span>（Asalkan bisa baca hiragana, kamu bisa main game ini）<br><b>さえ yang berdiri sendiri</b>＝bahkan ～ pun: <span class='gd-jp'>ひらがなさえ読めない。</span>（Hiragana pun tidak bisa dibaca）</div><div class='gd-warn'>Trik menilai: lihat apakah setelah さえ ada bentuk syarat (〜ば、〜たら、〜なら). Kalau ada, artinya \"asalkan\"; kalau tidak ada, artinya \"bahkan ～ pun\".</div><div class='gd-h'>Setelah paham, lanjut belajar ini</div><div class='gd-sec'>〜さえ yang berdiri sendiri (bahkan ～ pun) lebih mudah dipelajari sambil dibandingkan dengan <span class='gd-jp'>〜すら</span> dan <span class='gd-jp'>〜まで</span> yang artinya mirip.</div>","n3-24":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜代わりに」 artinya <b>\"mengganti A dengan B\"</b>. Bisa mengganti barang, orang, atau cara, bisa juga pertukaran seperti \"kamu bantu aku, aku traktir kamu\", atau untung-rugi seperti \"gajinya tinggi, tapi sebagai gantinya capek\". Intinya sama: <b>satu sisi ditukar dengan sisi lain, pas impas</b>.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Mengganti barang・cara</span>Seharusnya pakai A / melakukan A, tapi diganti jadi B.</div><div class='gd-ex-line'>・<span class='gd-jp'>砂糖の代わりに、はちみつを使った。</span>（Aku pakai madu sebagai pengganti gula）</div><div class='gd-ex-line'>・<span class='gd-jp'>今日は外食する代わりに、家で作ろう。</span>（Hari ini jangan makan di luar, masak di rumah saja）</div><div class='gd-sec'><span class='gd-tag'>Mengganti orang</span>Awalnya A yang melakukan, lalu digantikan oleh B.</div><div class='gd-ex-line'>・<span class='gd-jp'>社長の代わりに、部長が会議に出た。</span>（Kepala bagian menghadiri rapat menggantikan direktur）</div><div class='gd-ex-line'>・<span class='gd-jp'>私の代わりに電話に出てくれる？</span>（Bisa tolong angkat teleponnya menggantikan aku?）</div><div class='gd-sec'><span class='gd-tag'>Syarat pertukaran</span>Aku melakukan A, kamu melakukan B.</div><div class='gd-ex-line'>・<span class='gd-jp'>英語を教える代わりに、日本語を教えてもらっている。</span>（Aku mengajarinya bahasa Inggris, sebagai gantinya dia mengajariku bahasa Jepang）</div><div class='gd-ex-line'>・<span class='gd-jp'>宿題を手伝ってもらった代わりに、昼ご飯をおごった。</span>（Dia membantu PR-ku, sebagai balasannya aku mentraktirnya makan siang）</div><div class='gd-sec'><span class='gd-tag'>Ada untung ada rugi</span>Ada satu keuntungan, sebagai gantinya ada satu kerugian. Bisa juga sebaliknya.</div><div class='gd-ex-line'>・<span class='gd-jp'>給料が高い代わりに、仕事がきつい。</span>（Gajinya tinggi, tapi sebagai gantinya kerjanya berat）</div><div class='gd-ex-line'>・<span class='gd-jp'>この部屋は駅から遠い代わりに、家賃が安い。</span>（Kamar ini jauh dari stasiun, tapi sebagai gantinya sewanya murah）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Nomina</b>: di tengah harus ditambah 「の」.<span class='gd-pair'><span class='gd-jp'>砂糖</span> → <span class='gd-jp'>砂糖の代わりに</span></span><br><b>Verba・adjektiva-い</b>: sambung langsung dengan bentuk biasa; positif, negatif, dan lampau semuanya bisa.<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行く代わりに</span></span><span class='gd-pair'><span class='gd-jp'>行かない</span> → <span class='gd-jp'>行かない代わりに</span></span><span class='gd-pair'><span class='gd-jp'>手伝ってもらった</span> → <span class='gd-jp'>手伝ってもらった代わりに</span></span><br><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高い代わりに</span></span><span class='gd-pair'><span class='gd-jp'>効かない</span> → <span class='gd-jp'>効かない代わりに</span></span><br><b>Adjektiva-な</b>: 「な」 tetap dipertahankan.<span class='gd-pair'><span class='gd-jp'>便利</span> → <span class='gd-jp'>便利な代わりに</span></span><br>Saat mengatakan \"tidak melakukan A, melainkan B\", verba biasanya memakai bentuk kamus, misalnya <span class='gd-jp'>行く代わりに</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>この薬はあまり効かない代わりに、副作用もない。</span>（Obat ini kurang manjur, tapi sebagai gantinya juga tidak ada efek samping）</div><div class='gd-h'>Bentuk yang paling sering terdengar</div><div class='gd-sec'><span class='gd-tag'>その代わり</span>Berdiri sendiri di awal kalimat, artinya \"tapi sebagai gantinya ～\". Sering sekali dipakai saat bernegosiasi dengan teman.</div><div class='gd-ex-line'>・<span class='gd-jp'>車、貸してあげる。その代わり、ガソリン入れてきてね。</span>（Mobilnya kupinjamkan. Tapi sebagai gantinya, isiin bensin ya）</div><div class='gd-h'>Bagian yang sering keliru</div><div class='gd-warn'>・<b>Urutannya kebalikan dari bahasa Indonesia</b>: dalam bahasa Indonesia kita bilang \"madu sebagai pengganti gula\" (yang baru disebut dulu), sedangkan bahasa Jepang <span class='gd-jp'>砂糖の代わりにはちみつ</span>: yang diganti ditaruh di depan 「代わりに」. Kalau ditulis mengikuti urutan Indonesia menjadi <span class='gd-jp'>はちみつの代わりに砂糖</span>, artinya jadi terbalik total.<br>・Jangan lupa 「の」 setelah nomina dan 「な」 setelah adjektiva-な.<br>・Untuk pemakaian \"ada untung ada rugi\", kedua sisi harus bisa saling mengimbangi. Untuk \"tapi\" biasa, pakai 「けど」: <span class='gd-jp'>日本語は難しいけど、毎日勉強している。</span> Kalimat ini tidak bisa diganti dengan 代わりに.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'><b>代わりに</b>＝satu untung satu rugi, <b>pas impas</b>:<br><span class='gd-jp'>この店は高い代わりに、すごくおいしい。</span>（Toko ini mahal, tapi sebagai gantinya enak sekali）<br><b>わりに</b>＝untuk ukuran A, hasilnya <b>tidak sesuai dugaan</b>:<br><span class='gd-jp'>この店は高いわりに、あまりおいしくない。</span>（Toko ini semahal itu, tapi tidak terlalu enak）<br>Selain itu, <b>反面</b> juga bisa menyatakan satu untung satu rugi (<span class='gd-jp'>給料が高い反面、仕事がきつい。</span>). Artinya sangat dekat dengan 代わりに, hanya lebih formal (bahasa tulis) dan cenderung menunjukkan dua sisi dari satu hal yang sama.</div><div class='gd-warn'>Trik menilai: kalau terasa \"tukar satu dengan satu, impas\", pakai 代わりに; kalau terasa \"untuk ukuran ～, kok bisa begini\", pakai わりに.</div>","n3-4":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「によって」mirip dengan <b>“lewat ~”, “karena ~”, “tergantung ~”, “oleh ~”</b>. Di depannya ada sebuah nomina, dan artinya: sesuatu terjadi berkat nomina itu, disebabkan olehnya, atau bergantung padanya. Karena itu dalam bahasa Indonesia terjemahannya bisa “melalui”, “karena”, “berbeda-beda tergantung ~”, atau “oleh”. Pola ini sangat sering muncul di berita, teks penjelasan, dan situasi formal.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Di depannya selalu langsung <b>nomina</b>, tanpa 「の」. Bentuk yang kamu pakai ditentukan oleh apa yang ada di belakangnya:<br>Kalau di belakangnya ada tindakan atau kalimat lengkap → <b>によって</b>：<span class='gd-jp'>台風によって電車が止まった。</span>（Karena topan, kereta berhenti beroperasi）<br>Kalau di belakangnya langsung nomina → <b>による</b>：<span class='gd-jp'>台風による停電</span>（Pemadaman listrik akibat topan）<br>Dalam tulisan kamu juga sering menemukan 「<span class='gd-jp'>により</span>」. Artinya sama dengan によって, hanya lebih formal.</div><div class='gd-h'>Pemakaian yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>Berbeda tergantung ~</span>“Tergantung ~, setiap ~ berbeda-beda.” Di belakangnya hampir selalu ada kata yang berarti “berbeda”, seperti <span class='gd-jp'>違う</span>、<span class='gd-jp'>異なる</span>、<span class='gd-jp'>変わる</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>地域によって食文化が異なる。</span>（Budaya makanan berbeda-beda tergantung daerah）</div><div class='gd-ex-line'>・<span class='gd-jp'>人によって考え方が違う。</span>（Cara berpikir setiap orang berbeda-beda）</div><div class='gd-sec'><span class='gd-tag'>Sebab</span>“Karena ~, disebabkan oleh ~”. Nadanya objektif, seperti berita yang sedang melaporkan.</div><div class='gd-ex-line'>・<span class='gd-jp'>台風による停電が続いている。</span>（Pemadaman listrik akibat topan masih berlanjut）</div><div class='gd-ex-line'>・<span class='gd-jp'>事故によって電車が遅れています。</span>（Kereta terlambat karena kecelakaan）</div><div class='gd-sec'><span class='gd-tag'>Cara・metode</span>“Melalui ~”, ungkapan yang lebih formal.</div><div class='gd-ex-line'>・<span class='gd-jp'>この問題は話し合いによって解決した。</span>（Masalah ini diselesaikan melalui musyawarah）</div><div class='gd-sec'><span class='gd-tag'>“Oleh siapa” dalam kalimat pasif</span>Dipakai untuk menyebut siapa yang membuat karya, penemuan, atau bangunan.</div><div class='gd-ex-line'>・<span class='gd-jp'>この小説は有名な作家によって書かれた。</span>（Novel ini ditulis oleh seorang penulis terkenal）</div><div class='gd-ex-line'>・<span class='gd-jp'>電話はベルによって発明された。</span>（Telepon ditemukan oleh Bell）</div><div class='gd-sec'><span class='gd-tag'>によっては</span>Dengan tambahan 「は」, artinya jadi <b>“ada ~ yang …”</b>. Kamu hanya menyorot sebagian saja.</div><div class='gd-ex-line'>・<span class='gd-jp'>店によって値段が違う。</span>（Harganya berbeda-beda di setiap toko）</div><div class='gd-ex-line'>・<span class='gd-jp'>店によっては、カードが使えない。</span>（Ada toko yang tidak bisa pakai kartu）</div><div class='gd-h'>Bagian yang sering keliru</div><div class='gd-warn'>・<b>Kalimat pasif tidak selalu memakai によって</b>. Untuk hal sehari-hari seperti “dimarahi seseorang” atau “dibilangi seseorang”, pakai 「に」：<span class='gd-jp'>母に叱られた。</span>（Dimarahi ibu）. Kalau kamu bilang 「母によって叱られた」, kedengarannya sangat aneh. によって dipakai untuk konteks “siapa yang menciptakan sesuatu”.<br>・<b>Untuk cara sehari-hari, 「で」sudah cukup</b>：<span class='gd-jp'>バスで行く</span>, bukan 「バスによって行く」. “Melalui” pada によって terasa formal, dan dipakai untuk hal yang lebih besar seperti metode atau sistem.<br>・<b>Setelah による harus ada nomina</b>. Kalau di belakangnya kalimat, kembali ke によって. Jangan menulis 「台風による電車が止まった」.<br>・「Berbeda tergantung ~」dan「ada ~ yang …」hanya beda satu 「は」, tapi artinya sudah lain. Perhatikan baik-baik ada tidaknya 「は」 itu.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Sama-sama “karena topan”, tapi nuansanya sangat berbeda:<br><b>によって</b>＝menyebut sebab secara objektif, tanpa emosi：<span class='gd-jp'>台風によって電車が止まった。</span>（Karena topan, kereta berhenti beroperasi）<br><b>せいで</b>＝menyalahkan sebab itu, bernada keluhan：<span class='gd-jp'>台風のせいで旅行に行けなかった。</span>（Gara-gara topan, aku tidak jadi pergi liburan）<br><b>おかげで</b>＝berkat sebab itu, bernada syukur atau terima kasih：<span class='gd-jp'>台風のおかげで学校が休みになった。</span>（Berkat topan, sekolah libur）<br>Kalau disambung dengan nomina, せいで dan おかげで memakai 「の」 di depannya (<span class='gd-jp'>雨のせいで</span>), sedangkan によって langsung menempel pada nomina tanpa 「の」 (<span class='gd-jp'>雨によって</span>).</div><div class='gd-warn'>Trik memilih: kalau mau menyebut sebab secara datar seperti di berita, pakai によって. Kalau mau mengeluh, pakai せいで. Kalau merasa bersyukur, pakai おかげで.</div>","n3-6":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜おかげで」sama dengan <b>“berkat ~”, “untung ada ~”, “syukurlah ada ~”</b> dalam bahasa Indonesia. Di depannya ada sebab yang membawa hasil baik, di belakangnya ada hasil baik itu, dan nadanya mengandung sedikit rasa terima kasih.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Berterima kasih pada seseorang</span>Karena ada orang yang membantu, semuanya berjalan lancar.</div><div class='gd-ex-line'>・<span class='gd-jp'>先生のおかげで、合格できました。</span>（Berkat Bapak/Ibu guru, saya bisa lulus）</div><div class='gd-ex-line'>・<span class='gd-jp'>友達が手伝ってくれたおかげで、早く終わった。</span>（Berkat bantuan teman, pekerjaannya cepat selesai）</div><div class='gd-sec'><span class='gd-tag'>Sebab yang baik</span>Tidak harus orang. Cuaca, lingkungan, atau benda pun bisa, asalkan membawa hasil yang baik.</div><div class='gd-ex-line'>・<span class='gd-jp'>この薬を飲んだおかげで、熱が下がった。</span>（Berkat minum obat ini, demamku turun）</div><div class='gd-ex-line'>・<span class='gd-jp'>駅が近いおかげで、通勤が楽です。</span>（Untung dekat stasiun, jadi berangkat kerja itu mudah）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Nomina</b>: tambahkan 「の」 di tengah.<br><span class='gd-pair'><span class='gd-jp'>先輩</span> → <span class='gd-jp'>先輩のおかげで</span></span></div><div class='gd-sec'><b>Verba</b>: langsung disambung dengan bentuk biasa (bentuk kamus, bentuk た, dan sebagainya, tanpa ます). Hasil baiknya biasanya sudah terjadi, jadi yang paling sering dipakai adalah bentuk た.<br><span class='gd-pair'><span class='gd-jp'>頑張った</span> → <span class='gd-jp'>頑張ったおかげで</span></span></div><div class='gd-sec'><b>Adjektiva-い</b>: langsung disambung.<br><span class='gd-pair'><span class='gd-jp'>近い</span> → <span class='gd-jp'>近いおかげで</span></span><br><span class='gd-pair'><span class='gd-jp'>よかった</span> → <span class='gd-jp'>よかったおかげで</span></span></div><div class='gd-sec'><b>Adjektiva-な</b>: bentuk sekarang memakai 「な」, bentuk lampau memakai 「だった」.<br><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かなおかげで</span></span><br><span class='gd-pair'><span class='gd-jp'>元気だった</span> → <span class='gd-jp'>元気だったおかげで</span></span></div><div class='gd-h'>Pemakaian yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>おかげさまで</span>Saat seseorang menyapa dan menanyakan kabarmu, kamu membalas sopan “berkat Anda”. Kalimat ini boleh dipakai walaupun orang itu sebenarnya tidak membantu apa-apa.</div><div class='gd-ex-line'>・<span class='gd-jp'>お元気ですか。</span>——<span class='gd-jp'>おかげさまで、元気です。</span>（Apa kabar? — Berkat Anda, saya baik-baik saja）</div><div class='gd-sec'><span class='gd-tag'>〜のおかげです</span>Diletakkan di akhir kalimat untuk memberikan pujian atau jasa kepada seseorang.</div><div class='gd-ex-line'>・<span class='gd-jp'>合格できたのは、先生のおかげです。</span>（Saya bisa lulus semua berkat Bapak/Ibu guru）</div><div class='gd-sec'><span class='gd-tag'>Sindiran</span>Sama seperti “berkat kamu nih” dalam bahasa Indonesia, pola ini juga bisa sengaja dipakai untuk menyindir, padahal hasilnya buruk.</div><div class='gd-ex-line'>・<span class='gd-jp'>君のおかげで、全部やり直しだよ。</span>（Berkat kamu nih, semuanya harus diulang dari awal）</div><div class='gd-h'>Bagian yang sering keliru</div><div class='gd-warn'>・Setelah nomina harus ada 「の」: yang benar <span class='gd-jp'>先生のおかげで</span>, bukan “先生おかげで”.<br>・Adjektiva-な bentuk sekarang tidak boleh disambung dengan 「だ」: yang benar <span class='gd-jp'>静かなおかげで</span>, bukan “静かだおかげで”.<br>・Di belakangnya harus ada <b>hasil yang sudah terjadi atau pasti akan terjadi</b>. Kalimat ajakan atau permintaan seperti “ayo ~” atau “tolong ~” tidak bisa dipakai.<br>・Dalam bahasa Indonesia kata “karena” bisa dipakai untuk apa saja, tapi tidak semua “karena” bisa diganti おかげで. Kalau cuma menjelaskan sebab (misalnya pertandingan dibatalkan karena hujan), pakai <span class='gd-jp'>から</span> atau <span class='gd-jp'>ので</span>. Kalau kamu pakai おかげで, kedengarannya kamu senang pertandingannya batal.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>おかげで</b>＝berkat ~, hasilnya <b>hal baik</b>, bernada terima kasih:<br><span class='gd-jp'>雨が降ったおかげで、涼しくなった。</span>（Berkat hujan, udaranya jadi sejuk）<br><b>せいで</b>＝gara-gara ~, hasilnya <b>hal buruk</b>, bernada keluhan atau menyalahkan:<br><span class='gd-jp'>雨が降ったせいで、試合が中止になった。</span>（Gara-gara hujan, pertandingan dibatalkan）<br>Cara menyambungnya sama persis. Bedanya hanya pada perasaanmu terhadap hasilnya: berterima kasih atau mengeluh.</div><div class='gd-warn'>Trik memilih: kalau mau bilang “berkat / untung ada”, pakai おかげで. Kalau mau bilang “gara-gara ~”, pakai せいで. Kalau hanya menyebut sebab tanpa perasaan baik atau buruk, pakai から・ので.</div>","n3-10":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'><span class='gd-jp'>ところ</span>aslinya berarti “tempat”, tapi di sini artinya <b>“titik dalam waktu”</b>. Satu kejadian dibagi jadi tiga tahap: <b>belum mulai, sedang di tengah, baru selesai</b>. <span class='gd-jp'>ところだ</span> memberi tahu lawan bicara kamu sedang “berdiri di kotak mana”, mirip dengan “baru mau ~”, “sedang ~”, dan “baru saja ~” dalam bahasa Indonesia.</div><div class='gd-h'>Cara menyambung: bentuk di depannya menentukan tahapnya</div><div class='gd-sec'><span class='gd-tag'>Baru mau</span>Bentuk kamus (bentuk dasar yang ada di kamus) ＋ところだ. Kejadiannya <b>belum dimulai</b>, sebentar lagi dilakukan.</div><div class='gd-ex-line'>・<span class='gd-jp'>今から出かけるところです。</span>（Aku baru mau berangkat）</div><div class='gd-ex-line'>・<span class='gd-jp'>A：もうご飯食べた？　B：ううん、これから食べるところ。</span>（A: Sudah makan? B: Belum, baru mau makan）</div><div class='gd-sec'><span class='gd-tag'>Sedang melakukan</span>Bentuk て＋いる＋ところだ. Kejadiannya <b>sedang di tengah jalan</b>, belum selesai.</div><div class='gd-ex-line'>・<span class='gd-jp'>今シャワーを浴びているところだから、あとでかけ直すね。</span>（Aku lagi mandi, nanti aku telepon balik ya）</div><div class='gd-ex-line'>・<span class='gd-jp'>今調べているところなので、少々お待ちください。</span>（Sedang saya cek, mohon tunggu sebentar）</div><div class='gd-sec'><span class='gd-tag'>Baru selesai</span>Bentuk た (lampau)＋ところだ. Kejadiannya <b>baru saja</b> selesai.</div><div class='gd-ex-line'>・<span class='gd-jp'>たった今、家に帰ってきたところです。</span>（Aku baru saja sampai rumah）</div><div class='gd-ex-line'>・<span class='gd-jp'>会議がちょうど終わったところです。</span>（Rapatnya baru saja selesai）</div><div class='gd-sec'>Paling jelas kalau satu kata kerja yang sama dibandingkan berdampingan:<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べるところ</span></span>（baru mau makan）<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べているところ</span></span>（sedang makan）<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べたところ</span></span>（baru saja selesai makan）<br>Kepada orang yang lebih tua atau tamu, pakai <span class='gd-jp'>ところです</span>; ke teman boleh langsung <span class='gd-jp'>ところ</span>. Dalam percakapan, <span class='gd-jp'>ているところ</span> sering disingkat jadi <span class='gd-jp'>てるところ</span>.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'>Paling sering muncul saat ada yang bertanya “kamu lagi apa sekarang?”, saat menelepon, atau saat membalas pesan, untuk menjelaskan <b>keadaanmu saat ini</b>. Biasanya muncul bersama <span class='gd-jp'>これから</span>, <span class='gd-jp'>今から</span> (baru mau), <span class='gd-jp'>今</span> (sedang), <span class='gd-jp'>たった今</span>, <span class='gd-jp'>ちょうど</span> (baru saja). Begitu melihat kata-kata ini, kamu langsung tahu itu kotak yang mana.</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Bentuk kamus＋ところ artinya <b>belum mulai</b>. <span class='gd-jp'>今食べるところ</span> artinya “baru mau makan”, bukan “sedang makan”. Untuk “sedang makan”, bilang <span class='gd-jp'>食べているところ</span>.<br>・ているところ hanya bisa dipakai untuk <b>gerakan yang benar-benar sedang berlangsung</b>. Kata yang menyatakan keadaan, seperti <span class='gd-jp'>住んでいる</span> dan <span class='gd-jp'>知っている</span>, tidak bisa dipakai dalam 「住んでいるところだ」.<br>・たところ artinya <b>benar-benar baru saja</b>. Kamu tidak bisa bilang 「先月日本に来たところだ」, karena bulan lalu tidak dihitung sebagai “barusan”. Untuk itu pakai たばかり (lihat di bawah).<br>・<span class='gd-jp'>ところだ</span> di akhir kalimat baru berarti seperti ini. 「〜たところ、…」 yang diberi koma lalu kalimatnya dilanjutkan adalah tata bahasa lain (“setelah mencoba ~, ternyata …”), jangan sampai tertukar.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>たところだ</b> dan <b>たばかりだ</b> sama-sama diterjemahkan “baru ~”. Bedanya ada pada seberapa “baru” itu.<br><b>たところだ</b>: titik waktunya persis barusan, sekitar beberapa menit yang lalu.<br><span class='gd-jp'>今、駅に着いたところです。</span>（Aku baru saja sampai di stasiun）<br><b>たばかりだ</b>: si pembicara <b>merasa</b> belum lama berlalu, bisa beberapa hari atau beberapa bulan.<br><span class='gd-jp'>先月日本に来たばかりです。</span>（Aku baru bulan lalu datang ke Jepang）<br>Selain itu, たばかり sering membawa kesan “baru saja ~, tapi / jadi …”: <span class='gd-jp'>買ったばかりなのに、もう壊れた。</span>（Baru saja dibeli, sudah rusak）</div><div class='gd-warn'>Trik menentukan: kalau bisa diganti dengan “tepat pada saat ini”, pakai たところ; kalau maksudnya “belum lama berlalu, rasanya masih baru”, pakai たばかり. Kalau ragu, dan waktunya sudah lewat dari hari ini, pakai たばかり.</div><div class='gd-h'>Setelah ini bisa lanjut belajar</div><div class='gd-sec'>Bentuk kamus＋<span class='gd-jp'>ところだった</span> = hampir saja ~ (untung tidak terjadi): <span class='gd-jp'>もう少しで電車に乗り遅れるところだった。</span>（Hampir saja ketinggalan kereta）</div>","n3-11":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜たばかり」 sama dengan <b>“baru saja ~” atau “belum lama ~”</b> dalam bahasa Indonesia. Intinya, kamu <b>merasa</b> waktunya masih singkat, jadi sering terbawa perasaan seperti “belum terbiasa” atau “kok sudah ~ lagi”.</div><div class='gd-ex-line'>・<span class='gd-jp'>日本に来たばかりで、まだ慣れない。</span>（Baru datang ke Jepang, masih belum terbiasa）</div><div class='gd-h'>Cara menyambung</div><div class='gd-sec'>Selalu disambung dengan <b>bentuk た</b> kata kerja (bentuk lampau, seperti <span class='gd-jp'>食べた</span> dan <span class='gd-jp'>行った</span>), lalu tambahkan ばかり.<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べた</span> → <span class='gd-jp'>食べたばかり</span></span><br><span class='gd-pair'><span class='gd-jp'>買う</span> → <span class='gd-jp'>買った</span> → <span class='gd-jp'>買ったばかり</span></span><br><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来た</span> → <span class='gd-jp'>来たばかり</span></span></div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>Di akhir kalimat</span>〜たばかりだ／〜たばかりです</div><div class='gd-ex-line'>・<span class='gd-jp'>先月結婚したばかりです。</span>（Aku baru bulan lalu menikah）</div><div class='gd-sec'><span class='gd-tag'>Masih ada lanjutan</span>〜たばかりで, menjelaskan “karena baru saja ~, jadi …”</div><div class='gd-ex-line'>・<span class='gd-jp'>起きたばかりで、頭がぼんやりしている。</span>（Baru bangun, kepalaku masih linglung）</div><div class='gd-sec'><span class='gd-tag'>Menerangkan kata benda</span>〜たばかりの＋kata benda</div><div class='gd-ex-line'>・<span class='gd-jp'>これは買ったばかりの靴です。</span>（Ini sepatu yang baru saja kubeli）</div><div class='gd-sec'><span class='gd-tag'>Keluhan, tak terduga</span>〜たばかりなのに, “baru saja ~, kok sudah …”</div><div class='gd-ex-line'>・<span class='gd-jp'>さっき食べたばかりなのに、もうお腹がすいた。</span>（Baru saja makan, perut sudah lapar lagi）</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Di depannya harus bentuk た. Kalau jadi <span class='gd-jp'>来るばかり</span> atau <span class='gd-jp'>食べるばかり</span>, artinya berubah jadi hal lain (dijelaskan di bawah).<br>・Untuk menerangkan kata benda harus pakai <b>の</b>: yang benar <span class='gd-jp'>買ったばかりの靴</span>, bukan 買ったばかり靴.<br>・Seberapa “baru” itu tergantung perasaanmu: <span class='gd-jp'>去年入社したばかりです</span> (aku baru tahun lalu masuk perusahaan) dikatakan begini pun sama sekali tidak masalah, padahal sudah setahun.<br>・Di antara teman, sering diucapkan jadi <span class='gd-jp'>たばっか</span>: <span class='gd-jp'>今起きたばっか。</span>（Aku baru saja bangun）</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>〜たところだ</b> (ところだ di n3-10) juga diterjemahkan “baru ~”, tetapi yang ditekankan adalah <b>titik waktu saat tindakan baru selesai</b>, benar-benar beberapa detik atau menit yang lalu.<br>・<span class='gd-jp'>今、駅に着いたところです。</span>（Aku baru saja sampai di stasiun）<br>・<span class='gd-jp'>今、駅に着いたばかりです。</span>（Aku baru sampai di stasiun）<br>Untuk situasi “barusan” seperti ini, keduanya bisa dipakai. Tapi kalau rentang waktunya lebih panjang, hanya たばかり yang bisa:<br>・<span class='gd-jp'>先月引っ越したばかりです。</span>（Aku baru bulan lalu pindahan）○<br>・<span class='gd-jp'>先月引っ越したところです。</span> ×</div><div class='gd-sec'><b>Kalau bentuk di depan ばかり berganti, artinya ikut berubah</b>:<br><b>Bentuk kamus＋ばかり</b> umumnya berarti “terus berubah ke arah yang sama (makin lama makin ~)”, misalnya <span class='gd-jp'>物価は上がるばかりだ。</span>（Harga-harga terus naik）; bisa juga berarti “hanya ~ terus, cuma ~”, misalnya <span class='gd-jp'>彼女は泣くばかりで何も言わない。</span>（Dia hanya menangis terus dan tidak bilang apa-apa）<br><b>Bentuk て＋ばかりいる</b> = selalu hanya melakukan satu hal: <span class='gd-jp'>弟はゲームをしてばかりいる。</span>（Adikku kerjanya main game terus）</div><div class='gd-warn'>Trik menentukan: lihat dulu apa yang ada di depan ばかり. Bentuk た berarti “baru saja ~”, bentuk kamus berarti “terus ~ (makin ~ / cuma ~)”, bentuk て berarti “kerjanya ~ melulu”. Kalau kalimatnya menyebut waktu yang cukup lama seperti “bulan lalu” atau “tahun lalu”, untuk mengatakan “baru ~” pakai たばかり, bukan たところ.</div>","n3-12":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜最中に」artinya <b>\"tepat saat sedang ~, tiba-tiba ……\"</b>. Pola ini dipakai ketika kamu sedang di tengah-tengah suatu kegiatan, lalu terganggu hal lain atau kena kejadian tak terduga. Misalnya \"lagi presentasi, eh listrik mati\" atau \"lagi wawancara, HP berbunyi\". Bagian setelahnya biasanya berisi hal yang <b>terjadi mendadak dan bikin kelabakan</b>.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Terpotong di tengah kegiatan</span>Ini pemakaian yang paling khas.</div><div class='gd-ex-line'>・<span class='gd-jp'>会議の最中に、電話が鳴った。</span>（Saat sedang rapat, telepon berbunyi）</div><div class='gd-ex-line'>・<span class='gd-jp'>シャワーを浴びている最中に、お湯が出なくなった。</span>（Saat sedang mandi, air panasnya tiba-tiba mati）</div><div class='gd-sec'><span class='gd-tag'>最中だ</span>Ditaruh di akhir kalimat, artinya \"sekarang lagi sibuk ~\". Sering dipakai saat mengangkat telepon atau menolak orang dengan sopan.</div><div class='gd-ex-line'>・<span class='gd-jp'>今、食事の最中なので、あとでかけ直します。</span>（Sekarang aku lagi makan, nanti aku telepon balik ya）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Verba</b>: ubah dulu ke bentuk 「〜ている」, lalu tambahkan 最中に.<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べている</span> → <span class='gd-jp'>食べている最中に</span></span><br><span class='gd-pair'><span class='gd-jp'>話す</span> → <span class='gd-jp'>話している最中に</span></span></div><div class='gd-sec'><b>Nomina</b>: nomina + の + 最中に. Nomina-nya harus berupa <b>kegiatan yang sedang berlangsung</b>, seperti <span class='gd-jp'>会議</span>, <span class='gd-jp'>試合</span>, <span class='gd-jp'>授業</span>, <span class='gd-jp'>面接</span>.<br><span class='gd-pair'><span class='gd-jp'>試合</span> → <span class='gd-jp'>試合の最中に</span></span></div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Verba wajib memakai bentuk 「ている」: yang benar <span class='gd-jp'>食べている最中に</span>, bukan 食べる最中に.<br>・「の」setelah nomina tidak boleh dihilangkan: yang benar <span class='gd-jp'>授業の最中に</span>, bukan 授業最中に.<br>・「最中」di sini dibaca <b>さいちゅう</b>.<br>・Verba yang dipakai harus berupa tindakan yang \"sedang berlangsung selama beberapa waktu\". Tindakan yang selesai seketika seperti <span class='gd-jp'>着く</span> dan <span class='gd-jp'>始まる</span> tidak bisa dipakai dengan 最中に. Verba yang hanya menggambarkan keadaan seperti <span class='gd-jp'>いる</span> dan <span class='gd-jp'>ある</span> juga tidak bisa.<br>・Setelahnya biasanya ada <b>kejadian mendadak yang mengganggu</b>. Kalau kamu cuma ingin bilang \"selama waktu itu aku melakukan sesuatu\", memakai 最中に akan terdengar janggal.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'><b>最中に</b> = saat sedang melakukan sesuatu, lalu <b>tiba-tiba terganggu atau kena kejadian tak terduga</b>: <span class='gd-jp'>寝ている最中に、地震が起きた。</span>（Saat sedang tidur, terjadi gempa）<br><b>間に</b> = memanfaatkan rentang waktu itu untuk <b>melakukan sesuatu</b> (boleh disengaja): <span class='gd-jp'>子どもが寝ている間に、部屋を片付けた。</span>（Selagi anak tidur, aku membereskan kamar）<br>Kalau kalimat kedua diganti jadi 「寝ている最中に、部屋を片付けた」, terdengar janggal, karena membereskan kamar bukan hal yang \"muncul tiba-tiba\".</div><div class='gd-sec'><b>〜中</b> (misalnya <span class='gd-jp'>会議中</span>) hanya menyatakan \"sedang ~\" secara datar, dan sering ditulis di pintu atau papan pengumuman. <b>〜の最中</b> nadanya lebih kuat, menekankan \"sedang di tengah-tengah, lagi sibuk-sibuknya\".</div><div class='gd-warn'>Trik cepat: kalau mau bilang \"saat sedang ~, tiba-tiba ……\", pakai 最中に. Kalau mau bilang \"selagi ~, aku melakukan ……\", pakai 間に.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Kalau mau nada yang lebih kuat, kamu bisa bilang 「真っ最中」: <span class='gd-jp'>今、テストの真っ最中だ。</span>（Sekarang lagi ujian, tepat di tengah-tengahnya）</div>","n3-14":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「～間に」artinya <b>\"saat ~ (terjadi sesuatu)\"</b> atau <b>\"selagi ~ (melakukan sesuatu)\"</b>. Bayangkan sebuah rentang waktu sebagai garis. 「間に」itu seperti <b>menancapkan sebuah bendera</b> di garis tersebut: di satu titik dalam rentang waktu itu, ada kejadian yang muncul, atau kamu berhasil menyelesaikan sesuatu.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Terjadi tanpa disadari</span>Saat kamu tidak ada atau tidak memperhatikan, sesuatu sudah terjadi.</div><div class='gd-ex-line'>・<span class='gd-jp'>留守の間に宅配便が届いた。</span>（Waktu aku tidak di rumah, paketnya sudah datang）</div><div class='gd-ex-line'>・<span class='gd-jp'>知らない間に、もう夜の12時になっていた。</span>（Tanpa terasa, sudah jam 12 malam）</div><div class='gd-sec'><span class='gd-tag'>Memanfaatkan waktu itu</span>Menggunakan suatu rentang waktu untuk menyelesaikan sesuatu.</div><div class='gd-ex-line'>・<span class='gd-jp'>子どもが寝ている間に、部屋を掃除した。</span>（Selagi anak tidur, aku membersihkan kamar）</div><div class='gd-ex-line'>・<span class='gd-jp'>日本にいる間に、富士山に登りたい。</span>（Selama aku di Jepang, aku ingin mendaki Gunung Fuji sekali）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Yang ditaruh di depan harus berupa <b>rentang waktu</b> atau <b>keadaan yang berlangsung terus</b>.<br><b>Verba</b>: untuk tindakan seperti \"tidur, makan, melihat\", biasanya pakai bentuk ている (～ている) supaya jadi rentang waktu \"sedang ~\". <span class='gd-jp'>いる</span> dan <span class='gd-jp'>ある</span> sudah berupa keadaan, jadi pakai bentuk aslinya saja. Bentuk ない (～ない) juga bisa.<br><span class='gd-pair'><span class='gd-jp'>寝る</span> → <span class='gd-jp'>寝ている間に</span></span><span class='gd-pair'><span class='gd-jp'>日本にいる</span> → <span class='gd-jp'>日本にいる間に</span></span><span class='gd-pair'><span class='gd-jp'>知らない</span> → <span class='gd-jp'>知らない間に</span></span><br><b>Nomina</b>: sisipkan 「の」di tengah.<br><span class='gd-pair'><span class='gd-jp'>留守</span> → <span class='gd-jp'>留守の間に</span></span><span class='gd-pair'><span class='gd-jp'>夏休み</span> → <span class='gd-jp'>夏休みの間に</span></span></div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Setelah nomina wajib ada 「の」: yang benar <span class='gd-jp'>留守の間に</span>, bukan 「留守間に」.<br>・「間」di sini dibaca <b>あいだ</b>. 「かん」di <span class='gd-jp'>一週間</span> adalah pemakaian lain, jangan sampai tertukar.<br>・Dalam bahasa Indonesia kita cukup bilang \"waktu/saat ~\" untuk semuanya, tapi dalam bahasa Jepang kamu harus lihat kejadian setelahnya: kalau tindakannya <b>berlangsung terus-menerus</b>, jangan pakai に. Jadi setelah 「間に」jangan taruh 「ずっと～」. <span class='gd-jp'>寝ている間に、ずっと雨が降っていた</span> itu salah, に-nya harus dibuang.<br>・Meskipun seluruh kalimat bercerita tentang masa lalu, bagian depan biasanya tetap 「ている間に」, dan 「た」untuk lampau cukup ditaruh di akhir kalimat: <span class='gd-jp'>寝ている間に地震があった。</span>（Waktu tidur, ada gempa）</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Sama-sama membicarakan liburan musim panas:</div><div class='gd-ex-line'>・<span class='gd-jp'>夏休みの間、ずっとアルバイトをしていた。</span>（Sepanjang liburan musim panas, aku terus kerja paruh waktu）</div><div class='gd-ex-line'>・<span class='gd-jp'>夏休みの間に、運転免許を取った。</span>（Di suatu waktu selama liburan musim panas, aku mendapatkan SIM）</div><div class='gd-ex-line'>・<span class='gd-jp'>夏休みのうちに、宿題を終わらせたい。</span>（Aku ingin menyelesaikan PR selagi liburan musim panas belum berakhir）</div><div class='gd-sec'><b>間</b> (tanpa に) = <b>terus-menerus</b> melakukan sesuatu sepanjang rentang waktu itu, sering diikuti 「ずっと」.<br><b>間に</b> = di <b>satu titik</b> dalam rentang waktu itu, sesuatu terjadi atau selesai dilakukan.<br><b>うちに</b> = ada nuansa <b>\"mumpung masih sempat\"</b>, menyiratkan bahwa begitu waktu itu lewat, akan jadi repot.<br>Ada juga <b>最中に</b> = saat sedang di tengah suatu kegiatan, <b>eh malah</b> terganggu: <span class='gd-jp'>シャワーを浴びている最中に、電話が鳴った。</span>（Lagi mandi, eh telepon malah berbunyi）</div><div class='gd-warn'>Trik cepat: kalau setelahnya \"terus-menerus ~\", pakai <b>間</b>. Kalau setelahnya \"terjadi / selesai melakukan sesuatu\", pakai <b>間に</b>. Kalau maksudnya \"mumpung sekarang, cepat-cepat\", pakai <b>うちに</b>.</div>","n3-15":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜ついでに」artinya <b>「sekalian」</b>. A adalah hal yang memang sudah mau kamu lakukan, jadi sekalian saja memanfaatkan kesempatan itu untuk mengerjakan B. Misalnya 「turun ke bawah buang sampah, sekalian ambil surat」: buang sampah adalah A, ambil surat adalah B.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Ada tiga cara menyambungnya, dan yang diletakkan di depan selalu hal yang \"memang sudah mau dilakukan\":<br>Nomina＋の＋ついでに　<span class='gd-pair'><span class='gd-jp'>買い物</span> → <span class='gd-jp'>買い物のついでに</span></span><br>Verba bentuk kamus＋ついでに　<span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くついでに</span></span><br>Verba bentuk た＋ついでに　<span class='gd-pair'><span class='gd-jp'>来た</span> → <span class='gd-jp'>来たついでに</span></span><br>Nomina harus berupa 「satu kegiatan」, misalnya kata seperti <span class='gd-jp'>買い物</span>、<span class='gd-jp'>散歩</span>、<span class='gd-jp'>出張</span>、<span class='gd-jp'>旅行</span>.</div><div class='gd-h'>Bentuk kamus atau bentuk た?</div><div class='gd-sec'><span class='gd-tag'>Bentuk kamus</span>A belum dilakukan, kamu baru mau keluar untuk melakukannya, lalu sekalian mengerjakan B. Sering dipakai untuk meminta tolong orang lain.</div><div class='gd-ex-line'>・<span class='gd-jp'>コンビニに行くついでに、お茶を買ってきてくれる？</span>（Kalau kamu ke minimarket, bisa sekalian belikan aku teh?）</div><div class='gd-ex-line'>・<span class='gd-jp'>出かけるついでに、ゴミを出してくるね。</span>（Aku keluar dulu ya, sekalian buang sampah）</div><div class='gd-sec'><span class='gd-tag'>た形</span>Kamu sudah sampai di tempat itu, A sudah terjadi, lalu kamu memanfaatkan kesempatan itu untuk mengerjakan B.</div><div class='gd-ex-line'>・<span class='gd-jp'>京都に来たついでに、奈良にも行ってみた。</span>（Sudah sampai di Kyoto, sekalian aku coba mampir ke Nara juga）</div><div class='gd-ex-line'>・<span class='gd-jp'>本屋に寄ったついでに、ノートも買った。</span>（Waktu mampir ke toko buku, sekalian beli buku catatan）</div><div class='gd-sec'><span class='gd-tag'>Nomina の</span>Paling ringkas dan sangat berguna dalam keseharian.</div><div class='gd-ex-line'>・<span class='gd-jp'>買い物のついでに、銀行に寄った。</span>（Keluar belanja, sekalian mampir ke bank）</div><div class='gd-ex-line'>・<span class='gd-jp'>出張のついでに、大阪の友達に会った。</span>（Waktu dinas luar kota, sekalian bertemu teman di Osaka）</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-jp'>ついでに</span> juga bisa diletakkan sendiri di awal kalimat, langsung dipakai sebagai 「sekalian」. A di depannya sudah jelas dari konteks, jadi tidak perlu disebut lagi.</div><div class='gd-ex-line'>・<span class='gd-jp'>あ、ついでに牛乳も買ってきて。</span>（Eh, sekalian belikan susu juga ya）</div><div class='gd-h'>Bagian yang mudah keliru</div><div class='gd-warn'>・<b>Hal utama di depan, hal \"sekalian\" di belakang</b>. Kalau dibalik, artinya jadi hal lain itulah tujuan utamanya.<br>・Di depan harus ada 「satu kegiatan」, tidak boleh langsung tempat: kamu tidak bisa bilang 「駅のついでに」, tapi harus <span class='gd-jp'>駅に行くついでに</span>.<br>・A dan B harus sama-sama hal yang <b>kamu putuskan sendiri untuk dilakukan</b>. Kejadian alami seperti hujan tidak bisa dimasukkan, jadi tidak bisa bilang 「雨が降ったついでに」.<br>・Dalam bahasa Indonesia, \"omong-omong\" dipakai untuk menambah informasi. Dalam bahasa Jepang, yang lebih sering dipakai untuk itu adalah <span class='gd-jp'>ちなみに</span>, bukan ついでに.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Dalam bahasa Indonesia, \"sekalian\" dan \"sambil\" kadang tertukar, tapi bahasa Jepang membedakannya dengan jelas. Contohnya dalam situasi pergi ke stasiun:<br><b>ついでに</b>＝memanfaatkan kesempatan saat melakukan A untuk <b>mengerjakan satu hal lagi</b>; kedua hal itu belum tentu dilakukan bersamaan: <span class='gd-jp'>駅に行くついでに、手紙を出した。</span>（Waktu pergi ke stasiun, sekalian mengirim surat）<br><b>ながら</b>＝dua hal <b>berlangsung bersamaan</b>: <span class='gd-jp'>音楽を聞きながら、駅まで歩いた。</span>（Sambil mendengarkan musik, aku berjalan sampai stasiun）</div><div class='gd-warn'>Tips membedakan: kalau maksudnya \"sekalian mengerjakan satu hal lagi\", pakai ついでに; kalau \"sambil…\" dan dikerjakan bersamaan, pakai ながら.</div>","n3-16":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜てからでないと」artinya <b>「harus ～ dulu baru bisa ～」「kalau belum ～, tidak bisa ～」</b>. Seperti 「harus beli tiket dulu baru boleh masuk」 atau 「harus cuci tangan dulu baru boleh makan」. Intinya: <b>urutannya tidak boleh terbalik, hal di depan harus selesai dulu</b>.</div><div class='gd-h'>Dibongkar jadi gampang</div><div class='gd-sec'>Sebenarnya ini gabungan tiga bagian:<br>bentuk <span class='gd-jp'>て</span>（sudah melakukan ～）＋<span class='gd-jp'>から</span>（setelah）＋<span class='gd-jp'>でないと</span>（kalau tidak）<br>Digabung artinya \"kalau bukan setelah selesai ～\", yaitu \"kalau belum melakukan ～\".</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Ubah verba ke bentuk て dulu, lalu langsung tambahkan 「からでないと」.<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べて</span> → <span class='gd-jp'>食べてからでないと</span></span><br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>して</span> → <span class='gd-jp'>してからでないと</span></span><br><span class='gd-pair'><span class='gd-jp'>聞く</span> → <span class='gd-jp'>聞いて</span> → <span class='gd-jp'>聞いてからでないと</span></span></div><div class='gd-h'>Apa yang disambungkan di belakang</div><div class='gd-sec'>Bagian belakang hampir selalu berupa kalimat negatif seperti <b>「tidak boleh, tidak bisa, tidak mungkin」</b>: <span class='gd-jp'>できない</span>、<span class='gd-jp'>わからない</span>、<span class='gd-jp'>だめだ</span>、<span class='gd-jp'>無理だ</span>, bentuk negatif dari bentuk potensial verba, dan sebagainya.</div><div class='gd-ex-line'>・<span class='gd-jp'>手を洗ってからでないと、おやつはだめだよ。</span>（Kalau belum cuci tangan, tidak boleh makan camilan ya）</div><div class='gd-ex-line'>・<span class='gd-jp'>実際に見てからでないと、買うかどうか決められない。</span>（Kalau belum lihat langsung, aku tidak bisa memutuskan mau beli atau tidak）</div><div class='gd-ex-line'>・<span class='gd-jp'>お金を払ってからでないと、商品はお渡しできません。</span>（Barangnya baru bisa kami serahkan setelah Anda membayar）</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>からでないと</span>Bentuk umum, bisa dipakai dalam lisan maupun tulisan.<br><span class='gd-tag'>からでなければ</span>Lebih formal dan kaku, sering muncul di pengumuman dan dokumen petunjuk.<br><span class='gd-tag'>からじゃないと</span>Versi lisan di antara teman.</div><div class='gd-ex-line'>・<span class='gd-jp'>宿題やってからじゃないと、ゲームはできないよ。</span>（Kalau PR belum selesai, tidak boleh main game ya）</div><div class='gd-h'>Bagian yang mudah keliru</div><div class='gd-warn'>・Bagian belakang <b>tidak boleh berupa kalimat positif yang berarti \"boleh\"</b>. <span class='gd-jp'>予約してからでないと、入れます</span> itu salah; kalau mau bilang \"reservasi dulu baru masuk\", cukup pakai <span class='gd-jp'>予約してから入ります</span>.<br>・「<b>で</b>」di tengah tidak boleh hilang; menulis 「てからないと」itu salah.<br>・Bentuk て harus benar: <span class='gd-jp'>行く</span> jadi <span class='gd-jp'>行って</span>, <span class='gd-jp'>書く</span> jadi <span class='gd-jp'>書いて</span>. Kalau salah di sini, seluruh kalimat ikut salah.<br>・Nuansanya terdengar seperti \"aturan\" atau \"syarat\", jadi saat bicara dengan pelanggan, bagian belakang harus pakai bahasa sopan, misalnya <span class='gd-jp'>できません</span>、<span class='gd-jp'>お渡しできません</span>.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Situasinya sama: sebelum menandatangani kontrak, kamu harus membaca kontraknya.<br><b>てから</b>＝sekadar menyatakan <b>urutan</b>, A dulu baru B: <span class='gd-jp'>内容を確認してから、サインします。</span>（Aku cek isinya dulu, baru tanda tangan）<br><b>てからでないと</b>＝menekankan <b>harus A dulu, kalau tidak B tidak bisa dilakukan</b>: <span class='gd-jp'>内容を確認してからでないと、サインできません。</span>（Kalau belum cek isinya, aku tidak bisa tanda tangan）<br><b>た上で</b>＝setelah A selesai, lalu melakukan B <b>berdasarkan hasil A</b>, lebih formal dan hati-hati: <span class='gd-jp'>内容を確認した上で、サインします。</span>（Setelah memeriksa isinya, saya akan menandatangani）</div><div class='gd-warn'>Tips membedakan: kalau bagian belakangnya \"bisa dilakukan / akan dilakukan\", pakai <b>てから</b> atau <b>た上で</b>; kalau bagian belakangnya \"tidak boleh / tidak bisa\" dan kamu ingin menekankan \"harus ～ dulu\", pakai <b>てからでないと</b>.</div><div class='gd-h'>Setelah paham, lanjut belajar ini</div><div class='gd-sec'>Kamu bisa lanjut ke 「<span class='gd-jp'>〜上で</span>」（n3-23）, yang sering dipakai dalam situasi formal untuk mengatakan \"～ dulu baru ～\": <span class='gd-jp'>よく考えた上で、決めてください。</span>（Silakan putuskan setelah dipikirkan baik-baik）</div>","n3-18":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>「〜としたら」artinya kurang lebih <b>「seandainya benar-benar ～」</b>. Kamu mengandaikan satu situasi yang belum pasti, bahkan mungkin mustahil, <b>seolah-olah benar terjadi</b>. Setelah itu baru kamu lanjutkan dengan \"lalu apa yang terjadi\" atau \"lalu aku ingin apa\". Rasanya mirip ngobrol dengan teman: \"Misalnya nih, misalnya kamu menang lotre……\".</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Pengandaian murni</span>Untuk hal yang kecil kemungkinannya atau belum terjadi. Sering muncul bersama <span class='gd-jp'>もし</span> atau <span class='gd-jp'>仮に</span> (seandainya).</div><div class='gd-ex-line'>・<span class='gd-jp'>もし宝くじが当たったとしたら、何に使う？</span>(Seandainya kamu menang lotre, uangnya mau dipakai untuk apa?)</div><div class='gd-ex-line'>・<span class='gd-jp'>一週間休めるとしたら、どこに行きたい？</span>(Kalau kamu bisa libur seminggu, kamu mau pergi ke mana?)</div><div class='gd-sec'><span class='gd-tag'>Menyimpulkan dari kabar yang didengar</span>Kamu anggap dulu ucapan orang lain atau kabar yang kamu dengar itu benar, lalu menarik kesimpulan darinya.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の話が本当だとすれば、大変なことだ。</span>(Kalau yang dia bilang itu benar, berarti ini masalah besar)</div><div class='gd-sec'><span class='gd-tag'>Di awal kalimat</span>Tambahkan <span class='gd-jp'>だ</span> di depannya sehingga jadi <span class='gd-jp'>だとしたら</span> atau <span class='gd-jp'>だとすると</span>. Artinya \"kalau begitu\", dan kamu melanjutkan dari apa yang baru saja dikatakan lawan bicara.</div><div class='gd-ex-line'>・<span class='gd-jp'>A：明日は台風が来るらしいよ。</span>(Katanya besok ada topan)</div><div class='gd-ex-line'>・<span class='gd-jp'>B：だとすると、旅行は無理だね。</span>(Kalau begitu, sepertinya kita tidak bisa pergi liburan)</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Kata kerja dan kata sifat-い disambung langsung:<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くとしたら</span></span><span class='gd-pair'><span class='gd-jp'>当たった</span> → <span class='gd-jp'>当たったとしたら</span></span><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いとしたら</span></span><br>Kata benda dan kata sifat-な harus diberi <b>だ</b> dulu:<br><span class='gd-pair'><span class='gd-jp'>雨</span> → <span class='gd-jp'>雨だとしたら</span></span><span class='gd-pair'><span class='gd-jp'>暇</span> → <span class='gd-jp'>暇だとしたら</span></span><br>Ketiga bentuk <span class='gd-jp'>としたら</span>、<span class='gd-jp'>とすれば</span>、<span class='gd-jp'>とすると</span> cara menyambungnya sama persis.</div><div class='gd-h'>Memilih di antara tiga bentuk</div><div class='gd-sec'><b>としたら</b>: paling santai dan paling praktis. Kalau di belakangnya ada keinginan atau rencanamu sendiri seperti \"ingin ～\" atau \"mau ～\", inilah yang paling natural.<br><b>とすれば・とすると</b>: lebih berkesan \"menyimpulkan\". Di belakangnya sering ada penilaian seperti <span class='gd-jp'>〜だろう</span>、<span class='gd-jp'>〜はずだ</span>、<span class='gd-jp'>〜必要がある</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>明日雨だとすれば、運動会は延期だろう。</span>(Kalau besok hujan, acara olahraga kemungkinan besar ditunda)</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Jangan lupa <b>だ</b> untuk kata benda dan kata sifat-な: yang benar <span class='gd-jp'>雨だとしたら</span>, bukan 「雨としたら」.<br>・Kalau kata benda <b>tanpa だ</b> langsung disambung <span class='gd-jp'>としたら</span>, artinya jadi lain, yaitu \"dari sudut pandang ～\": <span class='gd-jp'>親としたら、心配だろう。</span>(Dari sudut pandang orang tua, pasti khawatir)<br>・<b>Hal yang pasti terjadi tidak bisa dipakai di sini</b>: \"Telepon aku kalau sudah sampai rumah\" adalah <span class='gd-jp'>家に着いたら電話して</span>. Kalau kamu bilang 「着いたとしたら」, kedengarannya seperti meragukan kamu bakal sampai rumah.<br>・Setelah <span class='gd-jp'>とすると</span> jarang ada ungkapan \"ingin ～\" atau \"tolong ～\". Untuk itu, ganti dengan <span class='gd-jp'>としたら</span>.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'><b>たら</b> = \"kalau ～ / setelah ～\" yang umum, dan hal itu mungkin benar-benar terjadi:<br><span class='gd-jp'>宝くじが当たったら、車を買う。</span>(Kalau menang, aku beli mobil)<br><b>としたら</b> = menekankan khusus bahwa \"ini cuma pengandaian\":<br><span class='gd-jp'>宝くじが当たったとしたら、車を買う。</span>(Seandainya benar-benar menang, aku akan beli mobil)<br>Untuk hal yang pasti terjadi, hanya たら yang bisa dipakai: <span class='gd-jp'>家に着いたら連絡するね。</span>(Nanti kukabari kalau sudah sampai rumah)</div><div class='gd-warn'>Tips menilai: kalau dalam bahasa Indonesia bisa kamu ucapkan \"seandainya benar-benar ～\" atau \"andai kata ～\", pakai としたら. Kalau cuma \"setelah ～ lalu ～\", pakai たら.</div>","n3-19":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>「〜たところ」artinya kurang lebih <b>\"setelah ～, ternyata…\"</b>. Kamu melakukan sesuatu dulu (menelepon untuk bertanya, mencari informasi, mencoba memakai), baru setelah itu tahu hasilnya. Contohnya: \"Aku telepon tokonya untuk tanya, ternyata sudah habis.\"<br><span class='gd-jp'>ところ</span> di sini tidak ada hubungannya dengan \"tempat\". Anggap saja itu \"tombol\" yang membuka hasilnya.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Kata kerja bentuk た + ところ.<br><span class='gd-pair'><span class='gd-jp'>聞く</span> → <span class='gd-jp'>聞いた</span> → <span class='gd-jp'>聞いたところ</span></span><br><span class='gd-pair'><span class='gd-jp'>調べる</span> → <span class='gd-jp'>調べた</span> → <span class='gd-jp'>調べたところ</span></span><br><span class='gd-pair'><span class='gd-jp'>電話する</span> → <span class='gd-jp'>電話した</span> → <span class='gd-jp'>電話したところ</span></span><br>Kalimatnya terbagi dua: bagian depan adalah <b>hal yang kamu lakukan</b>, bagian belakang adalah <b>hasil yang baru kamu ketahui atau muncul setelah melakukannya</b>.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Baru tahu setelah bertanya</span>Kabar yang kamu dapat setelah bertanya pada orang atau menelepon untuk memastikan.</div><div class='gd-ex-line'>・<span class='gd-jp'>店に電話したところ、もう売り切れだった。</span>(Aku telepon tokonya, ternyata sudah habis)</div><div class='gd-ex-line'>・<span class='gd-jp'>先生に相談したところ、いいアドバイスをもらえた。</span>(Setelah konsultasi dengan guru, aku mendapat saran yang bagus)</div><div class='gd-sec'><span class='gd-tag'>Baru tahu setelah mencoba</span>Hasil setelah mencari tahu atau mencoba sesuatu.</div><div class='gd-ex-line'>・<span class='gd-jp'>詳しく調べたところ、原因がわかった。</span>(Setelah diperiksa dengan teliti, penyebabnya ketahuan)</div><div class='gd-ex-line'>・<span class='gd-jp'>この薬を飲んだところ、熱が下がった。</span>(Setelah minum obat ini, demamnya turun)</div><div class='gd-sec'>Nuansanya cukup formal, sering muncul di laporan, email bisnis, dan berita. Kalau ngobrol dengan teman, biasanya langsung pakai 「〜たら」.</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Kalimat bagian belakang berisi <b>hal yang sudah terjadi dan sudah diketahui</b>, jadi biasanya berbentuk lampau. Tidak bisa diikuti rencana, permintaan, atau perintah:<br>×<span class='gd-jp'>調べたところ、先生に聞きます。</span><br>○<span class='gd-jp'>調べてから、先生に聞きます。</span>(Setelah mencari tahu, baru aku tanya guru)<br>・Bagian depan biasanya <b>hal yang kamu lakukan sendiri dengan sengaja</b>. Hal yang terjadi dengan sendirinya seperti hujan turun kurang cocok ditaruh di depan:<br>×<span class='gd-jp'>雨が降ったところ、涼しくなった。</span><br>○<span class='gd-jp'>雨が降ったら、涼しくなった。</span>(Setelah hujan turun, jadi sejuk)<br>・Intinya adalah \"hasil yang baru kamu sadari setelah melakukannya\", pola ini sendiri tidak berarti \"karena ～ maka ～\". Kadang depan dan belakang kebetulan berhubungan sebab-akibat (minum obat → demam turun), kadang tidak (menelepon toko bukan penyebab barangnya habis, hanya jadi jalan untuk kamu tahu). Dua-duanya boleh.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'><b>たところ</b> = setelah melakukan sesuatu, <b>masih ada kalimat hasil setelahnya</b>:<br><span class='gd-jp'>駅員に聞いたところ、電車は遅れているそうだ。</span>(Aku tanya petugas stasiun, katanya kereta terlambat)<br><b>たところだ</b> = <b>baru saja</b> selesai melakukan, dan kalimat berhenti di situ:<br><span class='gd-jp'>今、駅員に聞いたところだ。</span>(Aku baru saja bertanya pada petugas stasiun)<br><b>たら</b> = bisa juga berarti \"setelah ～ ternyata\", tapi lebih santai dan cakupan pemakaiannya lebih luas:<br><span class='gd-jp'>駅員に聞いたら、電車が遅れてるって。</span>(Aku tanya petugas stasiun, katanya kereta terlambat)</div><div class='gd-warn'>Tips menilai: kalau setelah 「ところ」 ada koma dan masih ada kalimat hasil, itu たところ. Kalau kalimat berhenti di 「ところだ」, artinya \"baru saja selesai\". Untuk menyampaikan hasil dalam situasi formal pakai たところ, kalau ngobrol dengan teman pakai たら.</div><div class='gd-h'>Setelah ini bisa lanjut belajar</div><div class='gd-sec'>Coba kembali bandingkan dengan tiga titik waktu <span class='gd-jp'>〜ところだ</span> (hendak melakukan, sedang melakukan, baru saja selesai), supaya tidak tertukar dengan たところ.</div>","n3-22":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜以上（は）」kira-kira berarti <b>\"karena sudah ~, maka ~\"</b> atau <b>\"mengingat ~, berarti ~\"</b>. Bagian depan menyebut hal yang sudah pasti, lalu bagian belakang berisi \"jadi aku harus ~\" atau \"jadi sudah seharusnya ~\". Rasanya mirip kalau kita bilang, \"Kan sudah janji, ya harus ditepati.\" Ada nuansa tekad: <b>karena sudah begini, aku harus bertanggung jawab</b>.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Kata kerja</b>: langsung sambung setelah bentuk biasa (bentuk tanpa ます).<br><span class='gd-pair'><span class='gd-jp'>約束した</span> → <span class='gd-jp'>約束した以上</span></span>（karena sudah janji）<br><span class='gd-pair'><span class='gd-jp'>やる</span> → <span class='gd-jp'>やる以上</span></span>（karena mau melakukannya）<br><span class='gd-pair'><span class='gd-jp'>来ない</span> → <span class='gd-jp'>来ない以上</span></span>（karena tidak datang）</div><div class='gd-sec'><b>Kata benda dan kata sifat-な</b>: harus ditambah 「である」, tidak bisa langsung disambung.<br><span class='gd-pair'><span class='gd-jp'>学生</span> → <span class='gd-jp'>学生である以上</span></span>（karena berstatus pelajar）<br><span class='gd-pair'><span class='gd-jp'>プロ</span> → <span class='gd-jp'>プロである以上</span></span>（karena seorang profesional）</div><div class='gd-sec'>「は」di belakangnya boleh ada, boleh tidak. Kalau ditambah, nadanya sedikit lebih kuat, tapi artinya sama.</div><div class='gd-h'>Apa yang datang di belakang?</div><div class='gd-sec'>Kuncinya ada di paruh kedua kalimat: isinya harus <b>tekad, kewajiban, atau penilaian</b> si pembicara, bukan sekadar menceritakan kejadian.</div><div class='gd-sec'><span class='gd-tag'>Aku akan ~ (tekad)</span></div><div class='gd-ex-line'>・<span class='gd-jp'>引き受けた以上は、最後までやります。</span>（Karena sudah menerima tugas ini, aku akan mengerjakannya sampai akhir）</div><div class='gd-ex-line'>・<span class='gd-jp'>やる以上は、一番を目指したい。</span>（Kalau mau melakukannya, aku ingin mengincar juara satu）</div><div class='gd-sec'><span class='gd-tag'>Seharusnya ~ / harus ~ (kewajiban)</span></div><div class='gd-ex-line'>・<span class='gd-jp'>日本に住んでいる以上、日本の法律を守らなければならない。</span>（Karena tinggal di Jepang, kita harus menaati hukum Jepang）</div><div class='gd-ex-line'>・<span class='gd-jp'>プロである以上、言い訳はできない。</span>（Karena seorang profesional, tidak boleh mencari-cari alasan）</div><div class='gd-sec'><span class='gd-tag'>Berarti hanya bisa ~ (penilaian)</span></div><div class='gd-ex-line'>・<span class='gd-jp'>本人が来ない以上、この話は進められない。</span>（Karena orangnya sendiri tidak datang, pembicaraan ini tidak bisa dilanjutkan）</div><div class='gd-sec'>Kalau bagian depan memakai bentuk <span class='gd-jp'>た</span>, artinya \"sudah terjadi, jadi ~\". Kalau memakai bentuk kamus, artinya \"karena memang mau begitu / karena statusnya begini, jadi ~\".</div><div class='gd-h'>Hal yang sering keliru</div><div class='gd-warn'>・Kata benda harus ditambah である: yang benar <span class='gd-jp'>学生である以上</span>, bukan 「学生な以上」. Kalau ditulis langsung <span class='gd-jp'>学生以上</span>, itu akan dibaca sebagai arti lain (tingkat di atas pelajar).<br>・Paruh kedua tidak boleh sekadar fakta biasa. Kamu tidak bisa bilang 「雨が降った以上、試合が中止になった」, karena \"pertandingan dibatalkan\" hanya kejadian, bukan tekad atau penilaian.<br>・<span class='gd-jp'>以上</span> juga punya arti lain, jangan dicampur: <span class='gd-jp'>三人以上</span> artinya \"tiga orang ke atas\", dan <span class='gd-jp'>以上です</span> yang diucapkan di akhir presentasi artinya \"demikian, selesai\".<br>・Nadanya cukup serius dan penuh tekad, jadi sering dipakai untuk topik tanggung jawab, janji, dan status. Kalau dipakai untuk hal sepele, terdengar berlebihan.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Yang paling gampang tertukar adalah <b>から</b> yang hanya menyatakan sebab.<br><span class='gd-jp'>約束したから、行きます。</span>（Karena sudah janji, aku akan pergi）: hanya menjelaskan alasan.<br><span class='gd-jp'>約束した以上、行かなければならない。</span>（Karena sudah janji, aku harus pergi）: menekankan \"hal ini sudah terjadi, jadi aku punya tanggung jawab\".<br>Selain itu, <span class='gd-jp'>雨が降ったから、試合が中止になった。</span>（Karena hujan, pertandingan dibatalkan）boleh memakai から, tapi kalau diganti 以上 jadi salah, sebab bagian belakangnya hanya kejadian.</div><div class='gd-warn'>Kiat cepat: kalau belakangnya berupa tekad atau penilaian seperti \"aku harus, seharusnya, hanya bisa\", pakai 以上. Kalau hanya sebab dan akibat, pakai から.</div><div class='gd-h'>Setelah ini, belajar apa lagi?</div><div class='gd-sec'>Sering muncul bersama <span class='gd-jp'>べきだ</span>: <span class='gd-jp'>約束した以上、守るべきだ。</span>（Karena sudah janji, seharusnya ditepati）. Nanti kamu juga akan belajar <span class='gd-jp'>からには</span> dan <span class='gd-jp'>上は</span> yang artinya hampir sama; <span class='gd-jp'>上は</span> lebih bergaya tulisan dan lebih formal.</div>","n3-23":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜上で」punya dua arti, dan <b>kamu bisa tahu yang mana dari bentuk yang ada di depannya</b>:<br>Kalau disambung dengan <b>bentuk た</b>: \"selesaikan ~ dengan baik dulu, <b>baru</b> …\", seperti \"dibicarakan dulu, <b>setelah itu</b> baru diputuskan\".<br>Kalau disambung dengan <b>bentuk kamus</b> (bentuk asli yang ada di kamus): \"<b>dalam hal</b> melakukan ~\", seperti \"dalam hidup di Jepang, bahasa sopan (敬語) itu penting\".</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><span class='gd-tag'>① Selesaikan dulu, baru …</span>Bentuk た＋上で／Kata benda の＋上で<br><span class='gd-pair'><span class='gd-jp'>相談する</span> → <span class='gd-jp'>相談した上で</span></span><span class='gd-pair'><span class='gd-jp'>確認</span> → <span class='gd-jp'>確認の上で</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>よく考えた上で、返事します。</span>（Setelah kupikirkan baik-baik, aku akan membalas）</div><div class='gd-ex-line'>・<span class='gd-jp'>家族とよく相談した上で、転職を決めた。</span>（Setelah berdiskusi baik-baik dengan keluarga, aku memutuskan untuk pindah kerja）</div><div class='gd-sec'>Intinya, hal di depan adalah <b>persiapan yang diperlukan</b>; setelah itu selesai, baru lanjut ke bagian belakang. Di belakang sering ada tindakan seperti \"mengambil keputusan, mengurus prosedur\", misalnya <span class='gd-jp'>決める</span>、<span class='gd-jp'>申し込む</span>、<span class='gd-jp'>返事する</span>.</div><div class='gd-sec'><span class='gd-tag'>② Dalam hal ~</span>Bentuk kamus＋上で／Kata benda の＋上で<br><span class='gd-pair'><span class='gd-jp'>生活する</span> → <span class='gd-jp'>生活する上で</span></span><span class='gd-pair'><span class='gd-jp'>仕事</span> → <span class='gd-jp'>仕事の上で</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>日本で生活する上で、敬語は大切だ。</span>（Dalam hidup di Jepang, bahasa sopan itu penting）</div><div class='gd-ex-line'>・<span class='gd-jp'>この本は日本語を勉強する上で役に立つ。</span>（Buku ini berguna dalam belajar bahasa Jepang）</div><div class='gd-ex-line'>・<span class='gd-jp'>仕事の上での付き合いは大切です。</span>（Hubungan dalam urusan pekerjaan itu penting）</div><div class='gd-sec'>Bagian belakang umumnya berupa penilaian: <span class='gd-jp'>大切だ</span>、<span class='gd-jp'>必要だ</span>、<span class='gd-jp'>欠かせない</span>、<span class='gd-jp'>役に立つ</span>、<span class='gd-jp'>注意が必要だ</span>. Kalau di belakangnya kata benda, ganti で menjadi <b>での</b>, seperti <span class='gd-jp'>仕事の上での付き合い</span> di atas.</div><div class='gd-h'>Bentuk yang paling sering kamu temui</div><div class='gd-sec'>Di pengumuman, formulir, dan keterangan toko, kamu sering melihat 「<b>ご＋kata benda＋の上</b>」; で sering dihilangkan. Ini ungkapan tulisan yang sangat sopan.</div><div class='gd-ex-line'>・<span class='gd-jp'>内容をご確認の上、サインしてください。</span>（Silakan tanda tangan setelah memeriksa isinya）</div><div class='gd-h'>Hal yang sering keliru</div><div class='gd-warn'>・Kalau salah bentuk, artinya melenceng: <span class='gd-jp'>相談した上で</span> artinya \"setelah selesai berunding\", sedangkan <span class='gd-jp'>相談する上で</span> artinya \"dalam hal berunding\" (contoh: <span class='gd-jp'>相談する上で大切なこと</span> = hal penting saat berunding). Untuk mengatakan \"setelah itu baru ...\", selalu pakai bentuk た.<br>・① bukan sekadar \"lalu\" biasa. <span class='gd-jp'>ご飯を食べた上で、テレビを見た</span> terdengar aneh; untuk urutan kejadian sehari-hari, cukup pakai <span class='gd-jp'>〜てから</span>.<br>・「上」di sini dibaca <b>うえ</b>. Ada juga <span class='gd-jp'>仕事上</span> yang langsung menempel pada kata benda dan dibaca しごと<b>じょう</b>. Artinya mirip <span class='gd-jp'>仕事の上で</span>, tapi tulisan dan bacaannya berbeda, jadi jangan dicampur.<br>・Jangan tulis menjadi 「上に」. <span class='gd-jp'>〜上に</span> artinya \"bukan hanya ~, tapi juga ~\", itu tata bahasa yang lain.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>た上で vs てから</b><br><span class='gd-jp'>家族と相談してから決めます。</span>（Berunding dulu dengan keluarga, lalu memutuskan: hanya soal urutan）<br><span class='gd-jp'>家族と相談した上で決めます。</span>（Setelah berunding baik-baik dengan keluarga, berdasarkan itu baru memutuskan: menekankan bahwa langkah itu benar-benar dijalani）<br>てから bisa dipakai di situasi apa saja; た上で lebih formal, dipakai untuk keputusan penting.</div><div class='gd-sec'><b>る上で vs ために</b><br><span class='gd-jp'>日本で働くために、日本語を勉強しています。</span>（Untuk bekerja di Jepang, aku belajar bahasa Jepang）<br><span class='gd-jp'>日本で働く上で、日本語は欠かせません。</span>（Dalam bekerja di Jepang, bahasa Jepang tidak bisa ditinggalkan）<br>Dalam bahasa Indonesia keduanya bisa terdengar mirip, tapi setelah ために datang <b>hal yang kamu lakukan demi tujuan itu</b>, sedangkan setelah る上で datang <b>apa yang dibutuhkan atau apa yang penting dalam hal itu</b>.</div><div class='gd-warn'>Kiat cepat: kalau mau bilang \"selesaikan ~ dulu, baru …\", pakai <b>た上で</b>. Kalau mau bilang \"saat melakukan ~, apa yang penting\", pakai <b>る上で</b>. Kalau belakangnya \"aku melakukan sesuatu\", pakai <b>ために</b>.</div>","n3-27":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜をはじめ」artinya <b>「mulai dari ~」「~ dan lainnya, semuanya…」</b>. Kamu menyebut satu hal yang paling mewakili dan paling terkenal dulu, lalu menyinggung anggota lain dalam kelompok yang sama. Mirip waktu kamu memperkenalkan kuliner Indonesia: kamu bilang dulu «nasi goreng», lalu lanjut «sate, rendang, dan sebagainya».</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Di depannya hanya boleh <b>kata benda</b>. <span class='gd-jp'>をはじめ</span> dan <span class='gd-jp'>をはじめとして</span> artinya sama; kalau pakai として, kesannya lebih formal dan lengkap.<br><span class='gd-pair'><span class='gd-jp'>東京</span> → <span class='gd-jp'>東京をはじめ</span></span><span class='gd-pair'><span class='gd-jp'>社長</span> → <span class='gd-jp'>社長をはじめとして</span></span><br>Kalau mau langsung disambung ke kata benda, pakai <b>をはじめとする＋kata benda</b>: <span class='gd-jp'>寿司をはじめとする日本料理</span> (masakan Jepang yang diwakili oleh sushi).</div><div class='gd-h'>Pola yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>Menyebut perwakilan</span>Sebut dulu yang paling terkenal, lalu bilang masih banyak lagi.</div><div class='gd-ex-line'>・<span class='gd-jp'>日本には、東京をはじめ、大きな都市がたくさんある。</span>(Di Jepang ada banyak kota besar, mulai dari Tokyo dan lainnya)</div><div class='gd-sec'><span class='gd-tag'>Yang berkedudukan tertinggi memimpin</span>Menyebut dari orang paling atas sampai semua orang. Sering terdengar di perusahaan dan upacara.</div><div class='gd-ex-line'>・<span class='gd-jp'>社長をはじめ、社員全員が会議に出た。</span>(Mulai dari direktur sampai seluruh karyawan hadir di rapat)</div><div class='gd-sec'><span class='gd-tag'>をはじめとする</span>Dipakai sebagai penjelas, langsung disambung ke kata benda.</div><div class='gd-ex-line'>・<span class='gd-jp'>寿司をはじめとする日本料理は、海外でも人気だ。</span>(Masakan Jepang yang diwakili sushi populer juga di luar negeri)</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Di depannya taruh yang <b>paling mewakili, paling terkenal, atau berkedudukan paling tinggi</b>. <span class='gd-jp'>社員をはじめ、社長も参加した</span> terdengar aneh karena urutannya terbalik. Yang benar: <span class='gd-jp'>社長をはじめ、社員も参加した</span>.<br>・Di belakangnya harus ada kesan «masih ada yang lain». Biasanya dipasangkan dengan <span class='gd-jp'>や</span>, <span class='gd-jp'>など</span>, <span class='gd-jp'>多くの</span>, <span class='gd-jp'>全員</span>, <span class='gd-jp'>も</span>. Kalau hanya menyebut satu hal, pola ini tidak bisa dipakai.<br>・はじめ di sini bukan «awal» dalam arti waktu. «Mulai bulan September» harus <span class='gd-jp'>9月から</span>, tidak boleh 9月をはじめ.<br>・Nuansanya agak formal, sering dipakai di berita, pemandu wisata, dan sambutan. Kalau ngobrol dengan teman, <span class='gd-jp'>京都とか奈良とか</span> terdengar lebih natural.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>を中心に</b> juga menaruh sesuatu di posisi terdepan, tapi artinya berbeda. Lihat hujan yang sama ini:<br><span class='gd-jp'>東京をはじめ、関東の各地で雨が降った。</span>(Hujan turun di Tokyo dan berbagai tempat di Kanto)<br>→ Semua tempat kebagian, hanya saja Tokyo disebut duluan.<br><span class='gd-jp'>東京を中心に雨が降った。</span>(Hujan turun dengan Tokyo sebagai pusatnya)<br>→ Hujan terpusat di sekitar Tokyo; makin ke luar makin sedikit.</div><div class='gd-warn'>Trik membedakan: kalau mau bilang «~ dan lainnya, semuanya…», pakai をはじめ; kalau mau bilang «titik beratnya ada di ~», pakai を中心に.</div>","n3-31":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜ほど」artinya <b>「sampai ~」「~ banget sampai…」</b>. Kamu tidak langsung bilang «sangat», tapi memberi sebuah gambaran supaya lawan bicara merasakan sendiri seberapa hebatnya. Seperti di bahasa Indonesia «capek setengah mati» atau «ketawa sampai nangis», di bahasa Jepang jadi <span class='gd-jp'>死ぬほど疲れた</span> dan <span class='gd-jp'>涙が出るほど笑った</span>.</div><div class='gd-h'>Pahami urutan kalimatnya dulu</div><div class='gd-sec'>Dalam bahasa Indonesia kita bilang «capek» dulu, baru «setengah mati». Bahasa Jepang justru <b>kebalikannya</b>: sebut dulu gambarannya, baru seberapa tingkatnya.<br>【Gambaran】＋ほど＋【Keadaannya】</div><div class='gd-ex-line'>・<span class='gd-jp'>涙が出るほど感動した。</span>(Terharu sampai menangis)</div><div class='gd-ex-line'>・<span class='gd-jp'>眠れないほど楽しみにしていた。</span>(Sangat menantikannya sampai tidak bisa tidur)</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Kata kerja</b>: bentuk kamus atau bentuk ない, langsung tambah ほど.<br><span class='gd-pair'><span class='gd-jp'>涙が出る</span> → <span class='gd-jp'>涙が出るほど</span></span><span class='gd-pair'><span class='gd-jp'>眠れない</span> → <span class='gd-jp'>眠れないほど</span></span><br><b>Kata sifat い</b>: langsung tambah ほど.<br><span class='gd-pair'><span class='gd-jp'>痛い</span> → <span class='gd-jp'>痛いほど</span></span><br><b>Kata sifat な</b>: tambah な dulu, baru ほど.<br><span class='gd-pair'><span class='gd-jp'>不思議</span> → <span class='gd-jp'>不思議なほど</span></span><br><b>Kata benda</b>: langsung tambah ほど.<br><span class='gd-pair'><span class='gd-jp'>山</span> → <span class='gd-jp'>山ほど</span></span></div><div class='gd-h'>Pola yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>死ぬほど</span>Sangat sering dipakai dalam percakapan, artinya «~ banget/setengah mati». Bukan benar-benar mau mati.</div><div class='gd-ex-line'>・<span class='gd-jp'>このラーメン、死ぬほどおいしい。</span>(Ramen ini enak banget)</div><div class='gd-sec'><span class='gd-tag'>山ほど</span>Banyaknya sampai menumpuk seperti gunung, artinya «banyak banget».</div><div class='gd-ex-line'>・<span class='gd-jp'>宿題が山ほどある。</span>(PR-nya menumpuk segunung)</div><div class='gd-sec'><span class='gd-tag'>痛いほどわかる</span>Paham sampai hati terasa sakit, artinya «benar-benar bisa merasakannya».</div><div class='gd-ex-line'>・<span class='gd-jp'>その気持ち、痛いほどわかるよ。</span>(Perasaanmu itu, aku benar-benar paham)</div><div class='gd-sec'><span class='gd-tag'>ほどだ</span>Boleh juga di akhir kalimat. Sebut dulu penyebabnya, lalu tutup dengan tingkat yang dilebih-lebihkan.</div><div class='gd-ex-line'>・<span class='gd-jp'>寒くて、手が動かないほどだった。</span>(Dinginnya sampai tangan tidak bisa digerakkan)</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Jangan menyusun urutannya seperti bahasa Indonesia: yang benar <span class='gd-jp'>涙が出るほど感動した</span>, bukan «感動したほど涙が出る».<br>・Jangan lupa な pada kata sifat な: yang benar <span class='gd-jp'>不思議なほど</span>, bukan 不思議ほど.<br>・Kalau ほど dipasang <b>setelah jumlah</b>, artinya lain: <span class='gd-jp'>3時間ほど待った</span> berarti «menunggu sekitar 3 jam». Di sini artinya «sekitar», bukan melebih-lebihkan.<br>・Kalau diikuti bentuk negatif, itu juga pemakaian lain: <span class='gd-jp'>今年の夏は去年ほど暑くない</span> berarti «musim panas tahun ini tidak sepanas tahun lalu». Ini perbandingan, bukan «sampai ~».</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>ほど dan くらい</b>: untuk menyatakan «tingkat yang dilebih-lebihkan», sebagian besar bisa saling menggantikan.<br><span class='gd-jp'>涙が出るほど笑った。</span>／<span class='gd-jp'>涙が出るくらい笑った。</span>(Keduanya «tertawa sampai menangis»)<br>くらい lebih kasual, ほど sedikit lebih formal.<br>Tapi untuk «<b>tingkatnya rendah, hal sepele</b>» hanya くらい yang bisa dipakai:<br><span class='gd-jp'>名前くらい自分で書いて。</span>(Setidaknya nama tulis sendiri dong)<br>Di sini tidak bisa diganti ほど, karena ほど mengarah ke «sangat berlebihan».</div><div class='gd-sec'><b>ほど dan ば〜ほど</b>: <span class='gd-jp'>練習すればするほど上手になる</span> berarti «makin banyak latihan, makin jago». Ini tentang dua hal yang berubah bersamaan, berbeda dengan «sampai ~» di pelajaran ini.</div><div class='gd-warn'>Trik membedakan: kalau mau bilang «saking ~», ほど dan くらい sama-sama bisa; kalau mau bilang «hal sepele, setidaknya ~», hanya くらい; kalau melihat «～ば～ほど», artinya «makin ~ makin ~».</div>","n3-25":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>Huruf 「限」 di <span class='gd-jp'>に限り</span> dan <span class='gd-jp'>に限って</span> artinya membatasi, yaitu <b>mempersempit cakupan sampai tinggal yang satu ini saja</b>. Pemakaiannya ada dua yang sangat berbeda. Yang pertama adalah <b>“khusus ～”</b> seperti di pengumuman. Yang kedua adalah <b>“kok justru ～”</b> saat kamu mengeluh soal keseharian, seperti dalam bahasa Indonesia: “Tiap kali lagi buru-buru, eh malah kena lampu merah.”</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Di depannya ada <b>kata benda</b>.<br>Kata benda langsung disambung: <span class='gd-pair'><span class='gd-jp'>本日</span> → <span class='gd-jp'>本日に限り</span></span><br>Kalau mau bilang “saat ～” atau “hari ketika ～”, lengkapi dulu dengan kata 「とき」 atau 「日」 setelah kata kerjanya, baru sambungkan:<br><span class='gd-pair'><span class='gd-jp'>急いでいる</span> → tambah とき → <span class='gd-jp'>急いでいるときに限って</span></span><br><span class='gd-pair'><span class='gd-jp'>傘を持っていない</span> → tambah 日 → <span class='gd-jp'>傘を持っていない日に限って</span></span></div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Khusus ～</span>Sering muncul di promo toko, tiket, dan peraturan. Nadanya cukup formal dan biasanya ditulis <span class='gd-jp'>に限り</span>. Artinya “hanya dalam cakupan ini yang boleh”.</div><div class='gd-ex-line'>・<span class='gd-jp'>先着100名様に限り、特典をプレゼントします。</span>(Hadiah spesial diberikan khusus untuk 100 pelanggan pertama)</div><div class='gd-ex-line'>・<span class='gd-jp'>このチケットは当日に限り有効です。</span>(Tiket ini hanya berlaku pada hari itu saja)</div><div class='gd-sec'><span class='gd-tag'>Kok justru ～</span>Biasanya tidak ada apa-apa, tapi justru di saat yang paling tidak kamu inginkan, ada masalah. Pola ini memakai <span class='gd-jp'>に限って</span>. Di belakangnya biasanya ada hal sial atau tidak sesuai harapan, dengan nada sedikit mengeluh.</div><div class='gd-ex-line'>・<span class='gd-jp'>傘を持っていない日に限って、急に雨が降る。</span>(Justru di hari aku tidak bawa payung, tiba-tiba hujan)</div><div class='gd-ex-line'>・<span class='gd-jp'>急いでいるときに限って、信号に引っかかる。</span>(Justru saat lagi buru-buru, malah kena lampu merah)</div><div class='gd-ex-line'>・<span class='gd-jp'>休みの日に限って、朝早く目が覚める。</span>(Justru di hari libur, aku bangun pagi-pagi sekali)</div><div class='gd-sec'><span class='gd-tag'>Dia pasti tidak mungkin</span>Di depannya ada orang yang sangat kamu percaya, dan di belakangnya ada “tidak mungkin ～”. Artinya “orang lain mungkin saja, tapi dia pasti tidak akan”.</div><div class='gd-ex-line'>・<span class='gd-jp'>うちの子に限って、うそをつくはずがない。</span>(Anakku pasti tidak mungkin berbohong)</div><div class='gd-ex-line'>・<span class='gd-jp'>あの真面目な田中さんに限って、約束を忘れるなんてありえない。</span>(Pak Tanaka yang serius itu tidak mungkin lupa janji)</div><div class='gd-h'>Bagian yang gampang keliru</div><div class='gd-warn'>・Arti “khusus” ini sangat formal, nadanya seperti pengumuman atau iklan. Kalau ngobrol dengan teman dan mau bilang “cuma hari ini”, cukup pakai <span class='gd-jp'>今日だけ</span>. Kalau pakai <span class='gd-jp'>今日に限り</span>, kesannya seperti membacakan pengumuman.<br>・<span class='gd-jp'>に限って</span> untuk arti “kok justru”, hampir selalu diikuti hal yang buruk. Jangan dipakai untuk hal yang menyenangkan.<br>・Untuk arti “dia pasti tidak”, di belakangnya harus ada bentuk negatif, seperti <span class='gd-jp'>はずがない</span> atau <span class='gd-jp'>ありえない</span>. Kalau kamu berhenti di <span class='gd-jp'>うちの子に限って</span> saja, orang Jepang pun tahu kamu mau bilang “tidak mungkin”.<br>・Jangan tertukar dengan <b><span class='gd-jp'>に限る</span></b>. Artinya “～ itu yang terbaik, pokoknya harus ～”: <span class='gd-jp'>暑い日は冷たいビールに限る。</span>(Hari panas ya paling pas minum bir dingin). Tulisannya beda sedikit saja, tapi artinya benar-benar lain.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Sama-sama bicara soal “hari ini”, tapi pemakaiannya beda dan artinya jauh berbeda:<br><span class='gd-jp'>本日に限り、入場無料です。</span>(Masuk gratis khusus hari ini) → pengumuman, “khusus”<br><span class='gd-jp'>今日に限って、財布を忘れた。</span>(Justru hari ini, aku lupa bawa dompet) → keluhan, “kok justru”<br><span class='gd-jp'>あの人に限って、そんなことはしない。</span>(Dia pasti tidak akan melakukan hal seperti itu) → kepercayaan, “dia pasti tidak”</div><div class='gd-warn'>Trik cepat menilai: kalau kamu lihat di pengumuman atau peraturan, artinya “khusus”. Kalau membicarakan nasib sialmu sendiri, artinya “kok justru”. Kalau di depannya orang dan di belakangnya “tidak mungkin”, artinya “dia pasti tidak”.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Kalau diubah ke bentuk negatif <span class='gd-jp'>に限らず</span>, artinya menjadi “tidak hanya ～”: <span class='gd-jp'>この店は週末に限らず、いつも混んでいる。</span>(Toko ini tidak hanya di akhir pekan, hari biasa pun selalu ramai)</div>","n3-26":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「きり」 punya dua wajah.<br>① Dipasang setelah kata benda = <b>“hanya ～”</b>, seperti “hanya kita berdua” atau “cuma sekali ini”.<br>② Dipasang setelah kata kerja bentuk た = <b>“sejak ～, tidak pernah lagi ～”</b>, seperti “pergi dan tak pernah kembali” atau “sejak itu tak ada kabar”.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><span class='gd-tag'>Hanya ～</span>Kata benda + きり. Kata bendanya kebanyakan jumlah orang, jumlah kali, atau 「これ」.<br><span class='gd-pair'><span class='gd-jp'>二人</span> → <span class='gd-jp'>二人きり</span></span>(hanya berdua) <span class='gd-pair'><span class='gd-jp'>一度</span> → <span class='gd-jp'>一度きり</span></span>(hanya sekali) <span class='gd-pair'><span class='gd-jp'>これ</span> → <span class='gd-jp'>これきり</span></span>(hanya ini saja)<br>Catatan: <span class='gd-jp'>あれきり</span> dan <span class='gd-jp'>それきり</span> biasanya bukan “hanya itu”, melainkan “sejak saat itu tidak ada lagi”, jadi termasuk pemakaian kedua di bawah.</div><div class='gd-ex-line'>・<span class='gd-jp'>二人きりで話したい。</span>(Aku mau bicara berdua saja)</div><div class='gd-ex-line'>・<span class='gd-jp'>チャンスは一度きりだ。</span>(Kesempatannya cuma sekali)</div><div class='gd-ex-line'>・<span class='gd-jp'>お金はこれきりしかない。</span>(Uangku tinggal segini saja)</div><div class='gd-sec'><span class='gd-tag'>Sejak itu tidak pernah lagi ～</span>Kata kerja bentuk た + きり. Ubah dulu kata kerjanya ke bentuk た, lalu tambahkan きり.<br><span class='gd-pair'><span class='gd-jp'>出かける</span> → <span class='gd-jp'>出かけた</span> → <span class='gd-jp'>出かけたきり</span></span><br>Yang mengikutinya adalah “hal yang seharusnya terjadi, tapi terus tidak terjadi”, jadi kalimatnya sering negatif. Bisa juga dipakai di akhir kalimat sebagai 「〜たきりだ」.</div><div class='gd-ex-line'>・<span class='gd-jp'>父は朝出かけたきり、まだ帰ってこない。</span>(Ayah pergi pagi tadi dan sampai sekarang belum pulang)</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女とは卒業式で会ったきりだ。</span>(Aku bertemu dengannya di upacara kelulusan, dan sejak itu tidak pernah bertemu lagi)</div><div class='gd-ex-line'>・<span class='gd-jp'>あれきり、彼から連絡はない。</span>(Sejak waktu itu, tidak ada kabar lagi darinya)</div><div class='gd-sec'>Ada satu kata yang sering muncul sehari-hari: <span class='gd-jp'>寝たきり</span> = sejak berbaring tidak bangun lagi = <b>terbaring di tempat tidur terus (tidak bisa bangun)</b>.<br><span class='gd-jp'>祖母は去年から寝たきりだ。</span>(Nenek sudah terbaring di tempat tidur sejak tahun lalu)</div><div class='gd-h'>Bagian yang gampang keliru</div><div class='gd-warn'>・Dalam percakapan sering dilafalkan <b>っきり</b>: <span class='gd-jp'>二人っきり</span>, <span class='gd-jp'>これっきり</span>. Artinya sama, jadi kalau mendengarnya jangan kira itu kata lain.<br>・Setelah 「たきり」 tidak bisa diikuti hal yang berarti “mulai melakukan hal baru”. Kalau mau bilang “sejak masuk perusahaan, tiap hari sibuk”, pakai てから: <span class='gd-jp'>会社に入ってから、毎日忙しい。</span> Kamu tidak bisa bilang 「会社に入ったきり、毎日忙しい」.<br>・きり sendiri sudah berarti “sejak itu”, jadi jangan ditumpuk dengan <span class='gd-jp'>以来</span>.<br>・Kalau 「○○きり」 dipakai untuk satu titik waktu, itu adalah <b>yang terakhir kali</b>, bukan berarti sebelumnya tidak pernah terjadi. <span class='gd-jp'>卒業式で会ったきり</span> artinya “upacara kelulusan adalah pertemuan terakhir”, bukan “hanya pernah bertemu sekali itu”.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>きり vs だけ</b>: keduanya bisa diartikan “hanya”, tapi きり hanya dipasang pada kata seperti jumlah orang, jumlah kali, atau これ, dan sering membawa kesan “tidak ada yang lain, ya sudah begitu saja”.<br><span class='gd-jp'>一人だけ来た。</span>／<span class='gd-jp'>一人きりだ。</span>(Hanya satu orang yang datang／Aku sendirian saja) Kedua cara ini boleh.<br><span class='gd-jp'>りんごだけ食べた。</span>(Aku cuma makan apel) Untuk benda biasa seperti ini, tidak bisa diganti dengan きり.</div><div class='gd-sec'><b>たきり vs っぱなし</b>: keduanya terasa seperti “sejak itu tidak ～”, tapi titik beratnya berbeda.<br><span class='gd-jp'>テレビをつけっぱなしで寝てしまった。</span>(Aku ketiduran dengan TV masih menyala): langkah penutup yang seharusnya dilakukan (mematikan) tidak dilakukan, dan keadaannya dibiarkan begitu saja.<br><span class='gd-jp'>兄は東京へ行ったきり、帰ってこない。</span>(Kakak pergi ke Tokyo dan tidak pernah pulang): setelah kejadian itu, hal selanjutnya tidak pernah terjadi lagi.</div><div class='gd-warn'>Trik cepat menilai: “hanya orang atau kali sebanyak ini” → kata benda + きり; “sejak saat itu tidak pernah lagi ～” → bentuk た + きり; “dibiarkan menyala atau terbuka tanpa dirapikan” → っぱなし.</div>","n3-32":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>「〜くらい」mirip dengan pola bahasa Indonesia <b>「sampai ～」</b>. Kita biasa bilang \"tertawa sampai perut sakit\" atau \"capek sampai nggak mau gerak\", yaitu memakai satu gambaran nyata untuk menunjukkan seberapa ekstrem suatu keadaan. Di bahasa Jepang, kamu pakai くらい: <span class='gd-jp'>お腹が痛くなるくらい笑った。</span>(Tertawa sampai perut sakit). <span class='gd-jp'>くらい</span> dan <span class='gd-jp'>ぐらい</span> artinya persis sama, jadi boleh pakai yang mana saja.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Gambaran berlebihan</span>Di depan くらい kamu taruh gambarannya, baru setelah itu keadaan yang sebenarnya ingin kamu sampaikan.</div><div class='gd-ex-line'>・<span class='gd-jp'>手が震えるくらい緊張した。</span>(Gugup sampai tangan gemetar)</div><div class='gd-ex-line'>・<span class='gd-jp'>泣きたいくらい悔しかった。</span>(Kesal sampai rasanya mau menangis)</div><div class='gd-ex-line'>・<span class='gd-jp'>朝の電車は動けないくらい混んでいる。</span>(Kereta pagi hari penuh sesak sampai tidak bisa bergerak)</div><div class='gd-sec'><span class='gd-tag'>Cuma segini</span>Sebaliknya, tingkatnya dibuat kecil, dengan kesan \"bukan masalah besar\".</div><div class='gd-ex-line'>・<span class='gd-jp'>これくらい、自分でできるよ。</span>(Cuma segini, aku bisa sendiri kok)</div><div class='gd-sec'><span class='gd-tag'>Setidaknya ～lah</span>Dipakai untuk hal yang \"minimal harus dilakukan\", sering dengan nada sedikit mengeluh.</div><div class='gd-ex-line'>・<span class='gd-jp'>忙しくても、電話くらいしてよ。</span>(Sesibuk apa pun, setidaknya telepon dong)</div><div class='gd-sec'><span class='gd-tag'>Tak ada yang lebih ～ dari ～</span>「名詞＋くらい～はない」dipakai untuk memuji habis-habisan atau menekankan sesuatu.</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんくらい優しい人はいない。</span>(Tidak ada orang yang sebaik Tanaka)</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Kata kerja</b>: bentuk kamus atau bentuk ない langsung disambung. Untuk hal yang ingin dilakukan, bentuk「たい」juga boleh.<br><span class='gd-pair'><span class='gd-jp'>震える</span> → <span class='gd-jp'>震えるくらい</span></span><span class='gd-pair'><span class='gd-jp'>動けない</span> → <span class='gd-jp'>動けないくらい</span></span><span class='gd-pair'><span class='gd-jp'>泣きたい</span> → <span class='gd-jp'>泣きたいくらい</span></span><br><b>Kata sifat い</b>: langsung disambung. <span class='gd-pair'><span class='gd-jp'>痛い</span> → <span class='gd-jp'>痛いくらい</span></span><br><b>Kata sifat な</b>: tambahkan「な」dulu. <span class='gd-pair'><span class='gd-jp'>不思議</span> → <span class='gd-jp'>不思議なくらい</span></span><br><b>Kata benda</b>: langsung disambung, tanpa「の」di tengah. <span class='gd-pair'><span class='gd-jp'>これ</span> → <span class='gd-jp'>これくらい</span></span><span class='gd-pair'><span class='gd-jp'>田中さん</span> → <span class='gd-jp'>田中さんくらい</span></span></div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Angka (jumlah) ＋くらい artinya \"kira-kira\", misalnya <span class='gd-jp'>三時間くらい</span> (kira-kira tiga jam). Kalau yang di depan kata kerja, kata sifat, atau kata benda bukan jumlah seperti <span class='gd-jp'>これ</span> dan <span class='gd-jp'>田中さん</span>, artinya \"sampai tingkat ～\".<br>・Jangan terbalik urutannya. Di depan くらい adalah gambaran perumpamaannya, di belakang adalah keadaan sebenarnya: <span class='gd-jp'>手が震えるくらい緊張した</span>, bukan「緊張したくらい手が震えた」.<br>・Kata kerja di depannya biasanya cukup bentuk kamus atau bentuk ない. Untuk kejadian lampau, ubah saja akhir kalimatnya ke bentuk lampau: <span class='gd-jp'>声が出ないくらい驚いた。</span>(Kaget sampai tidak bisa bersuara)<br>・Jangan lupa「な」untuk kata sifat な, dan jangan menambah「の」setelah kata benda: yang benar <span class='gd-jp'>これくらい</span>, bukan「これのくらい」.<br>・Pemakaian \"cuma segini\" terkesan meremehkan. Kalau kamu bilang <span class='gd-jp'>これくらいできるでしょう</span> (masa segini saja kamu tidak bisa) kepada orang yang lebih tua, kedengarannya sangat tidak sopan.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'><b>ほど</b> juga berarti \"sampai tingkat ～\". Untuk gambaran berlebihan keduanya bisa dipakai, tetapi <b>くらい lebih lisan, sedangkan ほど lebih formal dan bernuansa tulisan</b>:<br><span class='gd-jp'>手が震えるくらい緊張した。</span>(ngobrol dengan teman)<br><span class='gd-jp'>手が震えるほど緊張した。</span>(menulis artikel, pidato)</div><div class='gd-sec'>Namun untuk arti <b>\"cuma segini\"</b> dan <b>\"setidaknya\"</b>, hanya くらい yang bisa dipakai. <span class='gd-jp'>これほど</span> justru berarti \"sebegini ～\", artinya kamu merasa tingkatnya besar:<br><span class='gd-jp'>これくらい簡単だよ。</span>(Segini sih gampang)<br><span class='gd-jp'>これほど難しいとは思わなかった。</span>(Tidak menyangka sesulit ini)</div><div class='gd-sec'>Selain itu, perbandingan \"tidak se～ itu\" harus memakai ほど: <span class='gd-jp'>今年は去年ほど寒くない。</span>(Tahun ini tidak sedingin tahun lalu)</div><div class='gd-warn'>Trik cepat: untuk \"cuma segini, setidaknya ～\" pakai くらい; untuk \"tidak se～ itu\" atau tulisan formal pakai ほど; kalau hanya menggambarkan tingkat yang berlebihan, keduanya boleh, tetapi dalam percakapan くらい lebih sering terdengar.</div>","n3-35":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>「〜気味」artinya <b>\"agak ～\" atau \"terasa agak ～\"</b>. Misalnya tenggorokanmu terasa aneh dan kamu bilang \"sepertinya aku agak masuk angin\", dalam bahasa Jepang jadi <span class='gd-jp'>風邪気味です</span>. Biasanya dipakai untuk tubuh atau keadaan yang menunjukkan <b>sedikit tanda kurang baik</b>, tetapi belum parah.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Kondisi tubuh</span>Paling sering dipakai. Agak masuk angin, agak capek, agak gemuk, agak kurang tidur.</div><div class='gd-ex-line'>・<span class='gd-jp'>風邪気味なので、今日は早く寝ます。</span>(Agak masuk angin, jadi hari ini aku tidur lebih awal)</div><div class='gd-ex-line'>・<span class='gd-jp'>最近、ちょっと太り気味なんだ。</span>(Akhir-akhir ini aku agak gemuk)</div><div class='gd-ex-line'>・<span class='gd-jp'>寝不足気味で、授業中に眠くなった。</span>(Agak kurang tidur, jadi mengantuk saat pelajaran)</div><div class='gd-sec'><span class='gd-tag'>Perasaan, perkembangan sesuatu</span>Agak gugup atau pekerjaan agak tertinggal juga bisa dipakai.</div><div class='gd-ex-line'>・<span class='gd-jp'>初めての発表なので、少し緊張気味です。</span>(Ini presentasi pertamaku, jadi agak gugup)</div><div class='gd-ex-line'>・<span class='gd-jp'>工事が予定より遅れ気味だ。</span>(Pembangunan agak terlambat dari jadwal)</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Kata kerja</b>: pakai bentuk ます, buang ます-nya, lalu langsung sambung 気味.<br><span class='gd-pair'><span class='gd-jp'>疲れます</span> → <span class='gd-jp'>疲れ気味</span></span><span class='gd-pair'><span class='gd-jp'>太ります</span> → <span class='gd-jp'>太り気味</span></span><span class='gd-pair'><span class='gd-jp'>遅れます</span> → <span class='gd-jp'>遅れ気味</span></span></div><div class='gd-sec'><b>Kata benda</b>: langsung disambung.<br><span class='gd-pair'><span class='gd-jp'>風邪</span> → <span class='gd-jp'>風邪気味</span></span><span class='gd-pair'><span class='gd-jp'>緊張</span> → <span class='gd-jp'>緊張気味</span></span><span class='gd-pair'><span class='gd-jp'>運動不足</span> → <span class='gd-jp'>運動不足気味</span></span></div><div class='gd-sec'>「〜気味」sendiri berperilaku seperti kata benda: di akhir kalimat tambahkan <span class='gd-jp'>だ／です</span>; untuk menerangkan kata benda pakai <span class='gd-jp'>の</span>; untuk menyambung ke kalimat berikutnya pakai <span class='gd-jp'>で</span> atau <span class='gd-jp'>なので</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>風邪気味の人は、マスクをしてください。</span>(Orang yang agak masuk angin, tolong pakai masker)</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Saat menempel pada kata lain, dibaca <b>ぎみ</b>, bukan きみ: <span class='gd-jp'>風邪気味</span> dibaca かぜぎみ.<br>・Kata kerja harus dalam bentuk ます tanpa ます, bukan bentuk kamus: yang benar <span class='gd-jp'>太り気味</span>, tidak boleh 太る気味.<br>・Kata sifat tidak langsung disambung dengan 気味. Untuk \"agak panas\", jangan bilang 暑い気味, tetapi <span class='gd-jp'>ちょっと暑い</span>.<br>・Hampir selalu hanya untuk keadaan yang kurang baik. \"Agak senang\" atau \"agak bersemangat\" tidak memakai 気味.<br>・Untuk menerangkan kata benda pakai <span class='gd-jp'>の</span>: <span class='gd-jp'>風邪気味の人</span>, bukan 風邪気味な人.<br>・Walaupun 気味 sudah berarti \"agak\", orang Jepang sering menambahkan <span class='gd-jp'>少し</span> atau <span class='gd-jp'>ちょっと</span> di depannya. Itu terdengar natural dan tidak dianggap berulang.<br>・<span class='gd-jp'>気味が悪い</span> (dibaca きみがわるい) artinya \"seram, bikin merinding, menjijikkan\", tidak ada hubungannya dengan pola ini, jangan tertukar.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'><b>〜がち</b> = <b>sering</b> begitu, cenderung begitu (soal frekuensi atau kebiasaan).<br><b>〜気味</b> = <b>saat ini</b> ada tanda agak begitu (soal keadaan sekarang).</div><div class='gd-ex-line'>・<span class='gd-jp'>今日はちょっと風邪気味です。</span>(Hari ini agak masuk angin)</div><div class='gd-ex-line'>・<span class='gd-jp'>冬は風邪をひきがちです。</span>(Kalau musim dingin, aku sering masuk angin)</div><div class='gd-sec'><b>〜っぽい</b> juga bisa dipakai: <span class='gd-jp'>風邪っぽい</span> (sepertinya masuk angin), artinya mirip dengan <span class='gd-jp'>風邪気味</span>, tetapi lebih lisan dan cocok untuk ngobrol dengan teman. Kepada atasan atau dokter, <span class='gd-jp'>風邪気味です</span> lebih pantas. Cakupan っぽい juga jauh lebih luas, seperti <span class='gd-jp'>子どもっぽい</span> (kekanak-kanakan) dan <span class='gd-jp'>白っぽい</span> (agak keputihan). Semua itu adalah っぽい dan tidak bisa diganti dengan 気味.</div><div class='gd-warn'>Trik cepat: untuk \"akhir-akhir ini sering ～\" pakai がち; untuk \"sekarang agak ～\" pakai 気味; untuk bilang santai \"kayaknya ～\" ke teman, boleh pakai っぽい.</div>","n3-38":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜一方だ」artinya <b>\"terus makin ～\"</b>, <b>\"cuma bertambah, tidak berkurang\"</b>, atau <b>\"makin lama makin parah\"</b>. Keadaan terus berubah ke satu arah tanpa berhenti dan tanpa tanda-tanda akan berbalik, dan <b>biasanya ke arah yang kurang baik</b>.</div><div class='gd-ex-line'>・<span class='gd-jp'>物価は上がる一方だ。</span>(Harga barang cuma naik, tidak pernah turun)</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Kata kerja bentuk kamus (bentuk dasar yang kamu temukan di kamus) + 一方だ</b>。<br><span class='gd-pair'><span class='gd-jp'>増える</span> → <span class='gd-jp'>増える一方だ</span></span> (terus bertambah)<br><span class='gd-pair'><span class='gd-jp'>悪化する</span> → <span class='gd-jp'>悪化する一方だ</span></span> (terus memburuk)<br>Kata kerja di depannya harus berupa <b>kata kerja yang menunjukkan perubahan</b>, misalnya <span class='gd-jp'>増える</span>, <span class='gd-jp'>減る</span>, <span class='gd-jp'>上がる</span>, <span class='gd-jp'>下がる</span>, <span class='gd-jp'>広がる</span>, <span class='gd-jp'>進む</span>。</div><div class='gd-sec'><span class='gd-tag'>形容詞</span>Kata sifat tidak bisa langsung disambung. Ubah dulu jadi 「〜くなる」atau 「〜になる」(menjadi ～), baru tambahkan 一方だ。<br><span class='gd-pair'><span class='gd-jp'>寒い</span> → ganti い dengan く, tambah なる → <span class='gd-jp'>寒くなる一方だ</span></span><br><span class='gd-pair'><span class='gd-jp'>不便</span> → tambah になる → <span class='gd-jp'>不便になる一方だ</span></span></div><div class='gd-h'>Pemakaian yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>Mengeluh keadaan makin buruk</span>Sering dipakai di berita dan saat ngobrol soal kabar terbaru.</div><div class='gd-ex-line'>・<span class='gd-jp'>最近、仕事が増える一方だ。</span>(Akhir-akhir ini pekerjaan cuma bertambah, tidak berkurang)</div><div class='gd-ex-line'>・<span class='gd-jp'>父の病気は悪くなる一方だ。</span>(Penyakit ayahku terus memburuk)</div><div class='gd-ex-line'>・<span class='gd-jp'>この町は人が減って、寂しくなる一方だ。</span>(Penduduk kota kecil ini makin sedikit dan suasananya makin sepi)</div><div class='gd-sec'><span class='gd-tag'>Tren netral</span>Tidak selalu hal buruk. Kamu juga bisa memakainya untuk bilang \"terus melonjak naik\".</div><div class='gd-ex-line'>・<span class='gd-jp'>このアプリの利用者は増える一方だ。</span>(Pengguna aplikasi ini terus bertambah)</div><div class='gd-sec'>Untuk hal yang sudah lalu, pakai <b>一方だった</b>: <span class='gd-jp'>その後、二人の関係は悪くなる一方だった。</span>(Setelah itu, hubungan mereka berdua makin lama makin buruk)</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Kata \"terus\" dalam bahasa Indonesia gampang membuatmu memakainya untuk \"terus melakukan suatu kegiatan\", dan itu salah. <b>一方だ hanya untuk perubahan</b>:<br>　×<span class='gd-jp'>弟は毎日ゲームをする一方だ。</span><br>　○<span class='gd-jp'>弟は毎日ゲームばかりしている。</span>(Adikku main game terus setiap hari)<br>・Di depannya harus <b>bentuk kamus</b>. Jangan pakai ている atau ます: ×<span class='gd-jp'>増えている一方だ</span>、×<span class='gd-jp'>増えます一方だ</span>。Kalau mau lebih sopan, ubah bagian belakangnya saja: <span class='gd-jp'>増える一方です</span>。<br>・Kata sifat jangan langsung disambung: ×<span class='gd-jp'>寒い一方だ</span>. Yang benar <span class='gd-jp'>寒くなる一方だ</span>。<br>・Nuansanya membawa rasa pasrah karena \"tidak ada tanda membaik\", jadi jarang dipakai untuk kabar baik.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'><b>〜一方だ</b> (di akhir kalimat) = terus berubah ke satu arah: <span class='gd-jp'>家賃は高くなる一方だ。</span>(Uang sewa cuma makin mahal)<br><b>〜ばかりだ</b> (disambung bentuk kamus) = artinya hampir sama, lebih kasual, dan hampir hanya dipakai untuk hal buruk: <span class='gd-jp'>家賃は高くなるばかりだ。</span>(Uang sewa cuma makin mahal)<br><b>〜一方で</b> (di tengah kalimat) = \"di sisi lain\", untuk membandingkan dua hal dan tidak ada hubungannya dengan perubahan: <span class='gd-jp'>この町は便利な一方で、家賃が高い。</span>(Kota ini praktis, tapi di sisi lain uang sewanya mahal)</div><div class='gd-warn'>Trik cepat: <b>一方だ di akhir kalimat</b> berarti \"terus makin ～\", sedangkan <b>一方で di tengah kalimat</b> berarti \"di sisi lain\". Kalau ketemu 一方, lihat dulu posisinya.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Kalau mau menjelaskan proses \"pelan-pelan menjadi ～\", lanjutkan ke 「〜てくる・〜ていく」: <span class='gd-jp'>だんだん寒くなってきた。</span>(Cuacanya pelan-pelan jadi dingin)</div>","n3-39":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜ようにする」artinya <b>\"aku berusaha ～\"</b> atau <b>\"aku berusaha menjaga ～\"</b>. Seperti saat kamu bilang \"Akhir-akhir ini aku berusaha mengurangi minuman manis\". Intinya kamu sengaja berusaha, tapi tidak menjamin selalu berhasil.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Hal yang mau dilakukan: bentuk kamus (bentuk dasar yang ada di kamus) + ようにする<br><span class='gd-pair'><span class='gd-jp'>早く寝る</span> → <span class='gd-jp'>早く寝るようにする</span> (berusaha tidur lebih awal)</span><br>Hal yang tidak mau dilakukan: bentuk ない + ようにする<br><span class='gd-pair'><span class='gd-jp'>忘れない</span> → <span class='gd-jp'>忘れないようにする</span> (berusaha tidak lupa)</span><br>Untuk bentuk sopan, cukup ubah bagian paling belakang: <span class='gd-pair'><span class='gd-jp'>ようにする</span> → <span class='gd-jp'>ようにします</span></span></div><div class='gd-h'>Tiga pemakaian yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>ようにしている</span>Kebiasaan yang belakangan ini terus dijaga. Paling sering dipakai sehari-hari.</div><div class='gd-ex-line'>・<span class='gd-jp'>毎晩10時までに寝るようにしている。</span>(Aku berusaha tidur sebelum jam 10 setiap malam)</div><div class='gd-ex-line'>・<span class='gd-jp'>エレベーターより階段を使うようにしている。</span>(Aku berusaha pakai tangga, bukan lift)</div><div class='gd-sec'><span class='gd-tag'>ようにする</span>Mulai sekarang akan lebih memperhatikan.</div><div class='gd-ex-line'>・<span class='gd-jp'>これからは遅刻しないようにします。</span>(Mulai sekarang aku akan berusaha tidak terlambat)</div><div class='gd-sec'><span class='gd-tag'>ようにしてください</span>Meminta lawan bicara berusaha melakukannya. Sering diucapkan dokter dan guru.</div><div class='gd-ex-line'>・<span class='gd-jp'>水をたくさん飲むようにしてください。</span>(Usahakan minum air yang banyak, ya)</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Di depannya hanya boleh bentuk kamus atau bentuk ない, tidak boleh bentuk ます atau bentuk た. Tidak bisa bilang 寝ますようにする atau 寝たようにする. Kalau mau sopan, ubah bagian ekornya: <span class='gd-jp'>寝るようにします</span>。<br>・Untuk \"biasanya aku sudah berusaha ～\", pakai <b>ようにしている</b>. Kalau pakai <b>ようにする／ようにします</b>, kesannya \"mulai sekarang aku akan berusaha\", jadi belum dimulai.<br>・Hanya bisa dipakai untuk <b>hal yang bisa kamu kendalikan sendiri</b>. Misalnya \"semoga tidak hujan\" tidak bisa pakai ようにする, karena hujan atau tidak bukan kamu yang menentukan.<br>・<span class='gd-jp'>ようにしてください</span> berkesan mengingatkan atau memberi arahan. Wajar kalau dokter ke pasien atau guru ke murid, tapi kalau dipakai ke atasan atau pelanggan, kesannya seperti mengajari mereka, jadi hati-hati.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Sama-sama soal \"berbicara bahasa Jepang\", tapi ganti ekornya dan artinya jadi lain:<br><b>ようになる</b> = pelan-pelan <b>menjadi</b> begitu (hasil): <span class='gd-jp'>日本語が話せるようになった。</span>(Sekarang aku sudah bisa bicara bahasa Jepang)<br><b>ようにする</b> = <b>sengaja berusaha</b> sendiri (usaha): <span class='gd-jp'>毎日日本語を話すようにしている。</span>(Aku berusaha bicara bahasa Jepang setiap hari)<br><b>ことにする</b> = <b>mengambil keputusan</b>: <span class='gd-jp'>毎日日本語を話すことにした。</span>(Aku memutuskan untuk bicara bahasa Jepang setiap hari)</div><div class='gd-warn'>Trik cepat: \"jadi ～\" itu ようになる, \"berusaha ～\" itu ようにする, \"memutuskan ～\" itu ことにする.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>「〜ようになる」(menjadi ～) sering muncul bersama pelajaran ini, jadi bagus untuk dipelajari berikutnya. Ada juga 「〜ように」yang artinya \"supaya ～\", misalnya: <span class='gd-jp'>忘れないように、メモしておく。</span>(Supaya tidak lupa, aku catat dulu.) Bentuknya mirip dengan ようにする, jadi nanti bandingkan keduanya saat kamu sudah mempelajarinya.</div>","n3-49":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜ことはない」kira-kira artinya <b>「tidak perlu ～」「ngapain sih ～」</b>. Saat kamu melihat lawan bicara sedang khawatir, minta maaf, atau terburu-buru, kamu bilang \"tidak perlu begitu\". Biasanya nuansanya menenangkan dan mengajak orang untuk lebih santai.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Bentuk kamus verba (bentuk aslinya seperti yang tertulis di kamus) langsung ditambah ことはない.<br><span class='gd-pair'><span class='gd-jp'>心配する</span> → <span class='gd-jp'>心配することはない</span></span>（tidak perlu khawatir）<br><span class='gd-pair'><span class='gd-jp'>謝る</span> → <span class='gd-jp'>謝ることはない</span></span>（tidak perlu minta maaf）<br><span class='gd-pair'><span class='gd-jp'>急ぐ</span> → <span class='gd-jp'>急ぐことはない</span></span>（tidak perlu buru-buru）<br>Versi lebih sopan: <span class='gd-jp'>ことはありません</span>. Saat bicara dengan teman, 「は」 sering dihilangkan jadi <span class='gd-jp'>ことない</span>, lalu di belakangnya ditambah <span class='gd-jp'>よ</span>.</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>Menenangkan</span>Dipakai saat lawan bicara sedang cemas atau menyalahkan diri sendiri.</div><div class='gd-ex-line'>・<span class='gd-jp'>大したことじゃないから、気にすることないよ。</span>（Bukan masalah besar kok, tidak usah dipikirkan ya）</div><div class='gd-sec'><span class='gd-tag'>Menyuruh orang tidak repot-repot</span>Sering muncul bersama 「わざわざ（sengaja）」.</div><div class='gd-ex-line'>・<span class='gd-jp'>わざわざ来ることはないよ。電話でいいから。</span>（Tidak perlu repot-repot datang kok, telepon saja cukup）</div><div class='gd-sec'><span class='gd-tag'>Ngapain sih ～</span>Kalau di depannya ditambah 「何も」, nuansanya jadi agak jengkel: \"ngapain sih sampai ～\".</div><div class='gd-ex-line'>・<span class='gd-jp'>何もそんなに怒ることはないでしょう。</span>（Ngapain sih marah sampai segitunya）</div><div class='gd-h'>Bagian yang mudah keliru</div><div class='gd-warn'>・Di depannya harus <b>bentuk kamus</b>. Kalau diganti bentuk た, artinya jadi sama sekali berbeda: \"belum pernah ～\" (dibandingkan di bawah).<br>・Artinya \"<b>tidak perlu</b>\", bukan \"<b>tidak boleh</b>\". <span class='gd-jp'>行くことはない</span> artinya \"tidak perlu pergi\"; kalau kamu mau pergi, ya tetap boleh. Untuk \"dilarang pergi\" pakai <span class='gd-jp'>行ってはいけない</span>.<br>・Kalimat ini punya nuansa \"aku sudah menilai untukmu: tidak perlu\", jadi terdengar wajar kalau dipakai ke teman atau junior. Kalau langsung bilang 「〜ことはありません」 ke atasan atau pelanggan, bisa terdengar seperti sedang menggurui. Lebih aman pakai <span class='gd-jp'>大丈夫です</span> atau <span class='gd-jp'>ご心配なく</span>.<br>・Kadang artinya adalah \"<b>tidak akan terjadi</b>\": <span class='gd-jp'>もう二度と会うことはないだろう。</span>（Sepertinya kita tidak akan bertemu lagi）. Dalam konteks menenangkan atau menasihati artinya \"tidak perlu\", sedangkan dalam konteks kemungkinan artinya \"tidak akan\". Lihat konteksnya ya.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Sama-sama bilang \"pergi ke Jepang\", tapi begitu bentuk verba di depannya berubah, artinya jauh berbeda:<br><b>Bentuk kamus＋ことはない</b>＝tidak perlu: <span class='gd-jp'>日本へ行くことはない。</span>（Tidak perlu pergi ke Jepang）<br><b>Bentuk た＋ことはない</b>＝belum pernah: <span class='gd-jp'>日本へ行ったことはない。</span>（Aku belum pernah ke Jepang）<br><b>Bentuk ない＋ことはない</b>＝bukan berarti tidak: <span class='gd-jp'>日本へ行かないことはない。</span>（Bukan berarti aku tidak pergi ke Jepang, sesekali tetap pergi）</div><div class='gd-warn'>Trik cepat: lihat kata tepat sebelum 「こと」. Bentuk kamus berarti \"tidak perlu\", た berarti \"belum pernah\", ない berarti \"bukan berarti tidak\".</div><div class='gd-h'>Setelah ini, lanjut pelajari</div><div class='gd-sec'>Lawannya adalah 「〜ことだ」＝sebaiknya dilakukan: <span class='gd-jp'>心配なら、医者に相談することだ。</span>（Kalau khawatir, sebaiknya konsultasi ke dokter）. Yang satu menyarankan kamu melakukan, yang satu bilang kamu tidak perlu melakukan.<br>Ada juga yang artinya sangat dekat, yaitu <span class='gd-jp'>心配する必要はない</span>（tidak perlu khawatir）, nuansanya lebih objektif dan kaku, sering muncul di teks tertulis.</div>","n3-50":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>Keduanya sama-sama soal \"keputusan\", bedanya ada pada <b>siapa yang memutuskan</b>.<br><b>ことにする</b>＝aku sendiri yang memutuskan: \"Aku memutuskan berhenti merokok\".<br><b>ことになる</b>＝bukan aku sendiri yang memutuskan; itu diatur perusahaan, hasil diskusi bersama, atau keadaan berkembang begitu saja: \"Aku dipindahtugaskan oleh perusahaan\".<br>\"Aku memutuskan ～\" sesuai dengan ことにする, sedangkan \"jadinya harus ～\" atau \"diatur untuk ～\" sesuai dengan ことになる.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Hal yang akan dilakukan: bentuk kamus＋ことにする／ことになる　<span class='gd-pair'><span class='gd-jp'>やめる</span> → <span class='gd-jp'>やめることにした</span></span><br>Hal yang tidak dilakukan: bentuk ない＋ことにする／ことになる　<span class='gd-pair'><span class='gd-jp'>帰らない</span> → <span class='gd-jp'>帰らないことにした</span></span></div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>ことにした</span>Aku sendiri yang mengambil keputusan.</div><div class='gd-ex-line'>・<span class='gd-jp'>タバコをやめることにした。</span>（Aku memutuskan berhenti merokok）</div><div class='gd-ex-line'>・<span class='gd-jp'>今年の夏は実家に帰らないことにした。</span>（Musim panas tahun ini aku memutuskan tidak pulang kampung）</div><div class='gd-sec'><span class='gd-tag'>ことになった</span>Diputuskan oleh perusahaan, sekolah, atau orang lain; aku hanya menerima hasilnya.</div><div class='gd-ex-line'>・<span class='gd-jp'>来月から大阪に転勤することになった。</span>（Mulai bulan depan aku akan dipindahtugaskan ke Osaka）</div><div class='gd-sec'><span class='gd-tag'>Mengabarkan urusan sendiri</span>Walaupun itu keputusan sendiri, orang Jepang sering memakai <span class='gd-jp'>ことになりました</span> saat mengabarkan hal seperti menikah atau berhenti kerja. Terdengarnya lebih rendah hati, seperti \"kejadiannya sampai ke titik ini\", dan tidak terkesan menekankan \"ini kemauanku sendiri\".</div><div class='gd-ex-line'>・<span class='gd-jp'>実は、結婚することになりました。</span>（Sebenarnya, aku akan menikah）</div><div class='gd-sec'><span class='gd-tag'>ことにしている</span>Aturan yang dibuat sendiri untuk diri sendiri dan terus dijalankan.</div><div class='gd-ex-line'>・<span class='gd-jp'>寝る前はスマホを見ないことにしている。</span>（Aku punya aturan untuk tidak melihat HP sebelum tidur）</div><div class='gd-sec'><span class='gd-tag'>ことになっている</span>Peraturan, kebiasaan, atau jadwal yang sudah diatur.</div><div class='gd-ex-line'>・<span class='gd-jp'>この部屋では靴を脱ぐことになっています。</span>（Di ruangan ini, aturannya sepatu harus dilepas）</div><div class='gd-ex-line'>・<span class='gd-jp'>明日、田中さんと会うことになっている。</span>（Besok sudah dijadwalkan bertemu dengan Pak Tanaka）</div><div class='gd-h'>Bagian yang mudah keliru</div><div class='gd-warn'>・Dalam bahasa Indonesia kita bilang \"aku memutuskan\" (sekarang), tapi dalam bahasa Jepang biasanya dipakai bentuk lampau <span class='gd-jp'>ことにした</span>, yang menunjukkan bahwa keputusan sudah diambil.<br>・Kata benda yang bisa ditambah する, seperti 旅行 atau 勉強, harus diubah jadi verba dulu baru disambung: <span class='gd-jp'>旅行することにした</span>, bukan 旅行ことにした. (Kata benda biasa langsung disambung にする, misalnya <span class='gd-jp'>コーヒーにする</span>, yang artinya \"memilih ～\", jadi berbeda dengan pemakaian di sini)<br>・<span class='gd-jp'>ことになる</span> tidak selalu berarti ada orang yang memutuskan. Bisa juga berarti \"kalau terus begini, hasilnya akan jadi ～\": <span class='gd-jp'>今やめたら、後で後悔することになるよ。</span>（Kalau berhenti sekarang, nanti kamu akan menyesal lho）<br>・<span class='gd-jp'>ことにしている</span> adalah aturan yang dibuat oleh <b>diri sendiri</b>, sedangkan <span class='gd-jp'>ことになっている</span> adalah aturan yang dibuat oleh <b>pihak luar</b>. Jangan dicampur ya.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Sama-sama soal \"bangun pagi\":<br><b>ことにする</b>＝memutuskan sendiri: <span class='gd-jp'>明日から6時に起きることにした。</span>（Aku memutuskan mulai besok bangun jam enam）<br><b>ことになる</b>＝diatur atau keadaan jadi begitu: <span class='gd-jp'>仕事の関係で、毎朝6時に起きることになった。</span>（Karena urusan pekerjaan, jadinya aku harus bangun jam enam setiap pagi）<br><b>ようにする</b>＝berusaha melakukan: <span class='gd-jp'>毎朝6時に起きるようにしている。</span>（Aku berusaha bangun jam enam setiap pagi）<br><b>ようになる</b>＝perlahan jadi bisa: <span class='gd-jp'>6時に起きられるようになった。</span>（Aku sekarang jadi bisa bangun jam enam）</div><div class='gd-warn'>Trik cepat: kalau ada kesan \"memutuskan\", pakai こと; kalau \"berusaha, jadi bisa\", pakai よう. Lalu lihat siapa yang memutuskan: kalau diri sendiri pakai する, kalau diatur orang lain atau keadaan jadi begitu pakai なる.</div><div class='gd-h'>Setelah ini, lanjut pelajari</div><div class='gd-sec'>Kalau <span class='gd-jp'>ことにする</span> disambung bentuk lampau, artinya juga bisa \"anggap saja ～\": <span class='gd-jp'>今の話は聞かなかったことにする。</span>（Pembicaraan tadi anggap saja aku tidak mendengarnya）</div>","n3-46":"<div class='gd-h'>Pahami dulu dalam satu kalimat</div><div class='gd-sec'>「〜はずがない」artinya <b>“tidak mungkin ～”</b> atau <b>“mana mungkin ～”</b>. Kamu punya satu alasan di kepala, misalnya dia orangnya teliti, pintunya terkunci, atau dia sudah latihan selama itu. Kalau alasan itu diteruskan, kesimpulannya: “hal ini mustahil benar-benar terjadi”.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Menyimpulkan secara logis</span>Kamu punya dasar, lalu dengan yakin bilang “tidak mungkin”.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女があんなミスをするはずがない。</span>(Tidak mungkin dia membuat kesalahan seperti itu)</div><div class='gd-ex-line'>・<span class='gd-jp'>あんなに練習したんだから、負けるはずがない。</span>(Sudah latihan sebanyak itu, mana mungkin kalah)</div><div class='gd-sec'><span class='gd-tag'>Tidak percaya pada apa yang terjadi di depan mata</span>Saat menghadapi kejadian tak terduga, kamu spontan bilang “Masa sih?”.</div><div class='gd-ex-line'>・<span class='gd-jp'>え、財布がない？そんなはずない。さっきまであったのに。</span>(Hah, dompetnya hilang? Masa sih, tadi jelas-jelas masih ada)</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Kata kerja, kata sifat-い</b>: sambung langsung.<br><span class='gd-pair'><span class='gd-jp'>負ける</span> → <span class='gd-jp'>負けるはずがない</span></span><span class='gd-pair'><span class='gd-jp'>暑い</span> → <span class='gd-jp'>暑いはずがない</span></span><br><b>Kata sifat-な</b>: tambahkan「な」di tengah.<br><span class='gd-pair'><span class='gd-jp'>下手</span> → <span class='gd-jp'>下手なはずがない</span></span><br><b>Kata benda</b>: tambahkan「の」di tengah.<br><span class='gd-pair'><span class='gd-jp'>犯人</span> → <span class='gd-jp'>犯人のはずがない</span></span><br>Kalau mau bilang “tidak mungkin pernah ～” atau “tidak mungkin tidak ～”, taruh bentuk lampau atau negatif sebelum はず:<br><span class='gd-pair'><span class='gd-jp'>行った</span> → <span class='gd-jp'>行ったはずがない</span></span>(tidak mungkin pernah pergi)<br><span class='gd-pair'><span class='gd-jp'>知らない</span> → <span class='gd-jp'>知らないはずがない</span></span>(tidak mungkin tidak tahu)</div><div class='gd-ex-line'>・<span class='gd-jp'>まだ4月だから、そんなに暑いはずがない。</span>(Baru bulan April, mana mungkin sepanas itu)</div><div class='gd-ex-line'>・<span class='gd-jp'>10年も日本に住んでいるんだから、日本語が下手なはずがない。</span>(Sudah tinggal di Jepang 10 tahun, tidak mungkin bahasa Jepangnya jelek)</div><div class='gd-ex-line'>・<span class='gd-jp'>あんなに優しい人が犯人のはずがない。</span>(Orang sebaik itu tidak mungkin pelakunya)</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'>「が」sering diganti「は」supaya nadanya lebih tegas, dan dalam percakapan「が」juga sering dihilangkan. Yang paling sering kamu dengar adalah <span class='gd-jp'>そんなはずはない</span> dan <span class='gd-jp'>そんなはずない</span> (masa sih, mana mungkin). Hafalkan saja satu kalimat utuh.</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Kata benda dan kata sifat-な tidak bisa disambung langsung: yang benar <span class='gd-jp'>犯人のはずがない</span>, bukan「犯人だはずがない」。<br>・Dalam bahasa Indonesia “tidak mungkin”, “tidak boleh”, dan “tidak bisa” memang sudah beda makna, dan di bahasa Jepang juga harus dipisah. はずがない hanya untuk “tidak mungkin”; untuk “tidak boleh” dan “tidak bisa (kemampuan)” kamu tidak bisa memakainya. “Di sini tidak boleh merokok” adalah <span class='gd-jp'>ここでたばこを吸ってはいけません</span>, dan “Saya tidak bisa berenang” adalah <span class='gd-jp'>泳げません</span>。<br>・<span class='gd-jp'>知らないはずがない</span> artinya “tidak mungkin tidak tahu”, alias “dia pasti tahu”. Jangan diterjemahkan jadi “tidak mungkin tahu”.<br>・Nadanya sangat kuat. Bilang <span class='gd-jp'>あなたにできるはずがない</span> (kamu tidak mungkin bisa) langsung ke orangnya bisa sangat menyakitkan, jadi hati-hati.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Untuk hal yang sama, “apakah dia akan datang”, nadanya berbeda-beda:<br><b>はずだ</b> = seharusnya datang (yakin): <span class='gd-jp'>彼は来るはずだ。</span>(Dia seharusnya datang)<br><b>ないはずだ</b> = seharusnya tidak datang (condong ke negatif, tapi belum mutlak): <span class='gd-jp'>彼は来ないはずだ。</span>(Dia seharusnya tidak datang)<br><b>はずがない</b> = mustahil datang (mutlak): <span class='gd-jp'>彼が来るはずがない。</span>(Tidak mungkin dia datang)<br><b>わけがない</b> = artinya hampir sama dengan はずがない, dan di banyak situasi bisa saling menggantikan. Lebih sering terdengar dalam obrolan sehari-hari, dengan nada yang lebih ketus dan emosional: <span class='gd-jp'>彼が来るわけがない。</span>(Mana mungkin dia datang)</div><div class='gd-warn'>Tips memilih: untuk “seharusnya tidak” pakai ないはずだ, untuk “mustahil” pakai はずがない. Saat ngobrol dengan teman dan emosimu lagi naik, sering diganti jadi わけがない.</div>","n3-48":"<div class='gd-h'>Pahami dulu dalam satu kalimat</div><div class='gd-sec'>「〜ことだ」adalah kalimat yang dipakai orang yang lebih tua atau senior waktu memberimu saran: <b>“turuti saja kataku, ～ saja deh”</b> atau <b>“pokoknya ～ aja”</b>. Misalnya senior bilang, “Mau lulus N3? Hafalin kosakata tiap hari aja.” Dalam bahasa Jepang jadi <span class='gd-jp'>毎日単語を覚えることだ。</span></div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Menyuruh lawan bicara melakukan sesuatu: bentuk kamus＋ことだ<br><span class='gd-pair'><span class='gd-jp'>休む</span> → <span class='gd-jp'>休むことだ</span></span>(istirahat saja yang benar)<br>Menyuruh lawan bicara tidak melakukan sesuatu: bentuk ない＋ことだ<br><span class='gd-pair'><span class='gd-jp'>無理をしない</span> → <span class='gd-jp'>無理をしないことだ</span></span>(jangan memaksakan diri)</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Memberi saran</span>Di bagian depan biasanya dulu disebut “kalau kamu mau ～” atau “supaya ～”, lalu di belakang ことだ memberi jawabannya.</div><div class='gd-ex-line'>・<span class='gd-jp'>風邪のときは、ゆっくり休むことだ。</span>(Kalau lagi flu, istirahat saja yang cukup)</div><div class='gd-ex-line'>・<span class='gd-jp'>やせたいなら、甘いものを減らすことだ。</span>(Kalau mau kurus, kurangi saja makanan manis)</div><div class='gd-sec'><span class='gd-tag'>Menyarankan agar tidak melakukan sesuatu</span>Pakai bentuk ない, nadanya seperti “sudahlah, jangan ～”.</div><div class='gd-ex-line'>・<span class='gd-jp'>試験の前の日は、夜遅くまで勉強しないことだ。</span>(Sehari sebelum ujian, jangan belajar sampai larut malam)</div><div class='gd-sec'>Selain diucapkan langsung, pola ini juga sering muncul di buku motivasi, kolom artikel, dan cerita pengalaman para senior.</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Ini nada <b>atasan ke bawahan</b>, ada kesan “aku lebih tahu daripadamu”. Jangan dipakai ke guru, atasan, atau pelanggan. Walaupun diubah jadi <span class='gd-jp'>〜ことです</span>, tetap tidak sopan. Ke orang yang lebih tua, lebih baik pakai <span class='gd-jp'>〜たほうがいいと思います</span>。<br>・Di depannya hanya bisa bentuk kamus atau bentuk ない, tidak bisa bentuk た: <span class='gd-jp'>休んだことだ</span> bukan berarti “istirahat saja sana”.<br>・Kalau di depannya kata sifat, seperti <span class='gd-jp'>うらやましいことだ</span> dan <span class='gd-jp'>残念なことだ</span>, itu mengungkapkan perasaan (sungguh iri, sungguh disayangkan), <b>bukan memberi saran</b>. Jangan tertukar.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Sama-sama untuk teman yang sedang flu tapi memaksa masuk kerja:<br><b>ことだ</b> = memberi saran khusus untukmu: <span class='gd-jp'>今日は休むことだ。</span>(Hari ini izin saja dan istirahat)<br><b>べきだ</b> = bicara soal kewajiban, seharusnya atau tidak: <span class='gd-jp'>病気のときは休むべきだ。</span>(Kalau sakit, memang seharusnya istirahat). べきだ juga bisa dipakai untuk menyesali yang sudah lewat: <span class='gd-jp'>昨日休むべきだった。</span>(Kemarin seharusnya izin), sedangkan ことだ tidak punya pemakaian seperti ini.<br><b>ものだ</b> = bicara soal kebiasaan atau akal sehat dalam masyarakat: <span class='gd-jp'>体調が悪いときは無理をしないものだ。</span>(Kalau badan tidak enak, memang sewajarnya tidak memaksakan diri)<br><b>ことはない</b> = “tidak perlu ～”, dipakai untuk menenangkan orang: <span class='gd-jp'>そんなに心配することはない。</span>(Tidak perlu khawatir sampai segitunya). Ini berbeda dengan <span class='gd-jp'>心配しないことだ。</span>(Jangan khawatir saja ya): yang pertama berarti “tidak perlu”, yang kedua menyarankan “jangan”.</div><div class='gd-warn'>Tips memilih: kalau bilang “～ saja deh” ke orang di depanmu, pakai ことだ; kalau bicara soal kewajiban, seharusnya atau tidak, pakai べきだ; kalau bicara soal akal sehat yang semua orang tahu, pakai ものだ; kalau bilang “tidak perlu ～”, pakai ことはない.</div><div class='gd-h'>Setelah ini bisa lanjut belajar</div><div class='gd-sec'>Lanjut lihat <span class='gd-jp'>〜ことはない</span> (tidak perlu ～) dan <span class='gd-jp'>〜べきだ</span> (seharusnya ～). Kalau ketiganya dipelajari bersamaan, kamu paling kecil kemungkinannya tertukar.</div>","n3-40":"<div class='gd-h'>Intinya dalam satu kalimat</div><div class='gd-sec'>「〜ようになる」artinya <b>“sekarang sudah bisa ~” atau “mulai ~”</b>. Poinnya: <b>dulu tidak begitu, sekarang jadi begitu</b>. Contohnya “Sekarang aku berani jalan-jalan sendirian ke Jepang” atau “Anakku akhir-akhir ini sudah bisa memakai sepatu sendiri”. Untuk perubahan yang sudah terjadi, biasanya dipakai bentuk lampau 「<span class='gd-jp'>ようになった</span>」.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><span class='gd-tag'>Kemampuan berubah</span>Dulu tidak bisa, sekarang bisa: taruh <b>bentuk potensial</b> di depannya (bentuk yang berarti “bisa ~”).<br><span class='gd-pair'><span class='gd-jp'>読む</span> → <span class='gd-jp'>読める</span> → <span class='gd-jp'>読めるようになった</span></span><br><span class='gd-pair'><span class='gd-jp'>起きる</span> → <span class='gd-jp'>起きられる</span> → <span class='gd-jp'>起きられるようになった</span></span><br><b>Pengecualian</b>: kata kerja seperti <span class='gd-jp'>わかる</span>, <span class='gd-jp'>見える</span>, <span class='gd-jp'>聞こえる</span>, <span class='gd-jp'>できる</span> sudah punya arti “bisa” dengan sendirinya, jadi langsung pakai bentuk kamus: <span class='gd-jp'>わかるようになった</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>息子がひらがなを読めるようになった。</span>(Anakku sudah bisa membaca hiragana)</div><div class='gd-ex-line'>・<span class='gd-jp'>練習して、泳げるようになった。</span>(Setelah latihan, aku jadi bisa berenang)</div><div class='gd-sec'><span class='gd-tag'>Kebiasaan berubah</span>Dulu tidak dilakukan, sekarang mulai dilakukan: bentuk kamus + ようになる.</div><div class='gd-ex-line'>・<span class='gd-jp'>結婚してから、毎日料理するようになった。</span>(Sejak menikah, aku mulai memasak setiap hari)</div><div class='gd-ex-line'>・<span class='gd-jp'>何度も通ううちに、店員と雑談するようになった。</span>(Setelah sering datang, lama-lama aku jadi bisa ngobrol santai dengan pegawai toko)</div><div class='gd-h'>Review cepat bentuk potensial</div><div class='gd-sec'><b>Golongan 1 (kata kerja godan)</b>: ganti bunyi terakhir dengan bunyi baris 「え」 dari baris yang sama, lalu tambahkan る.<br><span class='gd-pair'><span class='gd-jp'>読む</span> → む jadi め → <span class='gd-jp'>読める</span></span><span class='gd-pair'><span class='gd-jp'>話す</span> → <span class='gd-jp'>話せる</span></span><br><b>Golongan 2 (kata kerja ichidan)</b>: buang る, lalu tambahkan られる.<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べられる</span></span><br><b>Golongan 3 (hafalkan saja)</b>: <span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>できる</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来られる</span>(こられる)</span></div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>ようになりたい</span>Ingin jadi bisa.</div><div class='gd-ex-line'>・<span class='gd-jp'>日本語がペラペラ話せるようになりたい。</span>(Aku ingin bisa bicara bahasa Jepang dengan lancar)</div><div class='gd-sec'><span class='gd-tag'>ようになる</span>Pakai bentuk kini untuk bilang “nanti akan jadi ~”.</div><div class='gd-ex-line'>・<span class='gd-jp'>毎日練習すれば、すぐ泳げるようになりますよ。</span>(Kalau latihan tiap hari, kamu akan segera bisa berenang, lho)</div><div class='gd-sec'><span class='gd-tag'>ようになってきた</span>Sedang berubah sedikit demi sedikit.</div><div class='gd-ex-line'>・<span class='gd-jp'>日本語が少しわかるようになってきた。</span>(Pelan-pelan aku mulai agak paham bahasa Jepang)</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Untuk bilang “jadi bisa”, pakai bentuk potensial: <span class='gd-jp'>泳げるようになった</span> artinya “sudah bisa berenang”, sedangkan <span class='gd-jp'>泳ぐようになった</span> artinya “mulai rutin berenang” (jadi kebiasaan). Artinya beda. Tapi kata seperti <span class='gd-jp'>わかる</span>, <span class='gd-jp'>見える</span>, <span class='gd-jp'>聞こえる</span>, <span class='gd-jp'>できる</span> langsung pakai bentuk kamus. Tidak bisa bilang わかれる atau 見えられる.<br>・Untuk “jadi tidak ~ lagi”, sehari-hari lebih sering dipakai 「なくなる」: <span class='gd-jp'>辛いものが食べられなくなった</span> (jadi tidak bisa makan pedas), <span class='gd-jp'>タバコを吸わなくなった</span> (tidak merokok lagi).<br>・Dalam bahasa Indonesia kita cukup bilang “jadi”, tapi untuk “menjadi suatu keadaan”, <b>adjektiva dan nomina tidak bisa langsung disambung ようになる</b>. “Jadi sibuk” adalah <span class='gd-jp'>忙しくなった</span>, “jadi cantik” adalah <span class='gd-jp'>きれいになった</span>, “jadi guru” adalah <span class='gd-jp'>先生になった</span>. Tambahan: nomina + <span class='gd-jp'>のようになる</span> artinya “menjadi seperti ~”, misalnya <span class='gd-jp'>先生のようになりたい</span> (ingin menjadi seperti guru). Ini bukan “menjadi guru”, jadi artinya beda, ya.<br>・Hasil dari usaha keras juga boleh pakai pola ini, bukan hanya perubahan yang terjadi “dengan sendirinya”. Fokusnya adalah <b>hasilnya sudah berubah</b>.</div><div class='gd-h'>Bedakan dari pola yang mirip</div><div class='gd-sec'>Sama-sama soal bangun pagi:<br><b>ようにする</b> = sengaja berusaha: <span class='gd-jp'>毎朝6時に起きるようにしている。</span>(Aku selalu berusaha bangun jam 6 setiap pagi)<br><b>ようになる</b> = hasilnya berubah: <span class='gd-jp'>朝6時に起きられるようになった。</span>(Sekarang aku sudah bisa bangun jam 6 pagi)<br><b>ことになる</b> = diputuskan atau diatur (oleh pihak lain): <span class='gd-jp'>来月から、6時に出勤することになった。</span>(Mulai bulan depan, aku harus masuk kerja jam 6)</div><div class='gd-warn'>Trik cepat: “berusaha ~” pakai ようにする, “sekarang sudah bisa ~” pakai ようになる, “diputuskan harus ~” pakai ことになる.</div>","n3-45":"<div class='gd-h'>Intinya dalam satu kalimat</div><div class='gd-sec'>「〜はずだ」artinya <b>“menurut logika, seharusnya ~”</b>. Kamu punya dasar (sesuatu yang kamu lihat, kamu tahu, atau sudah direncanakan), lalu dari situ kamu menarik kesimpulan yang cukup yakin. Misalnya kamu lihat lampu rumah temanmu menyala, lalu kamu berpikir “dia pasti ada di rumah”. Dalam bahasa Jepang: <span class='gd-jp'>家にいるはずだ</span>.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Kata kerja dan adjektiva-i</b>: langsung sambung dengan bentuk biasa (bentuk tanpa ます atau です).<br><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来るはずだ</span></span><span class='gd-pair'><span class='gd-jp'>来た</span> → <span class='gd-jp'>来たはずだ</span></span><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いはずだ</span></span></div><div class='gd-sec'><b>Adjektiva-na</b>: ganti だ dengan な.<br><span class='gd-pair'><span class='gd-jp'>便利だ</span> → <span class='gd-jp'>便利なはずだ</span></span></div><div class='gd-sec'><b>Nomina</b>: ganti だ dengan の.<br><span class='gd-pair'><span class='gd-jp'>休みだ</span> → <span class='gd-jp'>休みのはずだ</span></span></div><div class='gd-sec'>Supaya lebih sopan, ganti だ dengan です: <span class='gd-jp'>来るはずです</span>.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Dugaan yang ada dasarnya</span>Menarik kesimpulan dari fakta yang sudah diketahui.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は医者だから、詳しいはずだ。</span>(Dia dokter, jadi seharusnya dia paham betul)</div><div class='gd-ex-line'>・<span class='gd-jp'>電気がついているから、家にいるはずだ。</span>(Lampunya menyala, jadi dia pasti ada di rumah)</div><div class='gd-sec'><span class='gd-tag'>Sesuai jadwal atau rencana</span>Jadwal atau janji yang sudah dibuat, dan apa yang seharusnya terjadi.</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんは3時に来るはずです。</span>(Pak Tanaka seharusnya datang jam tiga)</div><div class='gd-ex-line'>・<span class='gd-jp'>荷物は明日届くはずです。</span>(Paketnya seharusnya sampai besok)</div><div class='gd-sec'><span class='gd-tag'>Padahal ~, kok …</span>Pakai 「はずなのに」. Kamu yakin, tapi kenyataannya tidak begitu, dan ada rasa “lho, aneh”.</div><div class='gd-ex-line'>・<span class='gd-jp'>ここに置いたはずなのに、ない。</span>(Padahal aku yakin menaruhnya di sini, kok tidak ada)</div><div class='gd-sec'><span class='gd-tag'>Pantas saja</span>Kamu merasakan hasilnya dulu, lalu baru sadar sebabnya.</div><div class='gd-ex-line'>・<span class='gd-jp'>寒いはずだ。雪が降っている。</span>(Pantas saja dingin, ternyata sedang turun salju)</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Kata “seharusnya” dalam bahasa Indonesia punya dua arti: “kemungkinan besar begitu” dan “wajib / sebaiknya dilakukan”. <b>はず hanya punya arti yang pertama</b>. “Kamu seharusnya tidur lebih awal” itu nasihat, jadi tidak boleh pakai はず.<br>・Nomina harus pakai の: yang benar <span class='gd-jp'>医者のはずだ</span>, bukan 「医者だはずだ」. Adjektiva-na harus <span class='gd-jp'>便利なはずだ</span>.<br>・Jangan pakai はず kalau tidak ada dasarnya dan cuma menebak asal. はず terdengar sangat yakin, jadi kalau tebakanmu salah, kamu terkesan sok tahu.<br>・Jangan pakai はず untuk hal yang kamu sendiri ingin lakukan. “Aku berencana pergi besok” harus bilang <span class='gd-jp'>明日行くつもりだ</span>. はず bicara tentang hal yang menurut logika atau jadwal akan terjadi, bukan kemauanmu.</div><div class='gd-h'>Bedakan dari pola yang mirip</div><div class='gd-sec'><b>はずだ</b> = menurut logika begitu (dugaan): <span class='gd-jp'>会議は3時に始まるはずだ。</span>(Sesuai jadwal, rapat seharusnya mulai jam tiga)<br><b>べきだ</b> = sebaiknya / wajib dilakukan (kewajiban, pendapat): <span class='gd-jp'>会議は時間どおりに始めるべきだ。</span>(Rapat seharusnya dimulai tepat waktu)</div><div class='gd-sec'><b>ないはずだ</b> = menurut logika tidak akan (dugaan yang tenang): <span class='gd-jp'>彼は今日来ないはずだ。</span>(Seharusnya dia tidak datang hari ini)<br><b>はずがない</b> = tidak mungkin (bantahan kuat): <span class='gd-jp'>彼が来るはずがない。</span>(Tidak mungkin dia datang)</div><div class='gd-warn'>Trik cepat: “seharusnya begitu” pakai はず, “sebaiknya dilakukan” pakai べき. “Seharusnya tidak” pakai ないはず, “tidak mungkin” pakai はずがない.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Kalau diubah ke bentuk lampau 「はずだった」 artinya “seharusnya ~, tapi ternyata tidak”: <span class='gd-jp'>3時に着くはずだったのに、電車が遅れた。</span>(Seharusnya sampai jam tiga, tapi keretanya terlambat)<br>Setelah itu, kamu bisa belajar <span class='gd-jp'>〜はずがない</span> yang berarti “tidak mungkin”.</div>","n3-51":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>「〜ようだ」「〜みたいだ」 artinya <b>「sepertinya ～」「kelihatannya ～」</b>. Kamu melihat, mendengar, atau merasakan beberapa petunjuk, lalu menyimpulkannya sendiri, tapi belum 100% yakin. Nah, di situlah pola ini dipakai. Keduanya punya arti yang sama: <b>みたい adalah versi santai untuk percakapan</b>, sedangkan ようだ lebih formal dan bisa dipakai dalam tulisan.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Menebak dari petunjuk</span>Petunjuknya kamu lihat, dengar, atau rasakan <b>sendiri</b>.</div><div class='gd-ex-line'>・<span class='gd-jp'>隣の部屋、電気が消えている。留守のようだ。</span>（Lampu kamar sebelah mati. Sepertinya tidak ada orang di rumah）</div><div class='gd-ex-line'>・<span class='gd-jp'>あれ、鍵がない。どこかで落としたみたい。</span>（Lho, kuncinya tidak ada. Sepertinya jatuh di suatu tempat）</div><div class='gd-sec'>Pola ini juga sering dipakai untuk menceritakan kondisi tubuh sendiri, artinya 「aku merasa begitu, tapi tidak bisa memastikan」.</div><div class='gd-ex-line'>・<span class='gd-jp'>ちょっと熱があるみたい。</span>（Sepertinya aku agak demam）</div><div class='gd-sec'><span class='gd-tag'>Seperti ～</span>Sebenarnya bukan, tapi mirip sekali. Sering muncul bersama <span class='gd-jp'>まるで</span>（seolah-olah）.</div><div class='gd-ex-line'>・<span class='gd-jp'>まるで夢みたい。</span>（Seperti mimpi saja）</div><div class='gd-ex-line'>・<span class='gd-jp'>今日は春のように暖かい。</span>（Hari ini hangat seperti musim semi）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Kata kerja, kata sifat-い</b>: langsung sambung dengan bentuk biasa (bentuk tanpa ます／です). Untuk keduanya sama.<br><span class='gd-pair'><span class='gd-jp'>降っている</span> → <span class='gd-jp'>降っているようだ</span></span>／<span class='gd-jp'>降っているみたいだ</span><br><span class='gd-pair'><span class='gd-jp'>寒い</span> → <span class='gd-jp'>寒いようだ</span></span>／<span class='gd-jp'>寒いみたいだ</span></div><div class='gd-sec'><b>Kata benda, kata sifat-な</b>: di sini keduanya berbeda, jadi ingat baik-baik.<br>Kata benda＋ようだ harus ditambah 「の」 dulu: <span class='gd-pair'><span class='gd-jp'>留守</span> → <span class='gd-jp'>留守のようだ</span></span><br>Kata benda＋みたいだ langsung disambung: <span class='gd-pair'><span class='gd-jp'>留守</span> → <span class='gd-jp'>留守みたいだ</span></span><br>Kata sifat-な＋ようだ harus ditambah 「な」 dulu: <span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かなようだ</span></span><br>Kata sifat-な＋みたいだ langsung disambung: <span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かみたいだ</span></span></div><div class='gd-sec'>Untuk hal yang sudah lampau, kata benda dan kata sifat-な diubah dulu menjadi 「だった」 baru disambung. Di bentuk ini keduanya jadi sama: <span class='gd-pair'><span class='gd-jp'>留守だった</span> → <span class='gd-jp'>留守だったようだ</span></span>／<span class='gd-jp'>留守だったみたいだ</span><br>Supaya terdengar sopan, ganti だ dengan です: <span class='gd-jp'>ようです</span>、<span class='gd-jp'>みたいです</span>.</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'>Kalau diikuti kata benda, bentuknya jadi <b>ような／みたいな</b>. Kalau diikuti kata kerja atau kata sifat, jadi <b>ように／みたいに</b>.</div><div class='gd-ex-line'>・<span class='gd-jp'>お寿司みたいな日本料理が好きです。</span>（Aku suka masakan Jepang seperti sushi）</div><div class='gd-ex-line'>・<span class='gd-jp'>日本人みたいに日本語を話したい。</span>（Aku ingin bicara bahasa Jepang seperti orang Jepang）</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Setelah kata benda: ようだ pakai 「の」, みたいだ tidak. <span class='gd-jp'>学生のようだ</span> dan <span class='gd-jp'>学生みたいだ</span> sama-sama benar, sedangkan 「学生のみたい」 dan 「学生ようだ」 salah.<br>・Banyak yang mengira bentuk biasa harus memakai 「だ」 lalu menulis 「留守だみたい」. Itu salah. Kata benda bentuk sekarang langsung disambung: <span class='gd-jp'>留守みたい</span>.<br>・みたい dibaca sama dengan 「見たい」 (ingin melihat), jadi lihat konteksnya: <span class='gd-jp'>子供みたい</span> artinya 「seperti anak kecil」, sedangkan <span class='gd-jp'>映画が見たい</span> artinya 「ingin menonton film」.<br>・みたい adalah bahasa lisan. Untuk laporan, esai, atau surat resmi, pakai ようです. Ngobrol dengan orang yang lebih tua boleh pakai みたいです, tapi di situasi formal ようです lebih pantas.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Sama-sama soal 「hujan」, tapi lihat dari mana informasimu berasal:<br><b>ようだ／みたいだ</b>＝kesimpulan dari petunjuk yang kamu lihat sendiri: <span class='gd-jp'>みんな傘をさしている。雨が降っているみたいだ。</span>（Semua orang pakai payung. Sepertinya sedang hujan）<br><b>らしい</b>＝kata orang, kamu sendiri belum memastikan: <span class='gd-jp'>田中さんの話では、外は雨が降っているらしい。</span>（Kata Tanaka, di luar sepertinya hujan）<br><b>そうだ</b>（kelihatannya）＝di depan mata tampak akan segera terjadi, tapi belum terjadi: <span class='gd-jp'>空が暗い。雨が降りそうだ。</span>（Langitnya gelap. Kelihatannya mau hujan）. Cara menyambungnya berbeda: buang ます dari bentuk ます lalu tambahkan そうだ: <span class='gd-pair'><span class='gd-jp'>降ります</span> → <span class='gd-jp'>降りそうだ</span></span></div><div class='gd-warn'>Tips memilih: kalau kamu menebak dari yang kamu lihat atau rasakan sendiri, pakai ようだ／みたい. Kalau berdasarkan kata orang, pakai らしい. Kalau kelihatannya 「hampir ～」, pakai そうだ.</div>","n3-52":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>「らしい」 punya dua arti, seperti dua ungkapan yang berbeda:<br>①<b>「katanya ～」「sepertinya ～」</b>: tebakan berdasarkan kabar yang kamu dengar atau baca, atau petunjuk objektif yang kamu lihat. Bukan sesuatu yang bisa kamu pastikan sendiri.<br>②<b>「khas ～」「memang seperti ～」</b>: seperti kalau kita bilang 「benar-benar terasa seperti musim semi」 atau 「ini memang seperti dia banget」.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>①Katanya・Sepertinya</span>Menyampaikan kabar yang kamu dengar atau lihat, sekaligus menandakan 「aku cuma dengar, tidak menjamin」.</div><div class='gd-ex-line'>・<span class='gd-jp'>来週から気温が下がるらしい。</span>（Katanya mulai minggu depan suhu akan turun）</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さん、会社を辞めるらしいよ。</span>（Katanya Tanaka mau keluar dari kantor, lho）</div><div class='gd-ex-line'>・<span class='gd-jp'>あの店のラーメン、すごくおいしいらしい。</span>（Katanya ramen di toko itu enak banget）</div><div class='gd-ex-line'>・<span class='gd-jp'>地面が濡れている。雨が降ったらしい。</span>（Tanahnya basah. Sepertinya tadi hujan）</div><div class='gd-sec'><span class='gd-tag'>②Khas ～</span>Kata benda diletakkan di depannya, artinya 「sangat sesuai dengan kesan yang seharusnya dimiliki hal itu」. Biasanya bernada pujian.</div><div class='gd-ex-line'>・<span class='gd-jp'>今日は春らしい天気ですね。</span>（Cuaca hari ini terasa seperti musim semi, ya）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の発言はいかにも彼らしい。</span>（Ucapannya itu memang khas dia banget）</div><div class='gd-ex-line'>・<span class='gd-jp'>遅刻するなんて、彼らしくない。</span>（Masa terlambat, itu bukan dia banget）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Arti ①</b><br>Kata kerja, kata sifat-い: langsung disambung, bentuk lampau dan negatif juga boleh.<br><span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行くらしい</span></span><span class='gd-pair'><span class='gd-jp'>行かない</span> → <span class='gd-jp'>行かないらしい</span></span><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高いらしい</span></span><br>Kata sifat-な, kata benda: <b>buang だ</b> lalu sambung.<br><span class='gd-pair'><span class='gd-jp'>静かだ</span> → buang だ → <span class='gd-jp'>静からしい</span></span><span class='gd-pair'><span class='gd-jp'>雨だ</span> → <span class='gd-jp'>雨らしい</span></span><br>Untuk lampau, だった tetap dipertahankan: <span class='gd-pair'><span class='gd-jp'>雨だった</span> → <span class='gd-jp'>雨だったらしい</span></span></div><div class='gd-sec'><b>Arti ②</b><br>Kata benda＋らしい: <span class='gd-jp'>春らしい</span>、<span class='gd-jp'>学生らしい</span>、<span class='gd-jp'>彼らしい</span><br>Sering ditambah <span class='gd-jp'>いかにも</span> atau <span class='gd-jp'>本当に</span> untuk penekanan, misalnya <span class='gd-jp'>いかにも先生らしい話し方</span>（cara bicara yang benar-benar berwibawa seperti guru）.</div><div class='gd-sec'>「らしい」 sendiri berubah seperti kata sifat-い: <span class='gd-jp'>らしくない</span>、<span class='gd-jp'>らしかった</span>、<span class='gd-jp'>らしいです</span>.</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Jangan menambah だ pada kata sifat-な dan kata benda: yang benar <span class='gd-jp'>静からしい</span>, bukan 静かだらしい.<br>・<b>Kalau langsung disambung ke kata benda, kedua arti sama-sama mungkin</b>, jadi lihat konteksnya. Misalnya <span class='gd-jp'>先生らしい人が来た</span> biasanya arti ①: 「datang seseorang yang sepertinya guru」, bukan 「orang yang sangat berjiwa guru」.<br>・Letakkan negatif di tempat yang tepat: 「katanya dia tidak datang」 adalah <span class='gd-jp'>来ないらしい</span> (①, kata kerja di depannya yang dinegatifkan), sedangkan <span class='gd-jp'>彼らしくない</span> adalah ② 「tidak seperti dia」.<br>・① artinya 「aku dengar dari orang」, jadi tidak bisa dipakai untuk hal yang kamu alami sendiri. Kalau kamu sendiri yang besok pergi, katakan <span class='gd-jp'>明日行きます</span>. Kalau bilang 「明日行くらしい」, kedengarannya seperti sedang membicarakan orang lain.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'><b>らしい（①）</b>＝kata orang: <span class='gd-jp'>午後から雨が降るらしい。</span>（Katanya mulai siang akan hujan）<br><b>そうだ（kabar）</b>＝menyampaikan dengan jelas dari sumber tertentu: <span class='gd-jp'>天気予報によると、午後から雨が降るそうだ。</span>（Menurut ramalan cuaca, mulai siang akan hujan）<br><b>ようだ・みたいだ</b>＝kamu lihat atau rasakan sendiri: <span class='gd-jp'>傘を持った人が入ってきた。雨が降っているみたい。</span>（Ada orang masuk membawa payung. Sepertinya di luar hujan）<br>Selain itu, kalau melihat tanda-tanda di depan mata dan merasa sebentar lagi akan terjadi, pakai <span class='gd-jp'>雨が降りそうだ</span>（kelihatannya mau hujan）.</div><div class='gd-warn'>Tips memilih: kalau hanya meneruskan kabar yang kamu dengar apa adanya, pakai そうだ. Kalau menebak dari kabar yang kamu dengar atau petunjuk objektif, dengan nuansa 「kira-kira begitu」, pakai らしい. Kalau menilai dari perasaan atau pengalamanmu sendiri, pakai ようだ・みたいだ.</div><div class='gd-sec'><b>らしい（②）dan っぽい</b> juga sering tertukar:<br><span class='gd-jp'>子どもらしい笑顔</span>（senyum polos khas anak kecil）: memang anak kecil dan sesuai dengan sifat anak kecil, cenderung memuji.<br><span class='gd-jp'>大人なのに子どもっぽい。</span>（Sudah dewasa tapi kekanak-kanakan）: bukan anak kecil tapi mirip anak kecil, sering bernada negatif.</div><div class='gd-warn'>Tips memilih: 「memang begitu dan terasa khas」 pakai らしい; 「sebenarnya bukan, tapi agak mirip」 pakai っぽい.</div>","n3-57":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜たびに」artinya <b>「setiap kali ～, (selalu) ～」</b>. Begitu hal pertama terjadi, hal kedua ikut terjadi, nyaris tanpa pengecualian. Contohnya \"setiap kali dengar lagu ini, aku mau menangis\" atau \"setiap kali dinas ke luar kota, aku selalu beli oleh-oleh\". Nah, itu pakai pola ini.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Perasaan atau reaksi yang selalu muncul</span>Setiap menghadapi suatu hal, perasaan yang sama muncul di hatimu.</div><div class='gd-ex-line'>・<span class='gd-jp'>この写真を見るたびに、学生時代を思い出す。</span>（Setiap kali melihat foto ini, aku teringat masa sekolah）</div><div class='gd-ex-line'>・<span class='gd-jp'>この歌を聞くたびに、泣いてしまう。</span>（Setiap kali mendengar lagu ini, aku pasti menangis）</div><div class='gd-sec'><span class='gd-tag'>Hal yang selalu dilakukan</span>Setiap kali sesuatu terjadi, kamu selalu melakukan tindakan yang sama.</div><div class='gd-ex-line'>・<span class='gd-jp'>出張のたびにお土産を買って帰る。</span>（Setiap kali dinas ke luar kota, aku selalu membawa oleh-oleh pulang）</div><div class='gd-sec'><span class='gd-tag'>Selalu melihat perubahan</span>Setiap kali bertemu, kamu menyadari ada yang berbeda.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼に会うたびに、背が伸びている。</span>（Setiap kali bertemu dia, tubuhnya sudah tambah tinggi）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Kata kerja</b>: bentuk kamus (bentuk dasar seperti yang kamu temukan di kamus) langsung ditambah たびに.<br><span class='gd-pair'><span class='gd-jp'>会う</span> → <span class='gd-jp'>会うたびに</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見るたびに</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来るたびに</span></span></div><div class='gd-sec'><b>Kata benda</b>: sisipkan「の」di tengah.<br><span class='gd-pair'><span class='gd-jp'>旅行</span> → <span class='gd-jp'>旅行のたびに</span></span><span class='gd-pair'><span class='gd-jp'>試験</span> → <span class='gd-jp'>試験のたびに</span></span><br>Kata benda di depannya haruslah <b>peristiwa yang bisa berulang</b>, seperti <span class='gd-jp'>出張</span>, <span class='gd-jp'>旅行</span>, <span class='gd-jp'>試験</span>, <span class='gd-jp'>引っ越し</span>. Untuk hujan, <span class='gd-jp'>雨のたびに</span> dan <span class='gd-jp'>雨が降るたびに</span> sama-sama boleh.</div><div class='gd-h'>Hati-hati, ini sering salah</div><div class='gd-warn'>・Meskipun yang diceritakan masa lalu, <b>bagian depan tetap memakai bentuk kamus</b>. Bentuk lampau「た」cukup ditaruh di akhir kalimat: <span class='gd-jp'>子供のころ、祖母の家に行くたびに、お菓子をもらった。</span>（Waktu kecil, setiap kali pergi ke rumah nenek, aku selalu dikasih kue）Jangan bilang「行ったたびに」.<br>・Bagian depan harus berupa hal yang <b>bisa terjadi berkali-kali</b>. Hal yang hanya terjadi sekali seumur hidup (lahir, lulus kuliah) tidak bisa dipakai.<br>・Kata benda di depannya harus berupa \"suatu peristiwa\". Kata benda yang bukan peristiwa seperti <span class='gd-jp'>本</span> dan <span class='gd-jp'>先生</span> tidak bisa. Ubah jadi kata kerja: <span class='gd-jp'>本を読むたびに</span>（setiap kali membaca buku）.<br>・Rutinitas harian yang sudah biasa, misalnya sikat gigi atau sarapan, biasanya orang Jepang langsung bilang <span class='gd-jp'>毎朝</span> atau <span class='gd-jp'>いつも</span>. Kalau pakai たびに, kesannya seperti menekankan hal yang istimewa, jadi terdengar aneh.<br>・たびに juga sering ditulis dengan kanji <span class='gd-jp'>度に</span>. Bacaannya sama, jadi jangan kira itu tata bahasa lain.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Sama-sama soal \"pergi ke Jepang\":<br><span class='gd-jp'>日本へ行くたびに、ラーメンを食べる。</span>（Setiap kali pergi ke Jepang, aku selalu makan ramen）<br>　→ Menekankan \"setiap kali tanpa terlewat\".<br><span class='gd-jp'>日本へ行くときは、いつもラーメンを食べる。</span>（Kalau pergi ke Jepang, aku selalu makan ramen）<br>　→ Artinya hampir sama, tapi nadanya lebih datar dan sehari-hari.<br><span class='gd-jp'>二年ごとに日本へ行く。</span>（Aku pergi ke Jepang setiap dua tahun）<br>　→ Di depan <b>ごとに</b> bisa ada angka, untuk bilang \"setiap sekian waktu\" atau \"setiap sekian buah\". たびに tidak bisa begitu, jadi tidak boleh bilang「二年のたびに」.</div><div class='gd-warn'>Trik cepat: kalau di depannya <b>angka atau rentang waktu</b>, pakai ごとに. Kalau di depannya <b>suatu peristiwa</b> dan kamu mau bilang \"setiap kali ～, ～\", pakai たびに. Kalau mau terdengar lebih santai, boleh juga pakai「ときはいつも」.</div>","n3-58":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜を中心に」artinya <b>「berpusat pada ～」「dengan ～ sebagai inti」「terutama ～」</b>. Sesuatu dijadikan inti, lalu hal-hal lain berkembang mengelilinginya. Bisa juga untuk menyebut titik berat atau cakupan utama suatu hal.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Tempat</span>Berpusat di suatu tempat, lalu menyebar ke sekitarnya.</div><div class='gd-ex-line'>・<span class='gd-jp'>駅を中心に店が並んでいる。</span>（Berpusat di stasiun, toko-toko berjajar di sekelilingnya）</div><div class='gd-ex-line'>・<span class='gd-jp'>九州を中心に大雨が降った。</span>（Hujan lebat turun terutama di sekitar Kyushu）</div><div class='gd-sec'><span class='gd-tag'>Orang</span>Seseorang menjadi inti, dan semua orang bergerak mengelilinginya.</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんを中心に、新しいチームができた。</span>（Dengan Pak Tanaka sebagai inti, terbentuk tim baru）</div><div class='gd-sec'><span class='gd-tag'>Cakupan utama・titik berat</span>Artinya \"terutama ～\", tapi bukan berarti hanya itu saja.</div><div class='gd-ex-line'>・<span class='gd-jp'>このアニメは子どもを中心に人気がある。</span>（Anime ini populer terutama di kalangan anak-anak）</div><div class='gd-ex-line'>・<span class='gd-jp'>今日は文法を中心に復習しよう。</span>（Hari ini kita review terutama tata bahasa, yuk）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Di depan harus <b>kata benda</b>, lalu di belakangnya menyusul tindakan atau keadaan:<br><span class='gd-pair'><span class='gd-jp'>駅</span> → <span class='gd-jp'>駅を中心に</span></span>　Bisa juga <span class='gd-jp'>駅を中心にして</span> atau <span class='gd-jp'>駅を中心として</span>, artinya sama.<br>Kalau mau langsung menerangkan kata benda di belakangnya, ubah jadi <b>を中心とした</b> (atau <span class='gd-jp'>を中心とする</span>):</div><div class='gd-ex-line'>・<span class='gd-jp'>野菜を中心とした食事</span>（pola makan yang berpusat pada sayuran）</div><div class='gd-ex-line'>・<span class='gd-jp'>東京を中心とした関東地方</span>（wilayah Kanto yang berpusat di Tokyo）</div><div class='gd-h'>Hati-hati, ini sering salah</div><div class='gd-warn'>・Partikelnya adalah <b>を</b>: <span class='gd-jp'>駅を中心に</span>, bukan「駅に中心に」atau「駅が中心に」.<br>・Di depannya tidak bisa langsung kata kerja, harus kata benda. Kalau mau bilang \"terutama belajar\", pakai <span class='gd-jp'>勉強を中心に</span>.<br>・「を中心に」berbeda dengan「<b>の</b>中心に」. <span class='gd-jp'>公園の中心に噴水がある。</span> artinya \"di tengah-tengah taman ada air mancur\". Ini hanya menyebut posisi, bukan \"berkembang dengan ～ sebagai pusat\".<br>・\"Terutama ～\" tidak sama dengan \"hanya\": <span class='gd-jp'>若者を中心に人気だ</span> artinya paling banyak anak muda, tapi kelompok usia lain juga ada yang suka.<br>・Saat menerangkan kata benda di belakangnya, jangan tulis「野菜を中心にの食事」. Pakai <span class='gd-jp'>野菜を中心とした食事</span>.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'><b>をはじめ（として）</b> = \"mulai dari A, lalu ada B, C ...\". Ini <b>menyebut satu contoh wakil</b>, dan titik beratnya ada pada hal lain yang juga ada.<br><b>を中心に</b> = \"terutama A\". Titik beratnya ada pada <b>A sebagai inti dengan porsi terbesar</b>.<br>Coba bandingkan dalam situasi yang sama:</div><div class='gd-ex-line'>・<span class='gd-jp'>このお菓子は東京を中心に人気がある。</span>（Camilan ini populer terutama di Tokyo）</div><div class='gd-ex-line'>・<span class='gd-jp'>このお菓子は東京をはじめ、大阪や福岡でも人気がある。</span>（Camilan ini populer di Tokyo, juga di Osaka, Fukuoka, dan kota lainnya）</div><div class='gd-warn'>Trik cepat: kalau mau bilang \"terutama di A, berpusat di A\", pakai を中心に. Kalau mau bilang \"A hanya contoh wakil, B dan C juga sama\", pakai をはじめ.</div>","n3-55":"<div class='gd-h'>Intinya dulu</div><div class='gd-sec'>「〜ようにと」dipakai untuk <b>menyampaikan kembali pesan atau perintah orang lain</b>, seperti dalam bahasa Indonesia: \"Guru menyuruh kami datang tepat waktu\" atau \"Dokter berpesan agar aku mengurangi garam\". Kamu tidak mengulang kata-kata orangnya persis, tapi menyampaikan poin \"dia menyuruhku melakukan apa\". 「と」di belakangnya berfungsi seperti tanda kutip: menandai bahwa bagian di depannya adalah isi pesan.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Hal yang diminta untuk dilakukan: bentuk kamus＋ようにと　<span class='gd-pair'><span class='gd-jp'>守る</span> → <span class='gd-jp'>守るようにと</span></span><br>Hal yang diminta untuk tidak dilakukan: bentuk ない＋ようにと　<span class='gd-pair'><span class='gd-jp'>遅れない</span> → <span class='gd-jp'>遅れないようにと</span></span><br>Di belakangnya ada kata kerja \"menyampaikan pesan\": <span class='gd-jp'>言う</span>、<span class='gd-jp'>伝える</span>、<span class='gd-jp'>注意する</span>、<span class='gd-jp'>頼む</span>, dan juga kata kerja untuk berdoa atau berharap: <span class='gd-jp'>祈る</span>、<span class='gd-jp'>願う</span>.</div><div class='gd-sec'>Dalam percakapan, 「と」sering dihilangkan, jadi「〜ように言われた」, artinya sama. Kalau pakai 「と」, penekanannya lebih ke \"ini isi pesan dari orang itu\".</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>Disuruh</span>「〜ようにと言われた」: orang lain menyuruhku melakukan sesuatu. Ini yang paling sering dipakai sehari-hari.</div><div class='gd-ex-line'>・<span class='gd-jp'>母に早く帰るようにと言われた。</span>(Ibu menyuruhku pulang lebih awal)</div><div class='gd-ex-line'>・<span class='gd-jp'>医者にお酒を飲まないようにと言われた。</span>(Dokter menyuruhku tidak minum alkohol)</div><div class='gd-sec'><span class='gd-tag'>Minta tolong disampaikan</span>「〜ようにと伝えてください」: kamu minta tolong menyampaikan pesan ke orang ketiga.</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんに、明日は8時に来るようにと伝えてください。</span>(Tolong sampaikan ke Pak Tanaka agar besok datang jam 8)</div><div class='gd-sec'><span class='gd-tag'>Doa / harapan</span>「〜ようにと祈る」: berharap sesuatu bisa terwujud.</div><div class='gd-ex-line'>・<span class='gd-jp'>試験に合格できるようにと祈った。</span>(Aku berdoa semoga bisa lulus ujian)</div><div class='gd-h'>Bagian yang gampang keliru</div><div class='gd-warn'>・Tindakan di depan ように dilakukan oleh <b>orang yang diberi pesan</b>, bukan oleh orang yang memberi perintah. Misalnya <span class='gd-jp'>母に早く帰るように言われた</span>: yang harus pulang lebih awal itu aku, bukan ibu.<br>・Isi pesan memakai bentuk kamus atau bentuk ない, jangan bentuk た: yang benar <span class='gd-jp'>帰るように言われた</span>, bukan 「帰ったように言われた」. Dengan kata kerja seperti 「言う」「注意する」, jangan juga taruh bentuk ます di depan ように.<br>・「ように言う」terasa seperti <b>memberi perintah</b>, cocok dari atas ke bawah atau antar teman sebaya. Kalau kamu meminta guru atau atasan melakukan sesuatu, 「ように言った」terdengar seperti memerintah mereka. Dalam kasus itu, lebih sopan memakai 「〜てくださいとお願いした」.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'><b>「」と言った</b> = kutipan langsung persis seperti ucapan aslinya: <span class='gd-jp'>先生は「時間を守りなさい」と言った。</span>(Guru berkata: \"Tepati waktu!\")<br><b>ようにと言った</b> = menyampaikan intinya saja: <span class='gd-jp'>先生は時間を守るようにと言った。</span>(Guru menyuruh kami menepati waktu)<br>「〜なさい」atau「〜てください」dalam ucapan aslinya berubah menjadi「〜ように」saat disampaikan kembali.</div><div class='gd-sec'><b>ように (supaya)</b> = kamu sendiri melakukan sesuatu demi suatu tujuan: <span class='gd-jp'>忘れないようにメモした。</span>(Aku mencatat supaya tidak lupa)<br><b>ようにと (pesan)</b> = orang lain menyuruhku melakukan sesuatu: <span class='gd-jp'>忘れないようにと言われた。</span>(Aku diingatkan supaya jangan lupa)</div><div class='gd-warn'>Trik cepat: kalau di belakang ように ada kata kerja penyampai pesan seperti 「言う、伝える、注意する、頼む」, artinya \"pesan/perintah\". Kalau di belakangnya ada tindakan yang kamu lakukan sendiri, artinya \"supaya\".</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Kalau pesan yang kamu terima sudah jadi kebiasaanmu sendiri, pakai「〜ようにしている」: <span class='gd-jp'>医者に言われてから、塩分を控えるようにしている。</span>(Sejak diingatkan dokter, aku berusaha mengurangi garam)</div>","n3-56":"<div class='gd-h'>Intinya dulu</div><div class='gd-sec'>「〜ことから」artinya <b>\"karena hal ～ ini, makanya ～\"</b>. Mirip pemandu wisata yang menjelaskan: \"Gunung ini bentuknya mirip panci, makanya dinamai Gunung Panci\"; atau detektif yang menyimpulkan: \"Dilihat dari jendela yang pecah, rumah ini kemalingan\". Di depan ada <b>fakta yang bisa dilihat</b>, di belakang ada <b>nama</b> atau <b>kesimpulan</b> yang didapat dari fakta itu.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Asal-usul nama</span>Menjelaskan kenapa sesuatu diberi nama tertentu atau dijuluki begitu. Di belakangnya sering ada「<span class='gd-jp'>〜と呼ばれる</span>」「<span class='gd-jp'>〜という名前がついた</span>」.</div><div class='gd-ex-line'>・<span class='gd-jp'>山の形が鍋に似ていることから、「鍋山」という名前がついた。</span>(Karena bentuk gunungnya mirip panci, gunung itu dinamai 「鍋山」)</div><div class='gd-ex-line'>・<span class='gd-jp'>いつも笑顔でいることから、彼は「太陽」と呼ばれている。</span>(Karena selalu tersenyum, dia dijuluki 「太陽」)</div><div class='gd-sec'><span class='gd-tag'>Dasar penilaian</span>Menarik kesimpulan dari suatu petunjuk. Di belakangnya sering ada「<span class='gd-jp'>〜と分かる</span>」「<span class='gd-jp'>〜と考えられる</span>」.</div><div class='gd-ex-line'>・<span class='gd-jp'>窓が割れていることから、泥棒に入られたと分かった。</span>(Dari jendela yang pecah, ketahuan bahwa rumah dimasuki pencuri)</div><div class='gd-ex-line'>・<span class='gd-jp'>道がぬれていることから、夜の間に雨が降ったと考えられる。</span>(Dilihat dari jalan yang basah, sepertinya semalam hujan)</div><div class='gd-sec'><span class='gd-tag'>Menjelaskan latar belakang</span>Dalam teks pengenalan atau penjelasan, dipakai untuk menerangkan asal mula sesuatu.</div><div class='gd-ex-line'>・<span class='gd-jp'>この地域は温泉が湧いていることから、観光地として知られている。</span>(Karena di daerah ini ada air panas yang menyembur, tempat ini dikenal sebagai tempat wisata)</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Kata kerja, kata sifat-い</b>: langsung sambung dengan bentuk biasa (bentuk tanpa ます/です), bisa untuk bentuk sekarang, lampau, maupun negatif.<br><span class='gd-pair'><span class='gd-jp'>似ている</span> → <span class='gd-jp'>似ていることから</span></span><span class='gd-pair'><span class='gd-jp'>割れた</span> → <span class='gd-jp'>割れたことから</span></span><span class='gd-pair'><span class='gd-jp'>安い</span> → <span class='gd-jp'>安いことから</span></span><br><b>Kata sifat-な</b>: pertahankan「な」, atau ganti jadi「である」.<br><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かなことから</span></span><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かであることから</span></span><br><b>Kata benda</b>: tambahkan「である」di belakangnya.<br><span class='gd-pair'><span class='gd-jp'>港町</span> → <span class='gd-jp'>港町であることから</span></span></div><div class='gd-h'>Bagian yang gampang keliru</div><div class='gd-warn'>・Setelah kata benda, pakai <b>である</b>: yang benar <span class='gd-jp'>港町であることから</span>, bukan 「港町だことから」, dan bukan juga 「港町のことから」.<br>・Ini ungkapan <b>tulisan dan formal</b>, sering muncul di berita, panduan wisata, dan teks penjelasan. Kalau dipakai ngobrol dengan teman, terdengar kaku. Dalam percakapan sehari-hari cukup pakai「から」「ので」.<br>・Di belakangnya hanya boleh ada <b>fakta, nama, atau kesimpulan</b>. Tidak bisa diikuti ajakan (\"ayo ～\"), permintaan (\"tolong ～\"), atau perintah (\"～lah!\").<br>・Alasan di depan harus berupa <b>fakta yang bisa dilihat semua orang dan bisa dipastikan</b>, jadi tidak cocok untuk perasaan pribadi atau alasan yang dibuat-buat. Kalau mau bilang \"Aku capek, jadi pulang duluan\", pakai「から」「ので」.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Sama-sama tentang fakta \"jalanan basah\":<br><b>から・ので</b> = \"karena\" sehari-hari, di belakangnya boleh apa saja: peringatan, ajakan, permintaan, semuanya bisa.</div><div class='gd-ex-line'>・<span class='gd-jp'>道がぬれているから、気をつけてね。</span>(Jalannya basah, hati-hati ya)</div><div class='gd-sec'><b>ことから</b> = \"menarik kesimpulan dari fakta ini\", di belakangnya hanya boleh berupa kesimpulan atau nama.</div><div class='gd-ex-line'>・<span class='gd-jp'>道がぬれていることから、雨が降ったと分かる。</span>(Dari jalan yang basah, bisa diketahui bahwa tadi hujan)</div><div class='gd-sec'>Kalau kamu bilang「道がぬれていることから、気をつけてね」, itu salah, karena bagian belakangnya berubah menjadi peringatan untuk lawan bicara.</div><div class='gd-warn'>Trik cepat: kalau kalimatnya bisa diganti dengan \"dari fakta ～ (terlihat bahwa / makanya dinamai)\", pakai ことから. Kalau hanya \"karena\" biasa, pakai から atau ので.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Saat menjelaskan asal nama, di belakangnya hampir selalu ada bentuk pasif「<span class='gd-jp'>〜と呼ばれている</span>」(dijuluki ～). Sekalian ulangi materi「～（ら）れる（受身）」ya.</div>","n3-59":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜を通じて」「〜を通して」punya dua arti. Yang pertama <b>‘melalui ～’</b>: ada orang atau saluran perantara sehingga sesuatu bisa terjadi, misalnya ‘kenal lewat teman’ atau ‘berkomunikasi lewat internet’. Yang kedua <b>‘sepanjang ～’</b>: di depannya ada rentang waktu, artinya dari awal sampai akhir selalu begitu, seperti ‘sepanjang tahun’.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Gampang, langsung sambung setelah kata benda:<br><span class='gd-pair'><span class='gd-jp'>友達</span> → <span class='gd-jp'>友達を通じて</span></span><span class='gd-pair'><span class='gd-jp'>一年</span> → <span class='gd-jp'>一年を通して</span></span><br>Kalau dipakai di depan kata benda untuk menerangkannya, selipkan 「の」: <span class='gd-jp'>ボランティアを通しての出会い</span>（pertemuan yang terjadi lewat kegiatan sukarelawan）</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Lewat orang atau saluran</span>Ada orang yang menjadi perantara, atau saluran seperti internet, telepon, dan media.</div><div class='gd-ex-line'>・<span class='gd-jp'>友達を通じて、今の彼女と知り合った。</span>（Aku kenal pacarku yang sekarang lewat teman）</div><div class='gd-ex-line'>・<span class='gd-jp'>インターネットを通じて、世界中の人と話せる。</span>（Lewat internet, kita bisa mengobrol dengan orang di seluruh dunia）</div><div class='gd-sec'><span class='gd-tag'>Lewat pengalaman</span>Setelah melalui suatu pengalaman, kamu belajar atau merasakan sesuatu.</div><div class='gd-ex-line'>・<span class='gd-jp'>アルバイトを通して、敬語の使い方を覚えた。</span>（Lewat kerja paruh waktu, aku belajar cara memakai bahasa sopan）</div><div class='gd-sec'><span class='gd-tag'>Sepanjang periode</span>Di depannya ada rentang waktu seperti 「一年」「一生」, artinya sepanjang periode itu keadaannya sama.</div><div class='gd-ex-line'>・<span class='gd-jp'>この島は一年を通して暖かい。</span>（Pulau ini hangat sepanjang tahun）</div><div class='gd-ex-line'>・<span class='gd-jp'>祖父は一生を通じて、同じ会社で働いた。</span>（Kakekku bekerja di perusahaan yang sama seumur hidupnya）</div><div class='gd-h'>Apa bedanya を通じて dan を通して?</div><div class='gd-sec'>Di sebagian besar situasi <b>keduanya bisa saling menggantikan</b> dan artinya hampir sama, jadi santai saja. Kalau harus dibedakan:<br><b>を通じて</b> lebih sering dipakai untuk ‘saluran’ seperti internet, telepon, atau jaringan relasi.<br><b>を通して</b> lebih terasa ‘sengaja melalui sesuatu, mengalaminya sendiri’, jadi sering dipakai untuk pengalaman, latihan, dan percobaan.<br>Kalau ragu, pilih yang mana pun tidak akan salah jauh.</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・<b>Jangan dipakai untuk kendaraan atau alat biasa</b>: ‘pergi naik bus’ adalah <span class='gd-jp'>バスで行く</span>, ‘memotong pakai gunting’ adalah <span class='gd-jp'>はさみで切る</span>. Tidak bisa bilang バスを通して行く. を通じて untuk ‘orang atau saluran yang jadi perantara’, bukan alat yang kamu pegang.<br>・‘Lulus ujian’ bukan tata bahasa ini. Katakan <span class='gd-jp'>試験に合格する</span>. Jangan terkecoh oleh kata ‘melalui’ dalam bahasa Indonesia.<br>・Partikel di depannya adalah <b>を</b>, jangan ditulis に.<br>・Untuk arti ‘sepanjang periode’, di depannya harus ada <b>rentang waktu</b>, misalnya satu tahun, seumur hidup, empat musim. Artinya ‘selama seluruh periode itu’, bukan ‘setelah melewati periode itu’.<br>・Nuansanya agak formal dan sering muncul di berita, tulisan, dan perkenalan diri. Saat mengobrol dengan teman, untuk ‘dikenalkan teman’ biasanya orang bilang <span class='gd-jp'>友達の紹介で</span>.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Sama-sama ‘menyampaikan pesan ke guru’:<br><span class='gd-jp'>メールで先生に伝えた。</span>（Kusampaikan ke guru lewat email）: <b>で</b> = alat atau cara, yang paling biasa sehari-hari.<br><span class='gd-jp'>先輩を通じて先生に伝えた。</span>（Kusampaikan ke guru melalui kakak kelas）: <b>を通じて</b> = ada orang atau saluran yang menyampaikannya untukmu.<br><br>Yang juga gampang tertukar adalah <b>によって</b>, yang artinya ‘dengan cara apa sesuatu tercapai’ atau ‘karena apa sesuatu terjadi’:<br><span class='gd-jp'>この研究によって、病気の原因が分かった。</span>（Berkat penelitian ini, penyebab penyakitnya ketahuan）<br>Kalau kenalan karena dikenalkan teman, katakan <span class='gd-jp'>友達を通じて知り合った</span>, bukan 友達によって知り合った.</div><div class='gd-warn'>Trik cepat: kalau ada ‘orang, saluran, atau pengalaman’ yang jadi perantara, pakai を通じて／を通して; kalau cuma alat atau kendaraan, pakai で; kalau soal cara atau sebab, pakai によって.</div><div class='gd-h'>Setelah ini, belajar apa?</div><div class='gd-sec'>Pola yang sama, 「kata benda＋を＋〜」. Lanjutkan ke <span class='gd-jp'>〜を中心に</span>（berpusat pada ～）dan <span class='gd-jp'>〜をはじめ</span>（mulai dari ～, termasuk ～）. Ketiganya sering muncul bersama dalam satu artikel.</div>","n3-60":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜に基づいて」artinya <b>‘berdasarkan ～’ ‘sesuai dengan ～’</b>, yaitu apa yang dijadikan dasar saat melakukan sesuatu. Di awal film sering tertulis ‘Film ini diangkat dari kisah nyata’. Dalam bahasa Jepang jadi <span class='gd-jp'>この映画は実話に基づいている。</span><br>Yang ada di depannya adalah dasar ‘atas dasar apa kamu melakukannya’, misalnya fakta, data, aturan, atau pengalaman.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><span class='gd-tag'>Diikuti tindakan</span>Kata benda＋に基づいて＋kata kerja</div><div class='gd-ex-line'>・<span class='gd-jp'>規則に基づいて判断します。</span>（Kami menilai sesuai aturan）</div><div class='gd-ex-line'>・<span class='gd-jp'>データに基づいて計画を立てた。</span>（Aku menyusun rencana berdasarkan data）</div><div class='gd-sec'><span class='gd-tag'>Diikuti kata benda</span>Kata benda＋に基づく／に基づいた＋kata benda. Dua-duanya umum dipakai.</div><div class='gd-ex-line'>・<span class='gd-jp'>調査結果に基づく報告書</span>（laporan yang disusun berdasarkan hasil survei）</div><div class='gd-ex-line'>・<span class='gd-jp'>経験に基づいたアドバイス</span>（saran berdasarkan pengalaman）</div><div class='gd-sec'><span class='gd-tag'>Di akhir kalimat</span>Pakai <span class='gd-jp'>〜に基づいている</span>, artinya ‘didasarkan pada ～’.</div><div class='gd-ex-line'>・<span class='gd-jp'>この話は事実に基づいています。</span>（Cerita ini didasarkan pada kejadian nyata）</div><div class='gd-sec'>Di berita dan dokumen resmi kamu juga akan menemukan <span class='gd-jp'>に基づき</span>. Artinya sama dengan に基づいて, hanya lebih bergaya tulisan.</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Di depannya harus ada <b>dasar</b>, tidak bisa langsung orang. Untuk ‘kata guru’, katakan <span class='gd-jp'>先生の話に基づいて</span>, bukan 「先生に基づいて」.<br>・Kalau diikuti kata benda, pakai <b>基づく／基づいた</b>, jangan ditulis 「データに基づいて計画」.<br>・Dibaca <b>もとづいて</b>, kananya 「づ」 bukan 「ず」, dan saat mengetik ketik motodu.<br>・Nuansanya agak formal, sering muncul di laporan, berita, dan situasi kerja. Jarang dipakai saat mengobrol santai dengan teman.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Sama-sama membahas ‘data’, tiga ungkapan ini artinya berbeda:<br><span class='gd-jp'>データについて説明します。</span>（Aku akan menjelaskan <b>data itu sendiri</b>）<br><span class='gd-jp'>データに基づいて説明します。</span>（Aku menjelaskan dengan <b>data sebagai dasarnya</b>, misalnya menjelaskan rencana atau kesimpulan）<br><span class='gd-jp'>データによると、売り上げが増えています。</span>（<b>Menurut data</b>, penjualan sedang naik）<br>「によると」menyebutkan sumber informasi, dan diikuti ‘apa yang dikatakan data’, bukan tindakan yang kamu lakukan sendiri.</div><div class='gd-warn'>Trik cepat: ‘tentang ～’ pakai について; ‘menurut ～’ pakai によると; ‘melakukan atau menilai berdasarkan ～’ pakai に基づいて.</div>","n3-53":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「ために」punya dua arti. Yang paling sering dipakai adalah <b>「untuk～」</b>, yaitu menyatakan tujuan. Arti lainnya lebih formal, yaitu <b>「karena～」</b>, yaitu menyatakan sebab. Dalam bahasa Indonesia, \"untuk\" dan \"karena\" adalah dua kata yang berbeda. Bahasa Jepang justru memakai ために yang sama untuk keduanya, jadi kamu harus membedakannya dari konteks kalimat.</div><div class='gd-h'>Pemakaian 1: untuk～ (tujuan)</div><div class='gd-sec'><span class='gd-tag'>Untuk mencapai sesuatu</span>Kata kerja memakai <b>bentuk kamus</b> (bentuk dasar yang kamu temukan di kamus) ＋ ために. Kata benda harus diberi 「の」 dulu, jadi kata benda＋のために。</div><div class='gd-ex-line'>・<span class='gd-jp'>日本に留学するために、アルバイトでお金をためている。</span>(Untuk kuliah di Jepang, aku menabung dari kerja paruh waktu)</div><div class='gd-ex-line'>・<span class='gd-jp'>健康のために、毎朝歩いている。</span>(Demi kesehatan, aku jalan kaki setiap pagi)</div><div class='gd-sec'><span class='gd-tag'>Demi kebaikan seseorang</span>Kalau di depannya ada orang, artinya \"demi siapa\".</div><div class='gd-ex-line'>・<span class='gd-jp'>家族のために、毎日がんばって働いている。</span>(Demi keluarga, aku bekerja keras setiap hari)</div><div class='gd-h'>Pemakaian 2: karena～ (sebab)</div><div class='gd-sec'><span class='gd-tag'>\"Karena\" yang formal</span>Di depannya bisa dipasang: kata kerja bentuk た atau bentuk kamus, kata sifat-い, kata sifat-な＋な, atau kata benda＋の. Pola ini sering dipakai di berita, pengumuman stasiun, dan pengumuman tertulis. Sering juga に-nya dihilangkan sehingga hanya terdengar 「ため」. Hasil di belakangnya biasanya sesuatu yang sudah terjadi dan kurang menyenangkan, tapi tidak selalu.</div><div class='gd-ex-line'>・<span class='gd-jp'>大雪のために、電車が止まった。</span>(Karena salju lebat, kereta berhenti beroperasi)</div><div class='gd-ex-line'>・<span class='gd-jp'>事故があったために、道が混んでいる。</span>(Karena ada kecelakaan, jalanan macet)</div><div class='gd-ex-line'>・<span class='gd-jp'>台風のため、今日の授業は休みです。</span>(Karena topan, kelas hari ini diliburkan)</div><div class='gd-h'>Cara membedakan keduanya</div><div class='gd-sec'>Kalau bagian depan adalah <b>sesuatu yang ingin dicapai dan belum terjadi</b>, dan bagian belakang adalah usaha untuk itu, artinya \"untuk\".<br>Kalau bagian depan adalah <b>sesuatu yang sudah terjadi atau suatu keadaan</b>, dan bagian belakang adalah akibatnya, artinya \"karena\".<br>Kalau kamu melihat bentuk た (<span class='gd-jp'>あった</span>、<span class='gd-jp'>降った</span>), pasti artinya sebab. Kata benda＋のために bisa berarti keduanya, jadi lihat bagian belakangnya: <span class='gd-jp'>試験のために勉強する</span> (belajar untuk ujian), <span class='gd-jp'>雪のために遅れた</span> (terlambat karena salju).</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Setelah kata benda wajib ada の: tidak boleh bilang 健康ために, harus <span class='gd-jp'>健康のために</span>。<br>・Tidak boleh disambung dengan bentuk ます: tidak boleh bilang 合格しますために, harus <span class='gd-jp'>合格するために</span>。<br>・ために yang berarti \"untuk\" biasanya punya <b>subjek yang sama</b> di depan dan di belakang, dan bagian depannya harus <b>tindakan yang bisa kamu putuskan sendiri</b>. Kalau yang di depan adalah kemampuan atau keadaan seperti \"bisa bicara\", \"bisa terdengar\", \"bisa mengerti\", pakai ように (dibandingkan di bawah).<br>・ために yang berarti \"karena\" itu formal, dan bagian belakangnya tidak boleh berupa permintaan, ajakan, atau perintah. Tidak boleh bilang 雨のために傘を持っていこう, harus <span class='gd-jp'>雨だから、傘を持っていこう。</span> (Hujan nih, bawa payung yuk). Dalam obrolan sehari-hari, untuk menyatakan sebab cukup pakai から atau ので。</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>ために yang berarti \"untuk\" dan <b>ように</b> sama-sama bisa diterjemahkan jadi \"untuk / agar\", tapi isi bagian depannya berbeda.<br>Satu hal yang sama bisa diungkapkan dengan keduanya, hanya sudut pandangnya yang berbeda:<br>・<span class='gd-jp'>N2に合格するために、毎日勉強している。</span> (Untuk lulus N2, aku belajar setiap hari): 合格する adalah hal yang kamu usahakan capai.<br>・<span class='gd-jp'>N2に合格できるように、毎日勉強している。</span> (Supaya bisa lulus N2, aku belajar setiap hari): 合格できる adalah keadaan yang kamu harapkan terjadi.<br>Contoh di bawah ini hanya bisa memakai ように:<br>・<span class='gd-jp'>みんなに聞こえるように、大きな声で話した。</span> (Agar semua orang bisa dengar, aku bicara dengan suara keras)<br>・<span class='gd-jp'>子どもにも読めるように、ひらがなで書いた。</span> (Agar anak-anak juga bisa membaca, aku menulisnya dengan hiragana)<br>聞こえる dan 読める adalah kemampuan atau keadaan. Pada kalimat kedua, subjeknya juga berbeda (yang menulis aku, yang membaca anak-anak), jadi ために tidak bisa dipakai.</div><div class='gd-warn'>Tips cepat: kalau bagian depan adalah \"tindakan yang kamu lakukan dengan sengaja\", pakai ために. Kalau bagian depan adalah kemampuan atau keadaan seperti 「できる、わかる、聞こえる、見える」, atau subjek depan dan belakang berbeda, pakai ように。</div><div class='gd-h'>Lanjut belajar setelah ini</div><div class='gd-sec'>Untuk bagian tujuan, lanjut ke 「〜ように」 (n3-54). Untuk bagian sebab, kamu bisa membandingkan 「〜おかげで」 (berkat～, hasil baik) dan 「〜せいで」 (gara-gara～, hasil buruk). Keduanya juga mengungkapkan rasa terima kasih atau keluhan si pembicara.</div>","n3-54":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜ように」 artinya <b>「agar～」「supaya～」</b> dan juga <b>「supaya tidak～」</b>. Bagian depan menyatakan hasil yang kamu harapkan, bagian belakang menyatakan apa yang kamu lakukan demi hasil itu: <span class='gd-jp'>後ろの人にも聞こえるように、マイクを使った。</span> (Supaya orang di belakang juga bisa dengar, aku memakai mikrofon)</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Kalau berharap \"bisa～\": bentuk kamus＋ように<br><span class='gd-pair'><span class='gd-jp'>聞こえる</span> → <span class='gd-jp'>聞こえるように</span></span><br><span class='gd-pair'><span class='gd-jp'>話す</span> → ubah dulu jadi bentuk \"bisa bicara\" <span class='gd-jp'>話せる</span> → <span class='gd-jp'>話せるように</span></span><br>Kalau berharap \"supaya tidak～\": bentuk ない＋ように<br><span class='gd-pair'><span class='gd-jp'>忘れる</span> → <span class='gd-jp'>忘れない</span> → <span class='gd-jp'>忘れないように</span></span></div><div class='gd-h'>Biasanya yang ada di depan</div><div class='gd-sec'>Intinya: yang ada di depan ように adalah <b>hasil yang tidak bisa kamu putuskan langsung</b>, kamu hanya bisa berusaha agar hal itu terjadi. Yang umum ada beberapa macam:</div><div class='gd-sec'><span class='gd-tag'>Bisa～</span>Di depannya ada ungkapan \"bisa～\" (bentuk potensial).</div><div class='gd-ex-line'>・<span class='gd-jp'>字幕なしでドラマが見られるように、毎日日本語を聞いています。</span>(Supaya bisa menonton drama tanpa subtitle, aku mendengarkan bahasa Jepang setiap hari)</div><div class='gd-ex-line'>・<span class='gd-jp'>日本語で話せるように、毎日練習している。</span>(Supaya bisa mengobrol dalam bahasa Jepang, aku berlatih setiap hari)</div><div class='gd-sec'><span class='gd-tag'>Hal yang terjadi dengan sendirinya</span>Bukan tindakan yang bisa langsung kamu lakukan sesukamu, misalnya <span class='gd-jp'>聞こえる</span> (terdengar), <span class='gd-jp'>間に合う</span> (keburu), <span class='gd-jp'>治る</span> (sembuh).</div><div class='gd-ex-line'>・<span class='gd-jp'>風邪が早く治るように、薬を飲んで寝た。</span>(Supaya flunya cepat sembuh, aku minum obat lalu tidur)</div><div class='gd-ex-line'>・<span class='gd-jp'>最終便に間に合うように、早めに空港へ向かった。</span>(Supaya keburu naik penerbangan terakhir, aku berangkat lebih awal ke bandara)</div><div class='gd-sec'><span class='gd-tag'>Supaya tidak～</span>Bentuk ない＋ように＝supaya tidak～. Dalam pola ini, tindakan yang bisa kamu kendalikan sendiri pun boleh dipakai.</div><div class='gd-ex-line'>・<span class='gd-jp'>忘れないように、メモしておこう。</span>(Biar tidak lupa, dicatat dulu ya)</div><div class='gd-ex-line'>・<span class='gd-jp'>遅れないように、早めに家を出た。</span>(Supaya tidak terlambat, aku berangkat dari rumah lebih awal)</div><div class='gd-h'>Tambahan: subjek depan dan belakang boleh berbeda</div><div class='gd-sec'>Ini bukan pemakaian lain, tapi ciri khas ように: orang di bagian depan boleh berbeda dengan orang di bagian belakang. Pada kalimat di bawah, yang \"mengerti\" adalah anak, sedangkan yang \"menjelaskan\" adalah aku.</div><div class='gd-ex-line'>・<span class='gd-jp'>子どもにも分かるように、簡単な言葉で説明した。</span>(Supaya anak-anak juga mengerti, aku menjelaskannya dengan kata-kata sederhana)</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Untuk tindakan yang kamu sendiri bisa putuskan mau dilakukan atau tidak, <b>bentuk afirmatif</b> tidak bisa langsung disambung dengan ように:<br>× 日本語を勉強するように、日本へ来た。<br>○ <span class='gd-jp'>日本語を勉強するために、日本へ来た。</span> (Aku datang ke Jepang untuk belajar bahasa Jepang)<br>・Kata benda＋「のように」 artinya \"seperti～\", tidak ada hubungannya dengan arti \"agar\" di sini: <span class='gd-jp'>子どものように笑う</span> (tertawa seperti anak kecil).<br>・Setelah <span class='gd-jp'>ように</span> ada tindakan baru, sedangkan <span class='gd-jp'>ようにする</span> artinya \"aku berusaha～\". Jangan tertukar: <span class='gd-jp'>忘れないように、メモする</span> (mencatat supaya tidak lupa) vs <span class='gd-jp'>忘れないようにする</span> (aku akan berusaha tidak lupa).</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Sama-sama menabung untuk kuliah di luar negeri:<br><span class='gd-jp'>留学するために、お金をためている。</span> (Untuk kuliah di luar negeri, aku menabung)<br><span class='gd-jp'>留学できるように、お金をためている。</span> (Supaya bisa kuliah di luar negeri, aku menabung)<br>Di depan <b>ために</b> ada <b>hal yang kamu putuskan sendiri untuk dilakukan</b>, jadi \"kuliah di luar negeri\" adalah tujuannya sendiri. Di depan <b>ように</b> ada <b>bisa atau tidaknya</b>, jadi \"bisa kuliah di luar negeri\" tergantung cukup tidaknya uang.<br>Selain itu, di ために subjek depan dan belakang harus orang yang sama, sedangkan di ように boleh berbeda. ために bisa langsung dipasang pada kata benda (<span class='gd-jp'>健康のために</span>), sedangkan ように tidak bisa.</div><div class='gd-warn'>Tips cepat: kalau tindakan di depan sepenuhnya kamu yang menentukan, pakai ために. Kalau di depannya \"bisa～\", \"supaya tidak～\", atau bergantung pada keberuntungan atau orang lain, pakai ように。</div><div class='gd-h'>Lanjut belajar setelah ini</div><div class='gd-sec'>「〜ようにと」 dipakai untuk memunculkan isi doa atau pesan, misalnya <span class='gd-jp'>合格できるようにと祈った</span> (berdoa agar bisa lulus). Kamu juga bisa kembali membandingkan 「〜ようにする」 dan 「〜ようになる」。</div>","n3-62":"<div class='gd-h'>Pahami dulu lewat satu kalimat</div><div class='gd-sec'>「<span class='gd-jp'>〜ものだから</span>」「<span class='gd-jp'>〜もので</span>」mirip dengan <b>「soalnya… sih, makanya jadi…」</b> dalam bahasa Indonesia. Bayangkan kamu terlambat lalu bilang ke atasan, \"Maaf, soalnya kereta tadi tertahan sih…\" Nada yang <b>sedikit membela diri dan berharap lawan bicara maklum</b> seperti itulah rasa pola ini.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Menjelaskan saat minta maaf</span>Saat kamu berbuat salah atau merepotkan orang, tambahkan alasan bahwa \"aku tidak sengaja\".</div><div class='gd-ex-line'>・<span class='gd-jp'>すみません、電車が止まっていたものですから。</span>（Maaf, soalnya kereta berhenti…）</div><div class='gd-ex-line'>・<span class='gd-jp'>寝坊したもので、遅れてしまいました。</span>（Soalnya aku bangun kesiangan, jadi terlambat）</div><div class='gd-sec'>Pada kalimat pertama「<span class='gd-jp'>電車が止まっていたものですから。</span>」kalimatnya berhenti di「<span class='gd-jp'>ものですから。</span>」. Hanya alasannya yang disebut, bagian belakangnya dilewati. Bentuk ini sering sekali terdengar saat minta maaf.</div><div class='gd-sec'><span class='gd-tag'>Menjelaskan keadaan diri sendiri</span>Dipakai untuk menjelaskan dengan halus kenapa kamu tidak bisa melakukan sesuatu atau kenapa kamu bertindak begitu.</div><div class='gd-ex-line'>・<span class='gd-jp'>子どもがまだ小さいもので、夜はあまり出かけられないんです。</span>（Soalnya anak saya masih kecil, jadi malam hari tidak bisa sering keluar）</div><div class='gd-sec'><span class='gd-tag'>Terlalu ～, jadi akhirnya…</span>Menjelaskan bahwa kamu tidak tahan untuk melakukan sesuatu.</div><div class='gd-ex-line'>・<span class='gd-jp'>あまりにおいしかったものだから、全部食べちゃった。</span>（Soalnya enak banget, jadi kuhabiskan semuanya）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Kata kerja</b>: bentuk biasa langsung disambung　<span class='gd-pair'><span class='gd-jp'>寝坊した</span> → <span class='gd-jp'>寝坊したものだから</span></span><br><b>Kata sifat-い</b>: langsung disambung　<span class='gd-pair'><span class='gd-jp'>忙しい</span> → <span class='gd-jp'>忙しいものだから</span></span><br><b>Kata sifat-な</b>: tambahkan「な」　<span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かなものだから</span></span><br><b>Kata benda</b>: juga tambahkan「な」　<span class='gd-pair'><span class='gd-jp'>初めて</span> → <span class='gd-jp'>初めてなもので</span></span><br>Dalam percakapan sering disingkat jadi <span class='gd-jp'>もんだから</span>、<span class='gd-jp'>もんで</span>; kepada orang yang lebih tua atau tamu, pakai <span class='gd-jp'>ものですから</span>. <span class='gd-jp'>もので</span> sendiri sudah terdengar lebih sopan, dan sering dipakai juga di situasi formal.</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Setelah kata sifat-な dan kata benda yang muncul adalah「な」, bukan「だ」: katakan <span class='gd-jp'>静かなものだから</span>, bukan 「静かだものだから」.<br>・Bagian belakang <b>tidak boleh berupa perintah, permintaan, ajakan, atau niat sendiri</b>. <span class='gd-jp'>雨が降っているものだから、傘を持っていってください。</span> itu salah; harus diubah jadi <span class='gd-jp'>雨が降っているから、傘を持っていってください。</span>（Sedang hujan, jadi bawa payung ya）<br>・Pola ini untuk <b>keadaan diri sendiri dan alasan pribadi</b>. Untuk berita atau laporan yang menjelaskan sebab secara objektif, jangan dipakai; gunakan <span class='gd-jp'>ので</span>、<span class='gd-jp'>ため</span>.<br>・Kalau jelas-jelas itu salahmu lalu kamu terus memakainya, kedengarannya seperti mencari-cari alasan. Saat memang salah, minta maaf dengan tulus dulu itu lebih penting.</div><div class='gd-h'>Bedakan dari pola yang mirip</div><div class='gd-sec'><b>から／ので</b>＝sekadar menjelaskan alasan: <span class='gd-jp'>電車が遅れたので、遅刻しました。</span>（Karena kereta terlambat, saya jadi telat）<br><b>ものだから</b>＝menjelaskan alasan, ditambah rasa \"aku tidak sengaja, tolong dimaklumi\": <span class='gd-jp'>電車が遅れたものですから、遅刻してしまいました。</span>（Soalnya kereta terlambat sih, makanya saya telat…）<br>Kalau bagian belakangnya menyuruh orang melakukan sesuatu, hanya から／ので yang bisa dipakai: <span class='gd-jp'>電車が遅れているから、タクシーで行こう。</span>（Kereta terlambat, ayo naik taksi）</div><div class='gd-sec'><b>ものだ</b>（di akhir kalimat）＝ungkapan perasaan \"memang begitulah adanya\", bukan menyatakan alasan: <span class='gd-jp'>時間が経つのは早いものだ。</span>（Waktu memang cepat berlalu ya）<br><b>ものだから</b> masih diikuti 「から」 atau 「で」, jadi pasti menyatakan <b>alasan</b>.</div><div class='gd-warn'>Tips menilai: kalau kamu ingin lawan bicara maklum dan sedang menjelaskan keadaanmu, pakai ものだから／もので; kalau bagian belakangnya menyuruh atau mengajak orang, ganti dengan から／ので; kalau kalimat berhenti di 「ものだ。」, itu ungkapan perasaan, bukan alasan.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Dalam percakapan sehari-hari ada bentuk yang lebih singkat dan lebih manja, yaitu memakai <span class='gd-jp'>もん</span> langsung di akhir kalimat: <span class='gd-jp'>だって、知らなかったんだもん。</span>（Habisnya aku memang nggak tahu sih）Hanya dipakai dengan orang yang sangat akrab.</div>","n3-63":"<div class='gd-h'>Pahami dulu lewat satu kalimat</div><div class='gd-sec'>「<span class='gd-jp'>さえ</span>」artinya <b>「bahkan ～ pun…」</b>. Pola ini sengaja memilih contoh yang <b>paling dasar dan paling wajar</b>, maksudnya \"yang ini saja sudah begitu, apalagi yang lain\". Misalnya \"sibuk sampai tidak punya waktu bahkan untuk makan\", dalam bahasa Jepang jadi: <span class='gd-jp'>忙しくて、ご飯を食べる時間さえない。</span></div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><span class='gd-tag'>Setelah kata benda</span>Tambahkan <span class='gd-jp'>さえ</span> langsung setelah kata benda. 「<span class='gd-jp'>が</span>」dan「<span class='gd-jp'>を</span>」yang semula ada harus dibuang, digantikan oleh <span class='gd-jp'>さえ</span>.<br><span class='gd-pair'><span class='gd-jp'>時間がない</span> → <span class='gd-jp'>時間さえない</span></span>（bahkan waktu pun tidak ada）<br><span class='gd-pair'><span class='gd-jp'>自分の名前を書けない</span> → <span class='gd-jp'>自分の名前さえ書けない</span></span>（bahkan nama sendiri pun tidak bisa menulisnya）</div><div class='gd-sec'><span class='gd-tag'>Partikel lain dipertahankan</span>「<span class='gd-jp'>に</span>」「<span class='gd-jp'>で</span>」「<span class='gd-jp'>と</span>」tidak perlu dibuang; <span class='gd-jp'>さえ</span> langsung diletakkan setelahnya.<br><span class='gd-pair'><span class='gd-jp'>家族に話していない</span> → <span class='gd-jp'>家族にさえ話していない</span></span>（bahkan keluarga pun belum diberi tahu）</div><div class='gd-sec'><span class='gd-tag'>Untuk \"bahkan orang tertentu\"</span>Saat ingin menekankan \"bahkan orang ini pun ～\", sering dipakai「<span class='gd-jp'>でさえ</span>」: <span class='gd-jp'>子供でさえ知っている。</span>（Bahkan anak kecil pun tahu）</div><div class='gd-sec'><span class='gd-tag'>Setelah kata kerja</span>Kalau ingin bilang \"bahkan ～ pun tidak ～\", buang ます dari kata kerja lalu tambahkan <span class='gd-jp'>さえしない</span>.<br><span class='gd-pair'><span class='gd-jp'>見ます</span> → buang ます → <span class='gd-jp'>見さえしない</span></span>（melihat pun tidak）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は私の顔を見さえしなかった。</span>（Dia bahkan tidak melirik wajahku sama sekali）</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Diikuti bentuk negatif</span>Ini pemakaian yang paling umum: hal paling dasar pun tidak ada atau tidak bisa dilakukan.</div><div class='gd-ex-line'>・<span class='gd-jp'>忙しくて、水を飲む時間さえなかった。</span>（Sibuk sampai bahkan waktu untuk minum air pun tidak ada）</div><div class='gd-ex-line'>・<span class='gd-jp'>足が痛くて、歩くことさえできない。</span>（Kakiku sakit sampai berjalan pun tidak bisa）</div><div class='gd-sec'><span class='gd-tag'>Diikuti bentuk positif</span>Bahkan orang yang paling tidak mungkin pun tahu atau bisa melakukannya, dengan makna tersirat \"apalagi orang lain, seharusnya lebih bisa\".</div><div class='gd-ex-line'>・<span class='gd-jp'>そんなことは、子供でさえ知っている。</span>（Hal seperti itu, anak kecil pun tahu）</div><div class='gd-ex-line'>・<span class='gd-jp'>この問題は、先生でさえ間違えた。</span>（Soal ini bahkan guru pun menjawabnya salah）</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・「<span class='gd-jp'>が</span>」「<span class='gd-jp'>を</span>」harus dibuang: 「時間がさえない」itu salah, yang benar <span class='gd-jp'>時間さえない</span>. Tapi「<span class='gd-jp'>に</span>」「<span class='gd-jp'>で</span>」「<span class='gd-jp'>と</span>」dipertahankan, jadi yang benar <span class='gd-jp'>家族にさえ</span>, bukan 家族さえ.<br>・Nuansa <span class='gd-jp'>さえ</span> lebih kuat dan lebih formal. Saat mengobrol dengan teman, banyak orang langsung memakai「<span class='gd-jp'>も</span>」: <span class='gd-jp'>時間もない</span>. Artinya hampir sama, hanya saja rasa \"bahkan yang ini pun\" tidak sekuat itu.<br>・Kalau <span class='gd-jp'>さえ</span> muncul sendirian, artinya \"bahkan ～ pun\", <b>bukan \"asalkan\"</b>. Banyak orang begitu melihat <span class='gd-jp'>さえ</span> langsung mengartikannya \"asalkan\", padahal untuk arti \"asalkan\", di belakangnya harus ada bentuk pengandaian (lihat bagian berikut).</div><div class='gd-h'>Bedakan dari pola yang mirip</div><div class='gd-sec'>Sama-sama bicara soal \"waktu\", tapi apa yang mengikutinya berbeda, jadi artinya jauh berbeda:<br><b>さえ</b>＝bahkan ～ pun: <span class='gd-jp'>最近は寝る時間さえない。</span>（Akhir-akhir ini bahkan waktu untuk tidur pun tidak ada）<br><b>さえ〜ば</b>＝asalkan ～ maka: <span class='gd-jp'>時間さえあれば、旅行に行きたい。</span>（Asalkan ada waktu, aku ingin pergi traveling）<br><b>さえ〜たら／なら</b> juga berarti \"asalkan ～\": <span class='gd-jp'>時間さえあったら、行けるのに。</span>（Asalkan ada waktu, aku pasti bisa pergi）</div><div class='gd-warn'>Tips menilai: kalau setelah <span class='gd-jp'>さえ</span> ada bentuk pengandaian \"kalau ～\", artinya \"asalkan ～\". Bentuk ini mencakup「〜ば」, juga「〜たら」「〜なら」, misalnya <span class='gd-jp'>あれば</span>、<span class='gd-jp'>あったら</span>、<span class='gd-jp'>あるなら</span>. Kalau tidak ada bentuk pengandaian seperti itu, artinya \"bahkan ～ pun\".</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Berikutnya pelajari「<span class='gd-jp'>〜さえ〜ば</span>」(asalkan ～ maka): <span class='gd-jp'>この薬さえ飲めば、すぐ治りますよ。</span>（Asalkan minum obat ini, kamu akan cepat sembuh lho）</div>","n3-64":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>「〜こそ」itu seperti menandai kata di depannya dengan <b>stabilo</b>. Artinya 「<b>justru ini</b>」「<b>yang ini yang ～</b>」「<b>kali ini pasti ～</b>」. <span class='gd-jp'>今年頑張る</span>hanya berarti \"tahun ini aku akan berusaha\", sedangkan <span class='gd-jp'>今年こそ頑張る</span>jadi \"tahun ini, apa pun yang terjadi, aku akan berjuang\". Nadanya jauh lebih kuat.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Kali ini pasti</span>Dulu pernah gagal, lalu kali ini kamu bertekad. Sering muncul bersama <span class='gd-jp'>今年</span>, <span class='gd-jp'>明日</span>, <span class='gd-jp'>次</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>今年こそ合格するぞ。</span>(Tahun ini aku harus lulus!)</div><div class='gd-ex-line'>・<span class='gd-jp'>次こそ負けないよ。</span>(Lain kali aku pasti tidak akan kalah)</div><div class='gd-sec'><span class='gd-tag'>Justru aku yang ～</span>Kalau lawan bicara berterima kasih, minta maaf, atau bilang \"mohon bantuannya\", kamu membalas \"justru saya yang ...\". <span class='gd-jp'>こちらこそ</span>bisa dipakai sendiri sebagai satu kalimat, dan sangat berguna.</div><div class='gd-ex-line'>・<span class='gd-jp'>A：いつもありがとう。　B：こちらこそ。</span>(A: Terima kasih untuk semuanya selama ini. B: Justru aku yang berterima kasih)</div><div class='gd-ex-line'>・<span class='gd-jp'>A：遅れてすみません。　B：いえ、こちらこそすみません。</span>(A: Maaf, aku terlambat. B: Tidak apa-apa, justru aku yang minta maaf)</div><div class='gd-sec'><span class='gd-tag'>Ya, inilah dia</span>Menegaskan \"bukan yang lain, justru ini\".</div><div class='gd-ex-line'>・<span class='gd-jp'>今こそ挑戦するときだ。</span>(Sekaranglah saatnya menantang diri)</div><div class='gd-ex-line'>・<span class='gd-jp'>これこそ私が探していた本だ。</span>(Inilah buku yang selama ini kucari)</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Pada dasarnya <b>kata benda + こそ</b>. Kalau di kalimat asalnya ada <span class='gd-jp'>は</span>atau <span class='gd-jp'>が</span>, langsung ganti dengan <span class='gd-jp'>こそ</span>:<br><span class='gd-pair'><span class='gd-jp'>今年は頑張る</span> → <span class='gd-jp'>今年こそ頑張る</span></span><br><span class='gd-pair'><span class='gd-jp'>これが大切だ</span> → <span class='gd-jp'>これこそ大切だ</span></span><br><span class='gd-jp'>を</span>biasanya juga dibuang, lalu langsung disambung dengan <span class='gd-jp'>こそ</span>.<br>Kalau partikelnya seperti <span class='gd-jp'>に</span>, <span class='gd-jp'>で</span>, partikel itu dipertahankan dan <span class='gd-jp'>こそ</span>ditaruh sesudahnya:</div><div class='gd-ex-line'>・<span class='gd-jp'>あなたにこそ見てほしい。</span>(Orang yang paling ingin kuajak melihat ini justru kamu)</div><div class='gd-h'>Yang sering salah</div><div class='gd-warn'>・<span class='gd-jp'>は</span>・<span class='gd-jp'>が</span>tidak boleh ditaruh di depan <span class='gd-jp'>こそ</span>. <span class='gd-jp'>今年はこそ</span>dan <span class='gd-jp'>私がこそ</span>itu salah, jadi buang dulu partikelnya. <span class='gd-jp'>を</span>juga sama, biasanya dibuang. Tapi kalau ditaruh sesudah <span class='gd-jp'>こそ</span>boleh, misalnya <span class='gd-jp'>今年こそは</span>dan <span class='gd-jp'>これこそが</span>adalah ungkapan yang umum.<br>・<span class='gd-jp'>こちらこそ</span>itu sangat sopan, tapi kalau diganti <span class='gd-jp'>あなたこそ</span>atau <span class='gd-jp'>お前こそ</span>, sering jadi nada membalas saat bertengkar: <span class='gd-jp'>お前こそ何してるんだよ。</span>(Kamu sendiri tuh lagi ngapain!). Jangan asal dipakai ke orang yang lebih tua.<br>・<span class='gd-jp'>こそ</span>nadanya berat, dipakai untuk menandai poin penting. Kalau semua kata diberi, sama saja seperti menstabilo satu halaman penuh, jadi malah tidak ada yang menonjol.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Sama-sama bicara soal ujian tahun ini:<br><span class='gd-jp'>今年は合格したい。</span>(Tahun ini aku ingin lulus): disampaikan datar, tanpa emosi khusus.<br><span class='gd-jp'>今年こそ合格したい。</span>(Tahun ini aku harus lulus): dulu belum lulus, kali ini bertekad.<br><span class='gd-jp'>こそ</span>sering dipelajari bersama <span class='gd-jp'>さえ</span>, tapi arahnya sama sekali berlawanan. <span class='gd-jp'>さえ</span>berarti \"bahkan ～\": memberi satu contoh ekstrem untuk menunjukkan bahwa yang lain tentu lebih lagi, dan bisa dipakai untuk kalimat positif maupun negatif, misalnya <span class='gd-jp'>簡単な問題さえできなかった。</span>(Bahkan soal semudah itu pun tidak bisa) dan <span class='gd-jp'>子供でさえ知っている。</span>(Anak kecil pun tahu). Sedangkan <span class='gd-jp'>こそ</span>menjadikan kata itu tokoh utamanya.</div><div class='gd-warn'>Trik membedakan: kalau mau bilang \"justru ini\", \"kali ini pasti\", \"aku yang sebenarnya\", pakai こそ. Kalau mau bilang \"bahkan ～\", pakai さえ. Kalau hanya bicara biasa, pakai は.</div><div class='gd-h'>Setelah ini, pelajari juga</div><div class='gd-sec'><span class='gd-jp'>からこそ</span>= \"justru karena ～ makanya\", menekankan alasan: <span class='gd-jp'>好きだからこそ、厳しく言うんだ。</span>(Justru karena aku peduli padamu, aku bicara setegas ini). <span class='gd-jp'>だからこそ</span>juga sering terdengar, artinya \"justru karena itu\".</div>","n3-65":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>「〜そうだ」setara dengan <b>\"kelihatannya ～ / tampaknya ～\"</b> dalam bahasa Indonesia. Kuenya belum dimakan, tapi hanya dengan melihatnya kamu sudah merasa \"kelihatannya enak\". Dalam bahasa Jepang kamu bilang <span class='gd-jp'>おいしそう</span>. Intinya, ini <b>tebakan berdasarkan penampilan yang kamu lihat langsung</b>, belum benar-benar dipastikan.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Menebak dari penampilan</span>Kata sifat + そう berarti \"kelihatannya ～\".</div><div class='gd-ex-line'>・<span class='gd-jp'>このケーキ、おいしそう。</span>(Kue ini kelihatannya enak banget)</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さん、今日は元気そうですね。</span>(Tanaka-san hari ini kelihatannya segar ya)</div><div class='gd-sec'><span class='gd-tag'>Hampir terjadi</span>Kata kerja + そう kebanyakan berarti \"sepertinya sebentar lagi ～\".</div><div class='gd-ex-line'>・<span class='gd-jp'>空が暗くなってきた。雨が降りそうだ。</span>(Langit mulai gelap. Sepertinya sebentar lagi hujan)</div><div class='gd-ex-line'>・<span class='gd-jp'>シャツのボタンが取れそう。</span>(Kancing kemejanya sepertinya mau lepas)</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Kata sifat い</b>: buang 「い」di akhir, lalu tambahkan そう.<br><span class='gd-pair'><span class='gd-jp'>おいしい</span> → buang い → <span class='gd-jp'>おいしそう</span></span><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高そう</span></span></div><div class='gd-sec'><b>Kata sifat な</b>: langsung tambahkan そう.<br><span class='gd-pair'><span class='gd-jp'>元気</span> → <span class='gd-jp'>元気そう</span></span><span class='gd-pair'><span class='gd-jp'>暇</span> → <span class='gd-jp'>暇そう</span></span></div><div class='gd-sec'><b>Kata kerja</b>: ubah dulu ke bentuk ます, buang ます, lalu tambahkan そう.<br><span class='gd-pair'><span class='gd-jp'>降ります</span> → buang ます → <span class='gd-jp'>降りそう</span></span><span class='gd-pair'><span class='gd-jp'>落ちます</span> → <span class='gd-jp'>落ちそう</span></span></div><div class='gd-sec'><b>Dua pengecualian, hafalkan saja</b>: <span class='gd-pair'><span class='gd-jp'>いい</span> → <span class='gd-jp'>よさそう</span></span><span class='gd-pair'><span class='gd-jp'>ない</span> → <span class='gd-jp'>なさそう</span></span></div><div class='gd-sec'>Untuk menyambung ke kata benda pakai <b>そうな</b>, untuk menyambung ke kata kerja pakai <b>そうに</b>:</div><div class='gd-ex-line'>・<span class='gd-jp'>高そうな時計ですね。</span>(Jam tangannya kelihatan mahal ya)</div><div class='gd-ex-line'>・<span class='gd-jp'>子どもたちが楽しそうに遊んでいる。</span>(Anak-anak bermain dengan kelihatan senang)</div><div class='gd-h'>Mau bilang \"kelihatannya tidak ～\"</div><div class='gd-sec'>Kata sifat: <span class='gd-jp'>おいしくなさそう</span>(kelihatannya tidak enak), <span class='gd-jp'>暇じゃなさそう</span>(kelihatannya tidak senggang)<br>Kata kerja: pakai 「そうにない」atau 「そうもない」.</div><div class='gd-ex-line'>・<span class='gd-jp'>この仕事は今日中に終わりそうにない。</span>(Pekerjaan ini kelihatannya tidak akan selesai hari ini)</div><div class='gd-h'>Yang sering salah</div><div class='gd-warn'>・<span class='gd-jp'>いい</span>tidak boleh jadi 「いそう」, harus <span class='gd-jp'>よさそう</span>: <span class='gd-jp'>天気がよさそうだ</span>(Cuacanya kelihatannya bagus).<br>・<b>Kata benda tidak bisa langsung diberi そう ini</b>: ×学生そうだ. Untuk \"kelihatan seperti mahasiswa\", pakai <span class='gd-jp'>学生みたいだ</span>.<br>・Hal yang jelas terlihat dan tidak perlu ditebak tidak memakai そう: untuk bunga merah cukup bilang <span class='gd-jp'>赤い</span>, bukan 「赤そう」.<br>・<span class='gd-jp'>かわいそう</span>artinya \"kasihan\", bukan \"kelihatannya imut\". Kalau merasa imut, langsung bilang <span class='gd-jp'>かわいい</span>.<br>・そう pada kata kerja sering berarti \"hampir ～\": <span class='gd-jp'>泣きそう</span>artinya \"hampir menangis\", bukan \"sepertinya sedang menangis\".</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>そうだ yang berarti \"katanya\"</b> (tata bahasa berikutnya) bentuknya hampir sama, tapi artinya sama sekali berbeda. Coba bandingkan untuk hal yang sama:<br><span class='gd-jp'>雨が降りそうだ。</span>(Melihat langit, sepertinya sebentar lagi hujan)<br><span class='gd-jp'>雨が降るそうだ。</span>(Katanya, menurut ramalan cuaca, akan hujan)<br><span class='gd-jp'>おいしそうだ。</span>(Kelihatannya enak)<br><span class='gd-jp'>おいしいそうだ。</span>(Katanya enak)<br><span class='gd-jp'>元気そうだ。</span>(Kelihatannya segar)<br><span class='gd-jp'>元気だそうだ。</span>(Katanya segar)<br>Kata benda hanya punya versi \"katanya\": <span class='gd-jp'>学生だそうだ。</span>(Katanya dia mahasiswa)</div><div class='gd-warn'>Trik membedakan:<br>・Kata kerja dan kata sifat い: kalau bagian di depan そう dipotong pendek (<span class='gd-jp'>降り</span>, <span class='gd-jp'>おいし</span>) = kelihatannya; kalau di depannya bentuk utuh (<span class='gd-jp'>降る</span>, <span class='gd-jp'>おいしい</span>) = katanya.<br>・Kata sifat な dan kata benda: lihat ada 「だ」atau tidak. <span class='gd-jp'>元気そうだ</span>= kelihatannya; <span class='gd-jp'>元気だそうだ</span>= katanya; <span class='gd-jp'>学生だそうだ</span>= katanya dia mahasiswa.</div><div class='gd-sec'>Selain itu, <b>ようだ・みたいだ</b>juga berarti \"sepertinya\", tapi lebih seperti kesimpulan setelah menggabungkan beberapa petunjuk. Sedangkan そう adalah <b>kesan pertama dalam sekali lihat</b>. Melihat kue, kamu bilang <span class='gd-jp'>おいしそう</span>; baru setelah melihat semua orang makan dengan senang, kamu bilang <span class='gd-jp'>おいしいみたい</span>.</div>","n3-66":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜そうだ」artinya <b>「katanya ～」「konon ～」「kabarnya ～」</b>. Kalau kamu mendengar sesuatu dari berita, teman, atau prakiraan cuaca lalu ingin menyampaikannya ke orang lain, tambahkan そうだ di akhir kalimat. Intinya: <b>hal itu bukan kamu lihat sendiri atau kamu tebak, tapi kata orang lain</b>.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Menyampaikan kabar yang didengar</span>Meneruskan apa yang dikatakan orang lain apa adanya.</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんは来月結婚するそうです。</span>（Katanya Pak Tanaka akan menikah bulan depan）</div><div class='gd-ex-line'>・<span class='gd-jp'>部長は今日、会社に来ないそうです。</span>（Katanya kepala bagian tidak datang ke kantor hari ini）</div><div class='gd-sec'><span class='gd-tag'>Menyebut sumber kabar</span>Di depan kalimat sering ditambahkan 「<span class='gd-jp'>〜によると</span>」atau 「<span class='gd-jp'>〜の話では</span>」untuk menjelaskan dari mana kabar itu berasal.</div><div class='gd-ex-line'>・<span class='gd-jp'>天気予報によると、明日は雨だそうだ。</span>（Menurut prakiraan cuaca, besok akan hujan）</div><div class='gd-ex-line'>・<span class='gd-jp'>先生の話では、来週テストがあるそうです。</span>（Kata guru, minggu depan ada ujian）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Ubah dulu isi yang mau disampaikan ke <b>bentuk biasa</b> (bentuk tanpa ます dan です), lalu sambungkan そうだ. Waktu (sekarang atau lampau) dan positif atau negatif diatur di bagian depan.<br><b>Kata kerja</b>：<span class='gd-pair'><span class='gd-jp'>降る</span> → <span class='gd-jp'>降るそうだ</span></span><span class='gd-pair'><span class='gd-jp'>降った</span> → <span class='gd-jp'>降ったそうだ</span></span><span class='gd-pair'><span class='gd-jp'>降らない</span> → <span class='gd-jp'>降らないそうだ</span></span><br><b>Kata sifat い</b>：<span class='gd-pair'><span class='gd-jp'>寒い</span> → <span class='gd-jp'>寒いそうだ</span></span><span class='gd-pair'><span class='gd-jp'>寒かった</span> → <span class='gd-jp'>寒かったそうだ</span></span><br><b>Kata sifat な</b>：harus ditambah だ　<span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かだそうだ</span></span><br><b>Kata benda</b>：juga harus ditambah だ　<span class='gd-pair'><span class='gd-jp'>雨</span> → <span class='gd-jp'>雨だそうだ</span></span><span class='gd-pair'><span class='gd-jp'>雨だった</span> → <span class='gd-jp'>雨だったそうだ</span></span><br>Kalau bicara dengan guru atau tamu, ganti bagian akhirnya jadi <span class='gd-jp'>そうです</span>.</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>Antar teman</span>Dalam percakapan, 「<span class='gd-jp'>〜って</span>」dan 「<span class='gd-jp'>〜んだって</span>」lebih sering dipakai. Artinya sama: 「katanya ～」.</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さん、来月結婚するんだって。</span>（Katanya Tanaka mau menikah bulan depan, lho）</div><div class='gd-ex-line'>・<span class='gd-jp'>明日、雨だって。</span>（Katanya besok hujan）</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Setelah kata benda dan kata sifat な, <b>だ tidak boleh dihilangkan</b>. Kalau ditulis <span class='gd-jp'>静かそうだ</span>, artinya jadi 「kelihatannya sepi」, jauh berbeda. Untuk 「katanya sepi」, katakan <span class='gd-jp'>静かだそうだ</span>.<br>・<b>そうだ sendiri tidak bisa diubah jadi negatif atau lampau</b>. Tidak bisa bilang ×<span class='gd-jp'>来るそうではない</span> atau ×<span class='gd-jp'>来るそうだった</span>. Yang diubah adalah kalimat di depannya: <span class='gd-jp'>来ないそうだ</span>（katanya tidak datang）, <span class='gd-jp'>来たそうだ</span>（katanya sudah datang）.<br>・Dalam bahasa Indonesia, 「katanya」 biasanya ada di depan kalimat, tetapi そうだ selalu diletakkan di <b>akhir kalimat</b>.<br>・Bentuk kabar dari <span class='gd-jp'>いい</span> adalah <span class='gd-jp'>いいそうだ</span>（katanya bagus）. <span class='gd-jp'>よさそうだ</span> artinya 「kelihatannya bagus」, itu そうだ yang lain.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>そうだ penampakan (n3-65)</b>: kamu sendiri yang melihat atau merasakan 「kelihatannya ～ / hampir ～」. Kata kerja memakai bentuk ます tanpa ます, kata sifat い dibuang い-nya, lalu disambung そうだ.<br><b>そうだ kabar (pelajaran ini)</b>: 「katanya ～」 dari orang lain, disambung dengan bentuk biasa yang utuh.<br>Sama-sama soal cuaca:</div><div class='gd-ex-line'>・<span class='gd-jp'>雨が降りそうだ。</span>（Kelihatannya mau hujan: kamu menyimpulkan sendiri dari melihat langit）</div><div class='gd-ex-line'>・<span class='gd-jp'>雨が降るそうだ。</span>（Katanya akan hujan: dengar dari prakiraan cuaca）</div><div class='gd-sec'>Sama-sama soal kue:</div><div class='gd-ex-line'>・<span class='gd-jp'>このケーキはおいしそうだ。</span>（Kue ini kelihatannya enak）</div><div class='gd-ex-line'>・<span class='gd-jp'>このケーキはおいしいそうだ。</span>（Katanya kue ini enak）</div><div class='gd-sec'><b>らしい (n3-52)</b> juga bisa diterjemahkan 「katanya」, tetapi そうだ dipakai kalau ada orang yang jelas mengatakannya dan kamu meneruskannya. らしい lebih berarti 「sepertinya begitu」: sumbernya kurang jelas, atau kamu menyimpulkan sendiri dari hal yang kamu dengar atau lihat.</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんは来月結婚するそうだ。</span>（Katanya Pak Tanaka akan menikah bulan depan: ada orang yang bilang begitu padaku）</div><div class='gd-ex-line'>・<span class='gd-jp'>田中さんは来月結婚するらしい。</span>（Sepertinya Pak Tanaka akan menikah bulan depan: dengar-dengar saja）</div><div class='gd-warn'>Trik membedakan: kalau di depannya bentuk utuh seperti 「<span class='gd-jp'>降る</span>、<span class='gd-jp'>おいしい</span>、<span class='gd-jp'>雨だ</span>」, artinya 「katanya」. Kalau di depannya bentuk yang dipotong seperti 「<span class='gd-jp'>降り</span>、<span class='gd-jp'>おいし</span>」, artinya 「kelihatannya」.</div>","n3-67":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>Bayangkan 「くる」dan 「いく」sebagai panah: <b>くる＝bergerak mendekat ke 「sini, sekarang」</b>, <b>いく＝bergerak menjauh dari 「sini, sekarang」</b>. <span class='gd-jp'>てくる</span> sering berarti 「datang ke sini」「mulai ～」「jadi semakin ～」, sedangkan <span class='gd-jp'>ていく</span> sering berarti 「pergi ～」「terus ～ ke depan」.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Ubah kata kerja ke bentuk て dulu, lalu sambungkan くる atau いく.<br><span class='gd-pair'><span class='gd-jp'>増える</span> → <span class='gd-jp'>増えて</span> → <span class='gd-jp'>増えてくる</span></span><br><span class='gd-pair'><span class='gd-jp'>なる</span> → <span class='gd-jp'>なって</span> → <span class='gd-jp'>なっていく</span></span><br>くる dan いく di belakang berubah seperti biasa: <span class='gd-jp'>てきます</span>、<span class='gd-jp'>てきた</span>、<span class='gd-jp'>ていきます</span>、<span class='gd-jp'>ていった</span>.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Arah ruang</span>Kalau benda atau orang datang ke arahmu, pakai てくる. Kalau pergi menjauh darimu, pakai ていく. <b>Yang jadi patokan adalah di mana kamu berada saat bicara.</b></div><div class='gd-ex-line'>・<span class='gd-jp'>雨が降りそうだから、傘を持っていこう。</span>（Sepertinya mau hujan, ayo bawa payung）</div><div class='gd-ex-line'>・<span class='gd-jp'>友達がケーキを持ってきてくれた。</span>（Temanku membawakan kue untukku）</div><div class='gd-sec'><span class='gd-tag'>Pergi sebentar lalu kembali</span>てくる juga berarti 「pergi melakukan sesuatu lalu kembali」. <span class='gd-jp'>行ってきます</span> yang diucapkan saat keluar rumah artinya 「aku pergi dan segera kembali」.</div><div class='gd-ex-line'>・<span class='gd-jp'>ちょっとコンビニで飲み物を買ってくる。</span>（Aku beli minuman dulu di minimarket, nanti langsung balik）</div><div class='gd-sec'><span class='gd-tag'>Perubahan: sampai sekarang</span><span class='gd-jp'>てきた</span>＝berubah dari dulu sampai sekarang, dan perubahannya terasa saat ini.</div><div class='gd-ex-line'>・<span class='gd-jp'>最近、日本語が少し分かってきた。</span>（Akhir-akhir ini aku mulai sedikit mengerti bahasa Jepang）</div><div class='gd-ex-line'>・<span class='gd-jp'>ここ数年、オンライン会議が増えてきた。</span>（Beberapa tahun terakhir, rapat online makin banyak）</div><div class='gd-sec'><span class='gd-tag'>Perubahan: dari sekarang ke depan</span><span class='gd-jp'>ていく</span>＝mulai dari sekarang, perubahan atau tindakan itu akan terus berlanjut.</div><div class='gd-ex-line'>・<span class='gd-jp'>これからどんどん寒くなっていく。</span>（Mulai sekarang akan semakin dingin）</div><div class='gd-ex-line'>・<span class='gd-jp'>これからも日本語の勉強を続けていきたい。</span>（Ke depannya pun aku ingin terus belajar bahasa Jepang）</div><div class='gd-sec'><span class='gd-tag'>Mulai muncul</span><span class='gd-jp'>てきた</span> juga sering dipakai untuk menyatakan suatu keadaan 「mulai muncul」, mirip 「jadi ～ / mulai ～」 dalam bahasa Indonesia.</div><div class='gd-ex-line'>・<span class='gd-jp'>あ、雨が降ってきた。</span>（Ah, hujan mulai turun）</div><div class='gd-ex-line'>・<span class='gd-jp'>お腹がすいてきた。</span>（Perutku mulai lapar）</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Arah dilihat dari <b>posisimu saat bicara</b>, bukan posisi lawan bicara. Kalau kamu berjanji pada guru secara langsung di sekolah, kamu sendiri ada di tempat barang itu akan diantar, jadi <span class='gd-jp'>はい、明日持ってきます。</span> terdengar sangat wajar.<br>・Dalam bahasa Indonesia, 「aku beli dulu ya」 tidak membedakan arah. Dalam bahasa Jepang, kalau setelah membeli kamu akan kembali, orang sering bilang <span class='gd-jp'>買ってくる</span>. <span class='gd-jp'>買っていく</span> artinya 「membeli lalu membawanya ke tempat lain」, misalnya <span class='gd-jp'>お土産を買っていく</span>（membeli oleh-oleh untuk dibawa ke sana）.<br>・Saat bicara soal waktu, jangan campur 「sampai sekarang」 dan 「mulai sekarang」: kalau ada <span class='gd-jp'>これから</span> di depannya, harus pakai ていく. Tidak boleh bilang 「これから寒くなってきた」.<br>・くる dan いく di sini biasanya ditulis dengan hiragana. Bentuk lampaunya <span class='gd-jp'>てきた</span>, bukan 「てくた」. Bentuk lampau ていく adalah <span class='gd-jp'>ていった</span>.<br>・Dalam percakapan, ていく sering dilafalkan 「てく」: <span class='gd-jp'>寒くなってく</span>. Kalau mendengarnya, jangan kira itu tata bahasa lain.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Sama-sama soal 「cuaca jadi dingin」:<br><span class='gd-jp'>寒くなってきた。</span>（Sudah makin dingin, terasa sekarang）<br><span class='gd-jp'>寒くなっていく。</span>（Ke depannya akan makin dingin）<br><span class='gd-jp'>寒くなる一方だ。</span>（Terus makin dingin tanpa bisa berhenti, sering dengan nuansa pasrah）<br>Dua yang pertama berbeda pada arah waktunya, sedangkan <span class='gd-jp'>一方だ</span> menekankan 「hanya terus berkembang ke satu arah」.</div><div class='gd-warn'>Trik membedakan: kalau melihat dari masa lalu sampai sekarang, pakai てきた. Kalau melihat dari sekarang ke depan, pakai ていく. Kalau mau bilang 「terus memburuk tanpa bisa berhenti」, pakai 一方だ.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Kalau setelah てきた ditambah ている, jadinya <span class='gd-jp'>てきている</span>, yang berarti 「perubahan ini masih berlangsung sekarang」: <span class='gd-jp'>外国人観光客が増えてきている。</span>（Wisatawan asing makin banyak, dan jumlahnya masih terus bertambah）</div>","n3-71":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜（ら）れる」setara dengan <b>awalan “di-” atau “ter-/kena ～”</b> dalam bahasa Indonesia. Fokusnya ada pada 「orang yang menerima tindakan」: bukan “guru memarahiku”, melainkan “aku dimarahi guru”. Bahasa Jepang juga punya satu pemakaian khas: kalau ada kejadian yang merepotkanmu, bentuk ini dipakai untuk mengeluh, “aduh, sial banget aku”.</div><div class='gd-h'>Cara membentuknya: lihat dulu golongan kata kerjanya</div><div class='gd-sec'><b>Golongan 1 (kata kerja godan)</b>: ubah bunyi terakhir menjadi bunyi baris 「あ」 pada baris yang sama, lalu tambahkan 「れる」.<br><span class='gd-pair'><span class='gd-jp'>呼ぶ</span> → ぶ diganti ば → <span class='gd-jp'>呼ばれる</span></span><br><span class='gd-pair'><span class='gd-jp'>踏む</span> → <span class='gd-jp'>踏まれる</span></span><span class='gd-pair'><span class='gd-jp'>叱る</span> → <span class='gd-jp'>叱られる</span></span><br><b>Hati-hati dengan yang berakhiran う</b>: う bukan berubah jadi あ, tapi jadi <b>わ</b>.<br><span class='gd-pair'><span class='gd-jp'>言う</span> → <span class='gd-jp'>言われる</span></span><span class='gd-pair'><span class='gd-jp'>買う</span> → <span class='gd-jp'>買われる</span></span><br>Cara termudah: ubah dulu ke bentuk ない, buang ない, lalu tambahkan れる. <span class='gd-pair'><span class='gd-jp'>言わない</span> → <span class='gd-jp'>言われる</span></span></div><div class='gd-sec'><b>Golongan 2 (kata kerja ichidan)</b>: buang 「る」 di akhir, lalu tambahkan 「られる」.<br><span class='gd-pair'><span class='gd-jp'>褒める</span> → <span class='gd-jp'>褒められる</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見られる</span></span></div><div class='gd-sec'><b>Golongan 3 (cuma dua, hafalkan saja)</b>: <span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>される</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来られる</span>（こられる）</span></div><div class='gd-sec'>Setelah jadi, bentuk ini sendiri adalah kata kerja golongan 2, jadi lanjutkan perubahannya dengan aturan golongan 2:<br><span class='gd-pair'><span class='gd-jp'>褒められる</span> → <span class='gd-jp'>褒められた</span></span><span class='gd-pair'><span class='gd-jp'>褒められます</span></span><span class='gd-pair'><span class='gd-jp'>褒められない</span></span></div><div class='gd-h'>Cara menyusun kalimat</div><div class='gd-sec'>Pola dasar: <b>私は＋pelaku tindakan に＋bentuk pasif</b>. Pelaku tindakan diberi partikel 「に」.</div><div class='gd-ex-line'>・<span class='gd-jp'>私は先生に叱られた。</span>（Aku dimarahi guru）</div><div class='gd-ex-line'>・<span class='gd-jp'>上司にアイデアを褒められた。</span>（Idenya dipuji atasan）</div><div class='gd-sec'>Tidak harus hal buruk. Dipuji atau terpilih pun bisa memakai bentuk ini.</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>Tubuh atau barang yang kena</span>Kaki diinjak, dompet dicuri: bahasa Jepang biasanya memakai pola 「aku + benda を + bentuk pasif」, jadi tokoh utamanya tetap 「aku」.</div><div class='gd-ex-line'>・<span class='gd-jp'>電車で足を踏まれた。</span>（Kakiku diinjak di kereta）</div><div class='gd-ex-line'>・<span class='gd-jp'>駅で財布を盗まれた。</span>（Dompetku dicuri di stasiun）</div><div class='gd-sec'><span class='gd-tag'>Sial, merepotkan</span>Perbuatan orang lain (bahkan cuaca) membuatmu kerepotan. Dalam bahasa Indonesia, kalimat seperti ini sering tak bisa dipasifkan begitu saja (misalnya “ditangisi bayi” terdengar aneh), jadi ini ciri khas bahasa Jepang.</div><div class='gd-ex-line'>・<span class='gd-jp'>帰りに雨に降られた。</span>（Di jalan pulang aku kehujanan）</div><div class='gd-ex-line'>・<span class='gd-jp'>夜中に赤ちゃんに泣かれて、全然寝られなかった。</span>（Tengah malam bayinya terus menangis, jadi aku sama sekali tidak bisa tidur）</div><div class='gd-sec'><span class='gd-tag'>Deskripsi objektif</span>Sering dipakai di berita dan penjelasan, tanpa emosi dan tanpa menyebut siapa pelakunya.</div><div class='gd-ex-line'>・<span class='gd-jp'>このお寺は500年前に建てられた。</span>（Kuil ini dibangun 500 tahun lalu）</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Akhiran う berubah jadi <b>わ</b>: yang benar <span class='gd-jp'>買われる</span>, bukan 買あれる.<br>・Pelaku tindakan memakai 「に」: <span class='gd-jp'>先生に叱られた</span> artinya “aku dimarahi guru”; kalau ditulis <span class='gd-jp'>先生が叱られた</span>, artinya jadi “guru dimarahi”.<br>・Dalam bahasa Indonesia kita bilang “kakiku diinjak”, tapi dalam bahasa Jepang tidak bilang 私の足が踏まれた, melainkan <span class='gd-jp'>足を踏まれた</span>.<br>・Bentuk pasif golongan 2 sama persis dengan bentuk potensial 「bisa ～」: <span class='gd-jp'>食べられる</span> bisa berarti “dimakan” atau “bisa makan”, tergantung konteks.<br>・<span class='gd-jp'>来られる</span> dibaca <b>こられる</b>, bukan きられる.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'><b>られる (pasif)</b> = tindakan orang lain menimpa aku, akulah yang “kena”:<br><span class='gd-jp'>弟にケーキを食べられた。</span>（Kuenya dimakan adikku）<br><b>させる (kausatif)</b> = aku menyuruh atau membiarkan orang lain melakukan:<br><span class='gd-jp'>弟にケーキを食べさせた。</span>（Aku menyuruh adikku makan kue）<br><b>てもらう</b> = orang lain melakukan sesuatu untukku, dan aku berterima kasih:<br><span class='gd-jp'>先生に作文を褒めてもらった。</span>（Guru memuji karanganku, aku senang sekali）<br>Untuk hal yang sama, <span class='gd-jp'>褒められた</span> hanya menyatakan fakta “dipuji”, tanpa menonjolkan rasa terima kasih.</div><div class='gd-warn'>Trik cepat: “di-/kena ～” pakai れる・られる, “menyuruh orang ～” pakai せる・させる, “orang lain membantuku ～ (aku berterima kasih)” pakai てもらう.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Kausatif dan pasif digabung menjadi “dipaksa melakukan ～”: <span class='gd-jp'>母に野菜を食べさせられた。</span>（Aku dipaksa ibu makan sayur）</div>","n3-68":"<div class='gd-h'>Pahami dulu dalam satu kalimat</div><div class='gd-sec'>Ketiganya adalah 「bentuk て + sebuah ekor kecil」. Bedanya ada pada apa yang ingin kamu sampaikan:<br><b>ている</b>＝keadaan saat ini (sedang melakukan, atau terus berada dalam suatu keadaan)<br><b>てある</b>＝sesuatu sudah disiapkan seseorang dan dibiarkan di situ (terlihat ada yang sengaja melakukannya)<br><b>ておく</b>＝dikerjakan lebih dulu demi keperluan nanti (seperti 「siapkan dulu」, 「~ dulu」 dalam bahasa Indonesia)<br>Bayangkan kamu masuk ruang rapat dan melihat jendela terbuka: kalau hanya menggambarkan 「jendelanya terbuka」, pakai ている; kalau bilang 「jendelanya sudah dibukakan seseorang」, pakai てある; kalau sebelum rapat kamu sendiri bilang 「aku buka jendela dulu ya」, pakai ておく.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Semuanya ditambahkan setelah bentuk て kata kerja:<br><span class='gd-pair'><span class='gd-jp'>開ける</span> → <span class='gd-jp'>開けて</span></span> → <span class='gd-jp'>開けている</span>／<span class='gd-jp'>開けてある</span>／<span class='gd-jp'>開けておく</span></div><div class='gd-h'>ている：keadaan saat ini</div><div class='gd-sec'><span class='gd-tag'>Sedang melakukan</span>Aksinya sedang berlangsung.</div><div class='gd-ex-line'>・<span class='gd-jp'>今、ご飯を食べている。</span>（Sekarang aku sedang makan）</div><div class='gd-sec'><span class='gd-tag'>Keadaan bertahan</span>Sesuatu sudah terjadi, dan hasilnya terus bertahan.</div><div class='gd-ex-line'>・<span class='gd-jp'>エアコンがついている。</span>（AC-nya menyala）</div><div class='gd-ex-line'>・<span class='gd-jp'>姉は結婚している。</span>（Kakak perempuanku sudah menikah）</div><div class='gd-h'>てある：sudah disiapkan seseorang, dibiarkan begitu</div><div class='gd-sec'><span class='gd-tag'>Hasil + ada yang melakukan</span>Fokusnya: 「sekarang bendanya dalam kondisi begini, dan ada yang sengaja membuatnya begitu」. Siapa pelakunya biasanya tidak disebut. Benda di depannya kebanyakan memakai <b>が</b>.</div><div class='gd-ex-line'>・<span class='gd-jp'>ドアに名前が書いてある。</span>（Nama tertulis di pintu）</div><div class='gd-ex-line'>・<span class='gd-jp'>ビールが冷やしてある。</span>（Birnya sudah didinginkan）</div><div class='gd-h'>ておく：dikerjakan lebih dulu</div><div class='gd-sec'><span class='gd-tag'>Persiapan</span>Demi keperluan nanti, selesaikan dulu urusannya.</div><div class='gd-ex-line'>・<span class='gd-jp'>旅行の前に、ホテルを予約しておく。</span>（Sebelum bepergian, pesan hotel dulu）</div><div class='gd-sec'><span class='gd-tag'>Biarkan apa adanya</span>Sengaja membiarkannya tetap begitu, jangan diutak-atik dulu.</div><div class='gd-ex-line'>・<span class='gd-jp'>窓は開けておいてください。</span>（Tolong biarkan jendelanya terbuka, tidak usah ditutup）</div><div class='gd-sec'>Dalam percakapan sering dipersingkat jadi <b>とく</b>：<span class='gd-pair'><span class='gd-jp'>買っておく</span> → <span class='gd-jp'>買っとく</span></span><span class='gd-pair'><span class='gd-jp'>読んでおく</span> → <span class='gd-jp'>読んどく</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>ジュース、買っとくね。</span>（Jusnya aku belikan dulu ya）</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Bedakan dulu dua jenis kata kerja: kata kerja yang artinya <b>bendanya berubah sendiri</b> (<span class='gd-jp'>開く</span>、<span class='gd-jp'>つく</span>、<span class='gd-jp'>閉まる</span>, di depannya pakai が), dan kata kerja yang artinya <b>ada orang yang mengubahnya</b> (<span class='gd-jp'>開ける</span>、<span class='gd-jp'>つける</span>、<span class='gd-jp'>閉める</span>, di depannya pakai を).<br>・てある harus disambung dengan jenis 「ada orang yang mengubahnya」: <span class='gd-jp'>窓が開けてある</span> yang benar, bukan <span class='gd-jp'>窓が開いてある</span>.<br>・<span class='gd-jp'>窓が開けている</span> itu salah, karena artinya jadi 「jendela sedang membuka sesuatu」. Pilih <span class='gd-jp'>窓が開いている</span> atau <span class='gd-jp'>窓が開けてある</span>.<br>・<span class='gd-jp'>結婚している</span> artinya 「sudah menikah」, bukan 「sedang menikah」; <span class='gd-jp'>知っている</span> artinya 「tahu」. Jangan setiap melihat ている langsung diartikan 「sedang」.<br>・「てる」 dalam percakapan adalah singkatan dari ている, sedangkan 「とく」 baru singkatan dari ておく. Jangan dicampur.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Satu jendela yang sama, empat cara mengatakannya:<br>・<span class='gd-jp'>窓が開いている。</span>（Jendelanya terbuka: hanya menyebut apa yang terlihat）<br>・<span class='gd-jp'>窓が開けてある。</span>（Jendelanya sudah dibukakan seseorang: terasa ada yang sengaja membukanya untuk suatu tujuan）<br>・<span class='gd-jp'>窓を開けておく。</span>（Aku buka jendela dulu: untuk keperluan nanti）<br>・<span class='gd-jp'>田中さんが窓を開けている。</span>（Tanaka sedang membuka jendela: fokus pada aksi orangnya）<br>Selain itu, setelah <b>ておいた</b> selesai dilakukan, keadaan bendanya menjadi <b>てある</b>：<span class='gd-jp'>昨日資料を準備しておいたから、もう準備してある。</span>（Kemarin sudah kusiapkan duluan, jadi sekarang sudah siap）</div><div class='gd-warn'>Trik menentukan: kalau hanya menyebut keadaan bendanya, pakai 「が＋ている」; kalau ingin menekankan 「ada yang sudah menyiapkannya dan bendanya dibiarkan begitu」, pakai 「が＋てある」; kalau maksudnya 「dikerjakan dulu demi nanti」, pakai 「を＋ておく」.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>「〜っぱなし」 juga membuat sesuatu tetap apa adanya, tapi kebanyakan berarti <b>lupa dirapikan, dibiarkan begitu saja</b>, dengan kesan negatif: <span class='gd-jp'>窓を開けっぱなしにした。</span>（Jendelanya dibuka dan tidak ditutup lagi）. Ini kebalikan dari <span class='gd-jp'>開けておく</span> yang sengaja dibuka.</div>","n3-69":"<div class='gd-h'>Pahami dulu dalam satu kalimat</div><div class='gd-sec'>Dalam bahasa Indonesia, cukup bilang 「bantu」 atau 「tolong」: dia membantuku, aku membantunya, aku minta dia membantuku. Dalam bahasa Jepang, kamu menambahkan <b>くれる、あげる、もらう</b> setelah kata kerja untuk menunjukkan ke arah mana 「budi baik」 itu mengalir.<br><b>くれる</b>：orang lain → aku (orang lain melakukan sesuatu untukku)<br><b>あげる</b>：aku → orang lain (aku melakukan sesuatu untuk orang lain)<br><b>もらう</b>：aku menerima bantuan dari orang lain (aku minta orang lain melakukannya untukku)</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Ubah kata kerja ke bentuk て, lalu sambungkan langsung.<br><span class='gd-pair'><span class='gd-jp'>手伝う</span> → <span class='gd-jp'>手伝って</span> → <span class='gd-jp'>手伝ってくれる</span></span><br><span class='gd-pair'><span class='gd-jp'>教える</span> → <span class='gd-jp'>教えて</span> → <span class='gd-jp'>教えてもらう</span></span></div><div class='gd-h'>Lihat satu per satu: kuncinya ada di partikel</div><div class='gd-sec'><span class='gd-tag'>てくれる</span>Tokoh utamanya adalah <b>pihak lain</b>, dan pelakunya diikuti <b>が</b>. 「Aku」 biasanya tidak disebut. Keluargaku juga termasuk 「pihak kita」, jadi boleh memakai pola ini.</div><div class='gd-ex-line'>・<span class='gd-jp'>友達が引っ越しを手伝ってくれた。</span>（Temanku membantu aku pindahan）</div><div class='gd-ex-line'>・<span class='gd-jp'>母がお弁当を作ってくれた。</span>（Ibu membuatkan bekal untukku）</div><div class='gd-sec'><span class='gd-tag'>てもらう</span>Tokoh utamanya adalah <b>aku</b>, dan pelakunya diikuti <b>に</b>.</div><div class='gd-ex-line'>・<span class='gd-jp'>駅員さんに道を教えてもらった。</span>（Aku minta petugas stasiun menunjukkan jalan）</div><div class='gd-ex-line'>・<span class='gd-jp'>先生にほめてもらった。</span>（Aku dipuji oleh guru）</div><div class='gd-sec'><span class='gd-tag'>てあげる</span>Tokoh utamanya adalah aku. Partikel setelah lawan bicara <b>ditentukan oleh kata kerja aslinya</b>.</div><div class='gd-ex-line'>・<span class='gd-jp'>妹に本を読んであげた。</span>（Aku membacakan buku untuk adikku）</div><div class='gd-ex-line'>・<span class='gd-jp'>友達を駅まで送ってあげた。</span>（Aku mengantar temanku sampai stasiun）</div><div class='gd-h'>Bentuk yang paling sering terdengar: meminta tolong</div><div class='gd-sec'>Ubah jadi kalimat tanya, artinya 「Bisa tolong ~?」. Makin ke bawah makin sopan.</div><div class='gd-ex-line'>・<span class='gd-jp'>ちょっと手伝ってくれる？</span>（Bisa bantu sebentar? Untuk teman）</div><div class='gd-ex-line'>・<span class='gd-jp'>この書類、確認してもらえますか。</span>（Bisa tolong cek dokumen ini?）</div><div class='gd-ex-line'>・<span class='gd-jp'>もう少しゆっくり話してもらえませんか。</span>（Bisakah Anda bicara sedikit lebih pelan?）</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・<b>Arahnya terbalik</b>: くれる hanya bisa mengarah ke 「pihak kita」. 「Aku mengajari temanku」 tidak bisa dibilang <span class='gd-jp'>友達に教えてくれた</span>, harus <span class='gd-jp'>友達に教えてあげた</span>.<br>・<b>Partikelnya tertukar</b>: くれる berpasangan dengan が, もらう dengan に. <span class='gd-jp'>友達に手伝ってくれた</span> itu salah.<br>・<b>Kalau diterjemahkan langsung, jadi terdengar dingin</b>: 「Dia membelikanku」 kalau jadi <span class='gd-jp'>彼が買った</span> secara tata bahasa tidak salah, tapi terdengar seperti tidak berterima kasih. Kalau ada yang melakukan sesuatu untukmu, orang Jepang hampir selalu menambahkan <span class='gd-jp'>くれた</span>.<br>・<b>てあげる kurang sopan untuk orang yang lebih tua</b>: ada kesan 「aku berbaik hati padamu」. Ke guru, <span class='gd-jp'>荷物を持ってあげます</span> tidak boleh, harus <span class='gd-jp'>お持ちします</span>（akan saya bawakan）. Bahkan ke teman, mengatakan 「～てあげる」 langsung bisa terkesan sok tinggi, jadi sering diganti <span class='gd-jp'>手伝おうか？</span>（Mau kubantu?）.<br>・<b>もらう belum tentu berarti 「meminta」</b>: seperti <span class='gd-jp'>ほめてもらった</span>, kamu tidak meminta guru memuji, kamu hanya mendapat keuntungan.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>てくれる dan てもらう sering membicarakan <b>hal yang sama</b>, bedanya ada pada siapa yang jadi tokoh utama.<br><span class='gd-jp'>田中さんが傘を貸してくれた。</span>（Tanaka meminjamkan payung kepadaku: tokoh utamanya Tanaka, fokus pada kebaikan hatinya）<br><span class='gd-jp'>田中さんに傘を貸してもらった。</span>（Aku dipinjami payung oleh Tanaka: tokoh utamanya aku, sering terasa seperti 「aku yang minta」）</div><div class='gd-warn'>Trik menentukan: kalau pelakunya diikuti <b>が</b>, pakai くれる; kalau diikuti <b>に</b>, pakai もらう. Kalau ingin menekankan kebaikan hati orang lain, pakai くれる; kalau ingin bilang 「aku meminta dan mendapat bantuan」, pakai もらう.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Untuk guru dan atasan, ganti ke bentuk hormat: くれる → <span class='gd-jp'>くださる</span>, もらう → <span class='gd-jp'>いただく</span>.<br>・<span class='gd-jp'>先生が教えてくださいました。</span>（Guru mengajariku）<br>・<span class='gd-jp'>先生に教えていただきました。</span>（Aku diajari oleh guru）</div>","n3-72":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>「〜させられる」 artinya kurang lebih <b>“dipaksa ~” atau “disuruh ~”</b>. Kamu <b>sendiri yang melakukannya</b>, tapi bukan karena kamu mau, melainkan karena orang lain menyuruhmu. Biasanya diucapkan dengan nada sedikit kesal atau mengeluh.</div><div class='gd-h'>Dari mana bentuk ini berasal</div><div class='gd-sec'>Bentuk ini gabungan dua tata bahasa: 「させる」 = menyuruh orang lain melakukan sesuatu, 「られる」 = pasif (di-).<br>Ibu menyuruhku bersih-bersih. Ini dilihat dari sudut pandang ibu:</div><div class='gd-ex-line'>・<span class='gd-jp'>母は私に部屋を掃除させた。</span>（Ibu menyuruhku membersihkan kamar）</div><div class='gd-sec'>Sekarang kita lihat dari sudut pandang <b>aku</b>, jadi “aku disuruh ibu membersihkan kamar”:</div><div class='gd-ex-line'>・<span class='gd-jp'>私は母に部屋を掃除させられた。</span>（Aku dipaksa ibu membersihkan kamar）</div><div class='gd-sec'>Tokoh utamanya sekarang “aku”, dan orang yang memaksamu diberi partikel <b>に</b>.</div><div class='gd-h'>Cara membentuknya: lihat dulu jenis verbanya</div><div class='gd-sec'><b>Kelompok 1 (verba godan)</b>: ganti bunyi terakhir dengan bunyi baris 「あ」 dari baris yang sama, lalu tambahkan 「される」.<br><span class='gd-pair'><span class='gd-jp'>書く</span> → く diganti か → <span class='gd-jp'>書かされる</span></span><br><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲まされる</span></span><span class='gd-pair'><span class='gd-jp'>待つ</span> → <span class='gd-jp'>待たされる</span></span><span class='gd-pair'><span class='gd-jp'>買う</span> → <span class='gd-jp'>買わされる</span></span><br>Hati-hati: verba berakhiran 「う」 berubah jadi 「わ」, bukan 「あ」.<br>Ini versi singkat yang sering dipakai dalam percakapan. Versi lengkapnya <span class='gd-jp'>書かせられる</span>. Keduanya benar, tapi dalam obrolan sehari-hari versi singkat lebih sering terdengar.</div><div class='gd-sec'><b>Pengecualian di Kelompok 1: verba berakhiran 「す」</b> tidak bisa memakai versi singkat, harus ditambah 「させられる」.<br><span class='gd-pair'><span class='gd-jp'>話す</span> → <span class='gd-jp'>話させられる</span></span><span class='gd-pair'><span class='gd-jp'>出す</span> → <span class='gd-jp'>出させられる</span></span></div><div class='gd-sec'><b>Kelompok 2 (verba ichidan)</b>: buang 「る」 di akhir, lalu tambahkan 「させられる」.<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べさせられる</span></span><span class='gd-pair'><span class='gd-jp'>やめる</span> → <span class='gd-jp'>やめさせられる</span></span></div><div class='gd-sec'><b>Kelompok 3 (cuma dua, hafalkan saja)</b>：<span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>させられる</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来させられる</span>（こさせられる）</span><br>Pola “nomina＋する” seperti <span class='gd-jp'>残業する</span> dan <span class='gd-jp'>スピーチする</span> juga sama：<span class='gd-pair'><span class='gd-jp'>残業する</span> → <span class='gd-jp'>残業させられる</span></span></div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>Dipaksa melakukan</span>Pemakaian paling dasar, untuk mengeluh soal hal yang tidak ingin dilakukan.</div><div class='gd-ex-line'>・<span class='gd-jp'>子どものころ、毎日ピアノを練習させられた。</span>（Waktu kecil, aku dipaksa latihan piano setiap hari）</div><div class='gd-ex-line'>・<span class='gd-jp'>飲み会でお酒をたくさん飲まされた。</span>（Di acara minum-minum, aku dipaksa minum banyak alkohol）</div><div class='gd-sec'><span class='gd-tag'>Dibiarkan menunggu</span><span class='gd-jp'>待たされる</span> sangat sering dipakai, artinya “bikin aku menunggu lama”.</div><div class='gd-ex-line'>・<span class='gd-jp'>病院で一時間も待たされた。</span>（Di rumah sakit, aku dibiarkan menunggu sampai satu jam）</div><div class='gd-sec'><span class='gd-tag'>Jadi terbawa perasaan</span>Dipakai dengan kata seperti “berpikir” atau “terharu”, artinya “membuat orang tak bisa tidak ~”. Tidak ada nuansa mengeluh.</div><div class='gd-ex-line'>・<span class='gd-jp'>この映画にはいろいろ考えさせられた。</span>（Film ini membuatku banyak berpikir）</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・<span class='gd-jp'>話す</span> menjadi <span class='gd-jp'>話させられる</span>, tidak boleh “話さされる”. Semua verba berakhiran 「す」 sama saja.<br>・Orang yang memaksamu diberi <b>に</b>：<span class='gd-jp'>先生に作文を書かされた。</span>（Aku disuruh guru menulis karangan）<br>・Bentuk ini membawa perasaan “sebenarnya aku tidak mau”. Kalau orang lain dengan baik hati mengizinkanmu melakukan sesuatu dan kamu berterima kasih, memakai bentuk ini malah terdengar mengeluh dan tidak sopan.<br>・Jangan tertukar antara <span class='gd-jp'>書かされる</span> dan pasif biasa <span class='gd-jp'>書かれる</span>: dengan tambahan satu 「さ」, artinya berubah dari “ditulis” menjadi “dipaksa menulis”.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'><b>られる</b> = orang lain <b>melakukan sesuatu padaku</b>, yang bertindak adalah pihak lain：<span class='gd-jp'>母に叱られた。</span>（Aku dimarahi ibu, yang memarahi adalah ibu）<br><b>させられる</b> = orang lain <b>menyuruhku melakukan</b>, yang bertindak adalah aku, dan aku sebenarnya tidak mau：<span class='gd-jp'>母に掃除させられた。</span>（Aku disuruh ibu bersih-bersih, yang membersihkan adalah aku）</div><div class='gd-sec'>Lalu 「させてもらう」: sama-sama orang lain yang membuatmu melakukan sesuatu, tapi perasaannya berlawanan:<br><b>させてもらう</b> = aku ingin melakukannya, pihak lain <b>mengizinkan</b>, dan aku berterima kasih：<span class='gd-jp'>店長に頼んで、休ませてもらった。</span>（Aku minta tolong pada manajer toko, dan aku diizinkan libur）<br><b>させられる</b> = aku tidak mau, pihak lain <b>memaksa</b>：<span class='gd-jp'>熱があって、店長に無理やり休まされた。</span>（Aku demam, dan dipaksa manajer toko untuk istirahat）</div><div class='gd-warn'>Trik cepat: tanyakan dulu “siapa yang bertindak?” Kalau pihak lain yang bertindak, pakai られる. Kalau aku yang bertindak tapi tidak rela, pakai させられる. Kalau aku yang bertindak dan memang aku yang ingin, pakai させてもらう.</div><div class='gd-h'>Yang bisa dipelajari selanjutnya</div><div class='gd-sec'>Kalau 「させる」 dan 「られる」 masih belum lancar, ulangi dulu <span class='gd-jp'>〜させる</span> (kausatif) dan <span class='gd-jp'>〜られる</span> (pasif). Tata bahasa ini hanya gabungan dari keduanya.</div>","n3-73":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>「〜ても」 artinya <b>“biarpun ~ tetap ~” atau “meskipun ~ tetap ~”</b>. Apa pun yang terjadi di bagian depan, hasil di belakang <b>tidak terpengaruh</b> dan tetap sama. Seperti kamu bilang “biarpun hujan, aku tetap pergi”: hujan tidak bisa mengubah keputusanmu untuk pergi.</div><div class='gd-ex-line'>・<span class='gd-jp'>雨が降っても、行きます。</span>（Biarpun hujan, aku tetap pergi）</div><div class='gd-ex-line'>・<span class='gd-jp'>高くても、買いたい。</span>（Biarpun mahal, aku ingin membelinya）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Verba</b>: ubah dulu ke bentuk て, lalu tambahkan も.<br><span class='gd-pair'><span class='gd-jp'>書く</span> → <span class='gd-jp'>書いて</span> → <span class='gd-jp'>書いても</span></span><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べて</span> → <span class='gd-jp'>食べても</span></span><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>しても</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ても</span>（きても）</span><br>Verba yang bentuk て-nya berakhiran 「で」 jadi 「でも」 kalau ditambah も：<span class='gd-pair'><span class='gd-jp'>読む</span> → <span class='gd-jp'>読んで</span> → <span class='gd-jp'>読んでも</span></span></div><div class='gd-sec'><b>Kata sifat-い</b>: ganti 「い」 di akhir dengan 「くても」.<br><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高くても</span></span><span class='gd-pair'><span class='gd-jp'>忙しい</span> → <span class='gd-jp'>忙しくても</span></span></div><div class='gd-sec'><b>Kata sifat-な・nomina</b>: langsung tambahkan 「でも」.<br><span class='gd-pair'><span class='gd-jp'>下手</span> → <span class='gd-jp'>下手でも</span></span><span class='gd-pair'><span class='gd-jp'>日曜日</span> → <span class='gd-jp'>日曜日でも</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>料理が下手でも、大丈夫です。</span>（Biarpun tidak jago masak, tidak apa-apa）</div><div class='gd-ex-line'>・<span class='gd-jp'>日曜日でも、仕事がある。</span>（Biarpun hari Minggu, tetap ada pekerjaan）</div><div class='gd-sec'><b>Bentuk negatif “biarpun tidak ~”</b>: ganti ない menjadi なくても。<span class='gd-pair'><span class='gd-jp'>行かない</span> → <span class='gd-jp'>行かなくても</span></span></div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>Kata tanya＋ても</span>Kalau di depannya ada kata tanya seperti “apa, siapa, di mana, kapan”, artinya jadi “apa pun/siapa pun/kapan pun ~ tetap ~”.</div><div class='gd-ex-line'>・<span class='gd-jp'>何を食べても、おいしい。</span>（Makan apa pun terasa enak）</div><div class='gd-ex-line'>・<span class='gd-jp'>いつ行っても、混んでいる。</span>（Kapan pun datang, selalu ramai）</div><div class='gd-ex-line'>・<span class='gd-jp'>何度確認しても、ミスが見つからない。</span>（Sudah dicek berkali-kali pun, kesalahannya tidak ketemu）</div><div class='gd-sec'><span class='gd-tag'>どんなに／いくら〜ても</span>“Sebagaimanapun ~ tetap ~”, menekankan bahwa seberapa tinggi pun tingkatnya, hasilnya tidak berubah.</div><div class='gd-ex-line'>・<span class='gd-jp'>どんなに忙しくても、朝ご飯は必ず食べる。</span>（Sesibuk apa pun, aku pasti sarapan）</div><div class='gd-ex-line'>・<span class='gd-jp'>いくら練習しても、上手にならない。</span>（Seberapa banyak pun latihan, tetap tidak jago）</div><div class='gd-sec'><span class='gd-tag'>たとえ〜ても</span>“Andaikan benar-benar ~”, nadanya lebih tegas dan sering dipakai untuk menyatakan tekad.</div><div class='gd-ex-line'>・<span class='gd-jp'>たとえ反対されても、留学したい。</span>（Sekalipun ditentang, aku tetap ingin kuliah di luar negeri）</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Nomina dan kata sifat-な langsung ditambah <b>でも</b>：<span class='gd-jp'>下手でも</span>, bukan “下手くても”.<br>・<span class='gd-jp'>いい</span> harus jadi <span class='gd-jp'>よくても</span>, bukan “いくても”.<br>・Verba harus diubah dulu ke bentuk て：<span class='gd-jp'>読んでも</span>, bukan “読むでも”.<br>・Pakai ても hanya kalau hasil di belakang <b>berlawanan</b> dengan “yang biasanya diharapkan”. Minum obat lalu demam turun itu hasil yang wajar, jadi tidak boleh bilang “薬を飲んでも、熱が下がった”. Yang benar: <span class='gd-jp'>薬を飲んだら、熱が下がった。</span>（Setelah minum obat, demamnya turun）. Kalau pakai ても jadinya：<span class='gd-jp'>薬を飲んでも、熱が下がらない。</span>（Sudah minum obat pun, demamnya tidak turun）</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Sama-sama soal keluar rumah saat hujan, tapi artinya berbeda tergantung tata bahasanya:<br><b>たら</b> = kalau ~ maka (syarat terpenuhi, hasilnya mengikuti)：<span class='gd-jp'>雨が降ったら、行かない。</span>（Kalau hujan, aku tidak pergi）<br><b>ても</b> = biarpun ~ tetap (syarat tidak mengubah hasil)：<span class='gd-jp'>雨が降っても、行く。</span>（Biarpun hujan, aku tetap pergi）<br><b>のに</b> = padahal ~ (fakta yang sudah terjadi, dengan rasa heran atau tidak puas seperti “kok bisa begini”)：<span class='gd-jp'>雨が降っているのに、傘を持たないで出かけた。</span>（Padahal sedang hujan, dia pergi tanpa membawa payung）</div><div class='gd-sec'>ても bisa dipakai untuk pengandaian yang belum terjadi, dan di belakangnya boleh ada ajakan “ayo” atau permintaan “tolong”：<span class='gd-jp'>雨が降っても、行きましょう。</span>（Biarpun hujan, ayo kita pergi）. のに membicarakan hal yang sudah terjadi, jadi di belakangnya tidak boleh ada ajakan atau permintaan. Makanya tidak boleh bilang “雨が降っているのに、行きましょう”.</div><div class='gd-warn'>Trik cepat: kalau dalam bahasa Indonesia kamu mau bilang “kalau ~ maka”, pakai たら. Untuk “biarpun / meskipun ~ tetap”, pakai ても. Untuk “padahal ~ kok”, pakai のに.</div>","n3-76":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>Ketiga pola ini dipakai untuk bilang <b>「…banget sampai nggak tahan」「…setengah mati」</b>. Panas banget, kangen rumah sampai nggak tahan, khawatir setengah mati. Pakai saja saat perasaanmu begitu kuat sampai tak bisa ditahan. Artinya hampir sama, bedanya ada di nuansa dan situasi pemakaian.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Sensasi tubuh</span>Panas, dingin, sakit, ngantuk, lapar, gatal.</div><div class='gd-ex-line'>・<span class='gd-jp'>お腹が空いてたまらない。</span>（lapar banget sampai nggak tahan）</div><div class='gd-ex-line'>・<span class='gd-jp'>足が痛くてしかたがない。</span>（kaki sakit setengah mati）</div><div class='gd-sec'><span class='gd-tag'>Perasaan</span>Senang, sedih, kesepian, khawatir, kepikiran.</div><div class='gd-ex-line'>・<span class='gd-jp'>試験の結果が心配でならない。</span>（khawatir banget soal hasil ujian）</div><div class='gd-sec'><span class='gd-tag'>Pengin banget</span>Taruh 「〜たい」 di depannya, jadi artinya 「pengin ～ banget sampai nggak tahan」.</div><div class='gd-ex-line'>・<span class='gd-jp'>家族に会いたくてたまらない。</span>（kangen banget pengin ketemu keluarga, sampai nggak tahan）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Kuncinya, bagian depan harus diubah dulu ke bentuk 「て」. Cara ubahnya beda untuk tiap jenis kata:<br><b>Kata kerja</b>: langsung pakai bentuk て　<span class='gd-pair'><span class='gd-jp'>気になる</span> → <span class='gd-jp'>気になって</span>しかたがない</span><br><b>Kata sifat-い</b>: ganti 「い」 di akhir dengan 「くて」　<span class='gd-pair'><span class='gd-jp'>暑い</span> → <span class='gd-jp'>暑くて</span>たまらない</span><br><b>Kata sifat-な</b>: langsung tambahkan 「で」　<span class='gd-pair'><span class='gd-jp'>心配</span> → <span class='gd-jp'>心配で</span>ならない</span><br>Bentuk 「〜たい」 berubah seperti kata sifat-い: <span class='gd-pair'><span class='gd-jp'>会いたい</span> → <span class='gd-jp'>会いたくて</span></span></div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Sama-sama berarti 「ngantuk banget」:<br>・<span class='gd-jp'>眠くてたまらない。</span>（paling langsung dan terasa, sering dipakai dalam percakapan）<br>・<span class='gd-jp'>眠くてしかたがない。</span>（ngantuk terus dan tak bisa dihentikan. Dalam percakapan sering jadi <span class='gd-jp'>眠くてしょうがない</span>）<br>・<span class='gd-jp'>眠くてならない。</span>（artinya sama, tapi lebih formal dan cenderung tulisan, jarang dipakai ngobrol sehari-hari）</div><div class='gd-sec'><b>ならない</b> punya satu pasangan yang sangat umum: 「<b>entah kenapa merasa ～, dan pikiran itu tak bisa hilang</b>」. Di sini ならない paling sering dipakai, sedangkan たまらない jarang dipakai begini.</div><div class='gd-ex-line'>・<span class='gd-jp'>何か忘れているような気がしてならない。</span>（terus merasa seperti ada yang terlupa）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の話は嘘のように思えてならない。</span>（apa pun yang kupikirkan, ceritanya terasa seperti bohong）</div><div class='gd-warn'>Trik cepat: kalau ngobrol dengan teman dan mau bilang 「…banget」, pakai たまらない atau しょうがない. Kalau menulis, atau mau bilang 「entah kenapa merasa ～」, pakai ならない.</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Kata sifat-い jangan langsung disambung て: yang benar <span class='gd-jp'>暑くてたまらない</span>, bukan 暑いてたまらない. Kata sifat-な pakai <span class='gd-jp'>心配で</span>, bukan 心配て.<br>・Pola ini untuk perasaan <b>dirimu sendiri</b>. Untuk orang lain, tambahkan <span class='gd-jp'>ようだ</span> atau <span class='gd-jp'>らしい</span>: <span class='gd-jp'>弟は寂しくてたまらないようだ。</span>（adikku kelihatannya kesepian banget）<br>・Hanya bisa untuk perasaan dan emosi, bukan deskripsi biasa. 「Kamar ini luas banget」 tidak bisa dibilang 広くてたまらない; pakai ungkapan seperti <span class='gd-jp'>すごく広い</span>.<br>・<span class='gd-jp'>てならない</span> tidak sama dengan <span class='gd-jp'>てはならない</span>! Kalau ada 「は」 di tengah, artinya jadi 「tidak boleh ～」: <span class='gd-jp'>ここに入ってはならない。</span>（dilarang masuk ke sini）<br>・<span class='gd-jp'>しかたがない</span> kalau dipakai sendiri artinya 「mau bagaimana lagi」: <span class='gd-jp'>雨だから、しかたがない。</span>（hujan sih, mau bagaimana lagi）. Baru kalau didahului bentuk て, artinya 「…banget sampai nggak tahan」.</div><div class='gd-h'>Setelah paham, lanjut belajar ini</div><div class='gd-sec'><span class='gd-jp'>たまらない</span> kalau dipakai sendiri sering artinya 「enak banget sampai nggak tahan」: <span class='gd-jp'>仕事の後のビール、たまらない！</span>（bir sepulang kerja, nikmat banget!）</div>","n3-77":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>「〜どおりに／〜とおりに」 artinya <b>「sesuai ～」「sama seperti ～」</b>. Masak sesuai resep, jalan sesuai rencana, menulis seperti yang dikatakan guru, semuanya pakai pola ini. Kanjinya 「通り」, jadi bayangkan contohnya sudah menggambar jalurnya dan kamu tinggal mengikuti jalur itu.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Mengikuti contoh</span>Kamu punya acuan, misalnya resep, buku panduan, rencana, atau ucapan orang lain, lalu kamu melakukannya persis seperti itu.</div><div class='gd-ex-line'>・<span class='gd-jp'>説明書どおりに組み立てた。</span>（merakitnya sesuai buku panduan）</div><div class='gd-ex-line'>・<span class='gd-jp'>先生が言ったとおりに書いてください。</span>（tolong tulis seperti yang dikatakan guru）</div><div class='gd-sec'><span class='gd-tag'>Sesuai dugaan</span>Hasilnya sama dengan yang dipikirkan atau diprediksi, mirip 「sudah kuduga」.</div><div class='gd-ex-line'>・<span class='gd-jp'>予想どおり、試験は難しかった。</span>（sesuai dugaan, ujiannya sulit）</div><div class='gd-ex-line'>・<span class='gd-jp'>思ったとおり、彼は来なかった。</span>（sudah kuduga, dia tidak datang）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Kuncinya, lihat <b>apa yang ada di depannya: kata benda atau kata kerja</b>, karena cara bacanya berbeda:<br><b>Kata benda langsung disambung</b>: dibaca <b>どおり</b> (dengan dakuten)<br><span class='gd-pair'><span class='gd-jp'>計画</span> → <span class='gd-jp'>計画どおり</span></span><span class='gd-pair'><span class='gd-jp'>予定</span> → <span class='gd-jp'>予定どおり</span></span><br><b>Kata benda + 「の」</b>: dibaca <b>とおり</b><br><span class='gd-pair'><span class='gd-jp'>説明書</span> → <span class='gd-jp'>説明書のとおり</span></span><br><b>Kata kerja</b>: pakai bentuk kamus atau bentuk た, dibaca <b>とおり</b><br><span class='gd-pair'><span class='gd-jp'>言う</span> → <span class='gd-jp'>言うとおり</span></span><span class='gd-pair'><span class='gd-jp'>教わった</span> → <span class='gd-jp'>教わったとおり</span></span><br>Oh ya, <span class='gd-jp'>そのとおりです</span> (betul sekali, kamu benar) sering dipakai untuk menyetujui lawan bicara yang bicaranya tepat.</div><div class='gd-sec'>Bagian setelahnya tergantung kelanjutannya:<br>Kalau diikuti kata kerja, pakai 「に」 (dalam percakapan sering dihilangkan): <span class='gd-jp'>計画どおり進んでいる。</span>（berjalan sesuai rencana）<br>Kalau diikuti kata benda, pakai 「の」: <span class='gd-jp'>予想どおりの結果だった。</span>（hasilnya sesuai dugaan）<br>Di akhir kalimat, pakai 「だ／です」: <span class='gd-jp'>結果は期待どおりだった。</span>（hasilnya sesuai harapan）</div><div class='gd-h'>Memilih bentuk kamus atau bentuk た</div><div class='gd-sec'><span class='gd-tag'>Bentuk た</span>Acuannya <b>sudah terjadi</b>, misalnya sudah diajarkan, sudah dikatakan, atau sudah dilihat. Ini yang paling sering dipakai.</div><div class='gd-ex-line'>・<span class='gd-jp'>見たとおりに話してください。</span>（tolong ceritakan seperti yang kamu lihat）</div><div class='gd-sec'><span class='gd-tag'>Bentuk kamus</span>Acuannya <b>sedang berlangsung</b>, atau dipakai untuk umum, seperti 「menuruti kata seseorang」.</div><div class='gd-ex-line'>・<span class='gd-jp'>私が言うとおりに書いてください。</span>（tolong tulis seperti yang aku (sekarang) ucapkan）</div><div class='gd-ex-line'>・<span class='gd-jp'>親の言うとおりにする。</span>（menurut apa kata orang tua）</div><div class='gd-h'>Bagian yang sering salah</div><div class='gd-warn'>・Hanya kalau kata benda disambung <b>langsung</b>, dibacanya どおり. Kalau ada の di tengah, jadi とおり: yang benar <span class='gd-jp'>説明書のとおり</span>, bukan 説明書のどおり; yang benar <span class='gd-jp'>計画どおり</span>, bukan 計画とおり.<br>・Setelah kata kerja, bacanya <b>とおり</b>, jangan ditulis どおり yang pakai dakuten.<br>・Dalam bahasa Jepang, jangan menambahkan <b>を</b> di depannya. 計画をどおりに itu salah.<br>・Kalau diikuti kata benda, の wajib ada: <span class='gd-jp'>予想どおりの結果</span>, tidak bisa 予想どおり結果.<br>・Kalau di Jepang kamu melihat nama jalan seperti <span class='gd-jp'>銀座通り</span>, 「通り」 di situ artinya 「jalan」 dan tidak ada hubungannya dengan tata bahasa ini.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'><b>どおりに</b> = caranya <b>persis sama</b> dengan acuan: <span class='gd-jp'>マニュアルどおりに対応した。</span>（menanganinya persis sesuai manual）<br><b>に基づいて</b> = acuan dipakai sebagai <b>dasar atau landasan</b>: <span class='gd-jp'>マニュアルに基づいて対応した。</span>（menanganinya berdasarkan manual）<br>Selain itu, untuk 「hasilnya sesuai dugaan」 hanya bisa pakai どおり, seperti <span class='gd-jp'>予想どおり</span>, tidak bisa diganti に基づいて.</div><div class='gd-warn'>Trik cepat: kalau melakukan sesuatu persis seperti acuan, atau mau bilang 「sudah kuduga, sama seperti yang kupikirkan」, pakai どおり／とおり. Kalau acuannya hanya dijadikan dasar atau landasan, pakai に基づいて.</div>","n3-78":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>「〜っけ」dipakai saat kamu <b>sebenarnya sudah tahu, tapi sekarang tiba-tiba lupa</b>. Rasanya seperti bilang, \"Eh, rapat besok jam berapa ya? Aku lupa\" atau \"Ulang tahunnya minggu depan, bukan sih?\" Kamu bertanya sambil mengingat-ingat.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Lupa</span>Dipakai untuk bertanya ke orang lain, atau untuk bergumam sendiri.</div><div class='gd-ex-line'>・<span class='gd-jp'>明日のミーティングは何時からだっけ？</span>（Rapat besok mulai jam berapa ya? Aku lupa）</div><div class='gd-ex-line'>・<span class='gd-jp'>あれ、鍵どこに置いたっけ？</span>（Lho, tadi aku taruh kunci di mana ya?）</div><div class='gd-sec'><span class='gd-tag'>Memastikan ingatan</span>Kamu sudah punya jawaban di kepala, dan ingin memastikan ingatanmu tidak salah.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼の誕生日は来週だっけ？</span>（Ulang tahunnya minggu depan, kan?）</div><div class='gd-sec'><span class='gd-tag'>Mengenang masa lalu</span>Bergumam sendiri tentang hal yang sudah lewat. Nada akhir kalimat tidak naik, dan terasa seperti \"dulu ya...\".</div><div class='gd-ex-line'>・<span class='gd-jp'>子どものころ、よくこの公園で遊んだっけ。</span>（Waktu kecil, aku sering main di taman ini ya）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Kata benda dan kata sifat-な</b>: tambahkan 「だ」 atau 「だった」 dulu, baru っけ.<br><span class='gd-pair'><span class='gd-jp'>明日</span> → <span class='gd-jp'>明日だっけ</span></span><span class='gd-pair'><span class='gd-jp'>静か</span> → <span class='gd-jp'>静かだったっけ</span></span></div><div class='gd-sec'><b>Kata kerja</b>: untuk menanyakan hal yang sudah lalu, pakai bentuk た lalu tambahkan っけ.<br><span class='gd-pair'><span class='gd-jp'>言う</span> → <span class='gd-jp'>言った</span> → <span class='gd-jp'>言ったっけ</span></span><br>Untuk hal yang belum terjadi, biasanya 「〜んだっけ」 terdengar lebih natural.<br><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来るんだっけ</span></span>（Dia datang, kan?）</div><div class='gd-sec'><b>Kata sifat-い</b>: ganti い menjadi かった, lalu tambahkan っけ.<br><span class='gd-pair'><span class='gd-jp'>高い</span> → <span class='gd-jp'>高かったっけ</span></span>（Tempat itu mahal ya? Aku lupa）</div><div class='gd-sec'><b>Kalau mau lebih sopan</b>: pakai 「でしたっけ」「ましたっけ」.</div><div class='gd-ex-line'>・<span class='gd-jp'>すみません、お名前は何でしたっけ？</span>（Maaf, nama Anda tadi siapa ya... Saya sedang lupa）</div><div class='gd-ex-line'>・<span class='gd-jp'>前に言いましたっけ？</span>（Apakah saya sudah pernah bilang sebelumnya?）</div><div class='gd-h'>Kesalahan yang sering terjadi</div><div class='gd-warn'>・Setelah kata benda, っけ tidak bisa langsung dipasang. <span class='gd-jp'>明日っけ</span> itu salah, yang benar <span class='gd-jp'>明日だっけ</span>.<br>・Syarat memakai っけ adalah kamu <b>pernah tahu</b> hal itu. Kalau baru pertama kali bertanya arah ke orang asing, kamu tidak boleh bilang <span class='gd-jp'>駅はどこだっけ？</span>. Bilanglah <span class='gd-jp'>駅はどこですか。</span><br>・Hal yang terjadi besok pun bisa memakai bentuk lampau: <span class='gd-jp'>明日の会議、何時からだったっけ？</span> 「た」 di sini bukan berarti rapatnya sudah selesai, tapi menunjuk pada \"hal yang dulu pernah kamu dengar\".<br>・「だっけ」 adalah versi untuk teman. Ke atasan atau pelanggan, pakai 「でしたっけ」「ましたっけ」. Ini sering terdengar di tempat kerja, tapi jangan dipakai di wawancara atau surat resmi.<br>・「っ」 kecil harus ditahan satu ketukan: <span class='gd-jp'>だっけ</span> dibaca dakke. Kalau ketukan itu hilang dan jadi <span class='gd-jp'>だけ</span>, artinya berubah menjadi \"hanya\".</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Sama-sama bertanya ke teman soal \"rapat besok jam berapa\":<br><span class='gd-jp'>明日の会議、何時から？</span>: pertanyaan biasa, kamu memang belum tahu.<br><span class='gd-jp'>明日の会議、何時からだっけ？</span>: kamu pernah dengar, tapi lupa.<br><span class='gd-jp'>明日の会議、何時からかな。</span>: kamu bertanya-tanya dalam hati, dan lawan bicara tidak harus menjawab.</div><div class='gd-warn'>Tips menentukan: \"dulu tahu, sekarang lupa\" pakai っけ; \"memang belum tahu\" pakai kalimat tanya biasa.</div>","n3-79":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>「〜反面」kira-kira artinya <b>\"di satu sisi... tapi di sisi lain...\"</b>, seperti <b>dua sisi mata uang</b>. Untuk satu hal yang sama, kamu sebut satu sisinya dulu, lalu sisi lainnya yang <b>berlawanan</b>. Contohnya \"gaji pekerjaan ini lumayan, tapi sibuk sekali\". Satu hal dengan dua sisi yang berlawanan seperti ini memakai 反面.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Satu baik, satu buruk</span>Pemakaian paling umum: satu orang atau satu benda punya kelebihan sekaligus kekurangan.</div><div class='gd-ex-line'>・<span class='gd-jp'>この仕事は給料がいい反面、休みが少ない。</span>（Gaji pekerjaan ini bagus, tapi hari liburnya sedikit）</div><div class='gd-ex-line'>・<span class='gd-jp'>一人暮らしは自由な反面、寂しいこともある。</span>（Tinggal sendiri itu bebas, tapi kadang juga terasa sepi）</div><div class='gd-sec'><span class='gd-tag'>Perasaan campur aduk</span>Di hati ada dua perasaan yang berlawanan sekaligus. Ini juga sering dipakai.</div><div class='gd-ex-line'>・<span class='gd-jp'>卒業はうれしい反面、少し寂しい。</span>（Lulus itu menyenangkan, tapi juga agak sedih berpisah）</div><div class='gd-sec'><span class='gd-tag'>Di awal kalimat</span>Setelah kalimat pertama selesai, kalimat berikutnya dibuka dengan 「その反面」, artinya \"tapi di sisi lain\".</div><div class='gd-ex-line'>・<span class='gd-jp'>スマホは便利だ。その反面、使いすぎると目が疲れる。</span>（Ponsel itu praktis. Tapi di sisi lain, kalau terlalu sering dipakai, mata jadi lelah）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Kata kerja</b>: sambung langsung, bentuk lampau juga boleh.<br><span class='gd-pair'><span class='gd-jp'>便利になった</span> → <span class='gd-jp'>便利になった反面</span></span><br><b>Kata sifat-い</b>: sambung langsung.<br><span class='gd-pair'><span class='gd-jp'>速い</span> → <span class='gd-jp'>速い反面</span></span><br><b>Kata sifat-な</b>: tambahkan 「な」, atau pakai 「である」 yang lebih formal.<br><span class='gd-pair'><span class='gd-jp'>便利</span> → <span class='gd-jp'>便利な反面</span>／<span class='gd-jp'>便利である反面</span></span><br><b>Kata benda</b>: tambahkan 「である」.<br><span class='gd-pair'><span class='gd-jp'>有名人</span> → <span class='gd-jp'>有名人である反面</span></span></div><div class='gd-ex-line'>・<span class='gd-jp'>彼女は有名人である反面、自由な時間が少ない。</span>（Dia seorang selebritas, tapi sebagai gantinya waktu bebasnya sedikit）</div><div class='gd-h'>Kesalahan yang sering terjadi</div><div class='gd-warn'>・Kata sifat-な tidak bisa disambung langsung. Bilang <span class='gd-jp'>便利な反面</span>, jangan 「便利反面」 dan jangan 「便利だ反面」.<br>・Kata benda harus memakai <span class='gd-jp'>である</span>, jangan bilang 「学生な反面」.<br>・反面 membicarakan dua sisi dari <b>satu hal yang sama</b>. Kalau dipakai untuk membandingkan dua orang yang berbeda, misalnya \"kakak tinggi, adik pendek\", rasanya janggal.<br>・反面 cenderung bahasa tulis dan formal, sering muncul di esai, berita, dan laporan. Saat ngobrol dengan teman, cukup pakai <span class='gd-jp'>けど</span>: <span class='gd-jp'>給料はいいけど、忙しい。</span>（Gajinya sih bagus, tapi sibuk）<br>・Cara bacanya <b>はんめん</b>.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'><b>反面</b> = dua sisi dari <b>satu</b> hal yang sama: <span class='gd-jp'>兄は優しい反面、気が弱い。</span>（Kakakku baik hati, tapi di sisi lain mentalnya lemah）<br><b>一方で</b> = bisa untuk dua sisi dari satu hal, <b>bisa juga</b> untuk membandingkan dua hal yang berbeda: <span class='gd-jp'>兄はスポーツが好きな一方で、弟は本が好きだ。</span>（Kakakku suka olahraga, sedangkan adikku suka buku）<br><b>に対して</b> = khusus untuk mengontraskan <b>dua hal yang berbeda</b>: <span class='gd-jp'>兄は背が高いのに対して、弟は低い。</span>（Kakakku tinggi, sedangkan adikku pendek）</div><div class='gd-warn'>Tips menentukan: kalau tokohnya hanya satu dan kamu membicarakan sisi baik dan buruknya, pakai 反面. Kalau tokohnya dua dan kamu membandingkannya, pakai 一方で atau に対して.<br>Satu lagi: <span class='gd-jp'>一方だ</span> di akhir kalimat artinya \"semakin ~\". Itu hal yang berbeda dari 「一方で」 di sini, jadi jangan tertukar.</div>","n3-74":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜たことがある」artinya <b>「pernah ～」</b> atau <b>「punya pengalaman ～」</b>. Yang penting bukan hari apa kamu melakukannya, tapi apakah dalam hidupmu <b>ada pengalaman itu atau tidak</b>. Seperti saat temanmu bertanya, \"Kamu pernah makan durian?\" Nah, itu yang sedang ditanyakan.</div><div class='gd-ex-line'>・<span class='gd-jp'>富士山に登ったことがある。</span>（Aku pernah mendaki Gunung Fuji.）</div><div class='gd-ex-line'>・<span class='gd-jp'>日本の温泉に入ったことがありますか。</span>（Kamu pernah berendam di onsen Jepang?）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Bentuk た</b> dari verba (bentuk lampau 「〜た」) ＋ <span class='gd-jp'>ことがある</span>.<br>Kalau mau lebih sopan, pakai <span class='gd-jp'>ことがあります</span>. Kalau belum pernah, ganti ある dengan <span class='gd-jp'>ない</span>:<br><span class='gd-pair'><span class='gd-jp'>食べたことがある</span> → <span class='gd-jp'>食べたことがない</span></span>（belum pernah makan）</div><div class='gd-h'>Cara mengubah: lihat dulu verbanya masuk kelompok mana</div><div class='gd-sec'>Bentuk た sebenarnya cuma bentuk て yang 「て」-nya diganti 「た」. Kalau kamu sudah bisa bentuk て, bentuk た pasti bisa juga.<br><b>Kelompok 1 (五段動詞)</b>: lihat bunyi terakhirnya.<br><span class='gd-pair'><span class='gd-jp'>会う</span> → <span class='gd-jp'>会った</span></span><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲んだ</span></span><span class='gd-pair'><span class='gd-jp'>書く</span> → <span class='gd-jp'>書いた</span></span><span class='gd-pair'><span class='gd-jp'>泳ぐ</span> → <span class='gd-jp'>泳いだ</span></span><span class='gd-pair'><span class='gd-jp'>話す</span> → <span class='gd-jp'>話した</span></span><br>Perhatikan khususnya: <span class='gd-pair'><span class='gd-jp'>行く</span> → <span class='gd-jp'>行った</span></span>, bukan 行いた.</div><div class='gd-sec'><b>Kelompok 2 (一段動詞)</b>: buang 「る」, lalu tambahkan 「た」.<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べた</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見た</span></span></div><div class='gd-sec'><b>Kelompok 3 (cuma dua, hafalkan saja)</b>: <span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>した</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来た</span>（きた）</span></div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>Menanyakan pengalaman</span>Enak banget buat membuka obrolan. Saat menjawab, kamu tidak perlu mengulang seluruh kalimat; cukup bilang 「あります／ありません」.</div><div class='gd-ex-line'>・<span class='gd-jp'>沖縄に行ったことがありますか。</span>（Kamu pernah ke Okinawa?）</div><div class='gd-ex-line'>・<span class='gd-jp'>はい、あります。</span>（Ya, pernah.）</div><div class='gd-ex-line'>・<span class='gd-jp'>いいえ、一度もありません。</span>（Belum, sekali pun belum pernah.）</div><div class='gd-sec'><span class='gd-tag'>Menambah jumlah kali</span>Sering muncul bersama <span class='gd-jp'>一度</span>, <span class='gd-jp'>何度も</span>, dan <span class='gd-jp'>一度も〜ない</span>.</div><div class='gd-ex-line'>・<span class='gd-jp'>あの店には何度も行ったことがある。</span>（Aku sudah beberapa kali ke toko itu.）</div><div class='gd-ex-line'>・<span class='gd-jp'>納豆は一度も食べたことがない。</span>（Natto, sekali pun aku belum pernah makan.）</div><div class='gd-sec'><span class='gd-tag'>Keadaan di masa lalu</span>Pakai <span class='gd-jp'>〜ていたことがある</span>, artinya \"dulu pernah ～ selama beberapa waktu\".</div><div class='gd-ex-line'>・<span class='gd-jp'>子どものころ、大阪に住んでいたことがある。</span>（Waktu kecil, aku pernah tinggal di Osaka.）</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・<b>Tidak semua \"sudah\" atau \"pernah\" dalam bahasa Indonesia sama dengan ini</b>. Kalimat \"Aku sudah ke supermarket kemarin\" hanya menceritakan apa yang dilakukan kemarin. Dalam bahasa Jepang cukup bilang <span class='gd-jp'>昨日スーパーに行きました</span>; kamu tidak boleh bilang 昨日スーパーに行ったことがあります.<br>・<b>Tidak bisa dipakai untuk hal yang baru saja terjadi</b>: waktu yang jelas dan dekat seperti <span class='gd-jp'>さっき</span>, <span class='gd-jp'>昨日</span>, dan <span class='gd-jp'>先週</span> tidak cocok dengan \"pengalaman hidup\". Rentang waktu yang panjang seperti <span class='gd-jp'>子どものころ</span> tidak masalah.<br>・<b>Hal yang dilakukan setiap hari juga terdengar aneh</b>: kalau kamu bilang \"Aku pernah makan nasi\" atau \"Aku pernah naik KRL\", orang Jepang akan berpikir, \"Memangnya kenapa?\" Pakai pola ini untuk pengalaman yang agak spesial, yang tidak dimiliki semua orang.<br>・Sebelumnya harus <b>bentuk た</b>. Kalau kamu tulis <span class='gd-jp'>行くことがある</span>, artinya berubah total (lihat di bawah).</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Sama-sama 「ことがある」, tapi bentuk di depannya berbeda, dan artinya pun beda jauh:<br><b>Bentuk た＋ことがある</b>＝<b>pernah</b> melakukan (pengalaman di masa lalu)<br><b>Bentuk kamus＋ことがある</b>＝<b>kadang-kadang</b> (hal yang sesekali terjadi)</div><div class='gd-ex-line'>・<span class='gd-jp'>一人で映画を見に行ったことがある。</span>（Aku pernah pergi menonton film sendirian.）</div><div class='gd-ex-line'>・<span class='gd-jp'>一人で映画を見に行くことがある。</span>（Kadang-kadang aku pergi menonton film sendirian.）</div><div class='gd-sec'>Kalimat pertama hanya bilang \"pernah sekali atau lebih\"; sekarang belum tentu masih begitu. Kalimat kedua bilang bahwa sekarang pun sesekali kamu melakukannya.</div><div class='gd-warn'>Trik membedakan: kalau di depannya ada 「た」, artikan \"pernah ～\". Kalau di depannya bentuk kamus, artikan \"kadang-kadang ～\".</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Ada pola lain yang juga diawali bentuk た, yaitu <span class='gd-jp'>〜たばかり</span> (baru saja ～). Pola ini membahas hal yang baru terjadi, jadi kebalikan dari \"pengalaman\". Hafalkan keduanya sekaligus.</div>","n3-75":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜ことができる」artinya <b>「bisa ～」</b> atau <b>「dapat ～」</b>. Maknanya hampir sama dengan bentuk potensial (seperti <span class='gd-jp'>話せる</span> dan <span class='gd-jp'>行ける</span>), hanya saja cara bilangnya lebih lengkap dan lebih formal. Pola ini sering muncul di pengumuman, penjelasan, wawancara, dan situasi resmi.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Bisa melakukan (kemampuan)</span>Kamu sudah belajar dan punya kemampuan untuk melakukannya.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼はピアノを弾くことができる。</span>（Dia bisa main piano.）</div><div class='gd-sec'><span class='gd-tag'>Boleh, memungkinkan</span>Aturan membolehkan, atau kondisinya memungkinkan.</div><div class='gd-ex-line'>・<span class='gd-jp'>ここで写真を撮ることができます。</span>（Di sini boleh memotret.）</div><div class='gd-ex-line'>・<span class='gd-jp'>この展示は予約なしで入場することができます。</span>（Pameran ini bisa dimasuki tanpa reservasi.）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Verba pakai bentuk kamus (bentuk asli yang kamu temukan di kamus), lalu langsung tambahkan 「ことができる」. Kabar baiknya, <b>kamu tidak perlu peduli verbanya masuk kelompok mana</b>; sambung saja.<br><span class='gd-pair'><span class='gd-jp'>話す</span> → <span class='gd-jp'>話すことができる</span></span><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べることができる</span></span><br><span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>することができる</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来ることができる</span>（くる）</span></div><div class='gd-sec'>Untuk bilang \"tidak bisa\" atau \"berhasil\", cukup ubah 「できる」 di bagian akhir:<br><span class='gd-pair'><span class='gd-jp'>できる</span> → <span class='gd-jp'>できない</span>（tidak bisa）</span><span class='gd-pair'><span class='gd-jp'>できる</span> → <span class='gd-jp'>できた</span>（berhasil）</span></div><div class='gd-sec'><b>Kata benda juga punya cara bilang sendiri</b>: kata benda yang menyatakan \"aktivitas\" seperti bahasa, olahraga, atau keterampilan bisa langsung disambung 「ができる」: <span class='gd-jp'>日本語ができる</span> (bisa bahasa Jepang), <span class='gd-jp'>テニスができる</span> (bisa main tenis).<br>Kata benda benda biasa tidak bisa. Misalnya, untuk \"bisa menyetir\" kamu harus bilang <span class='gd-jp'>車の運転ができる</span> atau <span class='gd-jp'>車を運転することができる</span>; tidak bisa bilang <span class='gd-jp'>車ができる</span>. Arti <span class='gd-jp'>本ができる</span> pun \"bukunya sudah jadi\", bukan \"bisa membaca buku\".</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>ことができます</span>Toko atau pengumuman memberi tahu apa yang bisa kamu lakukan.</div><div class='gd-ex-line'>・<span class='gd-jp'>カードで払うことができます。</span>（Bisa bayar dengan kartu.）</div><div class='gd-sec'><span class='gd-tag'>ことはできません</span>Aturan melarang. Dalam bentuk negatif, 「が」 sering diganti 「は」, sehingga terdengar seperti \"hal ini memang tidak bisa\".</div><div class='gd-ex-line'>・<span class='gd-jp'>ここでたばこを吸うことはできません。</span>（Di sini tidak boleh merokok.）</div><div class='gd-sec'><span class='gd-tag'>ことができました</span>Akhirnya berhasil setelah berusaha.</div><div class='gd-ex-line'>・<span class='gd-jp'>やっと切符を買うことができました。</span>（Akhirnya aku berhasil membeli tiketnya.）</div><div class='gd-sec'><span class='gd-tag'>ことができるようになった</span>Dulu tidak bisa, sekarang jadi bisa.</div><div class='gd-ex-line'>・<span class='gd-jp'>オンラインで申請することができるようになった。</span>（Sekarang sudah bisa mengajukan permohonan secara online.）</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Di depannya harus bentuk kamus, bukan bentuk ます: bilang <span class='gd-jp'>行くことができる</span>, jangan bilang 行きますことができる.<br>・「を」 di depan verba tidak perlu diubah: <span class='gd-jp'>日本語を話すことができる</span>. Baru saat diubah ke bentuk potensial, 「を」 sering diganti 「が」: <span class='gd-jp'>日本語が話せる</span>.<br>・Saat mengobrol dengan teman, bentuk potensial lebih natural. Kalau kamu tanya teman <span class='gd-jp'>明日来ることができる？</span>, kedengarannya sangat kaku; biasanya orang bilang <span class='gd-jp'>明日来られる？</span> (Besok bisa datang?).<br>・ことができる hanya untuk kemampuan, izin, atau kemungkinan. \"Besok akan hujan\" adalah prediksi, tidak ada hubungannya dengan kemampuan, jadi bilang <span class='gd-jp'>明日は雨が降るでしょう</span>.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>「ことができる」dan「ことがある」cuma beda satu kata, tapi artinya jauh berbeda. Kita bandingkan dengan satu hal yang sama:<br><b>ことができる</b>＝bisa: <span class='gd-jp'>納豆を食べることができる。</span>（Aku bisa makan natto.）<br><b>Bentuk potensial</b>＝artinya sama, lebih lisan: <span class='gd-jp'>納豆が食べられる。</span>（Aku bisa makan natto.）<br><b>Bentuk た＋ことがある</b>＝pernah: <span class='gd-jp'>納豆を食べたことがある。</span>（Aku pernah makan natto.）<br><b>Bentuk kamus＋ことがある</b>＝kadang-kadang: <span class='gd-jp'>納豆を食べることがある。</span>（Kadang-kadang aku makan natto.）</div><div class='gd-warn'>Trik membedakan: lihat akhirannya, 「できる」 atau 「ある」. できる＝bisa atau tidak; ある＝ada atau tidak (pernah melakukan, atau kadang-kadang melakukan).</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Kalau ditambah 「ようになる」 di belakangnya, artinya \"jadi bisa ～\": <span class='gd-jp'>日本語で電話することができるようになった。</span>（Aku jadi bisa menelepon dalam bahasa Jepang.）</div>","n3-36":"<div class='gd-h'>Pahami dulu dalam satu kalimat</div><div class='gd-sec'>「〜っぱなし」artinya kira-kira <b>“dibiarkan begitu saja setelah dipakai”, “dinyalakan terus dan tidak dimatikan”</b>. Seperti ibu yang mengomelimu: “Lampunya nyala terus, nggak dimatikan!” “Baju habis dilepas langsung dilempar sembarangan!” Dalam bahasa Jepang kamu akan bilang <span class='gd-jp'>つけっぱなし</span>、<span class='gd-jp'>出しっぱなし</span>、<span class='gd-jp'>脱ぎっぱなし</span>, dan biasanya nadanya <b>mengeluh atau tidak puas</b>.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Pakai bentuk ます, buang ます, lalu langsung tambahkan「っぱなし」. Ketiga golongan kata kerja caranya sama, jadi tidak perlu dibedakan.<br><span class='gd-pair'><span class='gd-jp'>つけます</span> → buang ます → <span class='gd-jp'>つけっぱなし</span></span>（dinyalakan terus, tidak dimatikan）<br><span class='gd-pair'><span class='gd-jp'>出します</span> → <span class='gd-jp'>出しっぱなし</span></span>（dikeluarkan tapi tidak dibereskan）<br><span class='gd-pair'><span class='gd-jp'>脱ぎます</span> → <span class='gd-jp'>脱ぎっぱなし</span></span>（dilepas lalu dibiarkan tergeletak）<br><span class='gd-pair'><span class='gd-jp'>開けます</span> → <span class='gd-jp'>開けっぱなし</span></span>（dibuka dan tidak ditutup）</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Seharusnya dibereskan, tapi tidak</span>Kamu melakukan suatu tindakan, lalu seharusnya ada kelanjutannya: dimatikan, ditutup, atau dirapikan. Tapi malah dibiarkan saja. Inilah pemakaian yang paling umum.</div><div class='gd-ex-line'>・<span class='gd-jp'>テレビをつけっぱなしで寝てしまった。</span>（Aku ketiduran dengan TV masih menyala）</div><div class='gd-ex-line'>・<span class='gd-jp'>水が出しっぱなしだよ。</span>（Airnya mengalir terus, belum dimatikan lho）</div><div class='gd-ex-line'>・<span class='gd-jp'>服を脱ぎっぱなしにしないで。</span>（Jangan lepas baju lalu dibiarkan tergeletak begitu saja）</div><div class='gd-sec'><span class='gd-tag'>Terus dalam keadaan yang sama</span>Satu hal berlangsung terus tanpa henti, dan biasanya terasa “kelamaan, capek banget”.</div><div class='gd-ex-line'>・<span class='gd-jp'>今日は一日中立ちっぱなしで、足が痛い。</span>（Hari ini berdiri terus seharian, kakiku sakit）</div><div class='gd-ex-line'>・<span class='gd-jp'>朝から働きっぱなしで疲れた。</span>（Kerja terus dari pagi sampai sekarang, capek banget）</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'>・<b>〜っぱなしだ</b>：<span class='gd-jp'>窓が開けっぱなしだ。</span>（Jendelanya terbuka terus, belum ditutup）<br>・<b>〜っぱなしで、〜</b>：di belakangnya disambung hasil atau kelanjutannya, seperti “ketiduran dengan TV menyala” di contoh tadi.<br>・<b>〜っぱなしにする</b>：membiarkannya begitu saja. Kalau mau menegur orang, bilang <span class='gd-jp'>〜っぱなしにしないで</span>。<br>・<b>〜っぱなしの＋名詞</b>：<span class='gd-jp'>出しっぱなしの本</span>（buku yang dikeluarkan dan tidak dibereskan）</div><div class='gd-h'>Hal yang gampang keliru</div><div class='gd-warn'>・Yang disambung adalah <b>bentuk ます tanpa ます</b>, bukan bentuk kamus: yang benar <span class='gd-jp'>つけっぱなし</span>, bukan つけるっぱなし。<br>・Di tengahnya ada <b>っ kecil</b>, jadi berhenti sejenak saat mengucapkannya: 「つけ・っ・ぱなし」, jangan dibaca つけぱなし。<br>・Pola ini sering membawa rasa tidak puas karena “seharusnya diurus tapi tidak diurus” (terutama untuk pemakaian “seharusnya dibereskan tapi tidak”). Kalau kamu hanya menyampaikan “melakukan sesuatu dalam keadaan tertentu” tanpa maksud mengeluh, 「〜たまま」 lebih natural. Tapi pemakaian untuk keadaan yang berlangsung kelamaan, seperti “berdiri terus” atau “bekerja terus”, tidak bisa diganti たまま: <span class='gd-jp'>立ったまま</span> hanya berarti “(melakukan sesuatu) sambil berdiri”, tanpa makna “sudah berdiri lama”.<br>・Inti っぱなし adalah “membiarkan keadaan itu terus berlangsung”, belum tentu karena lupa. Kalau sengaja dibiarkan pun boleh, misalnya <span class='gd-jp'>換気のために窓を開けっぱなしにしている。</span>（Jendela dibiarkan terbuka terus demi sirkulasi udara）. Kalau mau menekankan “disiapkan lebih dulu demi suatu tujuan”, pakai 〜ておく。</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Sama-sama “pergi dengan jendela terbuka”:<br><b>〜たまま</b>＝hanya menyatakan keadaan, tanpa emosi khusus: <span class='gd-jp'>窓を開けたまま出かけた。</span>（Aku pergi dengan jendela terbuka）<br><b>〜っぱanasi</b>＝bernada tidak puas karena “seharusnya ditutup tapi tidak”: <span class='gd-jp'>窓を開けっぱなしで出かけた。</span>（Dia pergi tanpa menutup jendela sama sekali）<br><b>〜ておく</b>＝<b>sengaja</b> dibiarkan begitu, ada tujuannya: <span class='gd-jp'>暑いから、窓を開けておいた。</span>（Karena panas, aku buka jendelanya dulu）<br>Cara menyambungnya juga beda: たまま dengan bentuk た, ておく dengan bentuk て, dan っぱなし dengan bentuk ます tanpa ます。</div><div class='gd-warn'>Trik memilih: kalau mau mengeluh “kok nggak dibereskan sih”, pakai っぱなし; kalau hanya bilang “dalam keadaan begitu”, pakai たまま; kalau “sengaja disiapkan dulu”, pakai ておく。</div>","n3-37":"<div class='gd-h'>Pahami dulu dalam satu kalimat</div><div class='gd-sec'>Keduanya sama-sama bicara soal “cocok untuk orang tertentu”. Bedanya, apakah sesuatu itu <b>memang dibuat khusus untuk mereka atau tidak</b>.<br><b>向き（むき）</b>＝“cocok untuk ～”, dilihat dari sifat bendanya sendiri, tidak peduli awalnya dibuat untuk siapa.<br><b>向け（むけ）</b>＝“dirancang khusus untuk ～”, sejak awal sasarannya memang kelompok itu, seperti “edisi anak-anak” atau “khusus pemula”.</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>Keduanya langsung dipasang setelah <b>nomina</b>, untuk menyatakan “untuk siapa” atau “dalam situasi apa”.<br>Di akhir kalimat: <span class='gd-pair'><span class='gd-jp'>子供</span> → <span class='gd-jp'>子供向きだ</span></span><span class='gd-pair'><span class='gd-jp'>子供</span> → <span class='gd-jp'>子供向けだ</span></span><br>Sebelum nomina: bisa ditambah「の」（<span class='gd-jp'>初心者向けの講座</span>）, dan sering juga langsung digabung jadi satu kata（<span class='gd-jp'>初心者向け講座</span>、<span class='gd-jp'>子供向け番組</span>）. Dua-duanya benar. Bentuk yang langsung digabung ini sangat sering muncul di judul, iklan, dan deskripsi produk. Kalau kamu bikin kalimat sendiri, pakai bentuk dengan「の」dulu supaya aman.<br>Sebelum kata kerja: <span class='gd-jp'>向けに</span>＋kata kerja seperti <span class='gd-jp'>作る</span>、<span class='gd-jp'>書く</span>, artinya “dibuat demi ～”.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>向き</span>Kondisi bendanya sendiri kebetulan pas. Sering dipakai untuk menilai rumah, pekerjaan, kepribadian, atau pakaian.</div><div class='gd-ex-line'>・<span class='gd-jp'>この部屋は一人暮らし向きだ。</span>（Kamar ini cocok untuk ditinggali sendirian）</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は営業向きの性格だ。</span>（Kepribadiannya cocok untuk kerja di bagian penjualan）</div><div class='gd-sec'>Kalau tidak cocok, bilang <b>不向き</b>：</div><div class='gd-ex-line'>・<span class='gd-jp'>この靴は長く歩くのには不向きだ。</span>（Sepatu ini tidak cocok untuk jalan jauh）</div><div class='gd-sec'><span class='gd-tag'>向け</span>Produk, acara, atau layanan yang sejak dirancang sudah menargetkan kelompok tertentu.</div><div class='gd-ex-line'>・<span class='gd-jp'>外国人向けのパンフレットをください。</span>（Tolong beri saya brosur untuk orang asing）</div><div class='gd-ex-line'>・<span class='gd-jp'>このアプリは高齢者向けに作られている。</span>（Aplikasi ini dibuat untuk lansia）</div><div class='gd-h'>Hal yang gampang keliru</div><div class='gd-warn'>・Cara baca: 向き dibaca <b>むき</b>, 向け dibaca <b>むけ</b>. Bedanya cuma bunyi terakhir, jadi dengarkan baik-baik.<br>・Untuk “dibuat demi ～” pakai <span class='gd-jp'>向けに作る</span>. Kita tidak bilang 向きに作る, karena 向き tidak membicarakan tujuan pembuatan.<br>・Untuk “tidak cocok” hanya ada <span class='gd-jp'>不向き</span>; tidak ada kata “不向け”.<br>・<span class='gd-jp'>南向きの部屋</span> artinya “kamar yang menghadap selatan”. Di sini 向き berarti <b>arah</b>, maknanya lain dari “cocok”, jadi jangan tertukar.</div><div class='gd-h'>Bedakan dari yang mirip</div><div class='gd-sec'>Sama-sama bicara hubungan sebuah buku dengan anak-anak:<br><span class='gd-jp'>これは子供向けの本だ。</span>（Ini buku anak-anak, memang ditulis untuk dibaca anak-anak）<br><span class='gd-jp'>大人向けに書かれた本だが、やさしいので子供向きでもある。</span>（Buku ini awalnya ditulis untuk orang dewasa, tapi isinya mudah, jadi cocok juga untuk anak-anak）<br>Kalimat kedua pas untuk melihat bedanya: dibuat untuk siapa adalah <b>向け</b>, hasilnya cocok untuk siapa adalah <b>向き</b>. Satu buku yang sama bisa memakai keduanya.</div><div class='gd-warn'>Trik memilih: kalau bisa diganti dengan “dibuat khusus untuk ～”, pakai 向け; kalau hanya terasa “cocok untuk ～”, pakai 向き。</div><div class='gd-h'>Bisa dilanjutkan setelah ini</div><div class='gd-sec'>向き berasal dari kata kerja <span class='gd-jp'>向く</span>（cocok）, jadi kamu juga bisa langsung bilang <span class='gd-jp'>この仕事は私に向いている。</span>（Pekerjaan ini cocok untukku）、<span class='gd-jp'>私は細かい作業に向いていない。</span>（Aku tidak cocok untuk pekerjaan yang detail）。</div>","n3-70":"<div class='gd-h'>Paham dalam satu kalimat</div><div class='gd-sec'>「〜させる」artinya <b>\"menyuruh seseorang melakukan ～\"</b> atau <b>\"membiarkan seseorang melakukan ～\"</b>. Ibu menyuruh anak makan sayur, atau bos membiarkan karyawan pulang lebih awal, dua-duanya pakai bentuk ini. Bisa berarti memaksa, bisa juga mengizinkan, tergantung konteks kalimatnya.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Menyuruh</span>Meminta orang lain melakukan sesuatu, biasanya dari atas ke bawah, misalnya orang tua ke anak atau atasan ke bawahan.</div><div class='gd-ex-line'>・<span class='gd-jp'>母は子供に野菜を食べさせた。</span>（Ibu menyuruh anaknya makan sayur）</div><div class='gd-sec'><span class='gd-tag'>Membiarkan / mengizinkan</span>Orang itu sebenarnya memang ingin melakukannya, lalu kamu menyetujui dan melepasnya.</div><div class='gd-ex-line'>・<span class='gd-jp'>父は私を一人で旅行に行かせてくれた。</span>（Ayah membiarkan aku pergi bepergian sendirian）</div><div class='gd-sec'><span class='gd-tag'>Membuat orang merasakan sesuatu</span>Membuat orang menangis, senang, atau khawatir.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼女を泣かせてしまった。</span>（Aku membuat pacarku menangis）</div><div class='gd-ex-line'>・<span class='gd-jp'>親を心配させたくない。</span>（Aku tidak mau membuat orang tuaku khawatir）</div><div class='gd-h'>Cara membentuknya: lihat dulu jenis verbanya</div><div class='gd-sec'><b>Golongan 1 (verba godan)</b>: ganti bunyi terakhir dengan bunyi baris 「あ」 yang sama, lalu tambahkan 「せる」.<br><span class='gd-pair'><span class='gd-jp'>書く</span> → く diganti か → <span class='gd-jp'>書かせる</span></span><br><span class='gd-pair'><span class='gd-jp'>飲む</span> → <span class='gd-jp'>飲ませる</span></span><span class='gd-pair'><span class='gd-jp'>待つ</span> → <span class='gd-jp'>待たせる</span></span><span class='gd-pair'><span class='gd-jp'>帰る</span> → <span class='gd-jp'>帰らせる</span></span><br>Hati-hati dengan verba yang berakhiran 「う」, karena 「う」 diganti jadi <b>わ</b>: <span class='gd-pair'><span class='gd-jp'>買う</span> → う diganti わ → <span class='gd-jp'>買わせる</span></span></div><div class='gd-sec'><b>Golongan 2 (verba ichidan)</b>: buang 「る」 di akhir, lalu tambahkan 「させる」.<br><span class='gd-pair'><span class='gd-jp'>食べる</span> → <span class='gd-jp'>食べさせる</span></span><span class='gd-pair'><span class='gd-jp'>見る</span> → <span class='gd-jp'>見させる</span></span><span class='gd-pair'><span class='gd-jp'>調べる</span> → <span class='gd-jp'>調べさせる</span></span></div><div class='gd-sec'><b>Golongan 3 (hanya dua, hafalkan saja)</b>: <span class='gd-pair'><span class='gd-jp'>する</span> → <span class='gd-jp'>させる</span></span><span class='gd-pair'><span class='gd-jp'>来る</span> → <span class='gd-jp'>来させる</span>（こさせる）</span></div><div class='gd-sec'>「〜させる」yang sudah terbentuk itu sendiri adalah verba golongan 2, jadi perubahan selanjutnya mengikuti aturan golongan 2: <span class='gd-jp'>書かせます</span>、<span class='gd-jp'>書かせた</span>、<span class='gd-jp'>書かせて</span>、<span class='gd-jp'>書かせない</span>.</div><div class='gd-h'>Siapa yang menyuruh, siapa yang melakukan: pasang partikelnya</div><div class='gd-sec'>Pola dasar: <b>orang yang menyuruh</b> + は／が, <b>orang yang melakukan</b> + に atau を, lalu diakhiri 〜させる. Apakah yang melakukan pakai に atau を, tergantung apakah tindakannya sendiri sudah punya 「を」:<br><b>Tindakan yang sudah punya objek dengan 「を」</b> (membaca buku, makan, mengerjakan PR): orang yang melakukan pakai <b>に</b>, karena を sudah dipakai oleh objeknya.</div><div class='gd-ex-line'>・<span class='gd-jp'>先生は学生に教科書を読ませた。</span>（Guru menyuruh murid membaca buku pelajaran）</div><div class='gd-sec'><b>Tindakan yang tidak punya objek dengan 「を」</b> (pergi, bermain, menangis, menunggu): orang yang melakukan biasanya pakai <b>を</b>.</div><div class='gd-ex-line'>・<span class='gd-jp'>子供を公園で遊ばせる。</span>（Membiarkan anak bermain di taman）</div><div class='gd-sec'>Pada kasus kedua, に juga boleh dipakai, misalnya <span class='gd-jp'>子供に自由に遊ばせる</span>, yang terdengar lebih seperti \"menghargai orang itu dan membiarkannya berbuat sesukanya\". Untuk pemula, hafalkan dulu aturan dasar di atas, itu sudah cukup.</div><div class='gd-h'>Bentuk yang paling sering kamu dengar</div><div class='gd-sec'><span class='gd-tag'>〜させてください</span>\"Tolong izinkan saya ～\", dipakai untuk meminta izin dengan sopan saat ingin melakukan sesuatu.</div><div class='gd-ex-line'>・<span class='gd-jp'>少し考えさせてください。</span>（Tolong beri saya waktu untuk berpikir sebentar）</div><div class='gd-ex-line'>・<span class='gd-jp'>ここで働かせてください。</span>（Tolong izinkan saya bekerja di sini）</div><div class='gd-sec'><span class='gd-tag'>待たせる</span>\"Membuat orang menunggu\", sangat sering dipakai saat minta maaf.</div><div class='gd-ex-line'>・<span class='gd-jp'>待たせてごめん。</span>（Maaf sudah membuatmu menunggu）</div><div class='gd-ex-line'>・<span class='gd-jp'>お待たせしました。</span>（Maaf sudah membuat Anda menunggu lama）</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Verba yang berakhiran 「う」 berubah jadi わ: <span class='gd-jp'>買わせる</span>、<span class='gd-jp'>会わせる</span>、<span class='gd-jp'>使わせる</span>, bukan 買あせる.<br>・<span class='gd-jp'>来させる</span> dibaca <b>こさせる</b>, bukan きさせる.<br>・Golongan 1 jangan ditambah 「さ」 berlebihan: yang benar <span class='gd-jp'>読ませる</span>, bukan 読まさせる. Orang Jepang sendiri sering salah ngomong begini, tapi umumnya dianggap tidak benar.<br>・Jangan pakai させる kepada guru, atasan, atau tamu, karena terdengar seperti kamu memerintah mereka. Kalau ingin meminta orang yang lebih tinggi melakukan sesuatu, pakai 「〜てもらう」「〜ていただく」: <span class='gd-jp'>先生に説明していただきました。</span>（Saya dijelaskan oleh guru / Guru berkenan menjelaskan kepada saya）<br>・Dalam bahasa Indonesia kita sering bilang \"film ini membuatku terharu\", tapi dalam bahasa Jepang lebih alami langsung bilang <span class='gd-jp'>この映画に感動した</span>. Kalau dipaksakan jadi この映画は私を感動させた, kedengarannya kaku seperti hasil terjemahan.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Untuk hal yang sama, yaitu \"membersihkan kamar\", lihat siapa yang menyuruh dan siapa yang melakukan:<br><b>させる</b>: <span class='gd-jp'>母は私に部屋を掃除させた。</span>（Ibu menyuruhku membersihkan kamar: ibu yang menyuruh, aku yang melakukan）<br><b>させられる</b>: <span class='gd-jp'>私は母に部屋を掃除させられた。</span>（Aku dipaksa ibu membersihkan kamar: tetap aku yang melakukan, tapi dari sudut pandangku ada rasa tidak rela）<br><b>てもらう</b>: <span class='gd-jp'>私は母に部屋を掃除してもらった。</span>（Aku minta ibu membersihkan kamarku: aku yang meminta, ibu yang melakukan）</div><div class='gd-warn'>Trik cepat: subjek menyuruh orang lain melakukan = させる; subjek sendiri yang dipaksa melakukan = させられる; subjek meminta orang lain melakukan sesuatu untuknya = てもらう.</div><div class='gd-h'>Setelah ini, lanjut belajar</div><div class='gd-sec'>Kalau させる digabung dengan bentuk pasif, jadilah <span class='gd-jp'>〜させられる</span> (kausatif pasif) yang artinya \"dipaksa melakukan ～\": <span class='gd-jp'>子供のころ、毎日ピアノを練習させられた。</span>（Waktu kecil, aku dipaksa latihan piano setiap hari）</div>","n3-7":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「〜せいで」artinya <b>「gara-gara ~」「gara-gara ~ jadi begini」</b>. Kalau hasilnya buruk dan kamu mau menyebut penyebabnya, pakai pola ini.<br>Kalau diganti jadi「〜せいか」, nadanya lebih lunak, jadi <b>「mungkin karena ~ ya」</b>. Artinya kamu sendiri juga kurang yakin soal penyebabnya.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>せいで</span>Hasilnya buruk dan kamu yakin siapa atau apa penyebabnya. Ada sedikit rasa menyalahkan atau mengeluh.</div><div class='gd-ex-line'>・<span class='gd-jp'>雨のせいで、試合が中止になった。</span>（Gara-gara hujan, pertandingannya dibatalkan）</div><div class='gd-ex-line'>・<span class='gd-jp'>私が寝坊したせいで、みんなを待たせてしまった。</span>（Gara-gara aku bangun kesiangan, semua orang jadi menunggu）</div><div class='gd-sec'><span class='gd-tag'>せいか</span>Hanya menebak penyebab, belum tentu benar. Dalam bahasa Indonesia sering jadi「mungkin karena ~」.</div><div class='gd-ex-line'>・<span class='gd-jp'>年のせいか、最近疲れやすい。</span>（Mungkin karena faktor usia, belakangan ini aku gampang capek）</div><div class='gd-ex-line'>・<span class='gd-jp'>寝不足のせいか、頭がぼんやりする。</span>（Mungkin karena kurang tidur, kepalaku terasa pusing dan melayang）</div><div class='gd-sec'><span class='gd-tag'>Di akhir kalimat</span>Penyebab disebut di bagian akhir, jadi bentuknya「~ itu gara-gara ~」.</div><div class='gd-ex-line'>・<span class='gd-jp'>失敗したのは準備不足のせいだ。</span>（Gagal itu gara-gara persiapan yang kurang）</div><div class='gd-ex-line'>・<span class='gd-jp'>私のせいです。すみません。</span>（Ini salahku. Maaf ya）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'>「せい」sendiri adalah kata benda, jadi cara menyambungnya sama seperti kata benda.<br><b>Kata benda</b>：tambah「の」<span class='gd-pair'><span class='gd-jp'>風邪</span> → <span class='gd-jp'>風邪のせいで</span></span><br><b>Kata sifat-な</b>：tambah「な」<span class='gd-pair'><span class='gd-jp'>下手</span> → <span class='gd-jp'>下手なせいで</span></span><br><b>Kata sifat-い</b>：langsung disambung<span class='gd-pair'><span class='gd-jp'>狭い</span> → <span class='gd-jp'>狭いせいで</span></span><br><b>Kata kerja</b>：pakai bentuk biasa (bentuk tanpa ます), bentuk lampau juga boleh<span class='gd-pair'><span class='gd-jp'>食べすぎた</span> → <span class='gd-jp'>食べすぎたせいで</span></span><br>Cara menyambung せいか persis sama, tinggal ganti で dengan か.</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Kata benda harus pakai「の」: yang benar <span class='gd-jp'>雪のせいで</span>, bukan「雪せいで」.<br>・Kata sifat-な pakai「な」, tidak boleh pakai「だ」: yang benar <span class='gd-jp'>暇なせいか</span>, bukan「暇だせいか」.<br>・<b>Untuk hasil yang baik, jangan pakai せいで</b>. Untuk「berkat guru, aku lulus ujian」pakai おかげで. Kalau pakai せいで, artinya malah kamu menyalahkan guru karena kamu lulus, aneh sekali.<br>・Mengatakan <span class='gd-jp'>あなたのせいで</span> langsung di depan orangnya berarti menuduh, nadanya berat, jadi hati-hati.<br>・<span class='gd-jp'>気のせいだよ</span> yang sering terdengar adalah ungkapan tetap, artinya「itu cuma perasaanmu saja」.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'>Sama-sama「karena hujan」, tapi kalau hasilnya beda, kata yang dipakai juga beda:<br><b>せいで</b>＝hasilnya buruk, menyalahkan: <span class='gd-jp'>雨のせいで、花火大会が中止になった。</span>（Gara-gara hujan, festival kembang api dibatalkan）<br><b>おかげで</b>＝hasilnya baik, berterima kasih: <span class='gd-jp'>雨のおかげで、涼しくなった。</span>（Berkat hujan, udaranya jadi sejuk）<br>Sebaliknya, kalau <span class='gd-jp'>おかげで</span> dipakai untuk hasil buruk, itu sindiran: <span class='gd-jp'>君のおかげで、また怒られたよ。</span>（Berkat kamu, aku dimarahi lagi nih）</div><div class='gd-warn'>Trik cepat: mau bilang「gara-gara ~」pakai せいで, mau bilang「berkat ~」pakai おかげで; kalau penyebabnya tidak pasti dan cuma menebak, pakai せいか.</div>","n3-9":"<div class='gd-h'>Pahami dalam satu kalimat</div><div class='gd-sec'>「とともに」kalau ditulis dengan kanji jadi「と共に」, artinya mirip dengan <b>「bersama ~」「seiring dengan ~」</b>. Ini ungkapan yang lebih <b>formal dan tulisan</b>, sering muncul di berita, pidato, karangan, dan sambutan. Rasanya seperti bilang「bersama keluarga」「seiring perubahan zaman」dalam bahasa Indonesia, jarang dipakai saat ngobrol santai.</div><div class='gd-h'>Kapan dipakai</div><div class='gd-sec'><span class='gd-tag'>Bersama</span>Melakukan sesuatu bersama seseorang, versi formal dari「と一緒に」.</div><div class='gd-ex-line'>・<span class='gd-jp'>家族とともに新居で新年を迎えた。</span>（Aku menyambut tahun baru di rumah baru bersama keluarga）</div><div class='gd-ex-line'>・<span class='gd-jp'>チームの仲間とともに優勝を喜んだ。</span>（Aku bergembira merayakan kemenangan bersama rekan satu tim）</div><div class='gd-sec'><span class='gd-tag'>Seiring</span>Begitu hal yang di depan berubah, hal yang di belakang ikut berubah. Ini penggunaan yang paling sering keluar di N3.</div><div class='gd-ex-line'>・<span class='gd-jp'>年齢とともに体力が落ちてきた。</span>（Seiring bertambahnya usia, stamina jadi menurun）</div><div class='gd-ex-line'>・<span class='gd-jp'>人口が減るとともに、町の店も少なくなった。</span>（Seiring berkurangnya penduduk, toko-toko di kota juga jadi sedikit）</div><div class='gd-sec'><span class='gd-tag'>Bersamaan</span>Saat A terjadi, B juga ikut terjadi.</div><div class='gd-ex-line'>・<span class='gd-jp'>ベルが鳴るとともに、子どもたちは教室を飛び出した。</span>（Begitu bel berbunyi, anak-anak langsung berlari keluar kelas）</div><div class='gd-h'>Cara menyambungnya</div><div class='gd-sec'><b>Kata benda＋とともに</b><br><span class='gd-pair'><span class='gd-jp'>家族</span> → <span class='gd-jp'>家族とともに</span></span><span class='gd-pair'><span class='gd-jp'>技術の発展</span> → <span class='gd-jp'>技術の発展とともに</span></span><br><b>Kata kerja bentuk kamus (bentuk dasar yang ada di kamus)＋とともに</b><br><span class='gd-pair'><span class='gd-jp'>増える</span> → <span class='gd-jp'>増えるとともに</span></span><span class='gd-pair'><span class='gd-jp'>鳴る</span> → <span class='gd-jp'>鳴るとともに</span></span><br>Sedikit lebih lanjut: <b>Kata benda＋であるとともに</b>＝「adalah ~, sekaligus ~」.</div><div class='gd-ex-line'>・<span class='gd-jp'>彼は医者であるとともに、作家でもある。</span>（Dia seorang dokter, sekaligus penulis）</div><div class='gd-h'>Bagian yang gampang salah</div><div class='gd-warn'>・Pola ini sangat formal. Kalau kamu bilang ke teman <span class='gd-jp'>友達とともにラーメンを食べた</span>, kedengarannya seperti membaca surat resmi. Untuk percakapan, pakai <span class='gd-jp'>友達と一緒に</span>.<br>・Untuk arti「seiring」, bagian belakang kalimat harus menyatakan <b>「berubah jadi bagaimana」</b>, tidak boleh hanya kebiasaan tetap: ×<span class='gd-jp'>年をとるとともに、毎日運動している</span>　○<span class='gd-jp'>年をとるとともに、運動する時間が増えた</span>.<br>・Kata kerja selalu pakai bentuk kamus, meskipun kejadiannya sudah lewat. Bentuk lampau diletakkan di akhir kalimat: ×<span class='gd-jp'>増えたとともに</span>　○<span class='gd-jp'>人口が増えるとともに、町がにぎやかになった</span>.<br>・Di depannya adalah「と」, bukan「に」: <span class='gd-jp'>家族とともに</span>, bukan 家族にともに.<br>・Di buku sering ditulis dengan kanji <span class='gd-jp'>と共に</span>, kedua cara penulisan itu benar.</div><div class='gd-h'>Bedakan dengan yang mirip</div><div class='gd-sec'><b>と一緒に</b>＝「bersama」dalam percakapan sehari-hari: <span class='gd-jp'>家族と一緒に旅行した。</span>（Aku pergi liburan bersama keluarga）<br><b>とともに</b>＝versi formal dari「bersama」: <span class='gd-jp'>家族とともに旅行した。</span>（Artinya sama, tapi gayanya seperti karangan atau berita）<br>Selain itu, <span class='gd-jp'>と一緒に</span> tidak punya arti「seiring」, jadi tidak boleh bilang ×<span class='gd-jp'>年齢と一緒に体力が落ちた</span>.</div><div class='gd-sec'><b>につれて</b>＝hanya berarti「seiring」: <span class='gd-jp'>年をとるにつれて、体力が落ちてきた。</span>（Seiring bertambahnya usia, stamina jadi menurun）<br><b>とともに</b>＝bisa juga berarti「seiring」, nadanya lebih formal: <span class='gd-jp'>年をとるとともに、体力が落ちてきた。</span><br>Bedanya, <span class='gd-jp'>につれて</span> tidak bisa dipakai untuk「bersama」atau「bersamaan」, sedangkan <span class='gd-jp'>とともに</span> bisa untuk ketiganya.</div><div class='gd-warn'>Trik cepat: untuk「bersama」sehari-hari pakai と一緒に; untuk「seiring」, につれて dan とともに sama-sama boleh, makin formal makin cocok とともに; kalau mau bilang「bersama」atau「bersamaan」dengan gaya formal, pilih とともに.</div>"});
